INSERT INTO `lessons` VALUES
(1,1,'Cộng và trừ số tự nhiên','toan-cong-tru-so-tu-nhien','Thực hiện đúng phép cộng, phép trừ số tự nhiên trong phạm vi 1 000 000.','de',10,'Đọc kỹ đề bài, thực hiện phép cộng hoặc phép trừ rồi chọn đáp án đúng. Kiểm tra lại phép tính trước khi nộp bài.','- Đặt tính theo hàng, cộng từ hàng đơn vị; nhớ 1 sang hàng cao hơn khi tổng từ 10 trở lên.\n- Trừ có nhớ: mượn 1 ở hàng cao hơn khi chữ số bị trừ nhỏ hơn chữ số trừ.\n- Bài toán thực tế: xác định phép cộng hay phép trừ rồi tính tổng hoặc hiệu.\n- Kiểm tra lại kết quả bằng phép tính ngược.\n- Tính nhẩm nhanh bằng cách nhóm số thành tròn chục, tròn trăm.',1,'published',6,1,'2026-10-07 20:45:30','2026-10-08 10:29:37'),
(2,1,'Nhân và chia số tự nhiên','toan-nhan-chia-so-tu-nhien','Thực hiện đúng phép nhân, phép chia hết cho số tự nhiên.','trung_binh',10,'Kéo thả từng ý vào nhóm đúng hoặc điền kết quả vào chỗ trống. Chú ý thứ tự thực hiện phép tính.','- Nhân: đặt tính và nhân từng hàng, cộng dồn kết quả.\n- Chia: ước lượng thương từng hàng, nhân ngược và trừ dần.\n- Ghi nhớ bảng cửu chương để tính nhanh và đúng.\n- Số lẻ nhân số lẻ cho kết quả lẻ; số chẵn chia hết cho 2.\n- Phân biệt dấu nhân và dấu chia trong đề bài.',2,'published',6,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(3,2,'Cộng và trừ phân số','toan-cong-tru-phan-so','Cộng, trừ được hai phân số (cùng mẫu số và khác mẫu số).','trung_binh',12,'Nhớ quy đồng mẫu số trước khi cộng, trừ phân số khác mẫu. Rút gọn kết quả nếu được.','- Cùng mẫu số: cộng hoặc trừ tử số, giữ nguyên mẫu số.\n- Khác mẫu số: quy đồng mẫu số trước rồi mới cộng hoặc trừ.\n- Rút gọn kết quả về phân số tối giản, ví dụ 2/4 = 1/2.\n- Phân số có tử bằng mẫu thì bằng 1: 3/3 = 1.\n- Kiểm tra kết quả bằng cách quy đồng lại.',1,'published',6,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(4,2,'Nhân và chia phân số','toan-nhan-chia-phan-so','Nhân, chia được hai phân số, biết rút gọn kết quả.','trung_binh',12,'Muốn nhân hai phân số ta nhân tử với tử, mẫu với mẫu. Muốn chia, ta nhân với phân số đảo ngược.','- Nhân phân số: nhân tử với tử, mẫu với mẫu rồi rút gọn.\n- Chia phân số: nhân với phân số nghịch đảo của số chia.\n- Phân số tử lớn hơn mẫu thì lớn hơn 1; tử nhỏ hơn mẫu thì nhỏ hơn 1.\n- Mọi số nhân với 0 đều bằng 0.\n- Rút gọn trước khi nhân để tính nhanh hơn.',2,'published',6,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(5,3,'Thu gọn đơn thức','toan-thu-gon-don-thuc','Thu gọn được đơn thức và xác định bậc của đơn thức.','trung_binh',12,'Nhân các hệ số với nhau, nhân các biến với nhau, cộng số mũ của cùng một biến.','- Đơn thức gồm hệ số và phần biến, ví dụ 2x, 3x bình phương.\n- Nhân đơn thức: nhân hệ số với hệ số, cộng số mũ của cùng biến.\n- Bậc của đơn thức là tổng số mũ của các biến: 4x²y³ có bậc 5.\n- Hai đơn thức đồng dạng có cùng phần biến.\n- Thu gọn trước khi tính giá trị để tính nhanh hơn.',1,'published',7,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(6,3,'Giá trị của biểu thức đại số','toan-gia-tri-bieu-thuc','Tính được giá trị của biểu thức đại số khi biết giá trị của biến.','kho',15,'Thay giá trị của biến vào biểu thức rồi tính theo đúng thứ tự phép tính: trong ngoặc trước, nhân chia trước cộng trừ sau.','- Thứ tự thực hiện: trong ngoặc trước, nhân/chia trước, cộng/trừ sau.\n- Tính giá trị biểu thức: thay số vào chữ rồi tính theo thứ tự.\n- Ví dụ: x = 5 thì 2x + 3 = 2 x 5 + 3 = 13.\n- Biểu thức một biến chỉ chứa một chữ; hai biến chứa hai chữ.\n- Thay đúng giá trị vào đúng vị trí của biến.',2,'published',7,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(7,4,'Góc và đường thẳng','toan-goc-va-duong-thang','Nhận biết được góc nhọn, góc vuông, góc tù, góc bẹt và vị trí hai đường thẳng.','de',10,'Quan sát hình vẽ (mô tả trong đề) và chọn đáp án đúng. Góc vuông 90 độ, góc nhọn nhỏ hơn 90 độ, góc tù lớn hơn 90 độ.','- Góc nhọn nhỏ hơn 90 độ; góc vuông bằng 90 độ; góc tù lớn hơn 90 độ và nhỏ hơn 180 độ; góc bẹt bằng 180 độ.\n- Hai đường thẳng song song không có điểm chung, không bao giờ cắt nhau.\n- Góc bẹt tạo bởi hai tia đối nhau.\n- Nhận diện loại góc theo số đo của nó.\n- Vẽ và đọc đúng kí hiệu góc, đường thẳng.',1,'published',7,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(8,4,'Tam giác và các góc','toan-tam-giac','Biết tổng ba góc trong tam giác bằng 180 độ và phân loại tam giác.','trung_binh',10,'Vận dụng: tổng ba góc trong của một tam giác luôn bằng 180 độ. Kéo thả các ý vào nhóm đúng.','- Tam giác có ba cạnh và ba góc; tổng ba góc bằng 180 độ.\n- Tam giác tù có một góc tù; tam giác vuông có một góc vuông.\n- Một tam giác có tối đa một góc vuông hoặc một góc tù.\n- Tìm góc còn lại: lấy 180 độ trừ hai góc đã biết.\n- Gọi tên tam giác ABC gồm các cạnh AB, BC, CA và các góc A, B, C.',2,'published',7,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(9,5,'Các từ loại cơ bản','tv-cac-tu-loai','Nhận biết được danh từ, động từ, tính từ, số từ, lượng từ trong câu.','de',10,'Danh từ chỉ người, vật, hiện tượng. Động từ chỉ hành động, trạng thái. Tính từ chỉ đặc điểm, tính chất.','- Danh từ chỉ người, vật, hiện tượng: học sinh, sách.\n- Động từ chỉ hành động, trạng thái: bơi, hát.\n- Tính từ chỉ đặc điểm, tính chất: cao, đỏ.\n- Danh từ trả lời \"ai? cái gì?\"; động từ trả lời \"làm gì?\"; tính từ trả lời \"thế nào?\".\n- Xếp đúng từ vào nhóm danh từ, động từ, tính từ.',1,'published',6,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(10,5,'Cấu tạo câu đơn','tv-cau-don','Xác định được chủ ngữ, vị ngữ và các thành phần phụ trong câu đơn.','trung_binh',10,'Chủ ngữ thường trả lời câu hỏi \"ai? cái gì?\". Vị ngữ trả lời \"làm gì? thế nào? là gì?\".','- Câu đơn gồm hai thành phần chính: chủ ngữ và vị ngữ.\n- Chủ ngữ trả lời \"ai? cái gì?\"; vị ngữ trả lời \"làm gì? thế nào? là gì?\".\n- Câu kể kết thúc bằng dấu chấm; câu hỏi kết thúc bằng dấu hỏi.\n- Câu cảm bộc lộ cảm xúc; câu khiến nêu yêu cầu, mệnh lệnh.\n- Xác định đúng chủ ngữ, vị ngữ và kiểu câu.',2,'published',6,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(11,6,'Dấu hỏi và dấu ngã','tv-dau-hoi-dau-nga','Viết đúng dấu hỏi, dấu ngã trong các từ thường gặp.','de',10,'Đọc kỹ từng từ và chọn dạng viết đúng. Ghi nhớ các từ mẫu để tránh nhầm lẫn.','- Phân biệt cách viết các từ có dấu hỏi: nghỉ ngơi, mải mê.\n- Phân biệt cách viết các từ có dấu ngã: suy nghĩ, mãi mãi.\n- Ghi nhớ nghĩa của từ để viết đúng dấu thanh.\n- Nối từ với dấu thanh đúng của nó.\n- Viết đúng chính tả các từ dễ nhầm dấu hỏi, dấu ngã.',1,'published',6,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(12,6,'Âm đầu ch, tr, d, gi, r','tv-am-dau','Phân biệt được các âm đầu ch/tr, d/gi/r trong từ ngữ thông dụng.','de',10,'Đọc thầm từ rồi điền âm đầu còn thiếu. Đối chiếu với cách phát âm đúng của giáo viên.','- Âm đầu \"ch\": chú, chim; âm đầu \"tr\": trâu, tre, mặt trời.\n- Âm đầu \"d\": dê, dao; âm đầu \"gi\": gió, giun; âm đầu \"r\": rừng.\n- Ghi nhớ cách viết đúng của từng từ theo âm đầu.\n- Phân loại từ theo nhóm âm đầu ch/tr và d/gi/r.\n- Điền âm đầu còn thiếu cho đúng chính tả.',2,'published',6,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(13,7,'Bài văn miêu tả','tv-bai-van-mieu-ta','Nắm được bố cục và cách dùng từ ngữ trong bài văn miêu tả.','trung_binh',12,'Bài văn miêu tả gồm mở bài, thân bài, kết bài. Chú ý các từ ngữ gợi hình, gợi cảm.','- Bài văn miêu tả gồm 3 phần: mở bài, thân bài, kết bài.\n- Mở bài giới thiệu đối tượng miêu tả.\n- Thân bài tả chi tiết từ bao quát đến cụ thể.\n- Kết bài nêu cảm nghĩ, tình cảm của người viết.\n- Dùng từ ngữ gợi hình (từ láy như \"lấp lánh\") để tả sinh động.',1,'published',7,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(14,7,'Biện pháp tu từ','tv-bien-phap-tu-tu','Nhận biết được biện pháp so sánh, nhân hoá, ẩn dụ.','trung_binh',12,'So sánh dùng từ \"như, tựa, giống\". Nhân hoá gán đặc điểm con người cho sự vật. Ẩn dụ gọi tên sự vật này bằng tên sự vật khác.','- So sánh dùng từ so sánh \"như\": trăng tròn như cái đĩa.\n- Nhân hoá gán đặc điểm con người cho sự vật.\n- Ẩn dụ gọi tên sự vật này bằng tên sự vật khác, không dùng từ so sánh.\n- Nhận diện đúng biện pháp tu từ theo dấu hiệu của câu.\n- Câu có từ \"như\" thường là so sánh, không phải ẩn dụ.',2,'published',7,1,'2026-10-07 20:45:30','2026-10-07 20:45:30'),
(15,8,'Family vocabulary','en-my-family','Hiểu nghĩa và ghi nhớ các từ vựng về gia đình (father, mother, brother, sister...).','de',10,'Ghép từ tiếng Anh với nghĩa tiếng Việt tương ứng. Học thuộc cách viết của từng từ.','- \"father\" nghĩa là bố; \"mother\" nghĩa là mẹ.\n- \"brother\" nghĩa là anh trai hoặc em trai; \"sister\" nghĩa là chị gái hoặc em gái.\n- \"grandfather\" nghĩa là ông; \"grandmother\" nghĩa là bà.\n- Ghép đúng từ tiếng Anh với nghĩa tiếng Việt của từng thành viên trong gia đình.\n- Dùng từ vựng gia đình để giới thiệu người thân, ví dụ \"My mother is a teacher.\"',1,'published',6,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(16,8,'At school vocabulary','en-at-school','Hiểu nghĩa và ghi nhớ các từ vựng về trường học (book, pen, classroom, teacher...).','de',10,'Phân loại các từ vào nhóm đồ dùng hoặc nhóm con người. Điền từ còn thiếu vào câu.','- \"teacher\" là giáo viên; \"student\" là học sinh; \"book\" là quyển sách; \"pen\" là bút mực.\n- \"pencil\" là bút chì; \"eraser\" là cục tẩy; \"notebook\" là vở.\n- \"classroom\" là lớp học; \"school\" là trường học.\n- Đồ dùng học tập (pencil, ruler) để trong cặp; bàn ghế, bảng ở trong lớp học.\n- Đặt câu đơn giản với từ vựng trường học, ví dụ \"I write with a pen.\"',2,'published',6,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(17,9,'Present simple tense','en-present-simple','Chia đúng động từ ở thì hiện tại đơn với các chủ ngữ khác nhau.','trung_binh',12,'Chủ ngữ he, she, it → động từ thêm s/es. Các chủ ngữ còn lại giữ nguyên động từ.','- Ngôi he/she/it: động từ thêm s/es (she goes).\n- Ngôi I/you/we/they: động từ giữ nguyên mẫu (they play).\n- Câu phủ định với he/she/it dùng \"doesn\'t\" + động từ nguyên mẫu.\n- Câu phủ định với I/you/we/they dùng \"don\'t\" + động từ nguyên mẫu.\n- Ghép đúng chủ ngữ với dạng động từ \"go\" hoặc \"goes\" phù hợp.',1,'published',6,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(18,9,'Prepositions of place','en-prepositions','Dùng đúng giới từ chỉ nơi chốn: in, on, under, behind, next to...','de',10,'on = trên mặt phẳng, in = bên trong, under = phía dưới, behind = phía sau, next to = bên cạnh.','- \"on\" chỉ vị trí trên bề mặt: on the table, on the wall.\n- \"in\" chỉ vị trí bên trong: in the classroom.\n- \"under\" chỉ vị trí phía dưới.\n- Bếp, phòng ngủ ở trong nhà (indoors); vườn, sân chơi ở ngoài trời (outdoors).\n- Ghép đúng giới từ với từng câu mô tả vị trí.',2,'published',6,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(19,10,'Health vocabulary','en-health','Hiểu nghĩa và ghi nhớ các từ vựng về sức khoẻ (headache, fever, healthy...).','de',10,'Ghép từ tiếng Anh với nghĩa tiếng Việt tương ứng. Phân biệt các từ chỉ bệnh và từ chỉ thể trạng.','- \"headache\" là đau đầu (head + ache); \"fever\" là sốt; \"cough\" là ho.\n- \"healthy\" là khoẻ mạnh; \"sick\" là ốm.\n- \"doctor\" là bác sĩ; \"nurse\" là y tá.\n- Ghép từ tiếng Anh với nghĩa tiếng Việt đúng.\n- Dùng từ vựng sức khỏe để nói về tình trạng cơ thể.',1,'published',7,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(20,10,'Travel vocabulary','en-travel','Hiểu nghĩa và ghi nhớ các từ vựng về du lịch (ticket, suitcase, hotel, beach...).','de',10,'Điền từ còn thiếu vào câu về chuyến du lịch. Học thuộc các cụm từ thông dụng.','- \"ticket\" là vé; \"hotel\" là khách sạn; \"suitcase\" là vali.\n- \"train\" là tàu hoả; \"plane\" là máy bay.\n- \"by plane, by train, by bus, by bike\" chỉ phương tiện di chuyển.\n- Phân biệt đồ mang theo khi du lịch với địa điểm đến thăm.\n- Đặt câu đơn giản về chuyến đi, ví dụ \"We stay at a hotel when we travel.\"',2,'published',7,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(21,11,'Hệ xương của người','kh-he-xuong','Kể tên được một số xương chính và vai trò của hệ xương.','de',10,'Hệ xương nâng đỡ cơ thể và bảo vệ các cơ quan bên trong. Ghi nhớ tên các xương chính.','- Hệ xương nâng đỡ cơ thể, tạo khung và bảo vệ các cơ quan bên trong như não, tim, phổi.\n- Xương sọ tạo thành hộp sọ, bao bọc và bảo vệ não.\n- Xương sườn bảo vệ tim và phổi.\n- Cột sống nâng đỡ toàn bộ cơ thể.\n- Xương đùi là xương dài và chắc nhất trong cơ thể người.',1,'published',6,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(22,11,'Hệ tiêu hoá','kh-he-tieu-hoa','Mô tả được đường đi của thức ăn qua các cơ quan tiêu hoá.','trung_binh',10,'Thức ăn đi theo thứ tự: miệng → thực quản → dạ dày → ruột non → ruột già.','- Đường đi của thức ăn: miệng → thực quản → dạ dày → ruột non → ruột già.\n- Thực quản là ống nối miệng với dạ dày, đưa thức ăn xuống dạ dày.\n- Miệng là nơi đầu tiên tiếp nhận, nhai và nghiền nhỏ thức ăn.\n- Tim thuộc hệ tuần hoàn, phổi thuộc hệ hô hấp — đó không phải là cơ quan tiêu hoá.\n- Các cơ quan tiêu hoá phối hợp nhịp nhàng để biến thức ăn thành chất dinh dưỡng nuôi cơ thể.',2,'published',6,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(23,12,'Các trạng thái của chất','kh-trang-thai-chat','Nhận biết được ba trạng thái của chất: rắn, lỏng, khí.','de',10,'Chất rắn có hình dạng cố định, chất lỏng chảy được, chất khí lan toả chiếm đầy không gian.','- Chất tồn tại ở ba trạng thái cơ bản: rắn, lỏng và khí.\n- Nước đá có hình dạng cố định nên ở trạng thái rắn.\n- Chất lỏng có hình dạng theo vật chứa nó.\n- Chất khí không có hình dạng cố định, luôn lan toả chiếm đầy bình chứa.\n- Khi đun sôi, nước chuyển từ thể lỏng thành hơi nước ở thể khí.',1,'published',7,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(24,12,'Nước quanh ta','kh-nuoc','Biết được tính chất của nước và vai trò của nước với sự sống.','de',10,'Nước không màu, không mùi, không vị. Nhiệt độ sôi của nước là 100 độ C ở điều kiện thường.','- Nước tinh khiết không màu, không mùi, không vị.\n- Trong điều kiện thường, nước sôi ở 100°C và đóng băng ở 0°C.\n- Con người chỉ sống được vài ngày nếu thiếu nước.\n- Nước cần cho mọi hoạt động sống và sinh hoạt hằng ngày.\n- Nguồn nước sạch có hạn nên cần tiết kiệm mỗi ngày, ví dụ khoá vòi khi không dùng.',2,'published',7,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(25,13,'Nguồn năng lượng','kh-nguon-nang-luong','Phân biệt được năng lượng tái tạo và năng lượng không tái tạo.','trung_binh',10,'Năng lượng tái tạo: mặt trời, gió, nước. Không tái tạo: than đá, dầu mỏ, khí đốt.','- Mặt trời, gió, nước là nguồn năng lượng tái tạo vì không bao giờ cạn kiệt.\n- Than đá, dầu mỏ, khí đốt hình thành qua hàng triệu năm nên dùng hết là cạn kiệt — đó là năng lượng không tái tạo.\n- Tấm pin mặt trời biến ánh sáng mặt trời thành điện năng.\n- Ưu tiên dùng năng lượng tái tạo giúp tiết kiệm tài nguyên và giảm ô nhiễm môi trường.\n- Năng lượng mặt trời, gió và nước sạch, không gây ô nhiễm nên được khuyến khích sử dụng.',1,'published',8,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(26,13,'Điện và mạch điện','kh-dien','Biết các bộ phận của mạch điện đơn giản và tác dụng của dòng điện.','trung_binh',10,'Mạch điện đơn giản gồm: nguồn điện, dây dẫn, bóng đèn và công tắc. Dòng điện có tác dụng làm nóng và phát sáng.','- Kim loại như đồng, sắt dẫn điện; nhựa và gỗ khô cách điện.\n- Mạch điện đơn giản gồm: nguồn điện, dây dẫn, bóng đèn và công tắc.\n- Công tắc dùng để đóng, ngắt dòng điện trong mạch.\n- Nhờ vật cách điện bọc ngoài, dây điện và dụng cụ điện an toàn khi cầm nắm.\n- Tuyệt đối không chạm vào ổ điện; dùng điện phải luôn cẩn thận vì rất nguy hiểm.',2,'published',8,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(27,14,'Nước Văn Lang','ls-nuoc-van-lang','Biết được nước Văn Lang – nhà nước đầu tiên của người Việt.','de',10,'Nước Văn Lang do các vua Hùng dựng nên, kinh đô ở Phong Châu (Phú Thọ ngày nay).','- Nước Văn Lang là nhà nước đầu tiên của người Việt, do các vua Hùng dựng nên.\n- Người đứng đầu nước Văn Lang gọi là Vua Hùng (Hùng Vương).\n- Kinh đô Văn Lang đặt ở Phong Châu, thuộc tỉnh Phú Thọ ngày nay.\n- Vua Hùng đặt các Lạc tướng giúp việc cai trị các bộ.\n- Ngày Giỗ Tổ Hùng Vương (10/3 âm lịch) tưởng nhớ công lao dựng nước của các vua Hùng.',1,'published',6,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(28,14,'Các anh hùng dân tộc','ls-anh-hung-dan-toc','Kể tên được các anh hùng chống ngoại xâm: Hai Bà Trưng, Bà Triệu, Ngô Quyền...','de',10,'Ghép tên anh hùng với chiến công tương ứng. Ghi nhớ thứ tự thời gian các sự kiện.','- Hai Bà Trưng phất cờ khởi nghĩa năm 40 sau Công nguyên.\n- Bà Triệu khởi nghĩa năm 248; Lý Bí khởi nghĩa năm 542.\n- Lý Bí xưng đế năm 544, lập nước Vạn Xuân.\n- Ngô Quyền đại phá quân Nam Hán trên sông Bạch Đằng năm 938.\n- Hát Môn là nơi Hai Bà Trưng tuẫn tiết; Bạch Đằng gắn với chiến công của Ngô Quyền.',2,'published',6,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(29,15,'Đinh Bộ Lĩnh dẹp loạn 12 sứ quân','ls-dinh-bo-linh','Biết được công lao của Đinh Bộ Lĩnh trong việc thống nhất đất nước.','de',10,'Đinh Bộ Lĩnh dẹp loạn 12 sứ quân, lập nước Đại Cồ Việt, đóng đô ở Hoa Lư.','- Sau khi Ngô Quyền mất, các thế lực cát cứ nổi lên, sử gọi là loạn 12 sứ quân.\n- Đinh Bộ Lĩnh dẹp loạn 12 sứ quân, thống nhất đất nước năm 968.\n- Năm 968, Đinh Bộ Lĩnh lên ngôi, đặt tên nước là Đại Cồ Việt.\n- Nhà Đinh đóng đô ở Hoa Lư (Ninh Bình ngày nay) — vùng núi hiểm trở, dễ phòng thủ.\n- Việc đặt quốc hiệu Đại Cồ Việt khẳng định nước ta sánh ngang với phương Bắc.',1,'published',7,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(30,15,'Lê Hoàn và nhà Tiền Lê','ls-le-hoan','Biết được Lê Hoàn lên ngôi và chiến thắng quân Tống năm 981.','de',10,'Lê Hoàn đánh tan quân Tống xâm lược năm 981, mở đầu triều đại nhà Tiền Lê.','- Lê Đại Hành chính là hiệu của vua Lê Hoàn nhà Tiền Lê.\n- Nhà Đinh chỉ tồn tại 12 năm (968–980); nhà Tiền Lê tiếp tục đóng đô ở Hoa Lư.\n- Phạm Cự Lượng và Đinh Điền là các tướng tài thời Đinh – Tiền Lê.\n- Năm 981, Lê Hoàn chỉ huy đánh tan quân Tống xâm lược, bảo vệ vững chắc nền độc lập non trẻ.\n- Thắng lợi năm 981 cho thấy ý chí quyết tâm bảo vệ độc lập của dân tộc.',2,'published',7,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(31,16,'Ba lần kháng chiến chống Nguyên – Mông','ls-dong-bo-dau','Kể được ba lần kháng chiến chống quân Nguyên – Mông thắng lợi.','trung_binh',12,'Nhân dân Đại Việt đã ba lần đánh bại quân Nguyên – Mông (1258, 1285, 1287-1288).','- Quân dân Đại Việt đã ba lần đánh bại quân Nguyên – Mông: 1258, 1285 và 1287–1288.\n- Cuộc kháng chiến lần thứ hai diễn ra năm 1285.\n- Trần Hưng Đạo (Trần Quốc Tuấn) là tổng chỉ huy cuộc kháng chiến lần 2 và lần 3.\n- Quân dân nhà Trần đoàn kết một lòng, từ vua quan đến nhân dân cùng đánh giặc.\n- Ba lần thắng lợi giữ vững nền độc lập của Đại Việt trước đế quốc hùng mạnh nhất thời bấy giờ.',1,'published',8,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(32,16,'Trần Hưng Đạo','ls-tran-hung-dao','Biết được vai trò của Trần Hưng Đạo trong kháng chiến chống Nguyên – Mông.','trung_binh',12,'Trần Hưng Đạo là tổng chỉ huy kháng chiến lần 2 và lần 3, tác giả Hịch tướng sĩ.','- Trần Hưng Đạo tên thật là Trần Quốc Tuấn, được phong Hưng Đạo Đại Vương.\n- Ông là vị tướng tổng chỉ huy kháng chiến, không phải vua, và là bậc anh hùng dân tộc.\n- Chương Dương, Tây Kết là những trận đánh tiêu biểu của cuộc kháng chiến lần 2; Vân Đồn, Bạch Đằng thuộc lần 3.\n- Ông để lại các tác phẩm quân sự và bài “Hịch tướng sĩ” khích lệ tướng sĩ.\n- Cần phân biệt: “Nam quốc sơn hà” gắn với Lý Thường Kiệt; “Đại Việt sử ký toàn thư” do Ngô Sĩ Liên biên soạn.',2,'published',8,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(33,17,'Màu nóng và màu lạnh','mt-mau-nong-mau-lanh','Phân biệt được nhóm màu nóng và nhóm màu lạnh, nêu được cảm giác mỗi nhóm gợi ra.','de',10,'Đọc kỹ câu hỏi, chọn đáp án đúng nhất. Hãy tưởng tượng màu sắc trong tranh khi trả lời.','- Màu nóng gồm đỏ, cam, vàng — gợi cảm giác ấm áp, rực rỡ, sôi động.\n- Màu lạnh gồm xanh dương, xanh lá cây, tím — gợi cảm giác mát mẻ, yên bình, trầm lắng.\n- Đỏ là màu nóng mạnh nhất, dễ thu hút ánh nhìn; xanh dương là màu lạnh điển hình như bầu trời, mặt biển.\n- Muốn tranh vui tươi, năng động thì dùng gam nóng; muốn tranh nhẹ nhàng, sâu lắng thì dùng gam lạnh.\n- Kết hợp màu nóng – lạnh hợp lý giúp tranh cân bằng và sinh động hơn.',1,'published',6,1,'2026-10-07 21:37:45','2026-10-07 21:37:45'),
(34,17,'Pha màu cơ bản','mt-pha-mau-co-ban','Biết công thức pha các màu thứ cấp từ màu cơ bản và cách làm màu sáng hoặc tối hơn.','trung_binh',10,'Nhớ lại ba màu cơ bản: đỏ, vàng, xanh dương. Từ đó suy ra các màu pha được.','- Ba màu cơ bản là đỏ, vàng, xanh dương — không pha được từ màu nào khác.\n- Đỏ + vàng = cam; vàng + xanh dương = xanh lá cây; đỏ + xanh dương = tím.\n- Cam, tím, xanh lá cây là ba màu thứ cấp, pha từ hai màu cơ bản.\n- Thêm màu trắng làm màu nhạt dần (đỏ + trắng = hồng); thêm màu đen làm màu đậm dần.\n- Khi pha màu nên cho từng ít một, khuấy đều để màu lên chuẩn.',2,'published',6,1,'2026-10-07 21:37:45','2026-10-07 21:37:45'),
(35,18,'Đường nét và hình khối','mt-duong-net-hinh-khoi','Phân biệt các loại đường nét và cảm giác chúng gợi ra; phân biệt hình phẳng với hình khối.','trung_binh',10,'Quan sát đường nét trong tranh: thẳng hay cong, nét đậm hay nhạt, rồi suy nghĩ cảm giác chúng mang lại.','- Đường thẳng đứng gợi sự vững chắc, hiên ngang như thân cây, cột nhà.\n- Đường cong gợi sự mềm mại, uyển chuyển như dòng sông, làn tóc.\n- Đường zíc zắc (gấp khúc) gợi sự sôi động, mạnh mẽ như tia chớp.\n- Hình phẳng là hình hai chiều (tròn, vuông, tam giác); hình khối là hình ba chiều (cầu, hộp, trụ).\n- Chọn đường nét phù hợp giúp tranh diễn tả đúng cảm xúc muốn gửi gắm.',1,'published',7,1,'2026-10-07 21:37:45','2026-10-07 21:37:45'),
(36,19,'Bố cục trong tranh','mt-bo-cuc-tranh','Hiểu cách sắp xếp nhân vật chính – phụ, vật gần – xa để bức tranh cân đối, sinh động.','trung_binh',12,'Hãy tưởng tượng mình đang sắp xếp các nhân vật trong một bức tranh: ai là chính, ai là phụ, cái gì gần, cái gì xa.','- Bố cục là cách sắp xếp các hình, mảng trong tranh cho cân đối và sinh động.\n- Nhân vật chính đặt ở vị trí nổi bật để thu hút ánh nhìn đầu tiên của người xem.\n- Nhân vật phụ làm nền, phông nền tạo không gian cho bức tranh.\n- Vật ở gần vẽ to, rõ nét; vật ở xa vẽ nhỏ, mờ dần — tạo chiều sâu cho tranh.\n- Nhấn mạnh nhân vật chính và màu chủ đạo, tiết chế chi tiết rườm rà làm rối tranh.',1,'published',7,1,'2026-10-07 21:37:45','2026-10-07 21:37:45'),
(37,20,'Tranh Đông Hồ nổi tiếng','mt-tranh-dong-ho-noi-tieng','Biết nguồn gốc, chất liệu làm tranh Đông Hồ và nội dung một số bức tranh tiêu biểu.','trung_binh',12,'Tranh Đông Hồ là dòng tranh dân gian nổi tiếng của Việt Nam. Hãy tìm hiểu thật kỹ từng bức tranh nhé.','- Tranh Đông Hồ ra đời tại làng Đông Hồ, huyện Thuận Thành, tỉnh Bắc Ninh.\n- Giấy điệp làm từ vỏ sò điệp nghiền mịn quét lên giấy dó nên óng ánh, bền màu.\n- Màu vẽ từ nguyên liệu tự nhiên (cây cỏ, khoáng chất) nên trầm ấm, mộc mạc.\n- Tranh tiêu biểu: Gà trống tượng trưng sung túc, Đám cưới chuột châm biếm thói hối lộ, Hứng dừa thể hiện ước mơ đỗ đạt.\n- Tranh dân gian dùng nét mộc mạc, rõ ràng với đề tài gần gũi đời sống làng quê.',1,'published',8,1,'2026-10-07 21:37:45','2026-10-07 21:37:45'),
(38,21,'Lên ý tưởng tranh dân gian','mt-y-tuong-tranh-dan-gian','Biết chọn đề tài, bố cục và màu sắc theo phong cách tranh dân gian cho bức tranh của mình.','kho',12,'Bây giờ đến lượt em làm họa sĩ dân gian! Hãy vận dụng những gì đã học để lên ý tưởng cho bức tranh của mình.','- Tranh dân gian lấy đề tài từ đời sống làng quê gần gũi: chợ quê, trâu bò, lễ hội.\n- Quy trình vẽ tranh dân gian: chọn đề tài quen thuộc, phác bố cục rồi tô màu tươi rực rỡ.\n- Đường nét trong tranh dân gian mộc mạc, rõ ràng, dễ hiểu với mọi người.\n- Đề tài viễn tưởng, hiện đại chưa phù hợp với phong cách tranh dân gian.\n- Màu sắc tranh dân gian thường tươi, rực rỡ, tạo cảm giác vui tươi.',1,'published',8,1,'2026-10-07 21:37:45','2026-10-07 21:37:45'),
(39,22,'Các bộ phận của máy tính','th-cac-bo-phan-may-tinh','Kể tên và nhận biết được các bộ phận chính của máy tính: CPU, RAM, màn hình, bàn phím, chuột.','de',10,'Quan sát tên gọi và chức năng của từng bộ phận. Phân biệt thiết bị vào, thiết bị ra và bộ phận xử lý.','- CPU là bộ não của máy tính, thực hiện mọi phép tính và điều khiển hoạt động của máy.\n- Bàn phím, chuột là thiết bị vào (đưa dữ liệu vào máy); màn hình, loa, máy in là thiết bị ra (đưa kết quả ra).\n- RAM là bộ nhớ tạm thời: tắt máy thì dữ liệu trong RAM bị mất.\n- Ổ cứng (SSD) lưu dữ liệu lâu dài, không mất khi tắt máy.\n- Mỗi bộ phận có chức năng riêng và phối hợp với nhau để máy tính hoạt động.',1,'published',6,1,'2026-10-07 21:38:04','2026-10-07 21:38:04'),
(40,23,'Chức năng của từng bộ phận','th-chuc-nang-phan-cung','Nêu được chức năng của CPU, RAM, ổ cứng và các thiết bị vào/ra.','trung_binh',10,'Ghi nhớ: CPU xử lý, RAM nhớ tạm, ổ cứng lưu lâu dài. Thiết bị vào đưa dữ liệu vào, thiết bị ra đưa kết quả ra.','- Muốn giữ tài liệu dùng lâu dài phải lưu vào ổ cứng hoặc SSD, không để trong RAM.\n- Màn hình cảm ứng vừa là thiết bị vào (nhận thao tác chạm) vừa là thiết bị ra (hiển thị hình ảnh).\n- Tốc độ xử lý của máy tính phụ thuộc chủ yếu vào CPU: CPU càng mạnh, máy chạy càng nhanh.\n- RAM càng lớn thì máy tính chạy được nhiều chương trình cùng lúc càng mượt mà.\n- Nhận biết và phân loại được các thiết bị vào, thiết bị ra của máy tính.',1,'published',6,1,'2026-10-07 21:38:04','2026-10-07 21:38:04'),
(41,24,'Hệ điều hành và phần mềm ứng dụng','th-he-dieu-hanh-ung-dung','Phân biệt được hệ điều hành với phần mềm ứng dụng và kể tên ví dụ.','de',10,'Hệ điều hành quản lý toàn bộ máy tính (ví dụ Windows). Phần mềm ứng dụng phục vụ từng công việc cụ thể (Word, Chrome).','- Hệ điều hành (như Windows) quản lý phần cứng và phần mềm, là cầu nối giữa người dùng với máy tính.\n- Máy tính thiếu hệ điều hành sẽ không thể hoạt động bình thường.\n- Phần mềm ứng dụng phục vụ nhu cầu cụ thể: Word soạn văn bản, Chrome duyệt web.\n- Ví dụ: Windows là hệ điều hành, còn Word và Chrome là phần mềm ứng dụng.\n- Phân biệt được phần mềm hệ thống (hệ điều hành) và phần mềm ứng dụng.',1,'published',7,1,'2026-10-07 21:38:04','2026-10-07 21:38:04'),
(42,25,'Tệp và thư mục','th-tep-va-thu-muc','Nhận biết loại tệp qua phần mở rộng và biết cách sắp xếp tệp trong thư mục.','trung_binh',10,'Phần mở rộng (đuôi tệp) cho biết loại tệp: .docx văn bản, .jpg ảnh, .mp3 nhạc. Dùng thư mục để phân loại tệp gọn gàng.','- Phần mở rộng (đuôi tệp) cho biết tệp thuộc loại nào: .docx là văn bản Word, .mp3 là nhạc, .jpg là ảnh, .mp4 là video.\n- Đuôi tệp nằm sau dấu chấm trong tên tệp.\n- Thư mục (folder) dùng để chứa và phân loại các tệp cùng chủ đề cho gọn gàng.\n- Đặt tên tệp, thư mục rõ ràng giúp tìm kiếm nhanh chóng sau này.\n- Không nên đổi bừa đuôi tệp vì tệp có thể không mở được.',1,'published',7,1,'2026-10-07 21:38:04','2026-10-07 21:38:04'),
(43,26,'Mật khẩu mạnh và bảo mật cá nhân','th-mat-khau-bao-mat','Biết cách đặt mật khẩu mạnh và các quy tắc bảo vệ thông tin cá nhân trên mạng.','trung_binh',12,'Mật khẩu mạnh: dài, có chữ hoa, chữ thường, số và ký tự đặc biệt. Không chia sẻ mật khẩu và thông tin riêng tư cho người lạ.','- Mật khẩu mạnh phải dài và gồm chữ hoa, chữ thường, số cùng ký tự đặc biệt.\n- Tuyệt đối không cung cấp mật khẩu cho người lạ; tin nhắn yêu cầu mật khẩu là lừa đảo.\n- Địa chỉ nhà, số điện thoại là thông tin riêng tư, không chia sẻ công khai trên mạng.\n- Khi gặp yêu cầu khả nghi, hãy báo ngay cho người lớn biết.\n- Giữ kín thông tin cá nhân là nguyên tắc đầu tiên khi dùng máy tính.',1,'published',8,1,'2026-10-07 21:38:04','2026-10-07 21:38:04'),
(44,27,'Gõ phím và phím tắt văn bản','th-go-phim-tat','Biết hàng phím cơ sở và sử dụng được các phím tắt Ctrl+C, Ctrl+V, Ctrl+X, Ctrl+S.','de',10,'Đặt ngón tay lên hàng phím cơ sở (A S D F J K L). Nhớ các phím tắt: Ctrl+C sao chép, Ctrl+V dán, Ctrl+X cắt, Ctrl+S lưu.','- Ctrl+C sao chép, Ctrl+V dán, Ctrl+X cắt, Ctrl+S lưu nhanh văn bản.\n- Khi gõ tiếng Việt đúng kỹ thuật, các ngón tay đặt ở hàng phím cơ sở A S D F J K L.\n- Dùng phím tắt giúp thao tác nhanh hơn dùng chuột.\n- Luyện gõ 10 ngón giúp soạn thảo văn bản nhanh và chính xác.\n- Nhớ các phím tắt thông dụng để làm việc hiệu quả hơn.',1,'published',8,1,'2026-10-07 21:38:05','2026-10-07 21:38:05'),
(45,28,'Danh từ và động từ','nv-danh-tu-dong-tu','Nhận biết được danh từ và động từ, xác định đúng từ loại của từ trong câu.','de',10,'Danh từ chỉ người, vật, hiện tượng. Động từ chỉ hành động, trạng thái của người và sự vật.','- Danh từ chỉ người, vật, nơi chốn: trong câu “Mẹ nấu cơm”, “mẹ” và “cơm” là danh từ.\n- Động từ chỉ hành động, hoạt động: “nấu”, “bay”, “chạy nhảy”, “bơi lội” là động từ.\n- “Học sinh” chỉ người nên là danh từ chỉ người.\n- Muốn xác định đúng từ loại, cần xét nghĩa của từ trong câu cụ thể.\n- Phân biệt được danh từ, động từ giúp đặt câu và viết văn đúng.',1,'published',6,1,'2026-10-07 21:38:13','2026-10-07 21:38:13'),
(46,28,'Tính từ và câu văn','nv-tinh-tu','Nhận biết được tính từ và xác định chủ ngữ, vị ngữ trong câu đơn.','de',10,'Tính từ chỉ đặc điểm, tính chất. Câu đơn gồm chủ ngữ (ai? cái gì?) và vị ngữ (làm gì? thế nào?).','- Tính từ chỉ đặc điểm, tính chất: “cao lớn”, “chăm chỉ” là tính từ.\n- “Hiền lành” là tính từ chỉ tính cách con người.\n- Trong câu “Trời trong xanh”, chủ ngữ “trời” trả lời câu hỏi “cái gì?”, vị ngữ “trong xanh” trả lời “thế nào?”.\n- “Chạy nhanh”, “đọc truyện” chỉ hành động nên là cụm động từ.\n- Dùng tính từ phù hợp giúp câu văn sinh động, gợi cảm hơn.',2,'published',6,1,'2026-10-07 21:38:13','2026-10-07 21:38:13'),
(47,29,'Phân biệt từ loại trong câu','nv-phan-biet-tu-loai','Phân biệt được danh từ, động từ, tính từ khi đặt trong câu cụ thể.','trung_binh',12,'Đọc cả câu rồi mới xác định từ loại: cùng một hình thức từ có thể thuộc từ loại khác nhau tùy vị trí.','- “Hót” chỉ hoạt động của chim nên là động từ.\n- “Chạy” chỉ hành động là động từ; “nhanh” chỉ đặc điểm là tính từ.\n- Trong câu “Cô giáo giảng bài rất hay”, “hay” chỉ đặc điểm của bài giảng nên là tính từ.\n- Danh từ, động từ, tính từ là ba từ loại cơ bản nhất cần nắm vững.\n- Một từ có thể thuộc từ loại khác nhau, phải xét trong ngữ cảnh của câu.',1,'published',6,1,'2026-10-07 21:38:13','2026-10-07 21:38:13'),
(48,30,'So sánh và nhân hoá','nv-so-sanh-nhan-hoa','Nhận biết được biện pháp so sánh và nhân hoá qua dấu hiệu từ ngữ.','trung_binh',12,'So sánh thường có từ \"như, tựa, giống\". Nhân hoá gán hành động, đặc điểm của con người cho sự vật.','- “Mặt trời như một quả cầu lửa khổng lồ” dùng biện pháp so sánh vì có từ “như”.\n- “Chị gió thì thầm ngoài cửa sổ”: gió được gán hành động của con người (thì thầm) → nhân hoá.\n- So sánh thường xuất hiện cùng các từ ngữ: như, tựa, giống như...\n- Nhân hoá: gán hành động, tình cảm của người cho vật (“mỉm cười”, “gọi”).\n- So sánh và nhân hoá làm câu văn sinh động, gợi hình, gợi cảm hơn.',1,'published',7,1,'2026-10-07 21:38:13','2026-10-07 21:38:13'),
(49,30,'Ẩn dụ và hoán dụ','nv-an-du-hoan-du','Phân biệt được ẩn dụ và hoán dụ, hiểu cách gọi tên sự vật theo lối tu từ.','kho',12,'Ẩn dụ: gọi sự vật này bằng tên sự vật khác có nét tương đồng (không dùng từ so sánh). Hoán dụ: lấy cái gần gũi để chỉ cái cần nói (bộ phận chỉ toàn thể, vật chứa chỉ vật bị chứa...).','- “Thuyền”, “bến” gọi người ra đi, người ở lại bằng tên sự vật khác → ẩn dụ.\n- “Bàn tay ta làm nên tất cả”: lấy bộ phận (bàn tay) chỉ toàn thể (con người lao động) → hoán dụ.\n- So sánh dùng từ “như, tựa, giống”; ẩn dụ gọi thẳng tên sự vật khác mà không dùng từ so sánh.\n- “Quả” chỉ thành quả là ẩn dụ; “cả lớp” lấy vật chứa chỉ học sinh là hoán dụ.\n- Ẩn dụ và hoán dụ làm lời văn hàm súc, giàu hình ảnh.',2,'published',7,1,'2026-10-07 21:38:13','2026-10-07 21:38:13'),
(50,31,'Bố cục bài văn miêu tả','nv-bo-cuc-mieu-ta','Nắm được bố cục ba phần và cách dùng từ ngữ gợi hình, gợi cảm trong văn miêu tả.','trung_binh',12,'Bài văn miêu tả gồm mở bài, thân bài, kết bài. Chú ý từ ngữ gợi hình, gợi cảm và trình tự miêu tả hợp lí.','- Bài văn miêu tả gồm ba phần: mở bài, thân bài, kết bài.\n- Mở bài giới thiệu đối tượng được miêu tả.\n- Thân bài tả chi tiết các đặc điểm của đối tượng theo trình tự hợp lí.\n- Kết bài nêu cảm nghĩ, ấn tượng về đối tượng được tả.\n- Nên dùng từ ngữ gợi hình, gợi cảm (xanh mướt, rì rào) để bài văn sinh động.',1,'published',8,1,'2026-10-07 21:38:13','2026-10-07 21:38:13'),
(51,32,'Khởi động trước khi tập','tt-khoi-dong-truoc-khi-tap','Thực hiện đúng các động tác khởi động cơ bản và hiểu tác dụng của việc khởi động.','de',10,'Khởi động là bước không thể bỏ qua trước mỗi buổi tập. Hãy học kỹ từng động tác nhé.','- Khởi động 5–10 phút trước mỗi buổi tập: xoay khớp, chạy nhẹ tại chỗ, ép dẻo.\n- Khởi động làm nóng cơ, tăng linh hoạt khớp, giúp tránh chấn thương khi vận động mạnh.\n- Mỗi động tác xoay tác động trực tiếp lên khớp cùng tên: cổ, vai, hông, gối, cổ tay.\n- Khởi động chỉ gồm động tác nhẹ nhàng; bài tập nặng để dành cho phần tập chính.\n- Bỏ qua khởi động dễ bị chuột rút, bong gân khi vận động đột ngột.',1,'published',6,1,'2026-10-07 21:38:13','2026-10-07 21:38:13'),
(52,31,'Dấu câu trong văn bản','nv-dau-cau','Dùng đúng dấu chấm, dấu hỏi, dấu than, dấu phẩy, dấu hai chấm trong câu.','de',10,'Dấu chấm kết thúc câu kể, dấu hỏi kết thúc câu hỏi, dấu than kết thúc câu cảm thán, dấu phẩy ngăn cách các bộ phận trong câu.','- Câu kể (câu trần thuật) kết thúc bằng dấu chấm.\n- Câu hỏi kết thúc bằng dấu hỏi (?).\n- Dấu hai chấm (:) báo hiệu phần giải thích, liệt kê hoặc lời nói trực tiếp.\n- Dấu phẩy dùng để ngăn cách các thành phần bên trong câu.\n- Dùng đúng dấu câu giúp người đọc hiểu đúng ý của câu văn.',2,'published',8,1,'2026-10-07 21:38:14','2026-10-07 21:38:14'),
(53,33,'An toàn khi vận động','tt-an-toan-khi-van-dong','Biết chọn trang phục, giày phù hợp; uống nước đúng cách và xử lý khi cơ thể mệt.','de',10,'An toàn là trên hết! Hãy ghi nhớ những quy tắc đơn giản để mỗi buổi tập đều vui và khỏe.','- Đi giày thể thao vừa chân, đế mềm để bảo vệ bàn chân và khớp gối khi vận động.\n- Mặc trang phục thoải mái, thấm mồ hôi, gọn gàng khi tập luyện.\n- Chuột rút: dừng lại và kéo giãn nhẹ; trầy xước: rửa sạch vết thương; chóng mặt: nghỉ ngay và báo thầy cô.\n- Không tập luyện khi quá no, không xô đẩy nhau khi chơi thể thao.\n- Uống nước từng ngụm nhỏ trước, trong và sau khi tập để bù nước cho cơ thể.',1,'published',6,1,'2026-10-07 21:38:14','2026-10-07 21:38:14'),
(54,34,'Luật bóng đá cơ bản','tt-luat-bong-da-co-ban','Nắm được số cầu thủ, thời gian thi đấu, lỗi việt vị đơn giản và các quả đá phạt.','trung_binh',12,'Bóng đá là môn thể thao vua. Nắm chắc luật cơ bản sẽ giúp em chơi hay và xem bóng đá thú vị hơn.','- Mỗi đội bóng đá có 11 cầu thủ trên sân, trong đó có 1 thủ môn.\n- Trận đấu chính thức gồm 2 hiệp, mỗi hiệp 45 phút, nghỉ giữa hiệp 15 phút.\n- Việt vị: cầu thủ tấn công đứng gần khung thành đối phương hơn bóng và hậu vệ cuối khi đồng đội chuyền bóng.\n- Chỉ thủ môn được dùng tay trong vòng cấm; cầu thủ khác dùng tay chơi bóng là phạm luật.\n- Phạm lỗi nghiêm trọng bị thẻ vàng cảnh cáo, rất nghiêm trọng bị thẻ đỏ truất quyền thi đấu.',1,'published',7,1,'2026-10-07 21:38:14','2026-10-07 21:38:14'),
(55,35,'Luật bóng rổ cơ bản','tt-luat-bong-ro-co-ban','Nắm được số cầu thủ, cách tính điểm và lỗi chạy bước trong bóng rổ.','trung_binh',12,'Bóng rổ là môn thể thao đồng đội hấp dẫn. Hãy tìm hiểu luật chơi cơ bản nhé.','- Mỗi đội bóng rổ có 5 cầu thủ thi đấu trên sân.\n- Cách tính điểm: ném trong vạch 2 điểm, ngoài vạch 3 điểm 3 điểm, ném phạt 1 điểm.\n- Dẫn bóng bằng một tay khi di chuyển; ôm bóng chạy nhiều bước là lỗi chạy bước.\n- Đẩy người, kéo áo đối phương là phạm luật trong bóng rổ.\n- Tranh bóng phải fair-play, không dùng tay chân thô bạo với đối thủ.',1,'published',7,1,'2026-10-07 21:38:14','2026-10-07 21:38:14'),
(56,36,'Rèn luyện sức khoẻ hằng ngày','tt-ren-luyen-suc-khoe','Xây dựng thói quen tập luyện, ăn uống và ngủ nghỉ hợp lý để nâng cao sức khoẻ.','de',10,'Sức khoẻ là vốn quý nhất. Hãy học cách chăm sóc cơ thể mình mỗi ngày nhé.','- Học sinh nên vận động thể chất ít nhất 60 phút mỗi ngày với hoạt động vừa sức.\n- Ngủ đủ 8–9 tiếng mỗi đêm giúp cơ thể phát triển và tỉnh táo học tập.\n- Ăn đủ chất, nhiều rau xanh, hạn chế đồ ngọt và nước có gas.\n- Thức khuya và lười vận động làm suy giảm sức khỏe và kết quả học tập.\n- Duy trì thói quen tốt mỗi ngày quan trọng hơn tập nặng nhưng thất thường.',1,'published',8,1,'2026-10-07 21:38:14','2026-10-07 21:38:14'),
(57,37,'Vệ sinh cá nhân khi tập luyện','tt-ve-sinh-ca-nhan-khi-tap','Biết giữ vệ sinh cơ thể, quần áo và dụng cụ sau khi tập luyện.','de',10,'Tập luyện ra nhiều mồ hôi nên vệ sinh cá nhân rất quan trọng. Cùng tìm hiểu nhé.','- Sau khi tập ra nhiều mồ hôi: tắm rửa sạch sẽ, thay quần áo khô để tránh cảm lạnh.\n- Khăn mặt thấm mồ hôi dễ sinh vi khuẩn — phải giặt sạch và phơi khô sau mỗi lần dùng.\n- Không dùng chung khăn mặt, bình nước với người khác để tránh lây bệnh.\n- Cắt móng tay gọn gàng trước khi chơi thể thao tập thể để tránh làm xước bạn chơi.\n- Rửa tay sạch trước khi ăn sau buổi tập.',1,'published',8,1,'2026-10-07 21:38:14','2026-10-07 21:38:14'),
(58,38,'Quy tắc an toàn khi dùng điện','cn-quy-tac-an-toan-dien','Nêu được các quy tắc an toàn điện: tay khô khi chạm ổ điện, ngắt điện khi sửa chữa.','de',10,'Điện rất nguy hiểm nếu dùng sai cách. Ghi nhớ: tay khô mới chạm vào thiết bị điện, ngắt điện trước khi sửa chữa, báo người lớn khi thấy dây điện hở.','- Nước dẫn điện tốt nên tay ướt chạm vào ổ điện hoặc thiết bị điện rất dễ bị điện giật.\n- Trước khi sửa chữa thiết bị điện phải ngắt cầu dao hoặc rút phích điện.\n- Thấy dây điện hở vỏ tuyệt đối không chạm vào, tránh xa và báo người lớn.\n- Trẻ em không tự ý sửa đồ điện; luôn nhờ người lớn xử lý.\n- Tuân thủ quy tắc an toàn điện bảo vệ tính mạng của chính mình.',1,'published',6,1,'2026-10-07 21:38:26','2026-10-07 21:38:26'),
(59,39,'Xử lý khi gặp sự cố điện','cn-xu-ly-su-co-dien','Biết cách xử lý đúng khi gặp người bị điện giật, chập điện có mùi khét.','trung_binh',12,'Khi có sự cố điện: ngắt nguồn điện trước, dùng vật cách điện để cứu người, gọi số khẩn cấp 114 (cháy), 115 (cấp cứu) khi cần.','- Thấy người bị điện giật: tuyệt đối không chạm tay vào nạn nhân, phải ngắt điện trước.\n- Dùng vật cách điện như gậy gỗ khô để gạt dây điện ra khỏi người bị nạn.\n- Ngửi thấy mùi khét từ ổ điện phải ngắt điện và báo người lớn ngay.\n- Vật kim loại hoặc ướt dẫn điện nên không dùng để cứu người bị điện giật.\n- Bình tĩnh, ngắt điện trước rồi mới cứu là nguyên tắc quan trọng nhất.',1,'published',6,1,'2026-10-07 21:38:26','2026-10-07 21:38:26'),
(60,40,'Gỗ, kim loại và nhựa','cn-go-kim-loai-nhua','Nêu được tính chất cơ bản của gỗ, kim loại, nhựa và đồ vật làm từ chúng.','de',10,'Gỗ nhẹ dễ gia công; kim loại cứng chắc nhưng sắt dễ gỉ; nhựa nhẹ, không thấm nước. Mỗi vật liệu phù hợp với những đồ vật khác nhau.','- Sắt (kim loại) dễ bị gỉ sét khi tiếp xúc với nước và không khí ẩm.\n- Tay cầm kìm, tua vít thường bọc nhựa vì nhựa cách điện, cách nhiệt, cầm an toàn.\n- Nhựa nhẹ, không thấm nước nên dùng làm chai lọ, hộp đựng, áo mưa.\n- Mỗi vật liệu có tính chất riêng, cần chọn vật liệu phù hợp với mục đích sử dụng.\n- Tính chất vật liệu quyết định công dụng của đồ vật.',1,'published',7,1,'2026-10-07 21:38:26','2026-10-07 21:38:26'),
(61,41,'Lập thời gian biểu','tnhn-lap-thoi-gian-bieu','Biết lập thời gian biểu cá nhân và ưu tiên việc quan trọng.','de',10,'Thời gian là tài sản quý giá. Hãy học cách sắp xếp một ngày của mình thật khoa học nhé.','- Thời gian biểu giúp phân bổ hợp lý giữa học tập, nghỉ ngơi và vui chơi.\n- Ưu tiên làm việc vừa quan trọng vừa gấp trước, ví dụ bài kiểm tra ngày mai.\n- Gợi ý phân bổ: sáng học tập trung, chiều vận động thể thao, tối ôn bài và chuẩn bị cho ngày mai.\n- Lập thời gian biểu và tuân thủ mỗi ngày giúp hình thành thói quen tốt.\n- Tránh lướt điện thoại khi học và thói quen nước đến chân mới nhảy.',1,'published',6,1,'2026-10-07 21:38:26','2026-10-07 21:38:26'),
(62,42,'Búa, kìm, tua vít và cưa','cn-bua-kim-tua-vit-cua','Nêu được công dụng của búa, kìm, tua vít, cưa và quy tắc dùng an toàn.','trung_binh',10,'Búa để đóng, kìm để kẹp cắt, tua vít để vặn ốc, cưa để cắt gỗ. Dụng cụ sắc nhọn phải có người lớn hướng dẫn khi dùng.','- Búa dùng để đóng đinh, gõ; kìm để kẹp, cắt; tua vít để vặn ốc; cưa để cắt gỗ.\n- Tua vít có đầu vừa với rãnh ốc nên dùng để vặn chặt hoặc tháo ốc vít.\n- Dụng cụ sắc nhọn như cưa dễ gây đứt tay, phải có người lớn hướng dẫn khi dùng.\n- Dùng dụng cụ phải cầm chắc, giữ tay xa lưỡi sắc để an toàn.\n- Chọn đúng dụng cụ giúp công việc nhanh và an toàn hơn.',1,'published',7,1,'2026-10-07 21:38:26','2026-10-07 21:38:26'),
(63,43,'Giao tiếp và làm việc nhóm','tnhn-giao-tiep-lam-viec-nhom','Biết lắng nghe, tôn trọng ý kiến bạn và phân công nhiệm vụ khi làm việc nhóm.','de',10,'Làm việc nhóm tốt giúp mọi việc nhanh hơn và vui hơn. Cùng học cách hợp tác nhé.','- Khi bạn trình bày ý kiến: lắng nghe chăm chú và không ngắt lời.\n- Lắng nghe hết ý và cảm ơn là giao tiếp tốt; ngắt lời, chê bai là thiếu tôn trọng.\n- Làm việc nhóm: phân công theo khả năng để mỗi bạn phát huy điểm mạnh.\n- Hoàn thành đúng phần việc của mình và sẵn sàng hỗ trợ bạn khi cần.\n- Nói năng lịch sự, tôn trọng ý kiến khác biệt của các thành viên trong nhóm.',1,'published',6,1,'2026-10-07 21:38:26','2026-10-07 21:38:26'),
(64,44,'Các bước trồng cây','cn-cac-buoc-trong-cay','Nêu được trình tự các bước trồng cây: làm đất, gieo trồng, tưới nước, chăm sóc.','de',10,'Trồng cây theo trình tự: làm đất tơi xốp → gieo hạt hoặc trồng cây con → tưới nước nhẹ → chăm sóc thường xuyên.','- Bước đầu tiên khi trồng cây là chuẩn bị đất: xới tơi xốp để rễ dễ phát triển và thoát nước tốt.\n- Đất tơi xốp giúp rễ đâm sâu, hút nước và chất dinh dưỡng dễ dàng.\n- Sau khi gieo hạt cần tưới nhẹ ngay để hạt có độ ẩm nảy mầm, không làm trôi hạt.\n- Trồng cây theo đúng trình tự: chuẩn bị đất, gieo trồng rồi chăm sóc.\n- Làm đúng kỹ thuật từng bước giúp cây sinh trưởng tốt.',1,'published',8,1,'2026-10-07 21:38:26','2026-10-07 21:38:26'),
(65,45,'An toàn giao thông','tnhn-an-toan-giao-thong','Biết đội mũ bảo hiểm, qua đường đúng cách và đi đúng phần đường quy định.','de',10,'Mỗi ngày em đều tham gia giao thông. Hãy ghi nhớ những quy tắc giữ an toàn cho bản thân nhé.','- Ngồi trên xe máy, xe đạp điện phải đội mũ bảo hiểm đạt chuẩn và cài quai chắc chắn.\n- Biển tròn viền đỏ là biển cấm, tam giác viền đỏ là biển cảnh báo, tròn nền xanh là biển hiệu lệnh.\n- Qua đường nơi không có đèn tín hiệu: quan sát kỹ hai hướng, đợi xe dừng hẳn mới qua.\n- Đi đúng phần đường quy định, không lạng lách, không vượt đèn đỏ.\n- Mũ bảo hiểm bảo vệ đầu khi có va chạm — thói quen đơn giản cứu sống.',1,'published',7,1,'2026-10-07 21:38:26','2026-10-07 21:38:26'),
(66,46,'Tưới nước và bón phân','cn-tuoi-nuoc-bon-phan','Biết thời điểm tưới nước phù hợp và nguyên tắc bón phân đúng liều lượng.','trung_binh',10,'Tưới nước vào sáng sớm hoặc chiều mát. Bón phân đúng loại, đúng liều; bón quá nhiều phân hoá học sẽ làm cây bị cháy rễ.','- Nên tưới nước cho cây vào sáng sớm hoặc chiều mát để cây hút nước tốt, tránh sốc nhiệt giữa trưa.\n- Bón quá nhiều phân hóa học làm cháy rễ, cây héo và chết; phải bón đúng liều lượng hướng dẫn.\n- Lá héo, rũ xuống là dấu hiệu cây thiếu nước, cần tưới ngay.\n- Phân hữu cơ có nguồn gốc tự nhiên như phân chuồng, phân xanh.\n- Chăm sóc đúng cách giúp cây khỏe, cho năng suất cao.',1,'published',8,1,'2026-10-07 21:38:26','2026-10-07 21:38:26'),
(67,47,'Phân loại rác, bảo vệ môi trường','tnhn-phan-loai-rac','Biết phân loại rác thải và các hành động đơn giản bảo vệ môi trường.','de',10,'Trái Đất là ngôi nhà chung. Những hành động nhỏ của em mỗi ngày sẽ giúp môi trường xanh hơn.','- Rác hữu cơ: vỏ rau, thức ăn thừa — có thể ủ làm phân bón cho cây.\n- Rác tái chế: chai nhựa, giấy báo — thu gom để tái chế thành sản phẩm mới.\n- Rác nguy hại: pin cũ, bóng đèn hỏng — phải thu gom riêng, không vứt bừa bãi.\n- Phân loại rác tại nguồn giúp xử lý rác hiệu quả, bảo vệ môi trường.\n- Mỗi hành động nhỏ như bỏ rác đúng nơi đều góp phần giữ môi trường xanh sạch.',1,'published',7,1,'2026-10-07 21:38:26','2026-10-07 21:38:26'),
(68,48,'Các nghề nghiệp quen thuộc','tnhn-cac-nghe-quen-thuoc','Kể được công việc chính và phẩm chất cần có của các nghề: bác sĩ, giáo viên, kỹ sư, nông dân.','trung_binh',12,'Xung quanh em có rất nhiều nghề nghiệp thú vị. Cùng tìm hiểu xem mỗi nghề làm gì và cần phẩm chất nào nhé.','- Bác sĩ: khám chữa bệnh, chăm sóc sức khỏe cộng đồng — làm việc chủ yếu tại bệnh viện.\n- Giáo viên: dạy học, giáo dục học sinh — cần yêu thương và kiên nhẫn.\n- Kỹ sư: thiết kế, xây dựng công trình và máy móc — thuộc nhóm sản xuất, xây dựng.\n- Nông dân: trồng trọt, chăn nuôi — cung cấp lương thực cho xã hội.\n- Mỗi nghề đều có giá trị và đóng góp riêng, đáng được tôn trọng như nhau.',1,'published',8,1,'2026-10-07 21:38:27','2026-10-07 21:38:27'),
(69,49,'Ước mơ nghề nghiệp của em','tnhn-uoc-mo-nghe-nghiep-cua-em','Biết chọn nghề phù hợp sở thích, năng lực và lập kế hoạch học tập để theo đuổi ước mơ.','trung_binh',12,'Mỗi người đều có ước mơ. Hãy tìm hiểu cách biến ước mơ nghề nghiệp thành hiện thực nhé.','- Chọn nghề dựa vào sở thích và năng lực của bản thân, không chạy theo phong trào.\n- Ước mơ cần hành động: muốn làm bác sĩ thì học giỏi Sinh, Hóa ngay từ bây giờ.\n- Học chăm và tìm hiểu nghề giúp đạt ước mơ; lười học và bỏ cuộc cản trở ước mơ.\n- Lập kế hoạch học tập cụ thể từng năm để tiến gần hơn đến ước mơ.\n- Trao đổi với thầy cô, cha mẹ để được định hướng nghề nghiệp phù hợp.',1,'published',8,1,'2026-10-07 21:38:27','2026-10-07 21:38:27'),
(70,50,'Các châu lục trên thế giới','dl-cac-chau-luc','Kể được tên 7 châu lục, biết châu Á có diện tích và dân số lớn nhất.','de',10,'Trái Đất có 7 châu lục: Á, Âu, Phi, Bắc Mỹ, Nam Mỹ, Đại Dương, Nam Cực. Châu Á lớn nhất cả về diện tích và dân số.','- Châu Á là châu lục có diện tích lớn nhất thế giới, chiếm khoảng 1/3 diện tích đất liền.\n- Châu Á cũng đông dân nhất, chiếm hơn một nửa dân số thế giới.\n- Việt Nam nằm ở khu vực Đông Nam Á, thuộc châu Á.\n- Mỗi châu lục có đặc điểm nổi bật: châu Phi có Xa-ha-ra, Nam Cực lạnh nhất, Đại Dương nhỏ nhất.\n- Nhận biết vị trí và đặc điểm cơ bản của các châu lục trên bản đồ.',1,'published',6,1,'2026-10-07 21:38:31','2026-10-07 21:38:31'),
(71,50,'Các đại dương','dl-dai-duong','Kể được tên 4 đại dương, biết Thái Bình Dương lớn nhất, Bắc Băng Dương nhỏ nhất.','de',10,'Có 4 đại dương: Thái Bình Dương, Đại Tây Dương, Ấn Độ Dương, Bắc Băng Dương. Biển Đông thuộc Thái Bình Dương.','- Thái Bình Dương là đại dương lớn nhất, chiếm khoảng 1/3 diện tích bề mặt Trái Đất.\n- Bắc Băng Dương nằm quanh Bắc Cực, là đại dương nhỏ nhất và lạnh nhất.\n- Biển Đông là biển ven bờ ở phía tây của Thái Bình Dương.\n- Mỗi đại dương có diện tích và đặc điểm khí hậu khác nhau.\n- Xác định được vị trí các đại dương trên bản đồ thế giới.',2,'published',6,1,'2026-10-07 21:38:31','2026-10-07 21:38:31'),
(72,51,'Vị trí địa lí Việt Nam','dl-vi-tri-viet-nam','Xác định được vị trí, hình dạng, thủ đô và các vùng giáp ranh của Việt Nam.','trung_binh',12,'Việt Nam hình chữ S, thủ đô Hà Nội, phía bắc giáp Trung Quốc, phía tây giáp Lào và Campuchia, phía đông và nam giáp Biển Đông.','- Hà Nội là thủ đô của nước Cộng hòa xã hội chủ nghĩa Việt Nam.\n- Lãnh thổ Việt Nam có hình chữ S kéo dài từ bắc xuống nam.\n- Phía bắc giáp Trung Quốc, phía tây giáp Lào và Campuchia, phía đông và phía nam giáp Biển Đông.\n- Việt Nam giáp biển ở phía đông và phía nam với vùng biển rộng lớn.\n- Nắm vị trí địa lí là cơ sở để hiểu đặc điểm tự nhiên, kinh tế đất nước.',1,'published',6,1,'2026-10-07 21:38:31','2026-10-07 21:38:31'),
(73,52,'Thủ đô các nước châu Á','dl-thu-do-chau-a','Nhớ được thủ đô của các nước châu Á tiêu biểu: Nhật Bản, Trung Quốc, Hàn Quốc, Thái Lan...','trung_binh',12,'Học theo nhóm: Đông Nam Á (Bangkok, Viêng Chăn, Phnom Penh, Jakarta...), Đông Á (Tokyo, Bắc Kinh, Seoul).','- Tokyo là thủ đô của Nhật Bản; Bắc Kinh là thủ đô của Trung Quốc.\n- Seoul là thủ đô của Hàn Quốc.\n- Thủ đô các nước Đông Nam Á: Hà Nội (Việt Nam), Bangkok (Thái Lan), Viêng Chăn (Lào), Phnom Penh (Campuchia).\n- Thủ đô là trung tâm chính trị, hành chính của một quốc gia.\n- Ghi nhớ thủ đô giúp hiểu biết thêm về các nước láng giềng.',1,'published',7,1,'2026-10-07 21:38:31','2026-10-07 21:38:31'),
(74,52,'Thủ đô các nước trên thế giới','dl-thu-do-the-gioi','Nhớ được thủ đô của các nước tiêu biểu ở châu Âu, châu Mỹ, châu Phi, châu Đại Dương.','trung_binh',12,'Chú ý các cặp dễ nhầm: thủ đô của Úc là Canberra (không phải Sydney), của Mỹ là Washington D.C. (không phải New York).','- Paris là thủ đô của Pháp, nổi tiếng với tháp Eiffel.\n- Washington D.C. là thủ đô của Mỹ; New York chỉ là thành phố lớn nhất.\n- London là thủ đô của Anh.\n- Thủ đô các nước châu Âu: Paris (Pháp), Berlin (Đức), Rome (Ý), Mát-xcơ-va (Nga).\n- Phân biệt thủ đô với thành phố lớn nhất của một nước.',2,'published',7,1,'2026-10-07 21:38:31','2026-10-07 21:38:31'),
(75,53,'Địa hình và sông ngòi Việt Nam','dl-dia-hinh-song-ngoi','Biết dãy Hoàng Liên Sơn, đỉnh Fansipan, các đồng bằng và sông lớn của Việt Nam.','trung_binh',12,'Địa hình Việt Nam 3/4 là đồi núi. Fansipan (3 143 m) là nóc nhà Đông Dương. Hai đồng bằng lớn: sông Hồng và sông Cửu Long.','- Dãy Hoàng Liên Sơn ở Tây Bắc có đỉnh Fansipan cao 3.143m, được gọi là nóc nhà Đông Dương.\n- Đồng bằng sông Cửu Long là đồng bằng châu thổ lớn nhất nước ta.\n- Sông Hồng bồi đắp đồng bằng Bắc Bộ; sông Mê Công bồi đắp đồng bằng Nam Bộ.\n- Địa hình Việt Nam đa dạng: vùng núi, trung du, đồng bằng và ven biển.\n- Sông ngòi và địa hình gắn bó chặt chẽ, tạo nên đồng bằng màu mỡ.',1,'published',8,1,'2026-10-07 21:38:31','2026-10-07 21:38:31'),
(76,53,'Khí hậu Việt Nam','dl-khi-hau','Nêu được đặc điểm khí hậu nhiệt đới gió mùa và sự phân hoá theo miền.','trung_binh',12,'Việt Nam có khí hậu nhiệt đới gió mùa: nóng ẩm, mưa nhiều. Miền Bắc có mùa đông lạnh, miền Nam hai mùa mưa – khô.','- Việt Nam có khí hậu nhiệt đới gió mùa: nóng ẩm, mưa nhiều.\n- Miền Nam có hai mùa rõ rệt: mùa mưa và mùa khô.\n- Gió mùa đông bắc mang không khí lạnh khiến miền Bắc có mùa đông lạnh.\n- Khí hậu phân hóa theo miền: miền Bắc có đông lạnh, miền Trung mưa lệch mùa, miền Nam hai mùa.\n- Khí hậu ảnh hưởng lớn đến sản xuất nông nghiệp và đời sống.',2,'published',8,1,'2026-10-07 21:38:31','2026-10-07 21:38:31'),
(77,54,'Bảy nốt nhạc','an-bay-not-nhac','Đọc đúng tên và thứ tự bảy nốt nhạc: Đồ, Rê, Mi, Fa, Sol, La, Si.','de',10,'Học thuộc thứ tự 7 nốt nhạc: Đồ – Rê – Mi – Fa – Sol – La – Si. Đồ thấp nhất, Si cao nhất.','- Có 7 nốt nhạc cơ bản: Đồ, Rê, Mi, Fa, Sol, La, Si.\n- Thứ tự 7 nốt nhạc: Đồ – Rê – Mi – Fa – Sol – La – Si, sau nốt Si lại quay về nốt Đồ cao hơn.\n- Nốt Đồ là nốt đầu tiên, nốt Si là nốt cuối cùng trong thang nhạc cơ bản.\n- Nốt càng về sau trong thứ tự thì cao độ càng cao.\n- Học thuộc tên và thứ tự 7 nốt nhạc là nền tảng để đọc nhạc.',1,'published',6,1,'2026-10-07 21:38:41','2026-10-07 21:38:41'),
(78,55,'Cao độ và trường độ','an-cao-do-truong-do','Phân biệt cao độ với trường độ; nhận biết nốt tròn, trắng, đen, móc đơn.','trung_binh',12,'Cao độ: âm cao hay thấp (do vị trí nốt trên khuông nhạc). Trường độ: âm dài hay ngắn (do hình dạng nốt).','- Cao độ cho biết âm thanh cao hay thấp; nốt nằm càng cao trên khuông nhạc thì cao độ càng cao.\n- Trường độ cho biết âm thanh dài hay ngắn: nốt tròn ngân dài nhất, nốt móc đơn ngân ngắn.\n- Bốn hình nốt cơ bản: tròn, trắng, đen, móc đơn — mỗi nốt sau ngắn bằng một nửa nốt trước.\n- Đọc nhạc cần kết hợp cả cao độ (nốt nào) và trường độ (ngân bao lâu).\n- Luyện nghe phân biệt cao – thấp, dài – ngắn giúp cảm thụ âm nhạc tốt hơn.',1,'published',6,1,'2026-10-07 21:38:41','2026-10-07 21:38:41'),
(79,56,'Nhịp 2/4 và nhịp 3/4','an-nhip-2-4-3-4','Hiểu ý nghĩa của số chỉ nhịp; phân biệt nhịp 2/4 và nhịp 3/4.','trung_binh',12,'Số trên chỉ số phách trong một ô nhịp, số dưới chỉ nốt làm đơn vị phách. Nhịp 2/4 có 2 phách, nhịp 3/4 có 3 phách; phách đầu luôn mạnh.','- Số chỉ nhịp gồm hai số: số trên chỉ số phách trong một ô nhịp, số dưới chỉ nốt đen là đơn vị phách.\n- Nhịp 2/4: mỗi ô nhịp có 2 phách — khỏe khoắn, hợp với hành khúc.\n- Nhịp 3/4: mỗi ô nhịp có 3 phách — uyển chuyển, hợp với điệu valse nhẹ nhàng.\n- Ô nhịp là đoạn nhạc nằm giữa hai vạch nhịp.\n- Nhận biết số chỉ nhịp giúp đánh đúng nhịp khi hát và chơi nhạc.',1,'published',7,1,'2026-10-07 21:38:41','2026-10-07 21:38:41'),
(80,57,'Các loại dấu lặng','an-cac-dau-lang','Nêu được công dụng của dấu lặng và phân biệt lặng tròn, lặng trắng, lặng đen.','trung_binh',10,'Dấu lặng chỉ chỗ nghỉ, không phát ra âm thanh. Mỗi loại nốt đều có dấu lặng tương ứng với độ dài nghỉ bằng nhau.','- Dấu lặng chỉ khoảng nghỉ — nơi người hát, người chơi nhạc tạm ngưng phát ra âm thanh.\n- Mỗi loại nốt đều có dấu lặng tương ứng: lặng tròn, lặng trắng, lặng đen.\n- Lặng tròn nghỉ bằng một nốt tròn, lặng đen nghỉ bằng một nốt đen.\n- Dấu lặng càng lớn thì thời gian nghỉ càng dài.\n- Tôn trọng dấu lặng giúp bản nhạc có nhịp điệu đúng, không bị vội vàng.',1,'published',7,1,'2026-10-07 21:38:41','2026-10-07 21:38:41'),
(81,58,'Đàn bầu, đàn tranh, sáo, trống cơm','an-dan-bau-tranh-sao-trong','Nhận biết được đàn bầu, đàn tranh, sáo, trống cơm và cách chơi của chúng.','de',10,'Đàn bầu một dây, đàn tranh nhiều dây, sáo thổi bằng hơi, trống cơm vỗ bằng tay. Đây đều là nhạc cụ dân tộc Việt Nam.','- Đàn bầu chỉ có duy nhất 1 dây — nhạc cụ độc đáo nhất của Việt Nam; một tay gảy, một tay rung cần đàn.\n- Sáo thuộc bộ hơi (thổi); đàn tranh, đàn bầu thuộc bộ dây; trống cơm thuộc bộ gõ.\n- Nhạc cụ dân tộc chia thành các bộ: dây, hơi, gõ.\n- Mỗi nhạc cụ có cách chơi riêng tạo nên âm sắc đặc trưng.\n- Tìm hiểu nhạc cụ dân tộc giúp thêm yêu và tự hào về văn hóa Việt Nam.',1,'published',8,1,'2026-10-07 21:38:41','2026-10-07 21:38:41'),
(82,59,'Hát đúng giai điệu','an-hat-bai-thieu-nhi','Biết các yếu tố để hát đúng giai điệu: nghe mẫu, lấy hơi, giữ nhịp.','de',10,'Muốn hát hay: nghe kỹ giai điệu mẫu, lấy hơi đúng chỗ, giữ đúng nhịp và phát âm rõ lời.','- Muốn hát đúng giai điệu, việc đầu tiên là nghe kỹ giai điệu mẫu.\n- Lấy hơi ở chỗ dấu lặng hoặc cuối câu nhạc; ngắt hơi giữa chừng làm sai giai điệu.\n- Giữ đúng nhịp khi hát, không hát nhanh chậm tùy ý.\n- Hát đúng cao độ từng nốt, chú ý những chỗ lên cao, xuống thấp.\n- Luyện tập thường xuyên với bài hát vừa sức giúp hát ngày càng hay.',1,'published',8,1,'2026-10-07 21:38:42','2026-10-07 21:38:42'),
(83,60,'Quyền của trẻ em','gd-quyen-cua-tre-em','Kể được các quyền cơ bản của trẻ em và biết cách tự bảo vệ mình khi gặp nguy hiểm.','de',10,'Trẻ em có quyền được sống, được giáo dục, được chăm sóc sức khoẻ, được vui chơi và được bảo vệ. Khi gặp nguy hiểm, gọi tổng đài 111.','- Trẻ em có quyền được giáo dục, tức là được đi học.\n- Trẻ em có quyền được chăm sóc sức khỏe: khám chữa bệnh, tiêm phòng đầy đủ.\n- Khi bị xâm hại hoặc gặp nguy hiểm, báo ngay cho người lớn tin cậy hoặc gọi tổng đài 111.\n- Các quyền cơ bản của trẻ em: được sống, được giáo dục, được vui chơi giải trí.\n- Biết quyền của mình để tự bảo vệ bản thân tốt hơn.',1,'published',6,1,'2026-10-07 21:38:46','2026-10-07 21:38:46'),
(84,60,'Bổn phận của trẻ em','gd-bon-phan-cua-tre-em','Nêu được bổn phận của trẻ em với gia đình, nhà trường và xã hội.','de',10,'Đi đôi với quyền là bổn phận: hiếu thảo với ông bà cha mẹ, lễ phép với thầy cô, chăm chỉ học tập, tôn trọng pháp luật.','- Trẻ em có bổn phận kính trọng, hiếu thảo với ông bà, cha mẹ.\n- Học sinh phải lễ phép, tôn trọng và vâng lời thầy cô giáo.\n- Trẻ em cần yêu quê hương đất nước, chăm học để sau này xây dựng đất nước.\n- Đối với bạn bè, trẻ em cần đoàn kết, giúp đỡ lẫn nhau.\n- Quyền đi đôi với bổn phận: hưởng quyền phải làm tròn bổn phận.',2,'published',6,1,'2026-10-07 21:38:46','2026-10-07 21:38:46'),
(85,61,'Tôn trọng kỷ luật','gd-ton-trong-ky-luat','Hiểu kỷ luật là gì và thực hiện nếp sống kỷ luật ở trường, ở nhà và nơi công cộng.','de',10,'Kỷ luật là tự giác chấp hành quy định chung: đi học đúng giờ, xếp hàng, giữ trật tự, chấp hành luật giao thông.','- Đi học đúng giờ là biểu hiện cơ bản của tôn trọng kỷ luật.\n- Xếp hàng ngay ngắn, không chen lấn là giữ kỷ luật nơi công cộng.\n- Kỷ luật giúp tập thể hoạt động nền nếp, đạt hiệu quả cao.\n- Tôn trọng kỷ luật thể hiện ở việc chấp hành thời gian, nội quy trường lớp và nơi công cộng.\n- Người có kỷ luật được mọi người tin tưởng, quý mến.',1,'published',6,1,'2026-10-07 21:38:46','2026-10-07 21:38:46'),
(86,62,'Tiết kiệm','gd-tiet-kiem','Biết tiết kiệm điện, nước, tiền bạc, thời gian và tránh lãng phí.','de',10,'Tiết kiệm là dùng hợp lí, đúng mức, không lãng phí: tắt điện khi không dùng, khoá vòi nước, bỏ ống heo...','- Tắt thiết bị điện khi không dùng là cách tiết kiệm điện đơn giản.\n- Bỏ ống heo là cách tiết kiệm tiền đơn giản và hiệu quả.\n- Tài nguyên thiên nhiên có hạn nên phải sử dụng hợp lý, tránh lãng phí.\n- Tiết kiệm thể hiện trong việc dùng điện, nước và thời gian hằng ngày.\n- Tiết kiệm là đức tính tốt cần rèn luyện từ nhỏ.',1,'published',7,1,'2026-10-07 21:38:46','2026-10-07 21:38:46'),
(87,62,'Tình bạn đẹp','gd-tinh-ban','Hiểu thế nào là tình bạn đẹp và cách giữ gìn tình bạn.','de',10,'Tình bạn đẹp xây dựng trên sự chân thành, tôn trọng, giúp đỡ lẫn nhau; tránh nói xấu, ích kỷ, ghen tị.','- Tình bạn đẹp xây dựng trên sự chân thành và giúp đỡ lẫn nhau.\n- Khi bạn mắc lỗi, góp ý chân thành để bạn sửa lỗi, không chê cười hay bỏ mặc.\n- Nói xấu sau lưng làm mất lòng tin, phá hoại tình bạn.\n- Chân thành, giúp đỡ, bao dung là nền tảng của tình bạn đẹp.\n- Giữ gìn tình bạn đẹp làm cuộc sống học trò thêm ý nghĩa.',2,'published',7,1,'2026-10-07 21:38:46','2026-10-07 21:38:46'),
(88,63,'An toàn trên mạng','gd-an-toan-mang','Biết bảo vệ thông tin cá nhân và ứng xử an toàn khi dùng mạng.','trung_binh',12,'Không chia sẻ địa chỉ, số điện thoại công khai; giữ bí mật mật khẩu; không gặp người lạ quen qua mạng; báo người lớn khi bị bắt nạt mạng.','- Địa chỉ nhà, số điện thoại là thông tin cá nhân, không chia sẻ công khai trên mạng.\n- Tuyệt đối không gặp riêng người lạ quen qua mạng; báo ngay cho cha mẹ.\n- Bị bắt nạt trên mạng: lưu bằng chứng, chặn kẻ bắt nạt và báo cha mẹ, thầy cô.\n- Mật khẩu giữ kín; cảnh giác với người lạ xin thông tin, ảnh riêng tư.\n- An toàn trên mạng bắt đầu từ việc bảo vệ thông tin cá nhân.',1,'published',8,1,'2026-10-07 21:38:46','2026-10-07 21:38:46'),
(89,63,'Bảo vệ môi trường','gd-bao-ve-moi-truong','Nêu được các hành động bảo vệ môi trường và phân loại rác đơn giản.','de',10,'Bảo vệ môi trường từ việc nhỏ: bỏ rác đúng nơi, trồng cây xanh, tiết kiệm nước, hạn chế đồ nhựa dùng một lần.','- Bỏ rác đúng nơi quy định giữ đường phố, trường học sạch đẹp.\n- Dùng bình nước cá nhân, làn đi chợ giúp giảm rác thải nhựa.\n- Cây xanh làm sạch không khí, cho bóng mát và chống xói mòn đất.\n- Những việc nhỏ mỗi ngày của mỗi người góp phần bảo vệ môi trường lớn.\n- Bảo vệ môi trường là bảo vệ cuộc sống của chính chúng ta.',2,'published',8,1,'2026-10-07 21:38:46','2026-10-07 21:38:46'),
(91,1,'Số tự nhiên lớp 6: phép cộng và phép trừ (1)','toan-so-tu-nhien-lop-6-1','Thực hiện thành thạo phép cộng, trừ số tự nhiên; vận dụng tính chất giao hoán, kết hợp để tính nhanh.','de',10,'Cộng, trừ theo hàng từ phải sang trái. Tính chất giao hoán: a + b = b + a. Tính chất kết hợp: (a + b) + c = a + (b + c). Nhóm các số tròn chục, tròn trăm để tính nhanh.','- Đặt tính theo hàng: cộng hoặc trừ từ hàng đơn vị sang trái.\n- Cộng có nhớ: nhớ 1 sang hàng cao hơn khi tổng từ 10 trở lên.\n- Trừ có nhớ: mượn 1 ở hàng cao hơn khi không trừ được.\n- Tính nhanh: nhóm các số thành tròn chục, tròn trăm (23 + 77 = 100).\n- Số liền sau của n là n + 1: 9 999 + 1 = 10 000.',3,'published',6,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(92,1,'Số tự nhiên lớp 6: phép nhân, phép chia và thứ tự thực hiện (2)','toan-so-tu-nhien-lop-6-2','Thực hiện phép nhân, phép chia hết và chia có dư; nắm thứ tự ưu tiên: ngoặc → nhân, chia → cộng, trừ.','de',10,'Trong phép chia có dư: số bị chia = thương × số chia + số dư (số dư nhỏ hơn số chia). Thứ tự thực hiện: tính trong ngoặc trước, rồi đến nhân – chia, cuối cùng là cộng – trừ.','- Thứ tự thực hiện: trong ngoặc trước, nhân/chia trước, cộng/trừ sau.\n- Ghi nhớ các tích đặc biệt: 25 x 4 = 100 để tính nhanh.\n- Phép chia có dư: số bị chia = thương x số chia + số dư.\n- Tính giá trị biểu thức theo đúng thứ tự các phép tính.\n- Kiểm tra lại bằng cách tính ngược hoặc ước lượng.',4,'published',6,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(93,1,'Số tự nhiên lớp 7: lũy thừa với số mũ tự nhiên (1)','toan-so-tu-nhien-lop-7-1','Hiểu định nghĩa lũy thừa a^n; nhân, chia hai lũy thừa cùng cơ số.','de',12,'Lũy thừa bậc n của a là tích của n thừa số a: a^n = a × a × ... × a (n lần). Nhân hai lũy thừa cùng cơ số: a^m × a^n = a^(m+n). Chia hai lũy thừa cùng cơ số: a^m : a^n = a^(m−n) (với m ≥ n, a ≠ 0).','- Luỹ thừa aⁿ là tích của n thừa số a: 2³ = 2 x 2 x 2 = 8.\n- Nhân hai luỹ thừa cùng cơ số: cộng số mũ (2³ x 2² = 2⁵).\n- Chia hai luỹ thừa cùng cơ số: trừ số mũ (a⁵ : a² = a³ với a khác 0).\n- 10ⁿ là số 1 tiếp theo là n chữ số 0: 10³ = 1 000.\n- Phân biệt aⁿ với a x n: 2³ = 8 khác 2 x 3 = 6.',5,'published',7,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(94,1,'Số tự nhiên lớp 7: biểu thức phức tạp và tính nhanh (2)','toan-so-tu-nhien-lop-7-2','Tính giá trị biểu thức có lũy thừa và ngoặc; vận dụng tính chất phân phối để tính nhanh.','trung_binh',12,'Thứ tự ưu tiên đầy đủ: ngoặc → lũy thừa → nhân, chia → cộng, trừ. Tính chất phân phối: a × (b + c) = a × b + a × c. Dùng tính chất này để tính nhanh các tích gần số tròn như 99, 101.','- Tính luỹ thừa trước, rồi nhân/chia, cuối cùng cộng/trừ.\n- Dùng tính chất phân phối và nhóm số để tính nhanh.\n- Ví dụ: 12 x 25 = 3 x 4 x 25 = 3 x 100 = 300.\n- Luỹ thừa của một tích: (a x b)ⁿ = aⁿ x bⁿ.\n- Tính theo đúng thứ tự để tránh sai kết quả.',6,'published',7,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(95,2,'Phân số lớp 6: cộng, trừ phân số đơn giản (1)','toan-phan-so-lop-6-1','Cộng, trừ hai phân số cùng mẫu số; rút gọn kết quả về phân số tối giản.','de',10,'Muốn cộng (hoặc trừ) hai phân số cùng mẫu số, ta cộng (hoặc trừ) hai tử số và giữ nguyên mẫu số. Sau khi tính, nhớ rút gọn kết quả nếu chưa tối giản.','- Cùng mẫu số: cộng hoặc trừ hai tử số, giữ nguyên mẫu số.\n- Rút gọn kết quả: chia cả tử và mẫu cho ước chung lớn nhất.\n- Hai phân số bằng nhau khi nhân hoặc chia cả tử và mẫu cho cùng một số.\n- Ví dụ: 1/2 = 2/4 khi nhân cả tử và mẫu với 2.\n- Viết kết quả dưới dạng phân số tối giản.',3,'published',6,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(96,2,'Phân số lớp 6: rút gọn, quy đồng và so sánh (2)','toan-phan-so-lop-6-2','Rút gọn phân số; quy đồng mẫu số; so sánh hai phân số.','de',10,'Rút gọn: chia cả tử và mẫu cho ước chung lớn nhất. Quy đồng: tìm mẫu số chung (thường là bội chung nhỏ nhất), nhân cả tử và mẫu với thừa số phụ. So sánh: phân số nào có tử lớn hơn (khi cùng mẫu dương) thì lớn hơn.','- Rút gọn: chia cả tử và mẫu cho ước chung, ví dụ 8/12 = 2/3.\n- Quy đồng: mẫu số chung nhỏ nhất là bội chung nhỏ nhất của các mẫu số.\n- So sánh phân số cùng mẫu dương: tử lớn hơn thì phân số lớn hơn.\n- So sánh phân số khác mẫu: quy đồng rồi so sánh tử số.\n- Phân số tối giản là phân số không rút gọn được nữa.',4,'published',6,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(97,2,'Phân số lớp 7: nhân, chia phân số và hỗn số (1)','toan-phan-so-lop-7-1','Nhân, chia hai phân số; đổi hỗn số thành phân số và ngược lại.','trung_binh',12,'Nhân hai phân số: nhân tử với tử, mẫu với mẫu. Chia: nhân phân số bị chia với phân số nghịch đảo của số chia. Hỗn số a b/c = (a × c + b)/c.','- Nhân phân số: nhân tử với tử, mẫu với mẫu rồi rút gọn.\n- Chia phân số: nhân với phân số nghịch đảo của số chia.\n- Hỗn số đổi ra phân số: tử = phần nguyên x mẫu + tử (1 1/2 = 3/2).\n- Mọi số nhân với 0 đều bằng 0.\n- Rút gọn kết quả về phân số tối giản.',5,'published',7,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(98,2,'Phân số lớp 7: biểu thức phân số và bài toán ứng dụng (2)','toan-phan-so-lop-7-2','Tính giá trị biểu thức có nhiều phép tính với phân số; giải bài toán thực tế đơn giản.','trung_binh',12,'Với biểu thức nhiều phép tính, tuân thủ thứ tự ưu tiên và dùng tính chất phân phối để tính nhanh, ví dụ (a + b) × c = a × c + b × c. Với bài toán thực tế, xác định \"cả\" tương ứng với 1 rồi tính từng phần.','- Quy đồng mẫu số chung trước khi cộng hoặc trừ nhiều phân số.\n- Dùng tính chất phân phối để tính nhanh: (2/3 + 1/4) x 12 = 8 + 3 = 11.\n- Bài toán phần - toàn thể: cả bể là 1, chia đều theo thời gian.\n- Tìm x: chuyển vế đổi dấu (x - 1/3 = 5/6 thì x = 5/6 + 1/3 = 7/6).\n- Kiểm tra kết quả bằng cách thay ngược vào đề.',6,'published',7,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(99,3,'Biểu thức đại số lớp 7: biểu thức chữ và giá trị biểu thức (1)','toan-bieu-thuc-dai-so-lop-7-1','Nhận biết biểu thức đại số; tính giá trị của biểu thức khi biết giá trị của biến.','de',12,'Biểu thức đại số là biểu thức gồm các số, chữ và phép tính. Muốn tính giá trị của biểu thức, ta thay giá trị của biến vào rồi thực hiện phép tính. Đơn thức gồm hệ số và phần biến, ví dụ trong 5x² thì 5 là hệ số, x² là phần biến.','- Biểu thức đại số chứa chữ đại diện cho số, ví dụ x + 5.\n- Diễn đạt bằng lời thành biểu thức: \"gấp đôi a rồi cộng 3\" là 2a + 3.\n- Tính giá trị: thay số vào chữ rồi thực hiện phép tính.\n- Ví dụ: x = 3 thì x + 7 = 10; x = 5 thì 2x = 10.\n- Viết đúng biểu thức theo diễn đạt của đề bài.',3,'published',7,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(100,3,'Biểu thức đại số lớp 7: đơn thức đồng dạng (2)','toan-bieu-thuc-dai-so-lop-7-2','Nhận biết hai đơn thức đồng dạng; cộng, trừ các đơn thức đồng dạng.','trung_binh',12,'Hai đơn thức đồng dạng là hai đơn thức có hệ số khác 0 và có cùng phần biến. Muốn cộng (trừ) các đơn thức đồng dạng, ta cộng (trừ) các hệ số và giữ nguyên phần biến.','- Hai đơn thức đồng dạng có cùng phần biến: 3x² và 5x².\n- Cộng hoặc trừ đơn thức đồng dạng: cộng hoặc trừ hệ số, giữ nguyên phần biến.\n- Ví dụ: 3x + 5x = 8x; 7xy - 2xy = 5xy.\n- Thu gọn: nhóm các đơn thức đồng dạng rồi cộng hệ số.\n- Không cộng được các đơn thức không đồng dạng.',4,'published',7,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(101,3,'Biểu thức đại số lớp 8: đa thức và thu gọn đa thức (1)','toan-bieu-thuc-dai-so-lop-8-1','Nhận biết đa thức, bậc của đa thức; thu gọn đa thức và tìm hệ số.','trung_binh',15,'Đa thức là tổng của những đơn thức. Bậc của đa thức là bậc của hạng tử có bậc cao nhất. Thu gọn đa thức: cộng, trừ các hạng tử đồng dạng. Hệ số cao nhất là hệ số của hạng tử bậc cao nhất; hệ số tự do là hạng tử không chứa biến.','- Đa thức là tổng của các đơn thức (hạng tử).\n- Bậc của đa thức là bậc cao nhất của các hạng tử.\n- Thu gọn đa thức: cộng hoặc trừ các hạng tử đồng dạng.\n- Hệ số cao nhất là hệ số của hạng tử bậc cao nhất.\n- Đa thức một biến chỉ chứa một biến x.',5,'published',8,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(102,3,'Biểu thức đại số lớp 8: nhân đơn thức, đa thức (2)','toan-bieu-thuc-dai-so-lop-8-2','Nhân hai đơn thức; nhân đơn thức với đa thức; nhận biết hằng đẳng thức cơ bản.','trung_binh',15,'Nhân hai đơn thức: nhân hệ số với hệ số, nhân phần biến với phần biến. Nhân đơn thức với đa thức: nhân đơn thức với từng hạng tử rồi cộng lại. Hằng đẳng thức đáng nhớ: (a + b)² = a² + 2ab + b²; (a − b)(a + b) = a² − b².','- Nhân đơn thức với đơn thức: nhân hệ số, cộng số mũ của cùng biến.\n- Nhân đơn thức với đa thức: nhân với từng hạng tử, ví dụ x(x + 2) = x² + 2x.\n- Nhân hai đa thức: nhân mỗi hạng tử của ngoặc này với từng hạng tử của ngoặc kia.\n- Chú ý dấu khi nhân với số âm: 3x x (-2y) = -6xy.\n- Thu gọn kết quả sau khi khai triển.',6,'published',8,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(103,4,'Hình học phẳng lớp 7: góc và cách đo góc (1)','toan-hinh-hoc-phang-lop-7-1','Nhận biết các loại góc: nhọn, vuông, tù, bẹt; đo góc bằng thước đo độ.','de',12,'Góc nhọn nhỏ hơn 90°, góc vuông bằng 90°, góc tù lớn hơn 90° và nhỏ hơn 180°, góc bẹt bằng 180°. Dùng thước đo độ đặt tâm trùng đỉnh, một cạnh trùng vạch 0° để đọc số đo.','- Góc vuông bằng 90 độ; góc nhọn nhỏ hơn 90 độ; góc bẹt bằng 180 độ.\n- Hai đường thẳng vuông góc tạo thành góc 90 độ.\n- Góc bẹt có hai cạnh là hai tia đối nhau.\n- Nhận diện loại góc theo số đo cho trước.\n- Dùng thước đo góc đúng cách để đo và vẽ góc.',3,'published',7,1,'2026-10-07 21:57:56','2026-10-07 21:57:56'),
(104,4,'Hình học phẳng lớp 7: góc kề bù và góc đối đỉnh (2)','toan-hinh-hoc-phang-lop-7-2','Nhận biết hai góc kề bù, hai góc đối đỉnh; tính số đo góc; hiểu tia phân giác.','trung_binh',12,'Hai góc kề bù là hai góc kề nhau có tổng số đo 180°. Hai góc đối đỉnh thì bằng nhau. Tia phân giác của một góc là tia nằm trong góc và chia góc thành hai góc bằng nhau.','- Hai góc kề bù có tổng số đo bằng 180 độ.\n- Hai góc đối đỉnh thì bằng nhau.\n- Tìm góc kề bù: lấy 180 độ trừ góc đã biết.\n- Tia phân giác chia góc thành hai góc bằng nhau: 80 độ thành 40 độ + 40 độ.\n- Vẽ hình minh hoạ để xác định đúng cặp góc.',4,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(105,4,'Hình học phẳng lớp 8: tổng ba góc tam giác, tam giác cân (1)','toan-hinh-hoc-phang-lop-8-1','Vận dụng tổng ba góc trong tam giác bằng 180°; nhận biết và vận dụng tính chất tam giác cân, tam giác đều.','trung_binh',15,'Tổng ba góc trong của một tam giác bằng 180°. Tam giác cân có hai cạnh bên bằng nhau và hai góc ở đáy bằng nhau. Tam giác đều có ba cạnh bằng nhau và ba góc đều bằng 60°.','- Tổng ba góc trong của một tam giác bằng 180 độ.\n- Tam giác cân có hai cạnh bên bằng nhau và hai góc ở đáy bằng nhau.\n- Tam giác đều có ba góc bằng nhau, mỗi góc 60 độ.\n- Tìm góc chưa biết: lấy 180 độ trừ hai góc đã biết.\n- Nhận diện tam giác cân, tam giác đều theo cạnh và góc.',5,'published',8,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(106,4,'Hình học phẳng lớp 8: tam giác đồng dạng cơ bản (2)','toan-hinh-hoc-phang-lop-8-2','Nhận biết hai tam giác đồng dạng; vận dụng tỉ số đồng dạng tính độ dài cạnh.','trung_binh',15,'Hai tam giác đồng dạng (kí hiệu ~) có các góc tương ứng bằng nhau và các cạnh tương ứng tỉ lệ. Tỉ số đồng dạng k cho biết cạnh của tam giác này gấp k lần cạnh tương ứng của tam giác kia; tỉ số chu vi cũng bằng k. Các trường hợp đồng dạng: cạnh – cạnh – cạnh, góc – góc, cạnh – góc – cạnh.','- Hai tam giác đồng dạng có các góc tương ứng bằng nhau.\n- Các cạnh tương ứng tỉ lệ với nhau theo tỉ số đồng dạng k.\n- Tỉ số chu vi của hai tam giác đồng dạng bằng tỉ số đồng dạng k.\n- Trường hợp cạnh - cạnh - cạnh: ba cạnh tương ứng tỉ lệ thì hai tam giác đồng dạng.\n- Dùng tỉ số k để tính độ dài cạnh tương ứng.',6,'published',8,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(107,5,'Từ và câu lớp 6: từ đơn, từ ghép, từ láy (1)','tv-tu-va-cau-lop-6-1','Phân biệt từ đơn, từ phức; nhận biết từ ghép và từ láy.','de',10,'Từ đơn chỉ gồm một tiếng. Từ phức gồm hai tiếng trở lên, chia thành từ ghép (các tiếng đều có nghĩa, ví dụ bàn ghế) và từ láy (láy lại âm hoặc vần, ví dụ xinh xắn, rì rào).','- Từ đơn gồm một tiếng: sách.\n- Từ ghép gồm hai tiếng đều có nghĩa: bàn ghế, học sinh.\n- Từ láy lặp lại âm đầu hoặc vần: xinh xắn láy âm đầu x.\n- Đếm số tiếng để phân biệt từ đơn với từ nhiều tiếng.\n- Xếp đúng từ vào nhóm từ đơn, từ ghép, từ láy.',3,'published',6,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(108,5,'Từ và câu lớp 6: danh từ, động từ, tính từ (2)','tv-tu-va-cau-lop-6-2','Nhận biết danh từ, động từ, tính từ trong câu.','de',10,'Danh từ chỉ người, vật, hiện tượng (danh từ riêng chỉ tên riêng phải viết hoa). Động từ chỉ hoạt động, trạng thái. Tính từ chỉ đặc điểm, tính chất.','- Danh từ chỉ người, vật: bàn là danh từ.\n- Động từ chỉ hành động: nhảy, hót là động từ.\n- Tính từ chỉ đặc điểm, màu sắc: đỏ là tính từ.\n- Xác định động từ trong câu theo hành động của chủ ngữ.\n- Xếp đúng từ vào nhóm từ loại phù hợp.',4,'published',6,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(109,5,'Từ và câu lớp 7: cụm danh từ, cụm động từ, cụm tính từ (1)','tv-tu-va-cau-lop-7-1','Nhận biết cụm từ; xác định từ trung tâm và phần phụ trong cụm danh từ, động từ, tính từ.','trung_binh',12,'Cụm từ gồm từ trung tâm và phần phụ (phụ trước, phụ sau). Cụm danh từ có từ trung tâm là danh từ (ví dụ những bông hoa đẹp), cụm động từ có từ trung tâm là động từ (đang nở rộ), cụm tính từ có từ trung tâm là tính từ (rất thơm).','- Cụm danh từ có từ trung tâm là danh từ: phụ trước + trung tâm + phụ sau.\n- Ví dụ: những (phụ trước) + bông hoa (trung tâm) + đẹp (phụ sau).\n- Cụm động từ có từ trung tâm là động từ: đang chạy nhanh.\n- Cụm tính từ có từ trung tâm là tính từ: rất đẹp lắm.\n- Xác định từ trung tâm để gọi đúng tên cụm từ.',5,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(110,5,'Từ và câu lớp 7: câu đơn, chủ ngữ – vị ngữ (2)','tv-tu-va-cau-lop-7-2','Nhận biết câu đơn; xác định chủ ngữ và vị ngữ trong câu.','trung_binh',12,'Câu đơn có một cụm chủ ngữ – vị ngữ. Chủ ngữ trả lời câu hỏi Ai? Cái gì? Con gì? Vị ngữ trả lời câu hỏi Làm gì? Thế nào? Là gì?','- Câu đơn chỉ có một cụm chủ ngữ - vị ngữ tạo thành một nòng cốt câu.\n- Chủ ngữ trả lời \"Ai?\"; vị ngữ trả lời \"Làm gì? Thế nào?\".\n- Ví dụ: \"Mẹ em / đang nấu cơm\" — chủ ngữ \"Mẹ em\", vị ngữ \"đang nấu cơm\".\n- Câu có hai cụm C-V trở lên là câu ghép, không phải câu đơn.\n- Phân tích đúng chủ ngữ, vị ngữ và nhận diện câu đơn.',6,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(111,6,'Chính tả lớp 6: phân biệt ch/tr, s/x, r/d/gi (1)','tv-chinh-ta-lop-6-1','Viết đúng các từ có âm đầu ch/tr, s/x, r/d/gi dễ nhầm lẫn.','de',10,'Muốn viết đúng, hãy đọc kĩ và ghi nhớ mặt chữ của từng từ: chăm chỉ (ch), trong trẻo (tr), sáng sủa (s), xinh xắn (x), rực rỡ (r), dịu dàng (d). Khi nghi ngờ, tra từ điển hoặc hỏi thầy cô.','- \"chăm chỉ\" (siêng năng) viết với ch; \"trong trẻo\" viết với tr.\n- \"sáng sủa\" viết với s.\n- \"rực rỡ\" viết với r.\n- Ghi nhớ nghĩa và cách viết đúng của từng từ.\n- Chọn từ viết đúng chính tả trong các đáp án.',3,'published',6,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(112,6,'Chính tả lớp 6: dấu hỏi, dấu ngã (2)','tv-chinh-ta-lop-6-2','Viết đúng dấu hỏi và dấu ngã trong các từ thường nhầm.','de',10,'Ghi nhớ theo cặp dễ nhầm: củ (hỏi) – cũ (ngã), nghỉ (hỏi) – nghĩ (ngã), vẻ (hỏi) – vẽ (ngã). Đặt từ vào nghĩa của câu để chọn dấu đúng: \"nghỉ ngơi\" (dấu hỏi), \"suy nghĩ\" (dấu ngã).','- \"củ cải\" (loại rau) viết củ với dấu hỏi; \"nghỉ ngơi\" viết nghỉ với dấu hỏi.\n- \"vẻ đẹp\" viết vẻ với dấu hỏi.\n- \"suy nghĩ\" viết nghĩ với dấu ngã.\n- Ghi nhớ nghĩa của từ để viết đúng dấu thanh.\n- Chọn từ viết đúng chính tả trong các đáp án.',4,'published',6,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(113,6,'Chính tả lớp 7: viết hoa tên riêng, từ Hán Việt (1)','tv-chinh-ta-lop-7-1','Viết hoa đúng tên người, tên địa lí; viết đúng các từ Hán Việt thông dụng.','trung_binh',12,'Tên riêng (người, địa danh) viết hoa chữ cái đầu mỗi tiếng: Hà Nội, Nguyễn Du, Sông Hồng. Từ Hán Việt là từ gốc Hán đã Việt hoá, cần nhớ mặt chữ: tổ quốc, giang sơn, đồng bào.','- Tên riêng viết hoa chữ cái đầu mỗi tiếng: Hà Nội, Nguyễn Du.\n- Tên địa lí viết hoa chữ cái đầu mỗi tiếng: Sông Hồng.\n- Từ Hán Việt chỉ đất nước: Tổ quốc.\n- Phân biệt tên riêng với từ thường để viết hoa đúng.\n- Chọn cách viết đúng chính tả trong các đáp án.',5,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(114,6,'Chính tả lớp 7: từ dễ nhầm và dấu câu (2)','tv-chinh-ta-lop-7-2','Viết đúng các từ khó dễ nhầm; đặt dấu chấm, hỏi, chấm than, phẩy đúng chỗ.','trung_binh',12,'Một số từ khó cần học thuộc: xán lạn, trau chuốt, dè dặt. Về dấu câu: cuối câu kể đặt dấu chấm, cuối câu hỏi đặt dấu hỏi, cuối câu cảm thán đặt dấu chấm than, dấu phẩy ngăn cách các bộ phận trong câu.','- \"xán lạn\" (rực rỡ, tươi sáng) viết với x; \"trau chuốt\" viết trau với tr, chuốt với ch.\n- \"dè dặt\" (thận trọng) viết với dấu huyền.\n- Câu kể kết thúc bằng dấu chấm.\n- Ghi nhớ nghĩa của từ để viết đúng chính tả.\n- Đặt dấu câu đúng cuối mỗi kiểu câu.',6,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(115,7,'Văn miêu tả lớp 7: nhận biết và từ ngữ miêu tả (1)','tv-van-mieu-ta-lop-7-1','Nhận biết văn miêu tả; dùng từ ngữ gợi hình, gợi âm thanh và biện pháp tu từ đơn giản.','de',12,'Văn miêu tả giúp người đọc hình dung sự vật như đang tận mắt trông thấy. Dùng từ láy gợi hình (xanh biếc), gợi âm thanh (rì rào) và các biện pháp so sánh, nhân hoá để câu văn sinh động.','- Văn miêu tả giúp người đọc hình dung sự vật như tận mắt trông thấy.\n- Từ gợi tả âm thanh: rì rào (tiếng gió, tiếng lá cây).\n- Từ gợi tả màu sắc: xanh biếc (màu xanh đẹp mắt).\n- Nhận diện câu văn miêu tả theo hình ảnh được gợi tả.\n- Dùng từ ngữ gợi hình, gợi cảm để tả sinh động.',3,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(116,7,'Văn miêu tả lớp 7: tả người (2)','tv-van-mieu-ta-lop-7-2','Nắm bố cục bài văn tả người; tả ngoại hình và tính cách theo trình tự hợp lí.','trung_binh',12,'Bài văn tả người có 3 phần: mở bài giới thiệu người được tả, thân bài tả chi tiết (ngoại hình từ bao quát đến chi tiết, rồi tính cách, hoạt động), kết bài nêu cảm nghĩ.','- Bài văn tả người gồm 3 phần: mở bài, thân bài, kết bài.\n- Mở bài giới thiệu người được tả (là ai, quan hệ với mình).\n- Tả ngoại hình từ bao quát (dáng người, tuổi) đến chi tiết (khuôn mặt, mái tóc).\n- Kết bài nêu cảm nghĩ, tình cảm với người được tả.\n- Nhận diện câu tả ngoại hình trong đoạn văn.',4,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(117,7,'Văn miêu tả lớp 8: tả cảnh và biện pháp tu từ (1)','tv-van-mieu-ta-lop-8-1','Tả cảnh gắn với thời gian, không gian; vận dụng so sánh, nhân hoá.','trung_binh',15,'Tả cảnh cần quan sát tinh tế và gắn với thời gian, không gian cụ thể (buổi sáng, hoàng hôn...). Dùng so sánh (trăng như chiếc đĩa bạc) và nhân hoá (chị gió đùa vui) để cảnh vật có hồn.','- Tả cảnh cần quan sát tinh tế bằng nhiều giác quan.\n- Câu có từ \"như\" là so sánh: \"Sương giăng mờ như tấm voan mỏng\".\n- Gán hành động con người cho sự vật là nhân hoá: \"Hàng cây rì rào hát ca\".\n- Tả cảnh gắn với thời gian, không gian cụ thể: bình minh, hoàng hôn.\n- Dùng biện pháp tu từ để cảnh vật sinh động.',5,'published',8,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(118,7,'Văn miêu tả lớp 8: cảm thụ và viết đoạn văn (2)','tv-van-mieu-ta-lop-8-2','Cảm thụ cái hay của đoạn văn miêu tả; viết đoạn văn có hình ảnh và cảm xúc, tránh lỗi thường gặp.','trung_binh',15,'Đoạn văn miêu tả hay cần hình ảnh sinh động và cảm xúc chân thành. Khi viết: quan sát kĩ, sắp xếp ý hợp lí, dùng từ gợi hình gợi cảm, tránh lặp từ và liệt kê số liệu khô khan.','- Đoạn văn miêu tả hay cần hình ảnh sinh động và cảm xúc chân thành.\n- Tiếng ve râm ran là âm thanh đặc trưng gợi mùa hè.\n- Câu bộc lộ tình cảm là câu nêu cảm xúc của người viết.\n- Tránh lặp từ gây đơn điệu; thay bằng từ đồng nghĩa.\n- Cảm thụ đúng hình ảnh, cảm xúc trong đoạn văn miêu tả.',6,'published',8,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(119,8,'Từ vựng lớp 6: chủ đề gia đình – family (1)','en-tu-vung-lop-6-lop-6-1','Nhớ và dùng đúng các từ vựng cơ bản về gia đình.','de',10,'Học từ vựng theo nhóm: bố mẹ (father, mother), anh chị em (brother, sister), ông bà (grandfather, grandmother), chú bác cô dì (uncle, aunt). Đặt câu đơn giản với mỗi từ mới, ví dụ: She is my sister.','- \"father\" nghĩa là bố; \"mother\" nghĩa là mẹ.\n- \"sister\" nghĩa là chị gái hoặc em gái; \"brother\" nghĩa là anh trai hoặc em trai.\n- \"grandfather\" nghĩa là ông; \"grandmother\" nghĩa là bà.\n- Nhận nghĩa của từ trong câu, ví dụ \"My mother is a teacher.\".\n- Ôn tập và mở rộng vốn từ chủ đề gia đình.',3,'published',6,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(120,8,'Từ vựng lớp 6: chủ đề trường học – school (2)','en-tu-vung-lop-6-lop-6-2','Nhớ và dùng đúng các từ vựng cơ bản về trường học, đồ dùng học tập, môn học.','de',10,'Học từ vựng theo nhóm: con người (teacher, student), nơi chốn (classroom, library), đồ dùng (pen, book, ruler), môn học (math, English, music).','- \"teacher\" nghĩa là giáo viên; \"student\" nghĩa là học sinh.\n- \"book\" là quyển sách; \"notebook\" là vở; \"pen\" là bút mực; \"pencil\" là bút chì.\n- \"classroom\" là lớp học; \"school\" là trường học.\n- Nhận diện nghĩa của từ trong ngữ cảnh câu đơn giản.\n- Ôn tập và mở rộng vốn từ chủ đề trường học.',4,'published',6,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(121,8,'Từ vựng lớp 7: hoạt động hằng ngày – daily life (1)','en-tu-vung-lop-6-lop-7-1','Nhớ và dùng đúng các cụm từ chỉ hoạt động hằng ngày và thời gian.','de',12,'Học cụm động từ theo trình tự một ngày: get up (thức dậy), have breakfast (ăn sáng), go to school (đi học), do homework (làm bài tập), go to bed (đi ngủ). Chú ý các cụm thời gian: in the morning, in the afternoon, in the evening.','- \"get up\" nghĩa là thức dậy; \"have breakfast\" nghĩa là ăn sáng.\n- \"do homework\" nghĩa là làm bài tập về nhà; \"brush teeth\" nghĩa là đánh răng.\n- Các cụm động từ thường dùng để diễn tả sinh hoạt hằng ngày.\n- Nhận nghĩa của cụm từ trong câu.\n- Mở rộng vốn từ chủ đề hoạt động hằng ngày.',5,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(122,8,'Từ vựng lớp 7: thời tiết và thiên nhiên – weather (2)','en-tu-vung-lop-6-lop-7-2','Nhớ và dùng đúng từ vựng thời tiết, mùa và cảnh quan thiên nhiên.','trung_binh',12,'Phân biệt danh từ và tính từ thời tiết: rain (danh từ) – rainy (tính từ), sun – sunny, cloud – cloudy, wind – windy. Nhớ 4 mùa: spring, summer, autumn, winter và các cảnh quan: mountain, river, forest, beach.','- \"sunny\" là trời nắng; \"rainy\" là trời mưa; \"windy\" là nhiều gió.\n- \"rainbow\" nghĩa là cầu vồng.\n- Câu \"It\'s windy today.\" nghĩa là \"Hôm nay trời nhiều gió.\".\n- Tính từ thời tiết thường đứng sau \"is\" trong câu.\n- Mở rộng vốn từ chủ đề thời tiết và thiên nhiên.',6,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(123,9,'Ngữ pháp lớp 6: động từ to be (1)','en-ngu-phap-co-ban-lop-6-1','Dùng đúng am/is/are trong câu khẳng định, phủ định, nghi vấn.','de',10,'I đi với am, he/she/it (ngôi thứ ba số ít) đi với is, you/we/they đi với are. Câu phủ định thêm not sau to be (is not = is not, are not = are not). Câu hỏi đảo to be lên trước chủ ngữ: Are you ready?','- Chủ ngữ \"I\" luôn đi với \"am\".\n- Ngôi thứ ba số ít (he, she, it) đi với \"is\".\n- Chủ ngữ số nhiều (you, we, they) đi với \"are\".\n- Câu hỏi đảo \"to be\" lên trước chủ ngữ: \"Are you a teacher?\".\n- Chia đúng \"am/is/are\" theo chủ ngữ trong câu.',3,'published',6,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(124,9,'Ngữ pháp lớp 6: thì hiện tại đơn (2)','en-ngu-phap-co-ban-lop-6-2','Chia đúng động từ thì hiện tại đơn; dùng thì này diễn tả thói quen.','de',10,'Thì hiện tại đơn diễn tả thói quen, sự thật hiển nhiên. Với chủ ngữ ngôi thứ ba số ít (he, she, it), động từ thêm s/es: play → plays, go → goes, watch → watches, study → studies. Dấu hiệu: every day, usually, sometimes.','- Thì hiện tại đơn diễn tả thói quen và sự thật hiển nhiên.\n- Ngôi thứ ba số ít: động từ thêm s/es (she goes, he watches).\n- Các ngôi còn lại: động từ giữ nguyên mẫu (they play).\n- Động từ tận cùng bằng \"o\" thêm \"es\": go thành goes.\n- Chia đúng động từ theo chủ ngữ trong câu.',4,'published',6,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(125,9,'Ngữ pháp lớp 7: câu phủ định, nghi vấn hiện tại đơn (1)','en-ngu-phap-co-ban-lop-7-1','Dùng đúng do/does, don’t/doesn’t trong câu phủ định và nghi vấn.','trung_binh',12,'Câu phủ định: chủ ngữ + do/does + not + động từ nguyên mẫu (She does not like tea). Câu hỏi: Do/Does + chủ ngữ + động từ nguyên mẫu? (Does she swim?). Chú ý: sau does/doesn’t, động từ luôn ở dạng nguyên mẫu, không thêm s.','- Câu phủ định với he/she/it: \"does not/doesn\'t\" + động từ nguyên mẫu.\n- Câu phủ định với I/you/we/they: \"do not/don\'t\" + động từ nguyên mẫu.\n- Câu hỏi với he/she/it: \"Does\" đứng đầu câu.\n- Câu hỏi với I/you/we/they: \"Do\" đứng đầu câu.\n- Sau \"do/does/does not\", động từ luôn ở dạng nguyên mẫu.',5,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(126,9,'Ngữ pháp lớp 7: thì hiện tại tiếp diễn (2)','en-ngu-phap-co-ban-lop-7-2','Chia đúng thì hiện tại tiếp diễn; phân biệt với thì hiện tại đơn.','trung_binh',12,'Hiện tại tiếp diễn: am/is/are + động từ thêm -ing, diễn tả hành động đang xảy ra lúc nói. Dấu hiệu: now, at the moment, Look!, Listen!. Chú ý chính tả: swim → swimming, write → writing, run → running.','- Thì hiện tại tiếp diễn diễn tả hành động đang xảy ra tại thời điểm nói.\n- Cấu trúc: am/is/are + động từ thêm -ing.\n- \"I\" đi với \"am\"; he/she/it đi với \"is\"; you/we/they đi với \"are\".\n- Dấu hiệu nhận biết: now, at the moment.\n- Chia đúng \"am/is/are\" và dạng V-ing theo chủ ngữ.',6,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(127,10,'Từ vựng lớp 7: sức khỏe – health (1)','en-tu-vung-lop-7-lop-7-1','Nhớ và dùng đúng từ vựng về bệnh thường gặp, bộ phận cơ thể và lời khuyên sức khỏe.','trung_binh',12,'Học từ vựng theo nhóm: các cơn đau (headache, stomachache, toothache), người và nơi chữa bệnh (doctor, nurse, hospital), lời khuyên (should + động từ: You should rest).','- \"headache\" nghĩa là đau đầu; \"fever\" nghĩa là sốt.\n- \"doctor\" nghĩa là bác sĩ; \"nurse\" nghĩa là y tá.\n- \"take medicine\" nghĩa là uống thuốc.\n- Nhận nghĩa của từ vựng sức khỏe trong câu.\n- Mở rộng vốn từ chủ đề sức khỏe.',3,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(128,10,'Từ vựng lớp 7: du lịch – travel (2)','en-tu-vung-lop-7-lop-7-2','Nhớ và dùng đúng từ vựng về phương tiện, địa điểm và hoạt động du lịch.','trung_binh',12,'Học từ vựng theo nhóm: giấy tờ và vé (passport, ticket), phương tiện (plane, train, bus, ship), nơi đến (hotel, beach, museum), hoạt động (visit, take photos, buy souvenirs).','- \"ticket\" nghĩa là vé (vé xe, vé máy bay...); \"passport\" nghĩa là hộ chiếu.\n- \"beach\" nghĩa là bãi biển; \"souvenir\" nghĩa là đồ lưu niệm.\n- Nhận nghĩa của từ vựng du lịch trong câu.\n- Mở rộng vốn từ chủ đề du lịch.',4,'published',7,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(129,10,'Từ vựng lớp 8: môi trường – environment (1)','en-tu-vung-lop-7-lop-8-1','Nhớ và dùng đúng từ vựng về ô nhiễm, bảo vệ môi trường và các hành động xanh.','trung_binh',15,'Phân biệt từ loại: pollution (danh từ) – polluted (tính từ) – pollute (động từ). Học các hành động bảo vệ môi trường: plant trees, save water, recycle, reduce plastic. Cấu trúc khuyên nhủ: should/should not + động từ.','- \"environment\" nghĩa là môi trường; \"pollution\" nghĩa là sự ô nhiễm.\n- \"recycle\" nghĩa là tái chế; \"plant trees\" nghĩa là trồng cây.\n- Nhận nghĩa của từ vựng môi trường trong câu.\n- Mở rộng vốn từ và ý thức bảo vệ môi trường.',5,'published',8,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(130,10,'Từ vựng lớp 8: cộng đồng – community (2)','en-tu-vung-lop-7-lop-8-2','Nhớ và dùng đúng từ vựng về hoạt động tình nguyện, từ thiện và cộng đồng.','trung_binh',15,'Học từ vựng theo nhóm: con người (volunteer, donor), hành động (donate, help, raise money), tổ chức và khái niệm (charity, community). Đặt câu kể về hoạt động tình nguyện bằng thì quá khứ đơn.','- \"volunteer\" nghĩa là tình nguyện viên; \"charity\" nghĩa là từ thiện.\n- \"donate\" nghĩa là quyên góp, tặng; \"community\" nghĩa là cộng đồng.\n- Nhận nghĩa của từ vựng cộng đồng trong câu.\n- Mở rộng vốn từ chủ đề hoạt động cộng đồng.',6,'published',8,1,'2026-10-07 21:57:57','2026-10-07 21:57:57'),
(131,60,'Quyền trẻ em lớp 6: 4 nhóm quyền cơ bản (1)','gd-quyen-tre-em-lop-6-1','Nêu được 4 nhóm quyền của trẻ em: sống còn, phát triển, bảo vệ, tham gia.','de',10,'Trẻ em có 4 nhóm quyền: sống còn (được nuôi dưỡng, chăm sóc), phát triển (được học tập, vui chơi), bảo vệ (không bị bạo lực, xâm hại), tham gia (được bày tỏ ý kiến). Mẹo nhớ: \"Sống – Phát triển – Bảo vệ – Tham gia\".','- Trẻ em có 4 nhóm quyền cơ bản: sống còn, phát triển, bảo vệ và tham gia.\n- Quyền được đi học thuộc nhóm quyền phát triển.\n- Quyền được bày tỏ ý kiến thuộc nhóm quyền tham gia.\n- Quyền được bảo vệ: trẻ em được bảo vệ khỏi mọi hình thức bạo lực, xâm hại.\n- Nhớ 4 nhóm quyền để biết mình được bảo vệ như thế nào.',3,'published',6,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(132,60,'Quyền trẻ em lớp 6: bổn phận của trẻ em (2)','gd-quyen-tre-em-lop-6-2','Kể được các bổn phận của trẻ em: hiếu thảo, chăm học, yêu Tổ quốc, tôn trọng mọi người.','de',10,'Bên cạnh quyền, trẻ em có bổn phận: kính trọng, hiếu thảo với ông bà cha mẹ; chăm chỉ học tập; yêu quê hương, đất nước; tôn trọng, giúp đỡ mọi người; giữ gìn vệ sinh, bảo vệ môi trường.','- Học tập là bổn phận hàng đầu của học sinh.\n- Giúp đỡ cha mẹ việc nhà là biểu hiện của lòng hiếu thảo.\n- Yêu quê hương, đất nước là bổn phận thiêng liêng của mỗi trẻ em Việt Nam.\n- Kính trọng người lớn tuổi là nét đẹp văn hóa của người Việt Nam.\n- Làm tròn bổn phận là cách thể hiện lòng biết ơn với gia đình và đất nước.',4,'published',6,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(133,60,'Quyền trẻ em lớp 7: phòng chống bạo lực trẻ em (1)','gd-quyen-tre-em-lop-7-1','Nhận biết các hành vi bạo lực với trẻ em và biết cách tự bảo vệ, tìm sự giúp đỡ.','de',12,'Bạo lực trẻ em gồm: đánh đập, chửi mắng xúc phạm; dụ dỗ xâm hại; bỏ mặc không chăm sóc. Khi gặp nguy hiểm: hét to, chạy đến nơi đông người, kể với người tin cậy, gọi tổng đài 111.','- Đánh đập trẻ em là bạo lực thể chất, bị pháp luật nghiêm cấm.\n- Khi bị người lạ dụ dỗ đi theo, hãy hét to và chạy đến nơi đông người.\n- Tổng đài quốc gia bảo vệ trẻ em là 111.\n- Khi gặp nguy hiểm, kể ngay với cha mẹ hoặc thầy cô tin cậy để được giúp đỡ.\n- Biết tự bảo vệ mình là kỹ năng quan trọng của mỗi trẻ em.',5,'published',7,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(134,60,'Quyền trẻ em lớp 7: bảo vệ trẻ em trên thực tế (2)','gd-quyen-tre-em-lop-7-2','Hiểu trách nhiệm của gia đình, nhà trường, xã hội trong bảo vệ trẻ em; biết quyền được tham gia ý kiến.','trung_binh',12,'Gia đình phải nuôi dưỡng, không được bạo hành; nhà trường bảo đảm môi trường học tập an toàn; xã hội lên án hành vi xâm hại trẻ em. Trẻ có quyền tham gia: bày tỏ ý kiến, tham gia hoạt động Đội, góp ý xây dựng trường lớp.','- Gia đình là nơi đầu tiên có trách nhiệm nuôi dưỡng và bảo vệ trẻ em.\n- Mọi hình thức đánh đập, xúc phạm học sinh đều bị pháp luật nghiêm cấm.\n- Quyền tham gia của trẻ em thể hiện qua việc được bày tỏ ý kiến về những việc liên quan đến mình.\n- Thấy bạn bị bạo hành, báo người lớn là cách giúp bạn an toàn và đúng đắn nhất.\n- Bảo vệ trẻ em là trách nhiệm của gia đình, nhà trường và xã hội.',6,'published',7,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(135,62,'Kỹ năng sống lớp 7: quản lý cảm xúc (1)','gd-ky-nang-song-lop-7-1','Nhận biết cảm xúc của bản thân và biết cách kiềm chế cơn giận.','de',10,'Cảm xúc có vui, buồn, giận, sợ... Khi tức giận: hít thở sâu, đếm từ 1 đến 10, rời khỏi chỗ gây bực, nói chuyện khi đã bình tĩnh. Không đập phá, không nói lời làm tổn thương người khác.','- Khi tức giận, hít thở sâu giúp bình tĩnh lại trước khi hành động.\n- Đang giận mà sắp nói thì đếm đến 10 để tránh nói lời làm tổn thương người khác.\n- Vui vẻ là cảm xúc tích cực, giúp khỏe mạnh và học tốt.\n- Khi buồn bã, chia sẻ với người tin cậy giúp nhẹ lòng và tìm được cách giải quyết.\n- Quản lý cảm xúc tốt giúp các mối quan hệ hài hòa hơn.',3,'published',7,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(136,62,'Kỹ năng sống lớp 7: giao tiếp ứng xử (2)','gd-ky-nang-song-lop-7-2','Biết chào hỏi lễ phép, lắng nghe người khác, nói lời cảm ơn và xin lỗi đúng lúc.','trung_binh',10,'Giao tiếp tốt: chào hỏi lễ phép, nhìn vào mắt người nói, lắng nghe không ngắt lời, nói \"cảm ơn\" khi được giúp, nói \"xin lỗi\" khi làm sai, không nói tục chửi bậy.','- Được giúp đỡ thì nói lời cảm ơn để thể hiện sự trân trọng và lịch sự.\n- Làm sai thì dám nhận lỗi và xin lỗi là biểu hiện của người dũng cảm.\n- Lắng nghe chăm chú, không ngắt lời là tôn trọng người đang nói.\n- Gặp thầy cô phải chào hỏi lễ phép, thể hiện sự kính trọng.\n- Giao tiếp lịch sự giúp ta được mọi người yêu quý.',4,'published',7,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(137,62,'Kỹ năng sống lớp 8: quản lý thời gian (1)','gd-ky-nang-song-lop-8-1','Biết lập thời gian biểu, phân biệt việc quan trọng – khẩn cấp, tránh lãng phí thời gian.','trung_binh',12,'Quản lý thời gian: liệt kê việc cần làm, xếp theo mức quan trọng, làm việc quan trọng trước, đặt giờ cố định cho học tập – nghỉ ngơi, hạn chế lướt điện thoại vô bổ.','- Việc đầu tiên khi quản lý thời gian là liệt kê các việc cần làm.\n- Ưu tiên làm trước những việc quan trọng và gấp.\n- Kẻ cắp thời gian lớn nhất của học sinh hiện nay là lướt điện thoại vô bổ.\n- Thời gian biểu tốt cân bằng giữa học tập, nghỉ ngơi và vui chơi.\n- Quản lý thời gian tốt giúp học tập hiệu quả mà vẫn vui chơi.',5,'published',8,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(138,62,'Kỹ năng sống lớp 8: giải quyết mâu thuẫn (2)','gd-ky-nang-song-lop-8-2','Biết kiềm chế khi mâu thuẫn, lắng nghe đối phương, tìm giải pháp đôi bên cùng có lợi.','trung_binh',12,'Khi mâu thuẫn: bình tĩnh, lắng nghe bạn nói hết, nói cảm xúc của mình (\"mình buồn vì...\"), không đổ lỗi, cùng tìm cách giải quyết, nhờ thầy cô hòa giải nếu không tự giải quyết được.','- Khi mâu thuẫn với bạn, điều đầu tiên là giữ bình tĩnh.\n- Nói về cảm xúc của mình thay vì đổ lỗi giúp đối phương dễ lắng nghe.\n- Không tự hòa giải được thì nhờ thầy cô giúp đỡ.\n- Lắng nghe giúp hiểu bạn nghĩ gì, từ đó dễ tìm tiếng nói chung.\n- Giải quyết mâu thuẫn trong hòa bình giữ được tình bạn.',6,'published',8,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(139,63,'An toàn mạng lớp 8: bảo vệ thông tin cá nhân (1)','gd-an-toan-mang-lop-8-1','Biết những thông tin cá nhân không được chia sẻ công khai; biết đặt mật khẩu mạnh.','trung_binh',12,'Thông tin cá nhân như họ tên đầy đủ, địa chỉ nhà, số điện thoại, trường lớp, ảnh riêng tư — không đăng công khai. Mật khẩu mạnh: dài từ 8 ký tự, có chữ hoa, chữ thường, số, ký tự đặc biệt; không dùng ngày sinh, tên mình.','- Địa chỉ nhà là thông tin nhạy cảm, không đăng công khai lên mạng.\n- Mật khẩu mạnh phải dài và có đủ chữ hoa, chữ thường, số, ký tự đặc biệt.\n- Tuyệt đối không gửi ảnh riêng tư cho người lạ; kể ngay với cha mẹ.\n- Để tài khoản mạng xã hội ở chế độ riêng tư để kiểm soát người xem thông tin.\n- Kiểm tra cài đặt riêng tư thường xuyên để bảo vệ tài khoản.',3,'published',8,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(140,63,'An toàn mạng lớp 8: nhận biết tin giả (2)','gd-an-toan-mang-lop-8-2','Nhận biết dấu hiệu tin giả và biết kiểm chứng thông tin trước khi chia sẻ.','trung_binh',12,'Dấu hiệu tin giả: tiêu đề giật gân, không rõ nguồn, chính tả sai nhiều, ảnh cắt ghép, kêu gọi chia sẻ gấp. Kiểm chứng: xem nguồn uy tín (báo chính thống), đối chiếu nhiều nguồn, hỏi thầy cô. Không chia sẻ tin chưa kiểm chứng.','- Tin giả thường có tiêu đề giật gân để câu lượt xem.\n- Trước khi chia sẻ tin giật gân phải kiểm chứng nguồn tin.\n- Báo chí chính thống có quy trình kiểm chứng nên đáng tin cậy hơn.\n- Lan truyền tin giả gây hoang mang dư luận và có thể bị xử phạt theo pháp luật.\n- Là người dùng mạng thông minh: đọc kỹ, kiểm chứng rồi mới chia sẻ.',4,'published',8,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(141,63,'An toàn mạng lớp 9: ứng phó lừa đảo mạng (1)','gd-an-toan-mang-lop-9-1','Nhận biết các chiêu lừa đảo trực tuyến; biết cách ứng phó và báo cáo.','trung_binh',12,'Chiêu lừa đảo: giả danh công an hoặc ngân hàng, trúng thưởng bấm link, việc nhẹ lương cao, xin mã OTP. Nguyên tắc: không bấm link lạ, không cung cấp OTP hay mật khẩu, không chuyển tiền cho người lạ, chặn và báo cáo.','- Tin nhắn trúng thưởng, bấm link nhận quà hầu hết là lừa đảo.\n- Mã OTP là chìa khóa tài khoản, không bao giờ cung cấp cho bất kỳ ai.\n- Việc nhẹ lương cao nhưng yêu cầu chuyển khoản đặt cọc trước là dấu hiệu lừa đảo.\n- Nghi ngờ bị lừa đảo: chặn, báo cáo tài khoản đó và kể ngay với người lớn.\n- Cảnh giác với món lợi bất ngờ trên mạng để không sập bẫy.',5,'published',9,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(142,63,'Môi trường lớp 9: trách nhiệm bảo vệ môi trường (2)','gd-an-toan-mang-lop-9-2','Hiểu trách nhiệm bảo vệ môi trường của công dân; biết các hành vi bị pháp luật cấm.','kho',15,'Bảo vệ môi trường: tiết kiệm điện nước, phân loại rác, trồng cây xanh, hạn chế túi nilon. Pháp luật cấm: xả rác bừa bãi, chặt phá rừng, xả thải chưa xử lý. Biến đổi khí hậu gây hạn hán, lũ lụt, nước biển dâng — mỗi người đều có trách nhiệm.','- Xả thải chưa qua xử lý ra môi trường là hành vi bị pháp luật nghiêm cấm và xử phạt.\n- Biến đổi khí hậu gây thời tiết cực đoan: lũ lụt, hạn hán, nước biển dâng.\n- Dùng túi vải nhiều lần giúp giảm đáng kể rác thải nhựa.\n- Tiết kiệm điện, tiết kiệm tài nguyên là trách nhiệm của mỗi người.\n- Bảo vệ môi trường vừa là đạo đức vừa là nghĩa vụ pháp luật.',6,'published',9,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(143,22,'Phần cứng máy tính lớp 6: các bộ phận chính (1)','th-phan-cung-may-tinh-lop-6-1','Kể tên các bộ phận chính của máy tính: thân máy, màn hình, bàn phím, chuột, loa.','de',10,'Máy tính để bàn gồm: thân máy (chứa CPU, bộ nhớ), màn hình (hiển thị), bàn phím (gõ chữ), chuột (điều khiển), loa (phát âm thanh). Laptop gộp tất cả trong một khối gọn nhẹ.','- Màn hình hiển thị mọi hình ảnh, chữ viết của máy tính.\n- Bàn phím dùng để gõ chữ, nhập văn bản và số liệu vào máy.\n- Chuột điều khiển con trỏ trên màn hình, nhấp chuột để chọn và mở.\n- Laptop gộp màn hình, bàn phím và thân máy thành một khối gọn nhẹ, dễ mang theo.\n- Máy tính để bàn gồm các bộ phận rời, thuận tiện nâng cấp từng phần.',2,'published',6,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(144,22,'Phần cứng máy tính lớp 6: thiết bị vào – ra (2)','th-phan-cung-may-tinh-lop-6-2','Phân biệt thiết bị vào (input) và thiết bị ra (output) của máy tính.','de',10,'Thiết bị vào đưa thông tin VÀO máy: bàn phím, chuột, micro, máy quét, webcam. Thiết bị ra đưa thông tin RA ngoài: màn hình, loa, máy in, máy chiếu. Mẹo nhớ: \"Vào là nhập, Ra là xuất\".','- Thiết bị vào đưa dữ liệu vào máy tính: bàn phím, chuột, micro, webcam.\n- Thiết bị ra đưa kết quả ra ngoài: màn hình, máy in, loa.\n- Webcam thu hình ảnh vào máy, dùng khi gọi video, học trực tuyến.\n- Micro thu âm thanh vào máy nên là thiết bị vào.\n- Phân biệt thiết bị vào và thiết bị ra giúp sử dụng máy tính đúng cách.',3,'published',6,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(145,22,'Phần cứng máy tính lớp 7: bộ xử lý và bộ nhớ (1)','th-phan-cung-may-tinh-lop-7-1','Biết CPU là bộ não, RAM là bộ nhớ tạm, ổ cứng và SSD lưu trữ lâu dài.','de',12,'CPU (bộ xử lý trung tâm) là \"bộ não\", thực hiện mọi tính toán. RAM là bộ nhớ tạm, mất dữ liệu khi tắt máy. Ổ cứng (HDD) và SSD lưu dữ liệu lâu dài; SSD nhanh hơn HDD.','- CPU là bộ não của máy tính, thực hiện mọi phép tính và điều khiển.\n- RAM là bộ nhớ tạm: tắt máy thì dữ liệu trong RAM mất hết.\n- SSD đọc ghi nhanh và êm hơn HDD vì không có đĩa quay.\n- RAM càng lớn, máy càng chạy được nhiều chương trình cùng lúc mượt mà.\n- Tốc độ máy tính phụ thuộc chủ yếu vào CPU và dung lượng RAM.',4,'published',7,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(146,22,'Phần cứng máy tính lớp 7: bảo quản thiết bị (2)','th-phan-cung-may-tinh-lop-7-2','Biết cách giữ gìn, vệ sinh và sử dụng thiết bị đúng cách, an toàn điện.','trung_binh',12,'Bảo quản máy tính: để nơi khô ráo thoáng mát, tránh nước và bụi, không ăn uống gần máy, tắt máy đúng cách (Start → Shut down), dùng ổn áp khi điện chập chờn, không tự tháo linh kiện.','- Tắt máy tính đúng cách giúp lưu dữ liệu và làm máy bền hơn.\n- Không để đồ ăn, nước uống gần máy tính vì đổ vào gây chập, hỏng bàn phím.\n- Đặt máy ở nơi khô ráo, thoáng mát để tản nhiệt tốt.\n- Khi điện chập chờn nên dùng ổn áp để bảo vệ linh kiện khỏi cháy hỏng.\n- Bảo quản thiết bị đúng cách giúp máy tính bền và hoạt động ổn định.',5,'published',7,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(147,24,'Phần mềm lớp 7: hệ thống và ứng dụng (1)','th-phan-mem-tep-thu-muc-lop-7-1','Phân biệt phần mềm hệ thống (hệ điều hành) và phần mềm ứng dụng.','de',10,'Phần mềm hệ thống: hệ điều hành (Windows, Android) điều khiển phần cứng. Phần mềm ứng dụng phục vụ nhu cầu người dùng (Word, trình duyệt, game). Không có hệ điều hành, máy tính không hoạt động được.','- Hệ điều hành (như Windows) là phần mềm hệ thống, điều hành toàn bộ máy tính.\n- Phần mềm ứng dụng phục vụ nhu cầu cụ thể của người dùng như soạn thảo, giải trí, học tập.\n- Không có hệ điều hành, máy tính không thể hoạt động.\n- Ví dụ: Windows là hệ điều hành, Word là phần mềm ứng dụng soạn thảo văn bản.\n- Mỗi phần mềm được tạo ra cho một mục đích sử dụng nhất định.',2,'published',7,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(148,24,'Tệp và thư mục lớp 7: phần mở rộng (2)','th-phan-mem-tep-thu-muc-lop-7-2','Nhận biết loại tệp qua phần mở rộng: .docx, .xlsx, .pptx, .pdf, .jpg, .mp3, .mp4.','de',10,'Tên tệp gồm tên và phần mở rộng sau dấu chấm. .docx là văn bản Word, .xlsx là bảng tính Excel, .pptx là trình chiếu, .pdf là tài liệu, .jpg/.png là ảnh, .mp3 là nhạc, .mp4 là video.','- .docx là tệp văn bản Word, .jpg là tệp ảnh, .mp4 là tệp video.\n- Phần mở rộng nằm sau dấu chấm trong tên tệp, cho biết loại tệp.\n- Biết đuôi tệp giúp chọn đúng phần mềm để mở.\n- Thư mục dùng để sắp xếp, phân loại các tệp cho gọn gàng.\n- Đặt tên tệp rõ ràng giúp tìm kiếm nhanh sau này.',3,'published',7,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(149,24,'Quản lý tệp lớp 8: thư mục (1)','th-phan-mem-tep-thu-muc-lop-8-1','Biết tạo, đổi tên, sao chép, di chuyển, xóa tệp và thư mục; sắp xếp khoa học.','trung_binh',12,'Thư mục (folder) chứa tệp và thư mục con. Thao tác: tạo mới (New → Folder), đổi tên (Rename), sao chép (Copy – Paste), di chuyển (Cut – Paste), xóa (Delete → thùng rác). Đặt tên rõ ràng, phân loại theo môn học.','- Nhấp chuột phải, chọn New rồi Folder để tạo thư mục mới.\n- Tệp đã xóa thường vào thùng rác (Recycle Bin), có thể khôi phục lại khi cần.\n- Copy sao chép tệp (tệp gốc vẫn còn), Paste để dán tệp vào vị trí mới.\n- Đặt tên thư mục rõ ràng giúp tìm tệp nhanh chóng sau này.\n- Sắp xếp tệp theo thư mục giúp máy tính gọn gàng, dễ quản lý.',4,'published',8,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(150,24,'Phần mềm lớp 8: bản quyền phần mềm (2)','th-phan-mem-tep-thu-muc-lop-8-2','Hiểu bản quyền phần mềm; phân biệt phần mềm có phí, miễn phí và mã nguồn mở.','trung_binh',12,'Phần mềm có bản quyền phải mua giấy phép, không sao chép lậu. Phần mềm miễn phí dùng không mất tiền. Mã nguồn mở được xem và sửa mã nguồn (ví dụ LibreOffice). Dùng phần mềm lậu là vi phạm pháp luật và dễ dính virus.','- Dùng phần mềm crack (bẻ khóa) là vi phạm bản quyền và dễ bị nhiễm virus.\n- Phần mềm mã nguồn mở cho phép xem, sửa và chia sẻ mã nguồn tự do.\n- LibreOffice là bộ phần mềm văn phòng miễn phí, hợp pháp.\n- Mua phần mềm có bản quyền được cập nhật, hỗ trợ kỹ thuật và yên tâm sử dụng.\n- Tôn trọng bản quyền là trách nhiệm của người dùng máy tính.',5,'published',8,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(151,26,'Sử dụng an toàn lớp 8: mật khẩu mạnh (1)','th-su-dung-an-toan-lop-8-1','Biết tạo và quản lý mật khẩu mạnh; biết bật xác thực hai bước.','trung_binh',12,'Mật khẩu mạnh: dài từ 8 ký tự, gồm chữ hoa, chữ thường, số, ký tự đặc biệt; không dùng thông tin cá nhân. Mỗi tài khoản một mật khẩu khác nhau. Bật xác thực hai bước (2FA). Không chia sẻ mật khẩu; đăng xuất khi dùng máy chung.','- Mật khẩu mạnh gồm chữ hoa, chữ thường, số và ký tự đặc biệt.\n- Mỗi tài khoản nên dùng một mật khẩu riêng để lộ một nơi không mất tất cả.\n- Xác thực hai bước (2FA) yêu cầu thêm mã xác nhận nên bảo vệ tốt hơn dù lộ mật khẩu.\n- Dùng xong máy tính chung ở trường phải đăng xuất tài khoản của mình.\n- Đổi mật khẩu định kỳ giúp tài khoản an toàn hơn.',2,'published',8,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(152,26,'Sử dụng an toàn lớp 8: virus máy tính (2)','th-su-dung-an-toan-lop-8-2','Biết virus lây lan qua đâu, cách phòng tránh và dùng phần mềm diệt virus.','trung_binh',12,'Virus lây qua USB lạ, tệp đính kèm email lạ, phần mềm crack, link lạ. Dấu hiệu: máy chậm bất thường, file lạ xuất hiện, quảng cáo bật liên tục. Phòng tránh: không cắm USB lạ, không mở tệp lạ, cài phần mềm diệt virus, cập nhật thường xuyên, sao lưu dữ liệu.','- USB lạ là con đường lây virus máy tính phổ biến nhất.\n- Dấu hiệu nghi nhiễm virus: máy tính đột nhiên chậm bất thường.\n- Không mở tệp đính kèm trong email lạ vì có thể chứa virus.\n- Phần mềm diệt virus cần cập nhật thường xuyên để nhận diện được virus mới.\n- Cẩn thận với thiết bị lạ và email lạ giúp phòng tránh virus hiệu quả.',3,'published',8,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(153,26,'Sử dụng an toàn lớp 9: quyền riêng tư trực tuyến (1)','th-su-dung-an-toan-lop-9-1','Hiểu dấu chân số; biết kiểm soát quyền riêng tư và ứng xử có trách nhiệm trên mạng.','trung_binh',12,'Dấu chân số: mọi thứ đăng lên mạng đều lưu lại lâu dài. Hãy kiểm tra cài đặt riêng tư, suy nghĩ trước khi đăng, xin phép trước khi đăng ảnh người khác, không bình luận ác ý, không lan truyền tin chưa kiểm chứng.','- Dấu chân số: mọi thứ đăng lên mạng đều lưu lại lâu dài, khó xóa hết.\n- Trước khi đăng ảnh có mặt bạn bè phải xin phép họ.\n- Bình luận ác ý, xúc phạm người khác trên mạng có thể bị xử lý theo pháp luật.\n- Kiểm tra cài đặt riêng tư của tài khoản thường xuyên để bảo vệ thông tin.\n- Nghĩ kỹ trước khi đăng bất cứ điều gì lên mạng.',4,'published',9,1,'2026-10-07 21:58:49','2026-10-07 21:58:49'),
(154,26,'Sử dụng an toàn lớp 9: ứng phó sự cố mạng (2)','th-su-dung-an-toan-lop-9-2','Biết quy trình ứng phó khi bị hack, bị lừa, bị bắt nạt mạng; biết các kênh hỗ trợ.','kho',15,'Bị hack: đổi mật khẩu ngay, đăng xuất mọi thiết bị, bật 2FA, báo cáo nền tảng. Bị lừa tiền: giữ bằng chứng, báo công an, báo ngân hàng. Bị bắt nạt mạng: không đáp trả, lưu bằng chứng, chặn và báo cáo, kể người lớn, gọi 111 nếu nghiêm trọng.','- Nghi ngờ tài khoản bị hack: đổi mật khẩu ngay lập tức.\n- Bị lừa chuyển tiền qua mạng: giữ lại bằng chứng giao dịch và báo công an.\n- Bị bắt nạt trên mạng: không đáp trả, hãy chặn, lưu bằng chứng và báo cáo.\n- Trẻ em bị hại trên mạng được hỗ trợ qua tổng đài 111.\n- Khi gặp sự cố trên mạng, kể ngay với người lớn để được giúp đỡ.',5,'published',9,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(155,38,'An toàn điện lớp 6: nhận biết nguy hiểm (1)','cn-an-toan-dien-lop-6-1','Nhận biết các tình huống nguy hiểm về điện trong gia đình.','de',10,'Tình huống nguy hiểm: dây điện hở, ổ cắm vỡ, tay ướt chạm đồ điện, dùng vật kim loại chọc ổ cắm, thả diều gần đường dây điện, trèo cột điện. Điện giật có thể gây bỏng, ngừng tim, tử vong.','- Tay ướt không được cắm điện vì nước dẫn điện rất tốt.\n- Thấy dây điện hở trong nhà phải báo người lớn xử lý, không tự chạm vào.\n- Không thả diều gần đường dây điện vì diều vướng vào gây điện giật, chập cháy.\n- Kim loại dẫn điện nên tuyệt đối không chọc vào ổ cắm.\n- Nhận biết dấu hiệu nguy hiểm về điện để tránh xa.',2,'published',6,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(156,38,'An toàn điện lớp 6: quy tắc dùng đồ điện (2)','cn-an-toan-dien-lop-6-2','Biết các quy tắc an toàn khi sử dụng đồ điện trong gia đình.','de',10,'Quy tắc: cắm và rút phích cầm vào phần nhựa, không giật dây; không dùng đồ điện khi tay ướt; rút phích khi không dùng; không để đồ điện gần nước; không tự sửa đồ điện hỏng; nhờ người lớn khi cần.','- Rút phích điện phải cầm phần nhựa cách điện rút thẳng ra, không giật dây.\n- Đồ điện trong nhà bị hỏng, trẻ em không tự sửa mà báo người lớn.\n- Dùng xong đồ điện nên tắt và rút phích, vừa an toàn vừa tiết kiệm điện.\n- Ấm điện nóng và dùng điện nên để xa trẻ nhỏ, xa nước.\n- Dùng đồ điện đúng cách mỗi ngày để an toàn cho cả gia đình.',3,'published',6,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(157,38,'An toàn điện lớp 7: xử lý sự cố điện (1)','cn-an-toan-dien-lop-7-1','Biết cách xử lý khi gặp sự cố điện: ngắt nguồn, gọi người lớn, gọi cứu hộ.','de',12,'Khi chập điện: ngắt cầu dao ngay. Người bị điện giật: KHÔNG chạm tay trực tiếp khi chưa ngắt điện — dùng vật cách điện (gậy gỗ khô) gạt dây ra. Gọi 114 khi cháy, 115 khi cấp cứu. Không dội nước vào đám cháy điện.','- Thấy chập điện trong nhà, việc đầu tiên là ngắt cầu dao để cắt nguồn điện.\n- Thấy người bị điện giật tuyệt đối không chạm trực tiếp vào nạn nhân.\n- Dùng gậy gỗ khô (vật cách điện) để gạt dây điện ra khỏi người bị nạn.\n- Xảy ra cháy do điện gọi ngay số 114 (cứu hỏa).\n- Ngắt điện là nguyên tắc an toàn đầu tiên và quan trọng nhất.',4,'published',7,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(158,38,'An toàn điện lớp 7: tiết kiệm điện (2)','cn-an-toan-dien-lop-7-2','Biết các biện pháp tiết kiệm điện trong gia đình và ý nghĩa của việc tiết kiệm điện.','trung_binh',12,'Tiết kiệm điện: tắt đèn và quạt khi ra khỏi phòng, dùng bóng đèn LED, rút sạc khi đầy pin, để điều hòa 26–27°C, tận dụng ánh sáng tự nhiên. Ý nghĩa: giảm tiền điện, giảm tải lưới điện, bảo vệ môi trường.','- Bóng đèn LED tiết kiệm điện nhất: sáng hơn mà tốn ít điện hơn bóng sợi đốt.\n- Ra khỏi phòng phải tắt đèn, quạt và các thiết bị điện.\n- Điều hòa để ở 26–27 độ C vừa mát vừa tiết kiệm điện, tốt cho sức khỏe.\n- Tiết kiệm điện giúp giảm chi phí, giảm tải lưới điện và bảo vệ môi trường.\n- Tiết kiệm điện là thói quen tốt mỗi học sinh nên rèn luyện.',5,'published',7,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(159,40,'Vật liệu lớp 7: gỗ, kim loại, nhựa (1)','cn-vat-lieu-dung-cu-lop-7-1','Nêu được tính chất cơ bản và ứng dụng của gỗ, kim loại, nhựa.','de',10,'Gỗ nhẹ, dễ gia công, làm bàn ghế. Kim loại (sắt, nhôm, đồng) cứng, dẫn điện, dẫn nhiệt; làm dụng cụ, dây điện, xoong nồi. Nhựa nhẹ, không dẫn điện, chống nước; làm chai lọ, đồ dùng hằng ngày.','- Kim loại như đồng, sắt dẫn điện rất tốt.\n- Gỗ nhẹ, dễ gia công nên thường dùng làm bàn ghế học sinh.\n- Nhựa nhẹ, không thấm nước nên dùng làm chai nước, đồ dùng hằng ngày.\n- Tính chất nổi bật của nhựa: nhẹ, cách điện, chống nước.\n- Nhận biết tính chất vật liệu giúp chọn đồ dùng phù hợp.',2,'published',7,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(160,40,'Dụng cụ lớp 7: đo và đánh dấu (2)','cn-vat-lieu-dung-cu-lop-7-2','Biết công dụng của thước, êke, compa; đo và đánh dấu đúng kỹ thuật.','de',10,'Thước thẳng đo độ dài, êke vẽ góc vuông, compa vẽ đường tròn. Khi đo: đặt vạch 0 trùng đầu vật, mắt nhìn thẳng. Đánh dấu bằng bút chì, vạch dấu rõ ràng trước khi cắt.','- Compa có chân nhọn cố định và chân chì, dùng để vẽ đường tròn.\n- Êke hình tam giác vuông dùng để vẽ và kiểm tra góc vuông.\n- Khi đo độ dài, đặt vạch 0 của thước trùng với đầu vật thì số đo mới chính xác.\n- Dùng bút chì đánh dấu trước khi cắt vì vạch rõ mà dễ tẩy xóa.\n- Đo và đánh dấu chính xác giúp sản phẩm làm ra đúng kích thước.',3,'published',7,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(161,40,'Dụng cụ lớp 8: cơ khí cầm tay (1)','cn-vat-lieu-dung-cu-lop-8-1','Biết công dụng và cách dùng an toàn của búa, tua vít, kìm, cờ lê, cưa.','trung_binh',12,'Búa đóng đinh; tua vít vặn ốc (đầu dẹt, đầu 4 cạnh); kìm kẹp và cắt dây; cờ lê, mỏ lết vặn bu-lông; cưa cắt gỗ. An toàn: cầm chắc cán, kiểm tra dụng cụ trước khi dùng, không dùng dụng cụ hỏng, đeo kính bảo hộ khi cần.','- Tua vít chuyên dùng để vặn ốc vít; búa dùng để đóng đinh và gõ.\n- Cưa tay có răng cưa thích hợp để cắt gỗ.\n- Khi dùng dụng cụ cơ khí phải cầm chắc, dùng đúng cách và đeo đồ bảo hộ.\n- Chọn dụng cụ phù hợp với công việc để làm việc hiệu quả.\n- An toàn là yêu cầu đầu tiên khi dùng mọi dụng cụ cơ khí.',4,'published',8,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(162,40,'Vật liệu lớp 8: dùng tiết kiệm và tái chế (2)','cn-vat-lieu-dung-cu-lop-8-2','Biết sử dụng vật liệu tiết kiệm, tái chế; biết phân loại rác thải.','trung_binh',12,'Tiết kiệm vật liệu: đo đạc kỹ trước khi cắt, tận dụng vật liệu thừa. Tái chế: giấy, nhựa, kim loại, thủy tinh có thể tái chế. Phân loại rác: hữu cơ, tái chế, nguy hại (pin, bóng đèn). Pin cũ không vứt bừa bãi.','- Đo đạc kỹ trước khi cắt để tránh lãng phí vật liệu.\n- Pin cũ chứa chì, thủy ngân nên là rác nguy hại, vứt bừa bãi gây ô nhiễm đất và nước.\n- Giấy, nhựa, kim loại, thủy tinh đều có thể tái chế.\n- Phân loại rác và tái chế giúp tiết kiệm tài nguyên, bảo vệ môi trường.\n- Dùng vật liệu tiết kiệm là trách nhiệm của mỗi người.',5,'published',8,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(163,44,'Trồng trọt lớp 8: các bước trồng cây (1)','cn-trong-trot-lop-8-1','Nêu được các bước cơ bản khi trồng cây: chọn giống, làm đất, gieo trồng, chăm sóc.','trung_binh',12,'Bước 1: chọn giống tốt, phù hợp. Bước 2: làm đất tơi xốp, bón lót. Bước 3: gieo hạt hoặc trồng cây con đúng thời vụ, đúng khoảng cách. Bước 4: chăm sóc — tưới nước, bón phân, phòng trừ sâu bệnh.','- Giống tốt là nền tảng cho vụ mùa bội thu, cần chọn giống khỏe và gieo đúng thời vụ.\n- Đất trồng cây cần tơi xốp để rễ phát triển và thoát nước tốt.\n- Gieo trồng đúng thời vụ giúp cây sinh trưởng tốt, ít sâu bệnh.\n- Bón lót là bón phân vào đất trước khi gieo trồng để cung cấp dinh dưỡng.\n- Chuẩn bị tốt từng bước quyết định năng suất cây trồng.',2,'published',8,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(164,44,'Trồng trọt lớp 8: tưới nước và bón phân (2)','cn-trong-trot-lop-8-2','Biết tưới nước đúng cách; phân biệt phân hữu cơ và phân hóa học.','trung_binh',12,'Tưới nước: đủ ẩm, không để úng; tưới sáng sớm hoặc chiều mát, tránh giữa trưa nắng gắt. Phân hữu cơ (phân chuồng, phân xanh) an toàn, cải tạo đất. Phân hóa học (đạm, lân, kali) tác dụng nhanh nhưng phải đúng liều; lạm dụng làm hại đất.','- Tưới cây vào sáng sớm hoặc chiều mát giúp cây hấp thụ tốt, ít bay hơi.\n- Tưới quá nhiều nước gây úng, làm rễ thối, cây héo và chết.\n- Phân hữu cơ có nguồn gốc tự nhiên như phân chuồng, phân xanh.\n- Lạm dụng phân hóa học làm đất chai cứng và gây ô nhiễm môi trường.\n- Tưới nước và bón phân vừa đủ giúp cây phát triển khỏe mạnh.',3,'published',8,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(165,44,'Trồng trọt lớp 9: phòng trừ sâu bệnh (1)','cn-trong-trot-lop-9-1','Nhận biết sâu bệnh hại cây; biết biện pháp phòng trừ tổng hợp an toàn.','trung_binh',12,'Sâu bệnh thường gặp: sâu ăn lá, rệp, bệnh đốm lá, thối rễ. Phòng trừ tổng hợp: vệ sinh đồng ruộng, bắt sâu bằng tay, dùng thiên địch (bọ rùa, ong), bẫy đèn, ưu tiên thuốc sinh học, hạn chế thuốc hóa học.','- Bọ rùa là thiên địch có ích, chuyên ăn rệp gây hại cho cây trồng.\n- Bắt sâu bằng tay là biện pháp an toàn nhất, không độc hại, bảo vệ môi trường.\n- Sâu ăn lá để lại những lỗ thủng trên phiến lá.\n- Thuốc bảo vệ thực vật hóa học phải dùng đúng liều, đúng lúc, đúng cách.\n- Ưu tiên biện pháp sinh học và thủ công trước khi dùng thuốc hóa học.',4,'published',9,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(166,44,'Trồng trọt lớp 9: thu hoạch, bảo quản và công nghệ mới (2)','cn-trong-trot-lop-9-2','Biết thu hoạch đúng thời điểm, bảo quản nông sản; làm quen với thủy canh, tưới nhỏ giọt.','kho',15,'Thu hoạch đúng độ chín, nhẹ tay, vào buổi sáng mát. Bảo quản nơi khô ráo thoáng mát; thóc phải phơi hoặc sấy khô. Công nghệ mới: thủy canh (trồng cây trong nước dinh dưỡng, không cần đất), nhà kính, tưới nhỏ giọt tiết kiệm nước.','- Nên thu hoạch nông sản vào sáng sớm mát mẻ để tươi lâu, ít dập nát.\n- Thóc ướt dễ mốc, mọc mầm nên phải phơi khô trước khi cất trữ.\n- Thủy canh là phương pháp trồng cây trong dung dịch dinh dưỡng thay cho đất.\n- Tưới nhỏ giọt đưa nước trực tiếp đến rễ, tiết kiệm nước đáng kể.\n- Ứng dụng công nghệ mới giúp trồng trọt hiệu quả và bền vững hơn.',5,'published',9,1,'2026-10-07 21:58:50','2026-10-07 21:58:50'),
(167,11,'Cơ thể người lớp 6: hệ xương (1)','kh-co-the-nguoi-lop-6-1','Kể được các bộ phận chính của hệ xương, nêu chức năng nâng đỡ – bảo vệ và cách giữ xương chắc khoẻ.','de',10,'Cơ thể người có hơn 200 chiếc xương. Xương có chức năng nâng đỡ cơ thể và bảo vệ các cơ quan bên trong. Các khớp giúp xương cử động được. Muốn xương chắc khoẻ cần ăn đủ canxi, tắm nắng và vận động thường xuyên.','- Cơ thể người trưởng thành có hơn 200 chiếc xương tạo thành bộ xương.\n- Xương nâng đỡ cơ thể, tạo khung cho cơ bám và bảo vệ các cơ quan bên trong như não, tim, phổi.\n- Khớp là chỗ nối giữa các xương, giúp xương cử động linh hoạt.\n- Canxi là thành phần chính cấu tạo nên xương.\n- Sữa, tôm cua nhỏ và tắm nắng giúp xương chắc khoẻ.',3,'published',6,1,'2026-10-07 21:59:45','2026-10-07 21:59:45'),
(168,11,'Cơ thể người lớp 6: hệ tiêu hoá (2)','kh-co-the-nguoi-lop-6-2','Kể được đường đi của thức ăn, nêu vai trò của răng – dạ dày – ruột và thói quen ăn uống tốt.','de',10,'Thức ăn đi qua miệng, thực quản, dạ dày rồi xuống ruột. Răng nhai nhỏ thức ăn, dạ dày co bóp và tiết dịch tiêu hoá, ruột non hấp thụ chất dinh dưỡng. Cần ăn chậm, nhai kĩ, ăn chín uống sôi.','- Thức ăn từ miệng qua thực quản rồi mới xuống dạ dày.\n- Dạ dày co bóp nhào trộn thức ăn và tiết dịch vị để tiêu hoá.\n- Ruột non là nơi hấp thụ chất dinh dưỡng vào máu nuôi cơ thể.\n- Sau ruột non, thức ăn đi tới ruột già, nơi hấp thụ nước và tạo thành phân.\n- Ăn chậm nhai kĩ giúp thức ăn được nghiền nhỏ, dễ tiêu hoá.',4,'published',6,1,'2026-10-07 21:59:45','2026-10-07 21:59:45'),
(169,11,'Cơ thể người lớp 7: hệ tuần hoàn và hô hấp (1)','kh-co-the-nguoi-lop-7-1','Nêu được vai trò của tim – máu – mạch máu, đường đi của không khí và ý nghĩa của hô hấp.','de',12,'Tim bơm máu đi khắp cơ thể qua mạch máu, máu mang ô-xy và chất dinh dưỡng nuôi tế bào. Không khí đi từ mũi qua khí quản vào phổi; hô hấp giúp lấy ô-xy, thải khí các-bô-níc.','- Tim co bóp liên tục để bơm máu đi nuôi khắp cơ thể.\n- Máu vận chuyển ô-xy và chất dinh dưỡng đến tế bào, đồng thời mang chất thải đi.\n- Đường đi của không khí khi hít vào: mũi → khí quản → phế quản → phổi.\n- Mũi có tác dụng lọc bụi trong không khí trước khi vào phổi.\n- Phổi là nơi trao đổi khí: lấy ô-xy vào máu và thải khí các-bô-níc ra ngoài.',5,'published',7,1,'2026-10-07 21:59:45','2026-10-07 21:59:45'),
(170,11,'Cơ thể người lớp 7: hệ bài tiết và vệ sinh cơ thể (2)','kh-co-the-nguoi-lop-7-2','Kể được các cơ quan bài tiết, nêu vai trò của thận và thói quen giữ vệ sinh cơ thể.','trung_binh',12,'Cơ thể bài tiết chất thải qua thận (nước tiểu), da (mồ hôi) và phổi (hơi thở). Thận lọc máu tạo nước tiểu. Cần uống đủ nước, ăn nhạt, giữ vệ sinh da và răng miệng hằng ngày.','- Thận lọc máu, loại bỏ chất thải tạo thành nước tiểu.\n- Ngoài thận, da bài tiết mồ hôi, phổi thải khí các-bô-níc và hơi nước.\n- Toát mồ hôi giúp thải một phần chất thải và làm mát cơ thể khi nóng.\n- Uống đủ nước giúp thận lọc tốt.\n- Ăn mặn và nhịn tiểu làm hại thận; cần giữ vệ sinh cơ thể hằng ngày.',6,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(171,12,'Chất quanh ta lớp 7: các trạng thái của chất (1)','kh-chat-quanh-ta-lop-7-1','Phân biệt ba trạng thái rắn – lỏng – khí, nêu sự chuyển thể khi nóng lên hoặc lạnh đi.','de',10,'Chất tồn tại ở ba trạng thái: rắn, lỏng, khí. Khi đun nóng, chất rắn nóng chảy thành lỏng, chất lỏng bay hơi thành khí; khi làm lạnh, quá trình diễn ra ngược lại (ngưng tụ, đông đặc).','- Chất tồn tại ở ba trạng thái cơ bản: rắn, lỏng và khí.\n- Đun nóng, nước đá (rắn) nóng chảy thành nước lỏng — đó là sự nóng chảy.\n- Nước bay hơi thành hơi nước khi được đun nóng; ngay ở nhiệt độ thường, nước để lâu cũng bay hơi dần.\n- Hơi nước trong không khí gặp lạnh ngưng tụ thành giọt — như sương đọng trên lá vào buổi sáng.\n- Sự chuyển thể của chất diễn ra khi nhiệt độ thay đổi: nóng chảy, bay hơi, ngưng tụ.',3,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(172,12,'Chất quanh ta lớp 7: nước trong đời sống (2)','kh-chat-quanh-ta-lop-7-2','Nêu vai trò của nước, vòng tuần hoàn của nước trong tự nhiên và cách tiết kiệm nước.','de',12,'Nước chiếm phần lớn cơ thể người và bề mặt Trái Đất. Nước bay hơi lên trời, ngưng tụ thành mây rồi rơi xuống thành mưa – đó là vòng tuần hoàn của nước. Cần tiết kiệm và giữ sạch nguồn nước.','- Nước chiếm khoảng 70% khối lượng cơ thể người.\n- Vòng tuần hoàn của nước trong tự nhiên: bay hơi → ngưng tụ thành mây → mưa rơi xuống → chảy ra sông biển → lại bay hơi.\n- Nước cần cho sinh hoạt và sản xuất; nguồn nước sạch có hạn.\n- Khoá vòi khi không dùng là cách tiết kiệm nước đơn giản nhất.\n- Nước ô nhiễm gây bệnh đường ruột, bệnh ngoài da và giết chết sinh vật dưới nước.',4,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(173,12,'Chất quanh ta lớp 8: hỗn hợp và dung dịch (1)','kh-chat-quanh-ta-lop-8-1','Phân biệt chất nguyên chất với hỗn hợp, hỗn hợp đồng nhất với không đồng nhất; nêu các cách tách chất.','trung_binh',12,'Hỗn hợp gồm hai hay nhiều chất trộn lẫn. Hỗn hợp đồng nhất (dung dịch) như nước đường; không đồng nhất như nước lẫn dầu. Tách chất bằng lọc, cô cạn, chưng cất tùy tính chất.','- Hỗn hợp gồm hai hay nhiều chất trộn lẫn, mỗi chất vẫn giữ tính chất riêng.\n- Dung dịch là hỗn hợp đồng nhất: các thành phần tan đều, không phân biệt được — như nước đường.\n- Dung môi là chất dùng để hoà tan chất khác; trong nước muối, nước là dung môi, muối là chất tan.\n- Cát không tan trong nước nên có thể tách cát ra khỏi nước bằng cách lọc qua giấy lọc.\n- Muốn tách một chất ra khỏi hỗn hợp, cần chọn phương pháp phù hợp với tính chất của các chất.',5,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(174,12,'Chất quanh ta lớp 8: nguyên tử và phân tử (2)','kh-chat-quanh-ta-lop-8-2','Mô tả cấu tạo nguyên tử (hạt nhân – electron), nêu khái niệm phân tử và ví dụ.','trung_binh',12,'Mọi chất đều cấu tạo từ những hạt vô cùng nhỏ. Nguyên tử gồm hạt nhân (proton, nơtron) ở giữa và electron chuyển động xung quanh. Nhiều nguyên tử liên kết tạo thành phân tử, ví dụ phân tử nước H2O.','- Nguyên tử gồm hạt nhân ở giữa (proton, nơtron) và các electron chuyển động xung quanh.\n- Proton mang điện dương, electron mang điện âm, nơtron không mang điện.\n- Mỗi phân tử nước (H2O) gồm 2 nguyên tử hiđrô liên kết với 1 nguyên tử ôxy.\n- Kim cương và than chì đều do nguyên tử cacbon tạo nên, chỉ khác cách sắp xếp các nguyên tử.\n- Mọi chất đều được cấu tạo từ các nguyên tử và phân tử vô cùng nhỏ bé.',6,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(175,13,'Năng lượng lớp 8: các dạng năng lượng (1)','kh-nang-luong-lop-8-1','Kể được các dạng năng lượng, nêu sự chuyển hoá năng lượng và định luật bảo toàn năng lượng.','trung_binh',12,'Năng lượng có nhiều dạng: động năng (do chuyển động), thế năng (do vị trí), nhiệt năng, hoá năng, điện năng. Năng lượng không tự sinh ra hay mất đi, chỉ chuyển từ dạng này sang dạng khác.','- Vật chuyển động có động năng; vật càng nặng, chạy càng nhanh thì động năng càng lớn.\n- Vật ở trên cao có thế năng hấp dẫn; càng cao thì thế năng càng lớn.\n- Khi quả bóng rơi từ trên cao xuống, độ cao giảm (thế năng giảm) và tốc độ tăng (động năng tăng).\n- Năng lượng không tự nhiên sinh ra hay mất đi, chỉ chuyển từ dạng này sang dạng khác — đó là định luật bảo toàn năng lượng.\n- Trong đời sống, các thiết bị biến đổi năng lượng từ dạng này sang dạng khác để phục vụ con người.',3,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(176,13,'Năng lượng lớp 8: công và công suất (2)','kh-nang-luong-lop-8-2','Tính được công cơ học và công suất trong trường hợp đơn giản, biết đơn vị jun và oát.','trung_binh',12,'Khi lực tác dụng làm vật chuyển dời, lực đã sinh công: A = F × s, đơn vị là jun (J). Công thực hiện trong một giây gọi là công suất: P = A / t, đơn vị là oát (W). Máy nào công suất lớn thì làm việc khoẻ hơn.','- Công cơ học A bằng lực F nhân với quãng đường s mà vật đi được theo hướng của lực: A = F × s.\n- Đơn vị công là jun (J); 1 J là công của lực 1 N làm vật đi được 1 m.\n- Ví dụ: kéo vật với lực 100 N đi được 5 m thì công thực hiện là 500 J.\n- Công suất P = A / t cho biết trong một giây thực hiện được bao nhiêu công.\n- Máy có công suất lớn làm được nhiều công trong cùng một thời gian.',4,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(177,13,'Năng lượng lớp 9: dòng điện và mạch điện (1)','kh-nang-luong-lop-9-1','Nêu khái niệm dòng điện, cường độ dòng điện, hiệu điện thế và điều kiện có dòng điện trong mạch.','trung_binh',12,'Dòng điện là dòng chuyển dời có hướng của các điện tích. Cường độ dòng điện đo bằng ampe kế, đơn vị ampe (A); hiệu điện thế đo bằng vôn kế, đơn vị vôn (V). Muốn có dòng điện, mạch phải kín và có nguồn điện.','- Dòng điện là dòng chuyển dời có hướng của các hạt mang điện (electron).\n- Muốn có dòng điện, mạch điện phải kín và phải có nguồn điện như pin, ắc quy.\n- Cường độ dòng điện được đo bằng ampe kế, đơn vị là ampe (A).\n- Hiệu điện thế được đo bằng vôn kế, đơn vị là vôn (V).\n- Cường độ dòng điện càng lớn thì tác dụng của dòng điện càng mạnh, nhưng phải dùng đúng mức an toàn.',5,'published',9,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(178,13,'Năng lượng lớp 9: điện năng và an toàn điện (2)','kh-nang-luong-lop-9-2','Tính công suất điện và điện năng tiêu thụ, nêu các quy tắc an toàn khi dùng điện.','kho',12,'Công suất điện P = U × I, đơn vị oát (W). Điện năng tiêu thụ tính bằng ki-lô-oát giờ (kWh), tức \"số điện\". Dùng điện phải an toàn: không chạm tay ướt vào ổ điện, ngắt điện trước khi sửa chữa, dùng dây dẫn đúng tiêu chuẩn.','- Công suất điện P bằng hiệu điện thế U nhân với cường độ dòng điện I.\n- Trên bóng đèn ghi “220 V – 100 W”: 220 V là hiệu điện thế định mức, 100 W là công suất định mức khi dùng đúng 220 V.\n- “Số điện” công tơ đo chính là kilôoát giờ (kWh): 1 số điện là điện năng của thiết bị 1000 W dùng trong 1 giờ.\n- Tay ướt dẫn điện tốt nên tuyệt đối không chạm vào ổ điện, công tắc khi tay ướt.\n- Sử dụng điện an toàn: không dùng dây điện hở, ngắt nguồn khi sửa chữa thiết bị điện.',6,'published',9,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(179,14,'Lịch sử lớp 6: nước Văn Lang (1)','ls-dung-nuoc-lop-6-1','Nêu được thời gian, người đứng đầu, kinh đô và tổ chức của nước Văn Lang – nhà nước đầu tiên của ta.','de',10,'Khoảng thế kỉ VII TCN, các bộ lạc hợp nhất thành nước Văn Lang do Hùng Vương đứng đầu, kinh đô ở Phong Châu (Phú Thọ ngày nay). Cả nước chia thành 15 bộ. Đây là nhà nước đầu tiên trong lịch sử Việt Nam.','- Khoảng thế kỉ VII TCN, các bộ lạc hợp nhất thành nước Văn Lang.\n- Hùng Vương là người đứng đầu nước Văn Lang, được nhân dân tôn thờ.\n- Kinh đô Văn Lang đặt ở Phong Châu, thuộc tỉnh Phú Thọ ngày nay.\n- Cả nước chia thành 15 bộ, đứng đầu mỗi bộ là Lạc tướng.\n- Đời sống người Văn Lang gắn với nghề trồng lúa nước và trống đồng Đông Sơn.',3,'published',6,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(180,14,'Lịch sử lớp 6: An Dương Vương và nước Âu Lạc (2)','ls-dung-nuoc-lop-6-2','Kể được sự ra đời của nước Âu Lạc, thành Cổ Loa và truyền thuyết nỏ thần.','de',10,'Năm 208 TCN, Thục Phán – An Dương Vương hợp nhất Âu Việt và Lạc Việt thành nước Âu Lạc, đóng đô ở Cổ Loa (Hà Nội). Ông cho xây thành Cổ Loa hình xoáy ốc và chế tạo nỏ thần bắn một lúc nhiều mũi tên.','- Năm 208 TCN, Thục Phán (An Dương Vương) lập nước Âu Lạc, thay thế nước Văn Lang.\n- An Dương Vương đóng đô ở Cổ Loa, nay thuộc Hà Nội.\n- Thành Cổ Loa xây theo hình xoáy ốc, gồm nhiều vòng thành vững chắc.\n- Truyền thuyết kể An Dương Vương được thần Kim Quy cho móng rùa làm lẫy nỏ thần.\n- Nước Âu Lạc có quân đội mạnh, song sau này bị Triệu Đà thôn tính.',4,'published',6,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(181,14,'Lịch sử lớp 7: khởi nghĩa Hai Bà Trưng (1)','ls-dung-nuoc-lop-7-1','Trình bày nguyên nhân, diễn biến chính và kết quả của cuộc khởi nghĩa Hai Bà Trưng năm 40.','de',12,'Năm 40, Trưng Trắc và Trưng Nhị phất cờ khởi nghĩa ở Mê Linh chống ách đô hộ nhà Hán. Nghĩa quân nhanh chóng làm chủ cả nước, Trưng Trắc lên làm vua. Năm 43, nhà Hán cử Mã Viện sang đàn áp, cuộc khởi nghĩa thất bại nhưng nêu cao tinh thần yêu nước.','- Mùa xuân năm 40, Hai Bà Trưng phất cờ khởi nghĩa ở Mê Linh (nay thuộc Hà Nội).\n- Nguyên nhân: nhà Hán cai trị tàn bạo, bắt dân nộp thuế nặng.\n- Nghĩa quân nhanh chóng làm chủ Mê Linh, Cổ Loa, Luy Lâu.\n- Sau thắng lợi, Trưng Trắc lên ngôi vua (Trưng Vương), đóng đô ở Mê Linh.\n- Đây là cuộc khởi nghĩa đầu tiên của nhân dân ta chống ách đô hộ phương Bắc.',5,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(182,14,'Lịch sử lớp 7: Ngô Quyền và chiến thắng Bạch Đằng (2)','ls-dung-nuoc-lop-7-2','Trình bày trận Bạch Đằng năm 938 và ý nghĩa mở đầu thời kì độc lập của dân tộc.','trung_binh',12,'Năm 938, Ngô Quyền đóng cọc gỗ đầu bịt sắt xuống lòng sông Bạch Đằng, dụ quân Nam Hán vào trận địa lúc thuỷ triều lên rồi đánh úp khi nước rút. Quân giặc tan vỡ, chấm dứt hơn một nghìn năm Bắc thuộc, mở đầu thời kì độc lập tự chủ.','- Năm 938, Ngô Quyền chỉ huy quân ta đánh tan quân Nam Hán trên sông Bạch Đằng.\n- Kế sách: đóng cọc gỗ xuống lòng sông, nhử giặc vào trận địa khi nước lên rồi đánh úp khi nước rút.\n- Quân Nam Hán do Lưu Hoằng Tháo chỉ huy bị tiêu diệt hoàn toàn.\n- Chiến thắng Bạch Đằng chấm dứt thời kì Bắc thuộc hơn 1000 năm.\n- Thắng lợi mở ra kỉ nguyên độc lập, tự chủ lâu dài của dân tộc.',6,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(183,15,'Lịch sử lớp 7: Đinh Bộ Lĩnh dẹp loạn 12 sứ quân (1)','ls-dinh-tien-le-lop-7-1','Trình bày quá trình Đinh Bộ Lĩnh thống nhất đất nước và sự ra đời của nước Đại Cồ Việt.','de',10,'Sau khi Ngô Quyền mất, đất nước rơi vào loạn 12 sứ quân. Đinh Bộ Lĩnh dẹp loạn, thống nhất đất nước, năm 968 lên ngôi hoàng đế, đặt tên nước là Đại Cồ Việt, đóng đô ở Hoa Lư (Ninh Bình), lấy niên hiệu Thái Bình.','- Sau khi Ngô Quyền mất, đất nước rơi vào tình trạng cát cứ của các sứ quân.\n- Đinh Bộ Lĩnh dẹp loạn 12 sứ quân, thống nhất đất nước năm 968.\n- Đinh Bộ Lĩnh lên ngôi hoàng đế (Đinh Tiên Hoàng), đặt tên nước là Đại Cồ Việt.\n- Kinh đô đặt ở Hoa Lư (Ninh Bình) — vùng núi hiểm trở, thuận lợi phòng thủ.\n- Nhà Đinh là triều đại phong kiến đầu tiên, mở đầu thời kì độc lập tự chủ.',3,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(184,15,'Lịch sử lớp 7: Lê Hoàn và kháng chiến chống Tống (2)','ls-dinh-tien-le-lop-7-2','Trình bày sự ra đời của nhà Tiền Lê và chiến thắng chống quân Tống năm 981.','de',12,'Năm 980, trước nguy cơ quân Tống xâm lược, Lê Hoàn – Thập đạo tướng quân được tôn lên làm vua, lập nhà Tiền Lê. Năm 981, ông chỉ huy quân dân đánh tan quân Tống trên sông Bạch Đằng và ở Chi Lăng, bảo vệ vững chắc nền độc lập.','- Trước khi lên ngôi, Lê Hoàn là Thập đạo tướng quân, chỉ huy quân đội nhà Đinh.\n- Năm 980, trước hoạ ngoại xâm, Lê Hoàn được tôn lên làm vua, lập nhà Tiền Lê.\n- Năm 981, Lê Hoàn chỉ huy đánh tan quân Tống ở Bạch Đằng và Chi Lăng.\n- Nhà Tiền Lê tiếp tục đóng đô ở Hoa Lư như nhà Đinh.\n- Thắng lợi năm 981 bảo vệ vững chắc nền độc lập còn non trẻ của đất nước.',4,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(185,15,'Lịch sử lớp 8: tổ chức nhà nước Đinh – Tiền Lê (1)','ls-dinh-tien-le-lop-8-1','Nêu được bộ máy nhà nước thời Đinh – Tiền Lê: vua, quan văn – võ, quân đội và luật pháp.','trung_binh',12,'Nhà nước Đinh – Tiền Lê do vua đứng đầu, giúp việc có thái sư, đại tổng quản; chia quan văn, quan võ. Quân đội gồm cấm quân bảo vệ kinh thành và quân các lộ. Nhà Đinh ban hành hình luật để giữ kỉ cương – bước đầu xây dựng nhà nước phong kiến độc lập.','- Vua là người đứng đầu nhà nước, nắm mọi quyền hành.\n- Giúp việc cho vua có các chức quan: thái sư, đại tổng quản, chia thành quan văn và quan võ.\n- Quân đội gồm cấm quân bảo vệ kinh thành và quân đóng ở các lộ, phủ.\n- Nhà Đinh ban hành hình luật — bộ luật thành văn đầu tiên để trừng trị kẻ có tội, giữ kỉ cương đất nước.\n- Bộ máy nhà nước tuy còn đơn giản nhưng đã mang tính chất nhà nước phong kiến tập quyền.',5,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(186,15,'Lịch sử lớp 8: kinh tế và văn hoá thời Đinh – Tiền Lê (2)','ls-dinh-tien-le-lop-8-2','Nêu nét chính về nông nghiệp, thủ công nghiệp, tiền tệ và đời sống văn hoá thời Đinh – Tiền Lê.','trung_binh',12,'Thời Đinh – Tiền Lê, nông nghiệp là gốc: nhà nước khuyến khích khai hoang, đắp đê. Thủ công nghiệp phát triển, đúc tiền đồng Thái Bình – đồng tiền đầu tiên của nước ta. Phật giáo thịnh hành, nhiều chùa tháp được xây dựng.','- Nông nghiệp trồng lúa nước là ngành kinh tế chính; nhà nước khuyến khích khai hoang mở rộng ruộng đồng.\n- Nhà Đinh cho đúc tiền đồng Thái Bình — đồng tiền đầu tiên của Việt Nam.\n- Thủ công nghiệp phát triển: đúc đồng, rèn sắt, dệt vải, làm gốm.\n- Phật giáo rất thịnh hành; nhiều chùa tháp được xây dựng, có chức Tăng thống đứng đầu tăng giới.\n- Kinh tế, văn hoá bước đầu phát triển tạo nền tảng cho các triều đại sau.',6,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(187,16,'Lịch sử lớp 8: ba lần kháng chiến chống quân Nguyên – Mông (1)','ls-chong-nguyen-mong-lop-8-1','Nêu được thời gian, đường lối kháng chiến và kết quả của ba lần đánh quân Nguyên – Mông.','trung_binh',12,'Quân Mông – Nguyên ba lần xâm lược Đại Việt (1258, 1285, 1287–1288) đều bị đánh bại. Nhà Trần thực hiện \"vườn không nhà trống\", rút lui bảo toàn lực lượng rồi phản công. Hội nghị Diên Hồng thể hiện quyết tâm \"đánh\" của toàn dân.','- Quân Mông – Nguyên xâm lược Đại Việt 3 lần: 1258, 1285 và 1287–1288.\n- Năm 1258, Trần Thủ Độ chỉ huy đánh tan quân Mông Cổ ở Đông Bộ Đầu.\n- Kế sách “vườn không nhà trống”: quân dân ta rút lui, mang theo lương thực khiến giặc thiếu ăn, ốm đau.\n- Hội nghị Diên Hồng: các bô lão cả nước đồng thanh hô “đánh”, thể hiện ý chí quyết chiến.\n- Thắng lợi của ba lần kháng chiến bắt nguồn từ sức mạnh đoàn kết toàn dân.',3,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(188,16,'Lịch sử lớp 8: trận Bạch Đằng năm 1288 (2)','ls-chong-nguyen-mong-lop-8-2','Trình bày trận Bạch Đằng 1288: kế sách của Trần Hưng Đạo, diễn biến và kết quả.','trung_binh',12,'Năm 1288, Trần Hưng Đạo học kế của Ngô Quyền: đóng cọc gỗ xuống sông Bạch Đằng, nhử quân Nguyên vào lúc nước lên rồi đánh úp khi nước rút. Ô Mã Nhi bị bắt sống, Thoát Hoan chui ống đồng chạy trốn. Chiến thắng kết thúc cuộc kháng chiến.','- Trận Bạch Đằng năm 1288 do Trần Hưng Đạo (Trần Quốc Tuấn) tổng chỉ huy.\n- Trần Hưng Đạo học kế đóng cọc gỗ dưới lòng sông của Ngô Quyền năm 938.\n- Tướng giặc Ô Mã Nhi bị bắt sống; Thoát Hoan phải chui vào ống đồng để chạy trốn.\n- Trận Bạch Đằng tiêu diệt đạo thuỷ binh giặc, kết thúc cuộc kháng chiến lần 3.\n- Đây là một trong những chiến thắng thuỷ chiến vĩ đại nhất lịch sử dân tộc.',4,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(189,16,'Lịch sử lớp 9: Trần Hưng Đạo và Hịch tướng sĩ (1)','ls-chong-nguyen-mong-lop-9-1','Nêu công lao của Trần Hưng Đạo, nội dung và ý nghĩa của Hịch tướng sĩ.','trung_binh',12,'Trần Hưng Đạo (Trần Quốc Tuấn) là tổng chỉ huy kháng chiến chống Nguyên – Mông. Khoảng năm 1284, ông viết Hịch tướng sĩ kêu gọi tướng sĩ đoàn kết đánh giặc, thể hiện lòng yêu nước nồng nàn. Ông còn soạn Binh thư yếu lược, Vạn Kiếp tông bí truyền thư.','- Trần Hưng Đạo tên thật là Trần Quốc Tuấn, được phong Hưng Đạo Vương.\n- Khoảng năm 1284, trước khi giặc sang lần 2, ông viết “Hịch tướng sĩ”.\n- Bài hịch khích lệ lòng yêu nước, kêu gọi tướng sĩ đồng lòng đánh giặc.\n- Ngoài “Hịch tướng sĩ”, ông còn soạn “Binh thư yếu lược” và “Vạn Kiếp tông bí truyền thư” về nghệ thuật quân sự.\n- Trần Hưng Đạo được nhân dân tôn thờ là Đức Thánh Trần.',5,'published',9,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(190,16,'Lịch sử lớp 9: ý nghĩa lịch sử của kháng chiến chống Nguyên – Mông (2)','ls-chong-nguyen-mong-lop-9-2','Đánh giá ý nghĩa lịch sử và rút ra bài học từ thắng lợi của ba lần kháng chiến.','kho',12,'Thắng lợi đập tan tham vọng xâm lược của đế quốc Nguyên – Mông, bảo vệ vững chắc nền độc lập và toàn vẹn lãnh thổ. Bài học: đoàn kết toàn dân, đường lối kháng chiến đúng đắn, nghệ thuật quân sự \"lấy yếu chống mạnh, lấy ít địch nhiều\" của nhà Trần.','- Thắng lợi đập tan ý đồ xâm lược của đế quốc Nguyên – Mông, giữ vững độc lập dân tộc.\n- Bài học lớn nhất: sức mạnh đoàn kết toàn dân, từ vua quan đến các bô lão và nhân dân.\n- Nghệ thuật quân sự nhà Trần: “lấy yếu chống mạnh, lấy ít địch nhiều”.\n- Đại Việt là một trong số ít nước đánh bại Mông – Nguyên, góp phần bảo vệ cả khu vực.\n- Thắng lợi hun đúc lòng tự hào và ý chí quật cường của dân tộc.',6,'published',9,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(191,28,'Ngữ văn lớp 6: danh từ (1)','nv-tu-loai-lop-6-1','Nhận biết danh từ, phân biệt danh từ chung – danh từ riêng và cấu tạo cụm danh từ.','de',10,'Danh từ là từ chỉ người, vật, hiện tượng, khái niệm. Danh từ chung chỉ loại sự vật (học sinh, con sông); danh từ riêng chỉ tên riêng (Hà Nội, sông Hồng) và viết hoa. Cụm danh từ gồm danh từ trung tâm và các thành tố phụ (ví dụ: \"những bông hoa đẹp\").','- Danh từ chỉ người, vật, hiện tượng, khái niệm: học sinh, bàn ghế, tình bạn.\n- Danh từ riêng chỉ tên riêng của người, địa danh... và được viết hoa: Hà Nội.\n- Danh từ chung chỉ loại sự vật: quyển sách.\n- Cụm danh từ gồm danh từ trung tâm (bông hoa) và các thành tố phụ (những, đẹp).\n- Nắm vững danh từ giúp gọi tên sự vật chính xác trong giao tiếp và viết văn.',3,'published',6,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(192,28,'Ngữ văn lớp 6: động từ và tính từ (2)','nv-tu-loai-lop-6-2','Nhận biết động từ, tính từ; biết cấu tạo cụm động từ và cụm tính từ.','de',10,'Động từ chỉ hành động, trạng thái của sự vật (chạy, đọc, ngủ). Tính từ chỉ đặc điểm, tính chất (đẹp, cao, nhanh). Cụm động từ và cụm tính từ mở rộng ý nghĩa cho từ trung tâm, ví dụ: \"đang chạy rất nhanh\", \"rất đẹp và hiền\".','- Động từ chỉ hành động, trạng thái: chạy, đọc, ngủ, suy nghĩ.\n- Tính từ chỉ đặc điểm, tính chất: đẹp, cao, nhanh, hiền lành.\n- “Đọc sách” chỉ hành động nên “đọc” là động từ; “quyển sách”, “bàn ghế” là danh từ.\n- Cụm tính từ lấy tính từ làm trung tâm: “rất đẹp và hiền”.\n- Động từ và tính từ thường làm vị ngữ, giúp câu văn đầy đủ ý nghĩa.',4,'published',6,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(193,28,'Ngữ văn lớp 7: nhận diện từ loại trong câu (1)','nv-tu-loai-lop-7-1','Xác định đúng từ loại của từ trong ngữ cảnh câu cụ thể, tránh nhầm lẫn.','de',12,'Một từ có thể thuộc từ loại khác nhau tùy ngữ cảnh: \"đá\" trong \"quả bóng đá\" là danh từ, trong \"anh ấy đá bóng\" là động từ. Muốn xác định đúng phải đặt từ vào câu và xét nghĩa, chức năng của nó.','- Một từ có thể thuộc từ loại khác nhau tùy ngữ cảnh, phải xét trong câu cụ thể.\n- Trong “quả bóng đá lăn tròn”, “đá” chỉ chất liệu làm bóng nên là danh từ.\n- Trong “anh ấy đá bóng rất giỏi”, “đá” chỉ hành động nên là động từ.\n- Trong “cô ấy hát hay”, “hay” chỉ đặc điểm của tiếng hát nên là tính từ.\n- Không thể xác định đúng từ loại nếu tách từ ra khỏi câu.',5,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(194,28,'Ngữ văn lớp 7: lượng từ và quan hệ từ (2)','nv-tu-loai-lop-7-2','Nhận biết lượng từ (những, các, mỗi) và quan hệ từ (và, với, nhưng, của).','trung_binh',12,'Lượng từ chỉ lượng ít nhiều của sự vật: những, các (số nhiều), mỗi, một (số ít). Quan hệ từ nối các từ ngữ trong câu, biểu thị quan hệ: và, với, cùng (nối), nhưng, mà (tương phản), của, ở, từ (quan hệ sở hữu, nơi chốn).','- Lượng từ chỉ lượng ít nhiều: những, các, mỗi, một, vài.\n- Quan hệ từ nối các từ ngữ với nhau: và, với, cùng, nhưng, của.\n- Trong “những bông hoa”, “những” chỉ số nhiều, là lượng từ đứng trước danh từ.\n- Trong “tôi đi học cùng bạn”, “cùng” nối “tôi” với “bạn”, biểu thị quan hệ cùng nhau.\n- Dùng đúng lượng từ, quan hệ từ giúp câu văn rõ ràng, mạch lạc.',6,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(195,30,'Ngữ văn lớp 7: so sánh (1)','nv-bien-phap-tu-tu-lop-7-1','Nhận biết phép so sánh, chỉ ra các vế và từ so sánh, nêu tác dụng.','de',12,'So sánh là đối chiếu sự vật này với sự vật khác có nét tương đồng để làm nổi bật hình ảnh. Mô hình: A như B (ví dụ: \"Trẻ em như búp trên cành\"). Từ so sánh thường gặp: như, tựa, bằng, là. So sánh có hai kiểu: ngang bằng và không ngang bằng.','- So sánh là đối chiếu hai sự vật có nét tương đồng để làm nổi bật hình ảnh.\n- Từ so sánh thường gặp: như, tựa, bằng, là.\n- Trong “trẻ em như búp trên cành”, “như” là từ so sánh.\n- Tác dụng: so sánh giúp hình ảnh trở nên cụ thể, sinh động và gợi cảm hơn.\n- So sánh gồm hai vế: vế được so sánh và vế dùng để so sánh.',3,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(196,30,'Ngữ văn lớp 7: nhân hoá (2)','nv-bien-phap-tu-tu-lop-7-2','Nhận biết phép nhân hoá, nêu các cách nhân hoá và tác dụng.','de',12,'Nhân hoá là gán đặc điểm của con người (hành động, tình cảm, cách xưng hô) cho sự vật để chúng trở nên sinh động, gần gũi. Cách nhân hoá: dùng từ chỉ người gọi vật, dùng động từ/tính từ của người cho vật, trò chuyện với vật như với người.','- Nhân hoá là gán hành động, tình cảm, cách xưng hô của người cho vật.\n- Cách nhân hoá: dùng từ ngữ vốn chỉ người để gọi, tả vật — như gọi gió là “chị”, gán hành động “mơn man”.\n- Nhân hoá khiến sự vật trở nên có hồn, gần gũi với con người.\n- Nhân hoá thường đi cùng với so sánh để tăng sức gợi hình.\n- Nhận diện nhân hoá giúp cảm thụ cái hay của câu văn, câu thơ.',4,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(197,30,'Ngữ văn lớp 8: ẩn dụ (1)','nv-bien-phap-tu-tu-lop-8-1','Nhận biết ẩn dụ, phân biệt bốn kiểu ẩn dụ và nêu tác dụng.','trung_binh',12,'Ẩn dụ là gọi tên sự vật này bằng tên sự vật khác có nét tương đồng, nhưng lược bỏ từ so sánh. Bốn kiểu: ẩn dụ hình thức (về hình dạng), cách thức (về cách tiến hành), phẩm chất (về tính chất), chuyển đổi cảm giác (từ giác quan này sang giác quan khác).','- Ẩn dụ giống so sánh nhưng không dùng từ so sánh.\n- “Thuyền – bến” ẩn dụ cho người đi – người ở lại, không dùng từ “như”.\n- Trong “Đêm nay Bác không ngủ”, “người cha” ẩn dụ chỉ Bác Hồ.\n- Phân biệt: so sánh nói “A như B”; ẩn dụ gọi thẳng A bằng tên của B.\n- Ẩn dụ làm lời thơ hàm súc, giàu sức gợi.',5,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(198,30,'Ngữ văn lớp 8: hoán dụ (2)','nv-bien-phap-tu-tu-lop-8-2','Nhận biết hoán dụ, phân biệt hoán dụ với ẩn dụ.','trung_binh',12,'Hoán dụ là gọi tên sự vật bằng tên sự vật khác có quan hệ gần gũi: lấy bộ phận chỉ toàn thể (\"bàn tay\" chỉ người lao động), vật chứa chỉ vật bị chứa (\"nhà\" chỉ gia đình), dấu hiệu chỉ sự vật (\"áo nâu\" chỉ người nông dân). Ẩn dụ dựa trên tương đồng, hoán dụ dựa trên gần gũi.','- Hoán dụ dựa trên quan hệ gần gũi giữa các sự vật.\n- “Bàn tay” lấy bộ phận chỉ toàn thể (người lao động) là hoán dụ.\n- “Áo nâu” chỉ người nông dân, “áo xanh” chỉ bộ đội: lấy dấu hiệu chỉ sự vật.\n- Phân biệt: ẩn dụ dựa trên nét tương đồng (thuyền – người đi); hoán dụ dựa trên quan hệ gần gũi (bàn tay – người).\n- Hoán dụ làm câu văn ngắn gọn mà giàu hình ảnh.',6,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(199,31,'Ngữ văn lớp 8: bài văn miêu tả (1)','nv-van-mieu-ta-lop-8-1','Nêu bố cục bài văn miêu tả, cách quan sát và trình tự miêu tả.','trung_binh',12,'Bài văn miêu tả gồm ba phần: mở bài (giới thiệu đối tượng), thân bài (miêu tả chi tiết), kết bài (cảm nghĩ). Muốn tả hay phải quan sát kĩ bằng nhiều giác quan và sắp xếp theo trình tự hợp lí: từ bao quát đến chi tiết hoặc theo trình tự không gian, thời gian.','- Bố cục 3 phần: mở bài giới thiệu, thân bài miêu tả chi tiết, kết bài nêu cảm nghĩ.\n- Muốn tả hay, trước hết phải quan sát kĩ bằng mắt, tai, mũi... để miêu tả chân thực, sinh động.\n- Khi tả cảnh, trình tự hợp lí là từ bao quát toàn cảnh rồi đi vào từng chi tiết cụ thể.\n- Kết bài bộc lộ tình cảm, ấn tượng sâu sắc về đối tượng được tả.\n- Chọn chi tiết tiêu biểu, tránh liệt kê dàn trải.',3,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(200,31,'Ngữ văn lớp 8: dấu câu trong văn bản (2)','nv-van-mieu-ta-lop-8-2','Dùng đúng dấu phẩy, dấu chấm, dấu hai chấm, dấu chấm hỏi – chấm than và dấu ngoặc kép.','trung_binh',12,'Dấu phẩy ngăn cách các bộ phận trong câu; dấu chấm kết thúc câu kể; dấu hai chấm báo hiệu lời giải thích hoặc lời dẫn; dấu chấm hỏi dùng cuối câu hỏi, dấu chấm than cuối câu cảm thán; dấu ngoặc kép đánh dấu lời nói trực tiếp hoặc từ ngữ được trích dẫn.','- Dấu phẩy ngăn cách các thành phần câu và các vế câu.\n- Dấu hai chấm báo hiệu phần giải thích, liệt kê hoặc dẫn lời nói trực tiếp.\n- Dấu ngoặc kép đánh dấu lời nói trực tiếp và từ ngữ được trích dẫn.\n- Khi liệt kê các thành phần cùng chức năng, phải ngăn cách bằng dấu phẩy.\n- Đặt sai dấu câu có thể làm thay đổi nghĩa của câu.',4,'published',8,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(201,31,'Ngữ văn lớp 9: văn tả người (1)','nv-van-mieu-ta-lop-9-1','Nêu yêu cầu của bài văn tả người: tả chân dung, tả hoạt động, kết hợp kể và biểu cảm.','trung_binh',12,'Tả người cần làm nổi bật chân dung (hình dáng, khuôn mặt, trang phục) và hoạt động, việc làm tiêu biểu. Chọn chi tiết tiêu biểu, kết hợp kể chuyện và bộc lộ tình cảm, tránh liệt kê chung chung.','- Tả người cần làm nổi bật chân dung (hình dáng, khuôn mặt) và hoạt động tiêu biểu.\n- Chi tiết tiêu biểu gợi được tính cách, cuộc đời của nhân vật.\n- Ngoài tả, cần kết hợp kể việc làm và bộc lộ tình cảm để nhân vật sống động.\n- Tránh liệt kê chung chung khiến bài văn nhạt nhoà, thiếu ấn tượng.\n- Nên sắp xếp chi tiết theo trình tự hợp lí: từ ngoại hình đến tính cách, việc làm.',5,'published',9,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(202,31,'Ngữ văn lớp 9: văn tả cảnh, tả vật (2)','nv-van-mieu-ta-lop-9-2','Nêu yêu cầu của bài văn tả cảnh, tả con vật, đồ vật: trình tự, chi tiết và cảm xúc.','kho',12,'Tả cảnh cần bao quát toàn cảnh rồi đi vào chi tiết theo trình tự không gian hoặc thời gian, lồng cảm xúc của người viết. Tả con vật, đồ vật cần nêu hình dáng, đặc điểm nổi bật và ích lợi; dùng so sánh, nhân hoá để bài văn sinh động.','- Tả cảnh cần trình tự hợp lí: bao quát → chi tiết, hoặc theo không gian, thời gian.\n- Tả con vật: chú ý hình dáng, màu sắc, đặc điểm nổi bật, ích lợi hoặc kỉ niệm.\n- Tả đồ vật: từ hình dáng chung đến từng bộ phận, rồi công dụng và kỉ niệm gắn bó.\n- Cảm xúc của người viết làm cảnh vật có hồn, bài văn thêm sâu sắc.\n- Kết hợp quan sát tinh tế với tưởng tượng, so sánh để bài văn sinh động.',6,'published',9,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(203,50,'Địa lý lớp 6: châu Á (1)','dl-chau-luc-dai-duong-lop-6-1','Nêu vị trí, diện tích, đặc điểm địa hình và dân cư của châu Á.','de',10,'Châu Á là châu lục lớn nhất thế giới, nằm chủ yếu ở bán cầu Bắc. Địa hình đa dạng: có dãy Hi-ma-lay-a với đỉnh Ê-vơ-rét cao nhất thế giới, nhiều đồng bằng và hoang mạc rộng lớn. Châu Á cũng đông dân nhất, tập trung ở Đông Á và Nam Á.','- Châu Á nằm chủ yếu ở bán cầu Bắc và bán cầu Đông.\n- Dãy Hi-ma-lay-a có đỉnh Ê-vơ-rét cao 8.848m, cao nhất thế giới.\n- Dân cư châu Á tập trung đông ở Đông Á (Trung Quốc) và Nam Á (Ấn Độ).\n- Hoang mạc Gô-bi ở Trung Á là hoang mạc lớn của châu Á; Xa-ha-ra ở châu Phi.\n- Châu Á có địa hình đa dạng và dân cư đông đúc nhất thế giới.',3,'published',6,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(204,50,'Địa lý lớp 6: các châu lục khác (2)','dl-chau-luc-dai-duong-lop-6-2','Kể tên và nêu nét nổi bật của châu Âu, châu Phi, châu Mỹ, châu Đại Dương, châu Nam Cực.','de',10,'Ngoài châu Á còn 6 châu lục: châu Âu (kinh tế phát triển), châu Phi (hoang mạc Xa-ha-ra, sông Nin), Bắc Mỹ và Nam Mỹ, châu Đại Dương (nhỏ nhất) và châu Nam Cực (lạnh nhất, quanh năm băng tuyết).','- Châu Đại Dương là châu lục nhỏ nhất, gồm nước Úc và các đảo Thái Bình Dương.\n- Châu Nam Cực nằm quanh cực Nam, lạnh nhất Trái Đất, quanh năm bao phủ băng tuyết.\n- Hoang mạc Xa-ha-ra ở Bắc Phi là hoang mạc nóng lớn nhất thế giới.\n- Dãy An-đét chạy dọc bờ tây Nam Mỹ là dãy núi dài nhất thế giới.\n- Mỗi châu lục có những kỷ lục địa lí riêng đáng nhớ.',4,'published',6,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(205,50,'Địa lý lớp 7: châu Âu (1)','dl-chau-luc-dai-duong-lop-7-1','Nêu đặc điểm địa hình, khí hậu và kinh tế của châu Âu.','de',12,'Châu Âu có địa hình chủ yếu là đồng bằng và núi thấp, khí hậu ôn hoà nhờ dòng biển nóng. Đây là châu lục có nền kinh tế phát triển cao, công nghiệp và dịch vụ hiện đại, nhiều nước thuộc Liên minh châu Âu (EU).','- Địa hình châu Âu chủ yếu là đồng bằng và núi thấp, thuận lợi cho sinh sống.\n- Dòng biển nóng Bắc Đại Tây Dương làm khí hậu Tây Âu ôn hòa, ấm áp.\n- Dãy An-pơ ở Nam Âu là dãy núi trẻ, cao, có nhiều đỉnh tuyết phủ.\n- EU là liên minh kinh tế, chính trị gồm nhiều nước châu Âu.\n- Thiên nhiên và khí hậu thuận lợi giúp châu Âu phát triển sớm.',5,'published',7,1,'2026-10-07 21:59:46','2026-10-07 21:59:46'),
(206,50,'Địa lý lớp 7: châu Phi và châu Mỹ (2)','dl-chau-luc-dai-duong-lop-7-2','Nêu nét nổi bật về tự nhiên và dân cư của châu Phi và châu Mỹ.','trung_binh',12,'Châu Phi có hoang mạc Xa-ha-ra lớn nhất thế giới, sông Nin dài nhất thế giới, khí hậu nóng. Châu Mỹ gồm Bắc Mỹ (kinh tế phát triển) và Nam Mỹ (rừng A-ma-dôn rộng lớn, dãy An-đét dài nhất thế giới).','- Sông Nin ở châu Phi dài khoảng 6.650km, là sông dài nhất thế giới.\n- Rừng A-ma-dôn ở Nam Mỹ được mệnh danh là lá phổi xanh của Trái Đất.\n- Kênh đào Pa-na-ma nối Thái Bình Dương với Đại Tây Dương, rút ngắn đường biển.\n- Hoa Kì là nền kinh tế lớn nhất châu Mỹ và hàng đầu thế giới.\n- Châu Phi và châu Mỹ có nhiều kỷ lục tự nhiên thế giới.',6,'published',7,1,'2026-10-07 21:59:47','2026-10-07 21:59:47'),
(207,52,'Địa lý lớp 7: thủ đô Đông Nam Á (1)','dl-thu-do-cac-nuoc-lop-7-1','Nhớ thủ đô của các nước Đông Nam Á, đặc biệt các nước láng giềng.','de',10,'Đông Nam Á có 11 nước. Thủ đô các nước tiêu biểu: Việt Nam – Hà Nội, Lào – Viêng Chăn, Campuchia – Phnom Penh, Thái Lan – Bangkok, Myanmar – Naypyidaw, Indonesia – Jakarta, Malaysia – Kuala Lumpur, Singapore – Singapore, Philippines – Manila, Brunei – Bandar Seri Begawan, Đông Timor – Dili.','- Viêng Chăn là thủ đô của Lào, nước láng giềng phía tây Việt Nam.\n- Phnom Penh là thủ đô của Campuchia.\n- Bangkok là thủ đô và thành phố lớn nhất Thái Lan.\n- Jakarta trên đảo Java là thủ đô của Indonesia.\n- Ghi nhớ thủ đô các nước Đông Nam Á, khu vực của Việt Nam.',3,'published',7,1,'2026-10-07 21:59:47','2026-10-07 21:59:47'),
(208,52,'Địa lý lớp 7: thủ đô châu Á (2)','dl-thu-do-cac-nuoc-lop-7-2','Nhớ thủ đô các nước Đông Á, Nam Á và Tây Á tiêu biểu.','de',12,'Đông Á: Nhật Bản – Tokyo, Trung Quốc – Bắc Kinh, Hàn Quốc – Seoul, Mông Cổ – Ulan Bator. Nam Á: Ấn Độ – New Delhi. Tây Á: Thổ Nhĩ Kỳ – Ankara, Ả Rập Xê Út – Riyadh. Học theo nhóm vùng sẽ dễ nhớ hơn.','- Tokyo là thủ đô của Nhật Bản; Bắc Kinh là thủ đô của Trung Quốc.\n- Seoul là thủ đô của Hàn Quốc; New Delhi là thủ đô của Ấn Độ.\n- Thượng Hải là thành phố lớn nhất Trung Quốc nhưng không phải thủ đô; Mumbai cũng vậy với Ấn Độ.\n- Thủ đô là nơi đặt cơ quan đầu não của quốc gia.\n- Phân biệt thủ đô với thành phố lớn nhất của một nước.',4,'published',7,1,'2026-10-07 21:59:47','2026-10-07 21:59:47'),
(209,52,'Địa lý lớp 8: thủ đô châu Âu (1)','dl-thu-do-cac-nuoc-lop-8-1','Nhớ thủ đô các nước châu Âu tiêu biểu và tránh nhầm lẫn thường gặp.','trung_binh',12,'Châu Âu: Pháp – Paris, Đức – Berlin, Ý – Rome, Anh – London, Nga – Mát-xcơ-va, Tây Ban Nha – Madrid, Hà Lan – Amsterdam, Thuỵ Sĩ – Bern. Chú ý: thủ đô Thổ Nhĩ Kỳ là Ankara (không phải Istanbul).','- Paris là thủ đô của Pháp, nổi tiếng với tháp Eiffel.\n- Berlin là thủ đô của Đức.\n- Rome là thủ đô của Ý, thành phố có lịch sử hàng nghìn năm.\n- Mát-xcơ-va (Moscow) là thủ đô của Liên bang Nga.\n- Các thủ đô châu Âu thường là trung tâm văn hóa, lịch sử lâu đời.',5,'published',8,1,'2026-10-07 21:59:47','2026-10-07 21:59:47'),
(210,52,'Địa lý lớp 8: thủ đô châu Mỹ, châu Phi, châu Đại Dương (2)','dl-thu-do-cac-nuoc-lop-8-2','Nhớ thủ đô các nước tiêu biểu ở châu Mỹ, châu Phi, châu Đại Dương; tránh nhầm thành phố lớn với thủ đô.','trung_binh',12,'Châu Mỹ: Mỹ – Washington D.C., Canada – Ottawa, Bra-xin – Brasilia, Argentina – Buenos Aires. Châu Phi: Ai Cập – Cairo, Nam Phi – Pretoria. Châu Đại Dương: Úc – Canberra, New Zealand – Wellington. Nhiều thành phố nổi tiếng (New York, Sydney) không phải thủ đô.','- Washington D.C. là thủ đô Hoa Kì; Ottawa là thủ đô Ca-na-đa.\n- Canberra là thủ đô Ô-xtrây-li-a (Úc); Sydney, Melbourne chỉ là thành phố lớn.\n- Cairo là thủ đô Ai Cập, thành phố lớn nhất châu Phi.\n- Nhiều nước có thủ đô không phải là thành phố lớn nhất.\n- Ghi nhớ thủ đô các châu lục để mở rộng hiểu biết thế giới.',6,'published',8,1,'2026-10-07 21:59:47','2026-10-07 21:59:47'),
(211,53,'Địa lý lớp 8: vùng núi và trung du Việt Nam (1)','dl-dia-hinh-viet-nam-lop-8-1','Nêu bốn vùng núi chính, dãy Hoàng Liên Sơn, đỉnh Fansipan và vùng trung du.','trung_binh',12,'Địa hình Việt Nam 3/4 là đồi núi, gồm bốn vùng: Tây Bắc (dãy Hoàng Liên Sơn, đỉnh Fansipan 3 143 m), Đông Bắc, Trường Sơn Bắc và Trường Sơn Nam. Vùng trung du Bắc Bộ nằm giữa miền núi và đồng bằng, đất feralit thích hợp trồng cây công nghiệp.','- 3/4 diện tích Việt Nam là đồi núi, 1/4 là đồng bằng.\n- Dãy Hoàng Liên Sơn ở Tây Bắc có đỉnh Fansipan, nóc nhà Đông Dương.\n- Vùng núi Tây Bắc có núi cao nhất nước; vùng Đông Bắc có địa hình cánh cung đặc trưng.\n- Trung du Bắc Bộ có đất feralit thích hợp trồng chè và cây ăn quả.\n- Đồi núi là đặc trưng nổi bật của địa hình Việt Nam.',3,'published',8,1,'2026-10-07 21:59:47','2026-10-07 21:59:47'),
(212,53,'Địa lý lớp 8: đồng bằng và ven biển Việt Nam (2)','dl-dia-hinh-viet-nam-lop-8-2','Nêu hai đồng bằng châu thổ lớn, đường bờ biển, các đảo và quần đảo của Việt Nam.','trung_binh',12,'Việt Nam có hai đồng bằng châu thổ lớn: đồng bằng sông Hồng và đồng bằng sông Cửu Long – vựa lúa của cả nước. Đường bờ biển dài hơn 3 260 km với nhiều vũng vịnh, đảo lớn (Phú Quốc, Cát Bà) và hai quần đảo Hoàng Sa, Trường Sa.','- Đồng bằng sông Cửu Long rộng khoảng 40.000km2, là đồng bằng châu thổ lớn nhất nước.\n- Đường bờ biển Việt Nam dài hơn 3.260km, từ Quảng Ninh đến Kiên Giang.\n- Hoàng Sa (Đà Nẵng) và Trường Sa (Khánh Hòa) là hai quần đảo xa bờ thiêng liêng của Tổ quốc.\n- Vùng biển Việt Nam giàu thủy sản, dầu khí và tiềm năng du lịch.\n- Đồng bằng và biển là hai thế mạnh lớn của đất nước.',4,'published',8,1,'2026-10-07 21:59:47','2026-10-07 21:59:47'),
(213,53,'Địa lý lớp 9: tài nguyên khoáng sản Việt Nam (1)','dl-dia-hinh-viet-nam-lop-9-1','Kể tên các loại khoáng sản chính, nơi phân bố và ý nghĩa kinh tế.','trung_binh',12,'Việt Nam giàu khoáng sản: than đá tập trung ở Quảng Ninh, dầu khí ở thềm lục địa phía Nam, bô-xít ở Tây Nguyên, sắt ở Thái Nguyên, a-pa-tít ở Lào Cai. Khoáng sản là nguyên liệu quan trọng cho công nghiệp nhưng cần khai thác hợp lí, tiết kiệm.','- Than đá tập trung chủ yếu ở Quảng Ninh với trữ lượng lớn.\n- Dầu khí phân bố ở thềm lục địa phía Nam với các mỏ Bạch Hổ, Đại Hùng.\n- Tây Nguyên có trữ lượng bô-xít rất lớn, là nguyên liệu sản xuất nhôm.\n- Khoáng sản là tài nguyên không tái tạo nên phải khai thác hợp lý, tiết kiệm.\n- Việt Nam giàu tài nguyên khoáng sản nhưng cần sử dụng bền vững.',5,'published',9,1,'2026-10-07 21:59:47','2026-10-07 21:59:47'),
(214,53,'Địa lý lớp 9: bảo vệ tài nguyên và môi trường (2)','dl-dia-hinh-viet-nam-lop-9-2','Nêu thực trạng suy giảm tài nguyên, các biện pháp bảo vệ và ứng phó biến đổi khí hậu.','kho',12,'Tài nguyên đang suy giảm do khai thác quá mức: rừng bị thu hẹp, đất bạc màu, ô nhiễm nguồn nước. Cần trồng rừng, xử lí chất thải, tiết kiệm năng lượng. Việt Nam là một trong những nước chịu ảnh hưởng nặng của biến đổi khí hậu: nước biển dâng đe doạ đồng bằng sông Cửu Long.','- Rừng Việt Nam bị thu hẹp do khai thác quá mức và đốt nương làm rẫy.\n- Trồng rừng và bảo vệ rừng đầu nguồn là biện pháp bảo vệ rừng quan trọng.\n- Biến đổi khí hậu gây nước biển dâng, đe dọa đồng bằng sông Cửu Long; bão lũ diễn biến phức tạp.\n- Mỗi học sinh có thể góp phần bảo vệ môi trường bằng cách tiết kiệm tài nguyên và trồng cây.\n- Bảo vệ tài nguyên, môi trường là trách nhiệm của mọi người.',6,'published',9,1,'2026-10-07 21:59:47','2026-10-07 21:59:47'),
(215,54,'Nốt nhạc cơ bản lớp 6: bảy nốt nhạc Đồ – Si (1)','an-not-nhac-cao-do-lop-6-1','Kể được tên 7 nốt nhạc, nhận biết hình nốt tròn – trắng – đen – móc đơn.','de',12,'Có 7 nốt nhạc: Đồ (C), Rê (D), Mi (E), Pha (F), Son (G), La (A), Si (B). Hình nốt cho biết trường độ: nốt tròn dài nhất, rồi đến nốt trắng, nốt đen, nốt móc đơn ngắn hơn.','- 7 nốt nhạc cơ bản: Đồ, Rê, Mi, Pha, Son, La, Si.\n- Ký hiệu quốc tế: Đồ = C, Rê = D, Mi = E, Pha = F, Son = G, La = A, Si = B.\n- Trong 7 nốt: Đồ – Rê – Mi trầm hơn; Son – La – Si bổng hơn.\n- Hình nốt cơ bản: tròn, trắng, đen, móc đơn — thể hiện độ dài ngắn của âm thanh.\n- Nốt Đồ là nốt đầu tiên trong thang nhạc 7 nốt.',2,'published',6,1,'2026-10-07 22:02:33','2026-10-07 22:02:33'),
(216,54,'Khuông nhạc và khóa Son lớp 6: đọc tên nốt trên dòng kẻ (2)','an-not-nhac-cao-do-lop-6-2','Biết khuông nhạc 5 dòng 4 khe, khóa Son; đọc được tên nốt trên dòng kẻ và trong khe.','de',12,'Khuông nhạc có 5 dòng kẻ và 4 khe. Khóa Son đặt ở đầu khuông nhạc cho biết vị trí nốt Son nằm trên dòng kẻ thứ hai. Nốt nhạc được viết trên dòng kẻ hoặc trong khe nhạc.','- Khuông nhạc gồm 5 dòng kẻ ngang song song, tạo thành 4 khe nhạc ở giữa.\n- Khóa Son đặt ở đầu khuông nhạc, xác định vị trí các nốt nhạc.\n- Với khóa Son, các nốt trên dòng kẻ: dòng 1 Mi, dòng 2 Son, dòng 3 Si, dòng 4 Rê, dòng 5 Pha.\n- Các nốt trong khe: khe 1 Pha, khe 2 La, khe 3 Đồ, khe 4 Mi.\n- Nốt nhạc viết trên dòng kẻ hoặc trong khe — đọc đúng vị trí là đọc đúng tên nốt.',3,'published',6,1,'2026-10-07 22:02:34','2026-10-07 22:02:34'),
(217,54,'Cao độ và quãng lớp 7: quãng 2, 3, 4, 5, 8 (1)','an-not-nhac-cao-do-lop-7-1','Hiểu quãng là khoảng cách cao độ; xác định được quãng 2, 3, 4, 5, 8 từ nốt Đồ.','de',13,'Quãng là khoảng cách cao độ giữa hai nốt nhạc. Từ nốt Đồ: Đồ–Rê là quãng 2, Đồ–Mi là quãng 3, Đồ–Pha là quãng 4, Đồ–Son là quãng 5, Đồ–Đồ (cao hơn) là quãng 8 còn gọi là bát độ.','- Quãng là khoảng cách cao độ giữa hai nốt nhạc, tính bằng số bậc.\n- Cách tính quãng: đếm số bậc từ nốt thấp đến nốt cao (Đồ = 1, Rê = 2, Mi = 3...).\n- Đồ – Mi là quãng 3 (đếm 3 bậc: Đồ, Rê, Mi); Đồ – Son là quãng 5.\n- Quãng 2, 3 là quãng hẹp (hai nốt gần nhau); quãng 5, 8 là quãng rộng (hai nốt xa nhau).\n- Quãng 8 là quãng tám: hai nốt cùng tên, nốt sau cao hơn nốt trước một quãng tám.',4,'published',7,1,'2026-10-07 22:02:36','2026-10-07 22:02:36'),
(218,54,'Dấu hóa và âm giai lớp 7: thăng, giáng, bình và âm giai Đô trưởng (2)','an-not-nhac-cao-do-lop-7-2','Biết tác dụng dấu thăng – giáng – bình; đọc được âm giai Đô trưởng 8 nốt.','trung_binh',13,'Dấu thăng (#) nâng nốt lên nửa cung, dấu giáng (b) hạ nốt xuống nửa cung, dấu bình hủy tác dụng thăng giáng. Âm giai Đô trưởng gồm 8 nốt: Đồ Rê Mi Pha Son La Si (Đồ cao). Trong đó Mi–Pha và Si–Đồ cách nhau nửa cung.','- Dấu thăng (#) đặt trước nốt nào thì nâng nốt đó lên nửa cung.\n- Dấu giáng (b) đặt trước nốt nào thì hạ nốt đó xuống nửa cung.\n- Dấu bình (♮) hủy bỏ thăng hoặc giáng, trả nốt về cao độ tự nhiên.\n- Ba dấu hóa cơ bản: thăng nâng, giáng hạ, bình hủy.\n- Âm giai Đô trưởng gồm 8 nốt: Đồ – Rê – Mi – Pha – Son – La – Si – Đố.',5,'published',7,1,'2026-10-07 22:02:37','2026-10-07 22:02:37'),
(219,56,'Nhịp và dấu lặng lớp 7: nhịp 2/4, 3/4 (1)','an-nhip-dau-lang-lop-7-1','Hiểu số chỉ nhịp; phân biệt nhịp 2/4 – 3/4; nhận biết dấu lặng tròn – trắng – đen.','de',12,'Số chỉ nhịp gồm hai số: số trên cho biết mỗi ô nhịp có mấy phách, số dưới cho biết giá trị mỗi phách (4 = nốt đen). Nhịp 2/4: mỗi ô 2 phách; nhịp 3/4: mỗi ô 3 phách. Dấu lặng là ký hiệu nghỉ: lặng tròn nghỉ 4 phách, lặng trắng 2 phách, lặng đen 1 phách.','- Số trên của số chỉ nhịp cho biết mỗi ô nhịp có bao nhiêu phách (2/4 có 2 phách, 3/4 có 3 phách).\n- Số dưới cho biết giá trị mỗi phách: số 4 nghĩa là nốt đen là đơn vị phách.\n- Nhịp 2/4 khỏe khoắn hợp hành khúc; nhịp 3/4 uyển chuyển hợp điệu valse.\n- Dấu lặng tròn, trắng, đen tương ứng với thời gian nghỉ của nốt tròn, trắng, đen.\n- Đọc đúng số chỉ nhịp và dấu lặng là nền tảng để đọc bản nhạc.',2,'published',7,1,'2026-10-07 22:02:38','2026-10-07 22:02:38'),
(220,56,'Nhịp 4/4 và dấu chấm dôi lớp 7: đọc bản nhạc đơn giản (2)','an-nhip-dau-lang-lop-7-2','Biết nhịp 4/4 (ký hiệu C); tính được giá trị nốt có dấu chấm dôi.','trung_binh',13,'Nhịp 4/4 (ký hiệu C): mỗi ô nhịp 4 phách đen, phách 1 mạnh nhất, phách 3 mạnh vừa. Dấu chấm dôi đặt sau nốt hoặc dấu lặng làm tăng thêm một nửa giá trị: nốt đen chấm dôi dài 1,5 phách, nốt trắng chấm dôi dài 3 phách.','- Nhịp 4/4: mỗi ô nhịp có 4 phách đen; còn được ký hiệu bằng chữ C.\n- Dấu chấm dôi đặt sau nốt nhạc làm tăng thêm một nửa giá trị của nốt đó.\n- Nốt trắng chấm dôi = 2 + 1 = 3 phách; nốt đen chấm dôi = 1 + 0,5 = 1,5 phách.\n- Trường độ các nốt (đơn vị nốt đen): tròn 4, trắng 2, đen 1, móc đơn 1/2, móc kép 1/4.\n- Ô nhịp 2/4 chứa tối đa 4 nốt móc đơn (2 phách, mỗi phách 2 móc đơn).',3,'published',7,1,'2026-10-07 22:02:40','2026-10-07 22:02:40'),
(221,56,'Nhịp đơn, nhịp kép lớp 8: nhịp 6/8 và phân loại (1)','an-nhip-dau-lang-lop-8-1','Phân biệt nhịp đơn – nhịp kép; biết nhịp 6/8 có 2 phách, mỗi phách bằng 3 nốt móc đơn.','trung_binh',13,'Nhịp đơn: mỗi phách chia thành 2 phần bằng nhau (2/4, 3/4, 4/4). Nhịp kép: mỗi phách chia thành 3 phần bằng nhau (6/8, 9/8, 12/8). Nhịp 6/8 có 2 phách, mỗi phách bằng một nốt đen chấm dôi, tức 3 nốt móc đơn.','- Nhịp đơn: mỗi phách chia thành 2 phần bằng nhau (mẫu số thường là 4 như 2/4, 3/4, 4/4).\n- Nhịp kép: mỗi phách chia thành 3 phần bằng nhau (mẫu số thường là 8 như 6/8, 9/8).\n- Nhịp 6/8 là nhịp kép, có 2 phách; mỗi phách bằng một nốt đen chấm dôi (3 nốt móc đơn).\n- Phân biệt nhịp đơn – kép qua cách chia phách chứ không chỉ nhìn số chỉ nhịp.\n- Nhịp kép thường gợi cảm giác nhún nhảy, uyển chuyển.',4,'published',8,1,'2026-10-07 22:02:41','2026-10-07 22:02:41'),
(222,56,'Trường độ và đếm phách lớp 8: thực hành tổng hợp (2)','an-nhip-dau-lang-lop-8-2','Tính nhanh giá trị các hình nốt (kể cả móc kép); biết đếm phách và dấu diễn cảm cơ bản.','trung_binh',14,'Khi đơn vị phách là nốt đen: nốt tròn = 4, nốt trắng = 2, nốt đen = 1, nốt móc đơn = 1/2, nốt móc kép = 1/4 phách. Đếm phách đều (\"1 và 2 và...\") giúp giữ đúng nhịp. Dấu legato: hát liền; dấu staccato: hát nảy ngắn gọn.','- Trường độ các nốt (đơn vị nốt đen): tròn 4, trắng 2, đen 1, móc đơn 1/2, móc kép 1/4.\n- Nốt móc kép = một nửa nốt móc đơn = 1/4 phách.\n- Ô nhịp 2/4 = 2 phách, chứa tối đa 4 nốt móc đơn.\n- Đếm phách đều khi đọc nhạc giúp giữ đúng nhịp của bản nhạc.\n- Dấu diễn cảm cơ bản (to – nhỏ, nhanh – chậm) giúp bản nhạc có hồn hơn.',5,'published',8,1,'2026-10-07 22:02:42','2026-10-07 22:02:42'),
(223,58,'Nhạc cụ dân tộc lớp 8: nhóm dây – gảy, dây – kéo (1)','an-nhac-cu-dan-toc-lop-8-1','Kể được đàn bầu, đàn tranh, đàn nguyệt, đàn nhị; phân biệt dây gảy và dây kéo.','trung_binh',13,'Nhạc cụ dây gảy: đàn bầu (1 dây, độc đáo nhất), đàn tranh (16 dây), đàn nguyệt (2 dây, mặt tròn), đàn tỳ bà (4 dây). Nhạc cụ dây kéo: đàn nhị (đàn cò) dùng vĩ kéo, âm thanh gần giọng người.','- Đàn bầu là nhạc cụ độc đáo chỉ có 1 dây của Việt Nam, âm thanh réo rắt đặc biệt.\n- Đàn tranh (đàn thập lục) có 16 dây, gảy bằng móng tay.\n- Nhóm dây gảy: đàn bầu, đàn tranh, đàn nguyệt, đàn tỳ bà — dùng tay hoặc móng gảy dây.\n- Nhóm dây kéo: đàn nhị, đàn gáo — dùng vĩ kéo trên dây.\n- Nhận biết nhạc cụ dây qua số dây và hình dáng mặt đàn.',2,'published',8,1,'2026-10-07 22:02:43','2026-10-07 22:02:43'),
(224,58,'Nhạc cụ dân tộc lớp 8: nhóm hơi và nhóm gõ (2)','an-nhac-cu-dan-toc-lop-8-2','Kể được sáo, kèn bầu, trống cơm, phách, cồng chiêng; biết cồng chiêng Tây Nguyên là di sản UNESCO.','trung_binh',13,'Nhạc cụ hơi: sáo trúc, tiêu, kèn bầu, tù và — dùng hơi thổi. Nhạc cụ gõ: trống cơm, trống chầu, phách, sanh tiền, đàn đá — dùng dùi hoặc tay gõ. Không gian văn hóa cồng chiêng Tây Nguyên là di sản văn hóa phi vật thể của nhân loại.','- Nhóm hơi: sáo (làm bằng trúc, âm thanh trong), kèn bầu — dùng hơi thổi.\n- Nhóm gõ: trống cơm, phách, cồng chiêng — dùng tay hoặc dùi tác động.\n- Không gian văn hóa cồng chiêng Tây Nguyên là di sản văn hóa phi vật thể của nhân loại (UNESCO).\n- Mỗi nhạc cụ có cách phát ra âm thanh riêng: thổi, gảy, kéo, gõ.\n- Nhạc cụ dân tộc là tài sản văn hóa quý báu cần giữ gìn.',3,'published',8,1,'2026-10-07 22:02:44','2026-10-07 22:02:44'),
(225,58,'Nghệ thuật truyền thống lớp 9: chèo, quan họ, ca trù (1)','an-nhac-cu-dan-toc-lop-9-1','Biết quan họ Bắc Ninh, chèo, ca trù, đờn ca tài tử; nêu được di sản UNESCO của Việt Nam.','trung_binh',13,'Quan họ Bắc Ninh: hát giao duyên, di sản UNESCO 2009. Chèo: sân khấu dân gian đồng bằng Bắc Bộ. Ca trù (hát ả đào): hát nói, hát thờ. Đờn ca tài tử Nam Bộ: di sản UNESCO 2013. Xẩm là hát của người khiếm thị.','- Dân ca quan họ Bắc Ninh được UNESCO công nhận là di sản văn hóa phi vật thể năm 2009.\n- Chèo là loại hình sân khấu dân gian Bắc Bộ, kết hợp hát, múa và diễn xuất.\n- Ca trù là nghệ thuật hát thơ đặc sắc của miền Bắc.\n- Đờn ca tài tử là nghệ thuật đờn – hát của Nam Bộ.\n- Mỗi loại hình có không gian diễn xướng riêng theo vùng miền: quan họ, chèo (Bắc); hò Huế (Trung); đờn ca tài tử (Nam).',4,'published',9,1,'2026-10-07 22:02:46','2026-10-07 22:02:46'),
(226,58,'Nhạc cụ phương Tây và dàn nhạc lớp 9: so sánh Đông – Tây (2)','an-nhac-cu-dan-toc-lop-9-2','Kể được violin, piano, trumpet, flute; phân biệt dàn nhạc giao hưởng và dàn nhạc dân tộc.','kho',14,'Nhạc cụ phương Tây: violin (dây kéo), piano (phím – búa gõ dây), trumpet (đồng thổi), flute (sáo ngang). Dàn nhạc giao hưởng khoảng 100 nhạc công do nhạc trưởng chỉ huy. Dàn nhạc dân tộc Việt Nam gồm đàn tranh, đàn bầu, sáo, đàn nhị, trống...','- Nhạc cụ phương Tây tiêu biểu: violin, piano, trumpet, flute.\n- Violin có 4 dây, dùng vĩ kéo — đứng đầu bộ dây trong dàn nhạc giao hưởng.\n- Bốn nhóm nhạc cụ phương Tây: dây, phím, kèn đồng, kèn gỗ.\n- Dàn nhạc giao hưởng gồm nhiều nhạc cụ phương Tây, do nhạc trưởng chỉ huy bằng đũa chỉ huy.\n- Dàn nhạc dân tộc gồm nhạc cụ truyền thống Việt Nam như đàn bầu, đàn tranh, sáo.',5,'published',9,1,'2026-10-07 22:02:47','2026-10-07 22:02:47'),
(227,17,'Màu sắc lớp 6: ba màu cơ bản và pha màu (1)','mt-mau-sac-lop-6-1','Kể được 3 màu cơ bản; pha được màu thứ cấp cam – lục – tím.','de',12,'Ba màu cơ bản: đỏ, vàng, lam — không pha được từ màu khác. Pha hai màu cơ bản được màu thứ cấp: đỏ + vàng = cam, vàng + lam = lục (xanh lá), lam + đỏ = tím.','- Ba màu cơ bản: đỏ, vàng, lam — không pha được từ màu khác mà có.\n- Ba màu thứ cấp: cam (đỏ + vàng), lục (vàng + lam), tím (đỏ + lam).\n- Đỏ + trắng = hồng: thêm trắng làm màu sáng và nhạt dần.\n- Biết pha màu giúp tạo ra nhiều màu mới từ bộ màu hạn chế.\n- Nên thử màu trên giấy nháp trước khi tô vào tranh chính.',3,'published',6,1,'2026-10-07 22:02:48','2026-10-07 22:02:48'),
(228,17,'Màu nóng – màu lạnh lớp 6: cảm xúc của màu sắc (2)','mt-mau-sac-lop-6-2','Phân biệt gam màu nóng – lạnh; biết màu sắc gợi cảm xúc khác nhau.','de',12,'Màu nóng: đỏ, cam, vàng — gợi cảm giác ấm áp, sôi động. Màu lạnh: lam, lục, tím — gợi cảm giác mát mẻ, yên tĩnh. Người vẽ chọn gam màu phù hợp với nội dung tranh: biển dùng gam lạnh, lửa trại dùng gam nóng.','- Màu nóng: đỏ, cam, vàng — gợi cảm giác ấm áp, sôi động, vui tươi.\n- Màu lạnh: lam, lục, tím — gợi cảm giác mát mẻ, yên tĩnh, trầm lắng.\n- Màu lam (xanh dương) gợi cảm giác mát mẻ nhất, như nước và bầu trời.\n- Màu sắc diễn tả được cảm xúc: vui dùng gam nóng, buồn dùng gam lạnh.\n- Cùng một vật, đổi gam màu sẽ đổi hẳn cảm xúc của bức tranh.',4,'published',6,1,'2026-10-07 22:02:50','2026-10-07 22:02:50'),
(229,17,'Sắc độ và hòa sắc lớp 7: đậm – nhạt, màu tương phản (1)','mt-mau-sac-lop-7-1','Hiểu sắc độ; xác định được cặp màu tương phản trên vòng tròn màu.','de',13,'Sắc độ là độ đậm nhạt của màu: thêm trắng thì nhạt dần, thêm đen thì đậm dần. Hai màu đối diện nhau trên vòng tròn màu gọi là màu tương phản: đỏ–lục, vàng–tím, cam–lam. Đặt cạnh nhau, màu tương phản làm nhau nổi bật.','- Thêm trắng làm màu nhạt dần, thêm đen làm màu đậm dần — gọi là sắc độ của màu.\n- Đỏ + trắng = hồng là ví dụ điển hình của việc tạo sắc độ nhạt.\n- Cặp màu tương phản nằm đối diện nhau trên vòng tròn màu: đỏ – lục, vàng – tím, cam – lam.\n- Cặp màu tương đồng nằm kề nhau trên vòng tròn màu, ví dụ đỏ – cam.\n- Dùng màu tương phản để tạo điểm nhấn, dùng màu tương đồng để tạo sự hài hòa.',5,'published',7,1,'2026-10-07 22:02:51','2026-10-07 22:02:51'),
(230,17,'Màu chủ đạo trong tranh lớp 7: bố cục màu (2)','mt-mau-sac-lop-7-2','Biết màu chủ đạo, điểm nhấn màu; biết màu tự nhiên trong tranh Đông Hồ.','trung_binh',13,'Màu chủ đạo chiếm diện tích lớn, quyết định cảm xúc chung của tranh. Điểm nhấn màu là mảng màu tương phản nhỏ thu hút mắt nhìn. Tranh dân gian Đông Hồ dùng màu tự nhiên: đen từ than, đỏ từ gạch non, vàng từ hoa hòe, trên giấy điệp làm từ vỏ sò.','- Màu chủ đạo chiếm diện tích lớn nhất, quyết định cảm xúc chung của bức tranh.\n- Điểm nhấn màu là mảng màu tương phản nhỏ, dẫn mắt người xem đến chi tiết quan trọng.\n- Tranh Đông Hồ dùng màu từ nguyên liệu tự nhiên nên có sắc trầm ấm, mộc mạc.\n- Phối hợp màu chủ đạo, màu nền và điểm nhấn tạo nên bố cục màu hoàn chỉnh.\n- Xác định màu chủ đạo trước khi tô giúp tranh có định hướng rõ ràng.',6,'published',7,1,'2026-10-07 22:02:53','2026-10-07 22:02:53'),
(231,18,'Đường nét lớp 7: các loại nét và cảm xúc (1)','mt-duong-net-bo-cuc-lop-7-1','Phân biệt nét thẳng – cong – gấp khúc – đứt; biết nét trong vẽ kỹ thuật.','de',12,'Nét thẳng gợi vững chãi, nét cong gợi mềm mại uyển chuyển, nét gấp khúc gợi mạnh mẽ gấp gáp, nét đứt gợi nhẹ nhàng. Trong vẽ kỹ thuật: nét liền đậm vẽ đường bao thấy được, nét đứt vẽ đường bị khuất, nét chấm gạch vẽ trục đối xứng.','- Nét thẳng gợi sự cứng cáp, chắc chắn; dùng vẽ vật cứng, công trình, nhà cửa.\n- Nét cong gợi sự mềm mại, uyển chuyển như sóng nước, cầu vồng; dùng vẽ vật mềm, uốn lượn.\n- Nét gấp khúc (zigzag) gợi sự mạnh mẽ, gấp gáp như tia chớp.\n- Nét đứt gợi sự nhẹ nhàng, xa xăm; dùng vẽ vật ở xa, mờ ảo.\n- Trong vẽ kỹ thuật, mỗi loại nét có quy ước riêng cần tuân thủ đúng.',2,'published',7,1,'2026-10-07 22:02:55','2026-10-07 22:02:55'),
(232,18,'Bố cục lớp 7: đối xứng, cân bằng và điểm nhấn (2)','mt-duong-net-bo-cuc-lop-7-2','Hiểu bố cục, bố cục đối xứng, điểm nhấn; biết đặt đường chân trời ở 1/3 tranh.','trung_binh',13,'Bố cục là cách sắp xếp các hình mảng trong tranh. Bố cục đối xứng: hai bên giống nhau qua một trục, tạo cảm giác trang nghiêm. Điểm nhấn là vị trí thu hút mắt nhìn nhất, thường đặt ở khoảng 1/3 tranh. Các mảng nặng – nhẹ cần phân bố cân bằng.','- Bố cục là cách sắp xếp các hình mảng trong tranh, quyết định nhịp điệu và cảm xúc.\n- Bố cục đối xứng: hai nửa tranh giống nhau qua trục giữa, ví dụ mặt người, con bướm.\n- Bố cục tự do: sắp xếp phóng khoáng không theo trục đối xứng, ví dụ dòng sông, đám mây.\n- Điểm nhấn dẫn mắt người xem đến chi tiết quan trọng nhất của bức tranh.\n- Đường chân trời trong tranh phong cảnh thường đặt ở 1/3 chiều cao tranh để cân đối.',3,'published',7,1,'2026-10-07 22:02:56','2026-10-07 22:02:56'),
(233,18,'Hình khối và không gian lớp 8: vẽ theo mẫu (1)','mt-duong-net-bo-cuc-lop-8-1','Nhận biết khối cầu – trụ – hộp – nón; hiểu phối cảnh gần to xa nhỏ và sáng – tối.','trung_binh',13,'Mọi vật thể đều gồm các khối cơ bản: khối cầu (quả cam), khối trụ (lon sữa), khối hộp (hộp quà), khối nón (nón lá). Phối cảnh: vật gần vẽ to, vật xa vẽ nhỏ. Ánh sáng tạo ba phần: phần sáng hướng về nguồn sáng, phần tối quay lưng lại, bóng đổ in trên mặt đất phía đối diện nguồn sáng.','- Bốn khối cơ bản: cầu, trụ, hộp, nón — mọi vật thể đều cấu tạo từ các khối này.\n- Quả cam, quả địa cầu gần với khối cầu; lon sữa bò gần với khối trụ.\n- Phối cảnh: vật ở gần vẽ to, rõ nét; vật ở xa vẽ nhỏ, mờ dần.\n- Ánh sáng tạo vùng sáng – tối trên khối, giúp khối có chiều sâu và thật hơn.\n- Khi vẽ theo mẫu, xác định khối cơ bản của vật trước rồi mới vẽ chi tiết.',4,'published',8,1,'2026-10-07 22:02:57','2026-10-07 22:02:57'),
(234,18,'Trang trí và họa tiết lớp 8: hoa văn dân tộc (2)','mt-duong-net-bo-cuc-lop-8-2','Biết họa tiết trang trí lặp lại có quy luật; nhận biết hoa văn trống đồng Đông Sơn.','trung_binh',13,'Họa tiết trang trí được lặp lại có quy luật tạo nhịp điệu: họa tiết hình học, hoa lá cách điệu, con vật. Trống đồng Đông Sơn có hoa văn chim Lạc và ngôi sao nhiều cánh ở trung tâm mặt trống — biểu tượng văn hóa Đông Sơn.','- Họa tiết trang trí thường lặp lại có quy luật, tạo nhịp điệu cho bố cục.\n- Trung tâm mặt trống đồng Đông Sơn là ngôi sao nhiều cánh tượng trưng cho mặt trời.\n- Họa tiết từ thiên nhiên: hoa lá, con vật được cách điệu; họa tiết hình học: đường nét, hình khối.\n- Mỗi chất liệu có kỹ thuật tạo họa tiết riêng như khắc, thêu, vẽ.\n- Hoa văn trống đồng Đông Sơn là di sản văn hóa tiêu biểu của người Việt cổ.',5,'published',8,1,'2026-10-07 22:02:59','2026-10-07 22:02:59'),
(235,20,'Tranh Đông Hồ lớp 8: làng nghề và đặc điểm (1)','mt-tranh-dan-gian-lop-8-1','Biết làng Đông Hồ (Bắc Ninh), giấy điệp, màu tự nhiên; kể được tranh Đám cưới chuột.','trung_binh',13,'Làng Đông Hồ (Thuận Thành, Bắc Ninh) làm tranh khắc ván. Giấy điệp quét từ vỏ sò điệp giã nhỏ, óng ánh. Màu tự nhiên: đen từ than, đỏ từ gạch non, vàng từ hoa hòe. Chủ đề: chúc tụng (Vinh hoa Phú quý), sinh hoạt (Đám cưới chuột), lịch sử.','- Làng tranh Đông Hồ thuộc huyện Thuận Thành, tỉnh Bắc Ninh.\n- Giấy điệp: vỏ sò điệp giã nhỏ, trộn hồ rồi quét lên giấy dó tạo độ óng ánh.\n- Màu vẽ từ nguyên liệu tự nhiên nên tranh có sắc trầm ấm, bền màu.\n- Tranh Đám cưới chuột châm biếm thói hối lộ của quan lại phong kiến xưa.\n- Nghề làm tranh đòi hỏi sự kiên nhẫn, tỉ mỉ qua nhiều công đoạn.',2,'published',8,1,'2026-10-07 22:03:01','2026-10-07 22:03:01'),
(236,20,'Tranh Hàng Trống và Kim Hoàng lớp 8: nét riêng (2)','mt-tranh-dan-gian-lop-8-2','Phân biệt Hàng Trống (in ván + vẽ tay), Kim Hoàng (giấy hồng điều), Đông Hồ.','trung_binh',13,'Tranh Hàng Trống (phố Hàng Trống, Hà Nội): in ván nét đen rồi tô màu bằng tay, nổi tiếng về tranh thờ (Ngũ hổ) và tranh Tố nữ. Tranh Kim Hoàng (Hoài Đức, Hà Nội): in trên giấy hồng điều đỏ, chủ yếu là tranh Tết.','- Tranh Hàng Trống: in ván lấy nét đen rồi nghệ nhân tô màu bằng tay nên mềm mại.\n- Tranh Kim Hoàng in trên giấy hồng điều đỏ — nét riêng không dòng tranh nào có.\n- Tranh Đông Hồ in ván khắc gỗ trên giấy điệp, màu từ nguyên liệu tự nhiên.\n- Mỗi dòng tranh có kỹ thuật, chất liệu và phong cách riêng.\n- Phân biệt các dòng tranh qua cách in, cách tô màu và loại giấy sử dụng.',3,'published',8,1,'2026-10-07 22:03:02','2026-10-07 22:03:02'),
(237,20,'Tranh dân gian các vùng miền lớp 9: Làng Sình, tranh kính (1)','mt-tranh-dan-gian-lop-9-1','Biết tranh Làng Sình (Huế, tranh thờ), tranh kính Nam Bộ; phân biệt vùng miền.','trung_binh',14,'Tranh Làng Sình (Huế): in ván rồi tô màu, chủ yếu dùng thờ cúng (Lý ngư vọng nguyệt). Tranh kính Nam Bộ: vẽ trực tiếp trên tờ kính, chủ đề Bát tiên, Tứ quý. Mỗi vùng miền có dòng tranh riêng: Bắc – Đông Hồ, Hàng Trống; Trung – Làng Sình; Nam – tranh kính.','- Tranh Làng Sình (Phú Vang, Thừa Thiên Huế) chủ yếu là tranh thờ cúng trong gia đình.\n- Tranh kính Nam Bộ vẽ trên mặt kính với màu sắc rực rỡ.\n- Miền Bắc có tranh Đông Hồ, Hàng Trống; miền Trung có tranh Làng Sình; miền Nam có tranh kính.\n- Mỗi vùng miền có đề tài, chất liệu gắn với đời sống văn hóa địa phương.\n- Tranh dân gian phản ánh ước mơ, tín ngưỡng và đời sống của người dân từng vùng.',4,'published',9,1,'2026-10-07 22:03:04','2026-10-07 22:03:04'),
(238,20,'Bảo tồn tranh dân gian lớp 9: nghệ nhân và phát huy (2)','mt-tranh-dan-gian-lop-9-2','Nêu được nguy cơ mai một; đề xuất cách bảo tồn và ứng dụng hiện đại.','kho',14,'Nhiều làng nghề tranh đứng trước nguy cơ mai một vì nghệ nhân cao tuổi, ít người kế nghiệp. Bảo tồn bằng: truyền nghề cho thế hệ trẻ, đưa vào trường học, phát triển du lịch làng nghề, số hóa lưu trữ, ứng dụng họa tiết dân gian vào thời trang và thiết kế hiện đại.','- Nghệ nhân là người tinh thông và truyền dạy nghề truyền thống — báu vật sống của làng nghề.\n- Thách thức lớn nhất hiện nay: nghệ nhân cao tuổi, giới trẻ ít theo nghề, tranh đứng trước nguy cơ mai một.\n- Bảo tồn tranh dân gian: truyền nghề cho thế hệ trẻ, quảng bá đến du khách, đưa vào trường học.\n- Ứng dụng hiện đại: đưa họa tiết dân gian vào thiết kế thời trang, bao bì, quà lưu niệm.\n- Mỗi hành động ủng hộ tranh dân gian đều góp phần giữ gìn di sản văn hóa dân tộc.',5,'published',9,1,'2026-10-07 22:03:05','2026-10-07 22:03:05'),
(239,32,'Khởi động và an toàn lớp 6: nguyên tắc vận động (1)','tt-van-dong-an-toan-lop-6-1','Biết khởi động 5-10 phút; mang giày thể thao; kiểm tra sân bãi trước khi chơi.','de',10,'Trước khi vận động phải khởi động 5-10 phút: xoay các khớp, chạy nhẹ tại chỗ để làm nóng cơ, tránh chấn thương. Mang giày thể thao vừa chân, trang phục thoải mái. Kiểm tra sân bãi khô ráo, dụng cụ chắc chắn; uống đủ nước.','- Việc đầu tiên trước khi chơi thể thao là khởi động 5–10 phút: xoay khớp, chạy nhẹ, ép dẻo.\n- Kiểm tra sân bãi, dụng cụ trước khi chơi để loại bỏ nguy cơ như đá sỏi, mặt sân trơn.\n- Khởi động trước buổi tập và thả lỏng nhẹ sau buổi tập là trình tự đúng.\n- Mang giày thể thao phù hợp, trang phục gọn gàng khi vận động.\n- An toàn là nguyên tắc đầu tiên của mọi hoạt động thể thao.',2,'published',6,1,'2026-10-07 22:03:07','2026-10-07 22:03:07'),
(240,32,'Tư thế vận động đúng lớp 6: chạy, nhảy, thở (2)','tt-van-dong-an-toan-lop-6-2','Thực hiện đúng tư thế chạy, cách tiếp đất khi nhảy, cách thở khi vận động.','de',11,'Chạy đúng: người hơi nghiêng về trước, mắt nhìn thẳng, hai tay đánh nhịp theo bước chân. Nhảy xuống: tiếp đất bằng cả bàn chân, gối khụy để giảm chấn động. Khi vận động mạnh: hít vào bằng mũi, thở ra bằng miệng, thở đều không nín thở.','- Khi chạy, hai tay đánh nhịp ngược với chân giúp giữ thăng bằng và tăng tốc.\n- Khi nhảy từ trên cao xuống, tiếp đất bằng mũi chân rồi khụy gối để hấp thụ lực.\n- Thở đều khi vận động: hít vào bằng mũi, thở ra bằng miệng.\n- Tư thế đúng giúp vận động hiệu quả và tránh chấn thương khớp gối.\n- Không nín thở khi gắng sức; thở nhịp nhàng theo từng động tác.',3,'published',6,1,'2026-10-07 22:03:08','2026-10-07 22:03:08'),
(241,32,'Chấn thương thể thao lớp 7: phòng tránh và sơ cứu (1)','tt-van-dong-an-toan-lop-7-1','Nhận biết chuột rút, bong gân, trật khớp; biết sơ cứu RICE.','de',12,'Chấn thương thường gặp: chuột rút (cơ co cứng đột ngột), bong gân, trật khớp, trầy xước. Sơ cứu theo RICE: Rest (nghỉ ngơi), Ice (chườm lạnh trong 48 giờ đầu), Compression (băng ép), Elevation (kê cao). Tuyệt đối không tự nắn khớp bị trật — cố định và đưa đến cơ sở y tế.','- Chuột rút là hiện tượng cơ co cứng đột ngột, đau nhói — cần dừng lại, kéo giãn nhẹ và bổ sung nước.\n- Nguyên tắc sơ cứu RICE: Rest (nghỉ ngơi), Ice (chườm lạnh), Compression (băng ép), Elevation (kê cao).\n- Khi bong gân: chườm lạnh trước, không chườm nóng ngay và không tự nắn khớp.\n- Trật khớp phải đến cơ sở y tế, tuyệt đối không tự nắn chỉnh tại chỗ.\n- Khởi động kỹ và tập đúng kỹ thuật là cách phòng tránh chấn thương tốt nhất.',4,'published',7,1,'2026-10-07 22:03:09','2026-10-07 22:03:09'),
(242,32,'Tố chất thể lực lớp 7: sức nhanh, mạnh, bền, dẻo (2)','tt-van-dong-an-toan-lop-7-2','Phân biệt sức nhanh – mạnh – bền – dẻo; chọn bài tập phù hợp từng tố chất.','trung_binh',12,'Các tố chất thể lực: sức nhanh (chạy 60m), sức mạnh (chống đẩy, bật xa), sức bền (chạy 800-1000m), sự dẻo dai (ép dẻo), sự khéo léo (đá cầu). Tập luyện phải tăng dần cường độ, đúng kỹ thuật, đều đặn — tập quá sức dễ chấn thương.','- Sức nhanh: chạy cự ly ngắn 60m, 100m — bứt tốc tối đa trong thời gian ngắn.\n- Sức mạnh: chống đẩy, nâng tạ — rèn cơ tay, vai, ngực, chân khỏe hơn.\n- Sức bền: chạy dài, bơi dài — duy trì vận động lâu mà không mệt.\n- Sức dẻo: ép dẻo, gập người — tăng linh hoạt cho khớp và cơ.\n- Chọn bài tập đúng với tố chất muốn phát triển; kết hợp nhiều tố chất để cơ thể phát triển toàn diện.',5,'published',7,1,'2026-10-07 22:03:11','2026-10-07 22:03:11'),
(243,34,'Luật bóng đá cơ bản lớp 7: sân, việt vị, phạt đền (1)','tt-luat-the-thao-lop-7-1','Biết mỗi đội 11 người, luật việt vị, phạt đền 11m, thẻ vàng – thẻ đỏ.','de',12,'Mỗi đội 11 cầu thủ. Việt vị: cầu thủ tấn công đứng gần khung thành đối phương hơn bóng và cầu thủ thứ hai cuối cùng khi đồng đội chuyền bóng. Phạm lỗi trong vòng cấm bị phạt đền: đá từ chấm 11m. Thẻ vàng cảnh cáo, thẻ đỏ truất quyền thi đấu.','- Bóng đá 11 người: mỗi đội có 11 cầu thủ trên sân khi thi đấu.\n- Quả phạt đền (penalty) được đá từ chấm 11m khi phạm lỗi trong vòng cấm địa.\n- Thẻ vàng là cảnh cáo, thẻ đỏ là truất quyền thi đấu ngay lập tức.\n- Trận đấu có 2 hiệp; đội ghi nhiều bàn thắng hơn thì thắng trận.\n- Luật việt vị khuyến khích lối chơi tấn công đẹp mắt, chống việc ăn sẵn gần khung thành.',2,'published',7,1,'2026-10-07 22:03:12','2026-10-07 22:03:12'),
(244,34,'Luật bóng rổ cơ bản lớp 7: dẫn bóng, bước chạy (2)','tt-luat-the-thao-lop-7-2','Biết cách dẫn bóng, lỗi chạy bước, cách tính điểm 1 – 2 – 3 điểm.','trung_binh',12,'Dẫn bóng bằng một tay (mỗi lần chạm một tay), không được cầm bóng chạy quá số bước quy định (lỗi chạy bước), không dẫn bóng lại sau khi đã dừng (lỗi hai lần dẫn). Ném trong vòng 2 điểm, ném phạt 1 điểm, ném ngoài vạch 3 điểm được 3 điểm. Rổ cao 3,05m.','- Dẫn bóng rổ: đập bóng bằng một tay, có thể đổi tay khi di chuyển.\n- Cầm bóng chỉ được chạy tối đa 2 bước; quá số bước là lỗi chạy bước.\n- Dẫn bóng hai tay cùng lúc rồi dẫn tiếp là lỗi hai lần dẫn bóng.\n- Ném trong vòng cung 3 điểm được 2 điểm; ngoài vòng cung được 3 điểm; ném phạt được 1 điểm.\n- Khi dẫn bóng cần giữ bóng chắc, mắt quan sát đồng đội và đối phương.',3,'published',7,1,'2026-10-07 22:03:13','2026-10-07 22:03:13'),
(245,34,'Luật bóng chuyền lớp 8: đội hình và lỗi (1)','tt-luat-the-thao-lop-8-1','Biết mỗi đội 6 người, tối đa 3 lần chạm bóng; nhận biết lỗi chạm lưới.','trung_binh',13,'Mỗi đội 6 người trên sân. Mỗi đội được chạm bóng tối đa 3 lần trước khi đưa sang sân đối phương. Lỗi thường gặp: chạm lưới, bóng ra ngoài, dẫm vạch khi phát bóng. Thắng 3 trong 5 set; set thường đến 25 điểm (cách 2 điểm), set 5 đến 15 điểm. Libero là cầu thủ chuyên phòng thủ mặc áo khác màu.','- Bóng chuyền trong nhà: mỗi đội có 6 người trên sân.\n- Mỗi đội được chạm bóng tối đa 3 lần trước khi đưa bóng sang sân đối phương.\n- Thứ tự chạm bóng thường là: đỡ bóng, chuyền hai rồi đập bóng.\n- Chạm lưới khi bóng còn trong cuộc là lỗi, đối phương được điểm.\n- Mỗi set đánh đến 25 điểm (hơn đối phương 2 điểm); set quyết định đánh đến 15 điểm.',4,'published',8,1,'2026-10-07 22:03:14','2026-10-07 22:03:14'),
(246,34,'Luật cầu lông lớp 8: tính điểm và giao cầu (2)','tt-luat-the-thao-lop-8-2','Biết tính điểm rally đến 21, giao cầu chéo sân, thắng 2/3 set.','trung_binh',13,'Tính điểm rally: mỗi pha bóng đều có điểm. Thắng 1 set khi đạt 21 điểm và hơn đối phương 2 điểm (tối đa 30 điểm). Giao cầu phải phát sang ô chéo sân, chân không dẫm vạch. Thắng trận khi thắng 2 trong 3 set. Sân đơn hẹp hơn sân đôi; lưới cao 1,55m ở biên.','- Cầu lông tính điểm rally: thắng set khi đạt 21 điểm và hơn đối phương 2 điểm (tối đa 30 điểm).\n- Thắng 2 trong 3 set thì thắng chung cuộc cả trận.\n- Giao cầu phải đánh chéo sân sang ô đối diện của đối phương.\n- Cầu chạm vạch vẫn tính là trong sân, không phải lỗi.\n- Nắm vững kỹ thuật giao cầu và di chuyển là nền tảng chơi cầu lông tốt.',5,'published',8,1,'2026-10-07 22:03:15','2026-10-07 22:03:15'),
(247,36,'Dinh dưỡng cho người vận động lớp 8: nhóm chất (1)','tt-suc-khoe-ve-sinh-lop-8-1','Kể được 4 nhóm chất; biết ăn uống – bổ sung nước đúng khi tập luyện.','trung_binh',13,'Bốn nhóm chất: bột đường (cơm, bánh mì — năng lượng chính), đạm (thịt, trứng, sữa — xây dựng cơ bắp), béo (dầu, mỡ — dự trữ năng lượng), vitamin – khoáng chất – chất xơ (rau, trái cây). Ăn nhẹ trước tập 1-2 giờ, uống nước từng ngụm, không nhịn khát.','- Bốn nhóm chất chính: bột đường, chất đạm, chất béo, vitamin và khoáng chất.\n- Bột đường (cơm, bánh mì, khoai) là nguồn năng lượng chính cho cơ thể vận động.\n- Chất đạm (thịt, trứng, sữa, đậu) xây dựng và phục hồi cơ bắp.\n- Rau củ cung cấp vitamin, chất xơ giúp tiêu hóa tốt và tăng sức đề kháng.\n- Bữa ăn đủ 4 nhóm chất mới cân đối, đảm bảo năng lượng cho tập luyện.',2,'published',8,1,'2026-10-07 22:03:16','2026-10-07 22:03:16'),
(248,36,'Vệ sinh trong tập luyện lớp 8: cá nhân và môi trường (2)','tt-suc-khoe-ve-sinh-lop-8-2','Biết vệ sinh cá nhân sau tập; giữ sân bãi, dụng cụ sạch sẽ; không dùng chung đồ cá nhân.','trung_binh',13,'Sau khi tập: tắm rửa, thay quần áo khô để tránh cảm lạnh và viêm da. Không dùng chung khăn mặt, bình nước để tránh lây bệnh ngoài da. Giữ sân bãi sạch: bỏ rác đúng nơi, không khạc nhổ bừa bãi; vệ sinh dụng cụ tập chung và báo ngay khi dụng cụ hỏng.','- Sau khi tập ra nhiều mồ hôi: tắm rửa sạch sẽ, thay đồ khô để tránh cảm lạnh và viêm da.\n- Không dùng chung khăn mặt, bình nước để tránh lây bệnh da liễu, cúm.\n- Giữ sân bãi và dụng cụ tập luyện sạch sẽ sau khi sử dụng.\n- Bỏ rác đúng nơi quy định, giữ vệ sinh chung nơi tập luyện.\n- Vệ sinh tốt bảo vệ sức khỏe của bản thân và cộng đồng.',3,'published',8,1,'2026-10-07 22:03:17','2026-10-07 22:03:17'),
(249,36,'Tim mạch và hô hấp khi vận động lớp 9: nhịp tim, nhịp thở (1)','tt-suc-khoe-ve-sinh-lop-9-1','Ước tính được nhịp tim tối đa (220 – tuổi); biết thở đúng khi vận động.','trung_binh',14,'Nhịp tim tối đa ước tính ≈ 220 – tuổi (bạn 15 tuổi ≈ 205 nhịp/phút). Khi vận động, tim đập nhanh để bơm máu, phổi thở nhanh để lấy oxy. Vùng tập hiệu quả khoảng 60-80% nhịp tim tối đa. Thở đúng: hít sâu bằng mũi, thở nhịp nhàng — không nín thở khi chạy bền.','- Công thức ước tính nhịp tim tối đa: 220 trừ đi số tuổi (ví dụ 15 tuổi thì khoảng 205 nhịp/phút).\n- Khi vận động, nhịp tim và nhịp thở tăng lên để cung cấp ôxy cho cơ bắp.\n- Tim, phổi, máu và cơ phối hợp nhịp nhàng trong mọi hoạt động vận động.\n- Thở đúng khi vận động: hít sâu bằng mũi, thở ra đều bằng miệng.\n- Theo dõi nhịp tim giúp tập luyện đúng cường độ, tránh vận động quá sức.',4,'published',9,1,'2026-10-07 22:03:19','2026-10-07 22:03:19'),
(250,36,'Chất kích thích và thể thao lớp 9: doping, rượu bia, thuốc lá (2)','tt-suc-khoe-ve-sinh-lop-9-2','Biết doping bị cấm; nêu tác hại của rượu bia, thuốc lá với thể lực.','kho',14,'Doping là chất kích thích bị cấm trong thể thao — vận động viên dương tính bị cấm thi đấu, tước huy chương và hại sức khỏe lâu dài. Rượu bia làm giảm phản xạ, hại gan; thuốc lá hại phổi, giảm sức bền. Người chơi thể thao phải nói không với mọi chất kích thích, thi đấu trung thực.','- Doping là chất cấm dùng để gian lận thành tích trong thể thao.\n- Vận động viên dương tính với doping bị phạt nặng: cấm thi đấu, tước danh hiệu.\n- Rượu bia làm giảm phản xạ, sức bền và khả năng tập trung khi thi đấu.\n- Thuốc lá gây hại phổi và tim mạch, làm giảm thể lực nghiêm trọng.\n- Nói không với chất kích thích để bảo vệ sức khỏe và thi đấu công bằng.',5,'published',9,1,'2026-10-07 22:03:20','2026-10-07 22:03:20'),
(251,41,'Quản lý thời gian lớp 6: thời gian biểu học tập (1)','tnhn-ky-nang-song-lop-6-1','Biết lập thời gian biểu; ưu tiên việc quan trọng; học 25-30 phút nghỉ 5 phút.','de',10,'Lập thời gian biểu: giờ học, giờ chơi, giờ ngủ rõ ràng. Việc quan trọng và gấp làm trước. Học tập trung 25-30 phút rồi nghỉ 5 phút để não hồi phục. Ngủ đủ 8-10 tiếng mỗi đêm, không thức khuya — thiếu ngủ làm giảm trí nhớ.','- Nên học tập trung 25–30 phút rồi nghỉ 5 phút giúp não hồi phục, nhớ lâu hơn.\n- Ưu tiên việc quan trọng trước là nguyên tắc cốt lõi của quản lý thời gian.\n- Lập thời gian biểu học tập cá nhân cho từng ngày, từng tuần.\n- Bắt đầu với việc nhỏ, dễ làm để tạo đà hoàn thành công việc.\n- Theo dõi việc đã làm mỗi ngày giúp điều chỉnh kế hoạch kịp thời.',2,'published',6,1,'2026-10-07 22:03:22','2026-10-07 22:03:22'),
(252,41,'Giao tiếp và làm việc nhóm lớp 6: lắng nghe, chia sẻ (2)','tnhn-ky-nang-song-lop-6-2','Biết lắng nghe không ngắt lời; phân công khi làm việc nhóm; nói năng lịch sự.','de',11,'Lắng nghe tích cực: nhìn người nói, không ngắt lời, gật đầu đồng cảm. Nói rõ ràng, dùng lời lẽ lịch sự, biết cảm ơn và xin lỗi. Làm việc nhóm: phân công rõ ràng (nhóm trưởng, thư ký, thành viên), tôn trọng ý kiến bạn, giúp đỡ nhau, cùng chịu trách nhiệm.','- Lắng nghe tích cực: chăm chú, không ngắt lời, gật đầu và đặt câu hỏi làm rõ.\n- Ngắt lời người khác là thiếu tôn trọng, làm mất thiện cảm trong giao tiếp.\n- Làm việc nhóm hiệu quả cần phân công rõ ràng: ai làm gì, khi nào xong.\n- Nói năng lịch sự, dùng lời cảm ơn và xin lỗi đúng lúc.\n- Chia sẻ ý kiến thẳng thắn nhưng tôn trọng giúp cả nhóm cùng tiến bộ.',3,'published',6,1,'2026-10-07 22:03:24','2026-10-07 22:03:24'),
(253,41,'Quản lý cảm xúc lớp 7: nhận diện và kiểm soát (1)','tnhn-ky-nang-song-lop-7-1','Nhận diện cảm xúc; biết cách bình tĩnh khi giận: hít thở sâu, đếm 1-10.','de',12,'Cảm xúc có tích cực (vui, yêu thương) và tiêu cực (giận, buồn, sợ) — cảm xúc nào cũng cần được nhận diện, không nên giấu kín. Khi giận: dừng lại, hít thở sâu, đếm từ 1 đến 10, chỉ nói chuyện khi đã bình tĩnh. Tuyệt đối không làm tổn thương người khác hay đập phá.','- Khi đang rất tức giận: dừng lại và hít thở thật sâu để cơn giận lắng xuống.\n- Đếm từ 1 đến 10 giúp kiềm chế bản thân trước khi nói hoặc hành động.\n- Nhận diện cảm xúc qua biểu hiện bên ngoài: vui, buồn, giận, sợ hãi.\n- Cảm xúc tích cực: vui vẻ, yêu thương, biết ơn; cảm xúc tiêu cực: giận dữ, buồn bã, lo lắng.\n- Cảm xúc tiêu cực cũng cần được chia sẻ với người tin cậy, không nên giấu kín.',4,'published',7,1,'2026-10-07 22:03:26','2026-10-07 22:03:26'),
(254,41,'Giải quyết vấn đề lớp 7: 5 bước xử lý tình huống (2)','tnhn-ky-nang-song-lop-7-2','Thực hiện 5 bước: xác định – tìm nguyên nhân – liệt kê giải pháp – chọn – đánh giá.','trung_binh',12,'5 bước giải quyết vấn đề: 1. Xác định vấn đề là gì; 2. Tìm hiểu nguyên nhân; 3. Liệt kê các giải pháp có thể; 4. Chọn giải pháp tốt nhất; 5. Thực hiện rồi đánh giá kết quả. Gặp vấn đề vượt khả năng (bị bắt nạt, thấy cháy...) phải nhờ người lớn giúp đỡ.','- Bước 1: xác định rõ vấn đề là gì — xác định đúng là đã giải quyết được một nửa.\n- Bước 2: tìm nguyên nhân gây ra vấn đề.\n- Bước 3: liệt kê các giải pháp có thể thực hiện.\n- Bước 4: so sánh các giải pháp rồi chọn cách tốt nhất.\n- Bước 5: thực hiện giải pháp đã chọn và đánh giá kết quả.',5,'published',7,1,'2026-10-07 22:03:27','2026-10-07 22:03:27'),
(255,45,'An toàn giao thông lớp 7: quy tắc đường bộ (1)','tnhn-an-toan-moi-truong-lop-7-1','Biết đội mũ bảo hiểm, đi bên phải, qua đường ở vạch kẻ; nhận biết biển cấm – nguy hiểm.','de',12,'Đội mũ bảo hiểm khi đi xe máy, xe đạp điện. Đi bên phải đường, không dàn hàng ngang, không lạng lách. Qua đường ở vạch kẻ dành cho người đi bộ, nhìn trước nhìn sau. Biển tròn viền đỏ là biển cấm; biển tam giác viền đỏ là biển nguy hiểm; đèn đỏ phải dừng lại.','- Đi xe máy, xe đạp điện bắt buộc đội mũ bảo hiểm đạt chuẩn bảo vệ đầu.\n- Đi bên phải theo chiều đi của mình, đúng phần đường quy định.\n- Qua đường ở vạch kẻ (vạch ngựa vằn) — nơi xe cộ phải nhường người đi bộ.\n- Tuân thủ tín hiệu đèn giao thông, tuyệt đối không vượt đèn đỏ.\n- Không dàn hàng ngang, không lạng lách khi tham gia giao thông.',2,'published',7,1,'2026-10-07 22:03:28','2026-10-07 22:03:28'),
(256,45,'Phòng cháy chữa cháy lớp 7: thoát hiểm (2)','tnhn-an-toan-moi-truong-lop-7-2','Nhớ số 114; biết thoát hiểm cúi thấp, đi thang bộ; cách dùng bình chữa cháy.','trung_binh',12,'Số điện thoại cứu hỏa là 114. Khi cháy: hô hoán báo động, gọi 114, thoát hiểm bằng thang bộ — cúi thấp người tránh khói, dùng khăn ướt che mũi, tuyệt đối không dùng thang máy, không quay lại lấy đồ. Quần áo bén lửa: nằm lăn để dập. Dùng bình chữa cháy: rút chốt, hướng vòi vào gốc lửa, bóp cò.','- Số điện thoại khẩn cấp: 114 cứu hỏa, 115 cấp cứu, 113 công an, 111 bảo vệ trẻ em.\n- Khi cháy trong tòa nhà: bình tĩnh, cúi thấp người tránh khói độc, đi thang bộ — tuyệt đối không đi thang máy.\n- Phát hiện cháy phải báo ngay cho người lớn và gọi 114.\n- Khi thoát hiểm không quay lại lấy đồ đạc, tính mạng là quan trọng nhất.\n- Học cách dùng bình chữa cháy mini để dập đám cháy nhỏ khi đảm bảo an toàn.',3,'published',7,1,'2026-10-07 22:03:30','2026-10-07 22:03:30'),
(257,45,'Bảo vệ môi trường lớp 8: rác thải và tái chế (1)','tnhn-an-toan-moi-truong-lop-8-1','Phân loại rác hữu cơ – tái chế – nguy hại; hiểu 3R; biết tác hại túi nilon.','trung_binh',13,'Phân loại rác: hữu cơ (vỏ rau củ — ủ làm phân), tái chế (chai nhựa, giấy), nguy hại (pin cũ — thu gom riêng). 3R: Reduce (giảm thiểu), Reuse (tái sử dụng), Recycle (tái chế). Túi nilon mất hàng trăm năm mới phân hủy — hãy mang túi vải đi chợ, dùng bình nước cá nhân.','- 3R trong bảo vệ môi trường: Reduce (giảm thiểu), Reuse (tái sử dụng), Recycle (tái chế).\n- Phân loại rác thành 3 nhóm: hữu cơ, tái chế và nguy hại.\n- Túi nilon khó phân hủy, gây ô nhiễm đất và đại dương — hạn chế dùng, thay bằng túi vải.\n- Chai nhựa, giấy báo tái chế được thành nhiều sản phẩm mới.\n- Mỗi người giảm một túi nilon mỗi ngày là góp phần bảo vệ môi trường.',4,'published',8,1,'2026-10-07 22:03:32','2026-10-07 22:03:32'),
(258,45,'An toàn trên mạng lớp 8: bảo mật thông tin (2)','tnhn-an-toan-moi-truong-lop-8-2','Không chia sẻ thông tin cá nhân; đặt mật khẩu mạnh; cảnh giác lừa đảo, bắt nạt mạng.','trung_binh',13,'Không chia sẻ công khai địa chỉ nhà, số điện thoại, trường lớp, ảnh thẻ với người lạ. Mật khẩu mạnh: dài, gồm chữ hoa, chữ thường, số và ký tự đặc biệt; bật xác thực 2 lớp. Tin nhắn \"trúng thưởng, bấm link\" là lừa đảo — không bấm. Bị bắt nạt trên mạng: chặn, báo cáo và báo ngay cho người lớn.','- Không chia sẻ công khai địa chỉ nhà, số điện thoại, trường lớp — người lạ có thể lợi dụng.\n- Đặt mật khẩu mạnh: dài, khó đoán, không dùng thông tin cá nhân dễ đoán.\n- Cảnh giác với tin nhắn lừa đảo và đường link lạ — không bấm vào khi chưa chắc chắn.\n- Bị bắt nạt trên mạng: chặn, báo cáo và kể ngay với người lớn tin cậy.\n- Thông tin cá nhân chỉ chia sẻ với người thực sự tin cậy.',5,'published',8,1,'2026-10-07 22:03:34','2026-10-07 22:03:34'),
(259,48,'Tìm hiểu nghề nghiệp lớp 8: các nhóm nghề cơ bản (1)','tnhn-dinh-huong-nghe-nghiep-lop-8-1','Kể được các nhóm nghề y tế, giáo dục, kỹ thuật, công nghệ, nghệ thuật; biết công việc đặc trưng.','trung_binh',13,'Các nhóm nghề cơ bản: y tế (bác sĩ khám chữa bệnh), giáo dục (giáo viên dạy học), kỹ thuật (kỹ sư thiết kế), công nghệ thông tin (lập trình viên viết phần mềm), nông nghiệp (nông dân trồng trọt), nghệ thuật (họa sĩ, ca sĩ), kinh doanh, pháp luật (luật sư). Mọi nghề chân chính đều đáng tôn trọng.','- Nhóm nghề y tế: bác sĩ, y tá — khám chữa bệnh, chăm sóc sức khỏe.\n- Nhóm nghề giáo dục: giáo viên — dạy học, giáo dục thế hệ trẻ.\n- Nhóm nghề kỹ thuật: kỹ sư — thiết kế, xây dựng, chế tạo máy móc.\n- Nhóm nghề công nghệ thông tin: lập trình viên — viết phần mềm, ứng dụng.\n- Mỗi nhóm nghề có công việc đặc trưng và yêu cầu năng lực riêng.',2,'published',8,1,'2026-10-07 22:03:37','2026-10-07 22:03:37'),
(260,48,'Khám phá bản thân lớp 8: sở thích và năng lực (2)','tnhn-dinh-huong-nghe-nghiep-lop-8-2','Phân biệt sở thích – điểm mạnh – điểm yếu; biết chọn nghề theo năng lực, không theo phong trào.','trung_binh',13,'Hiểu bản thân qua 4 yếu tố: sở thích (điều mình yêu thích), điểm mạnh (điều mình làm tốt), điểm yếu (điều cần cải thiện), giá trị (điều mình coi trọng). Chọn nghề phù hợp năng lực và đam mê — không chạy theo phong trào hay vì bạn bè chọn. Phát huy điểm mạnh, rèn luyện điểm yếu từng ngày.','- Sở thích là điều mình thích làm; năng lực là điều mình làm tốt; điểm mạnh cần được phát huy.\n- Ai cũng có điểm mạnh và điểm yếu — quan trọng là nhận ra chúng.\n- Chọn nghề theo năng lực và đam mê, không chạy theo phong trào hay bạn bè.\n- Điểm yếu có thể cải thiện bằng rèn luyện kiên trì mỗi ngày.\n- Hiểu rõ bản thân là bước đầu tiên để chọn nghề phù hợp.',3,'published',8,1,'2026-10-07 22:03:40','2026-10-07 22:03:40'),
(261,48,'Chọn trường, chọn ngành lớp 9: hướng đi sau THCS (1)','tnhn-dinh-huong-nghe-nghiep-lop-9-1','Biết các hướng đi sau lớp 9: THPT, trung cấp nghề; căn cứ chọn theo năng lực, gia đình.','trung_binh',14,'Sau tốt nghiệp THCS có nhiều hướng đi: thi vào THPT (học văn hóa 3 năm), học trung cấp nghề (học nghề cụ thể như điện, may, nấu ăn), hoặc vừa học văn hóa vừa học nghề. Sau THPT: đại học, cao đẳng, trường nghề hoặc đi làm. Chọn theo năng lực, sở thích, điều kiện gia đình và nhu cầu xã hội — học nghề cũng là hướng đi tốt.','- Sau lớp 9 có nhiều hướng đi: thi vào THPT, học trung cấp nghề, vừa học văn hóa vừa học nghề.\n- Trường trung cấp nghề đào tạo nghề cụ thể như điện, may, nấu ăn, sửa xe.\n- Chọn hướng đi căn cứ vào năng lực học tập, sở thích và điều kiện gia đình.\n- Học nghề sớm giúp có tay nghề vững, sớm đi làm nếu phù hợp.\n- Dù chọn hướng nào cũng cần học tập nghiêm túc và không ngừng nâng cao tay nghề.',4,'published',9,1,'2026-10-07 22:03:42','2026-10-07 22:03:42'),
(262,48,'Nghề nghiệp tương lai lớp 9: kỹ năng số và học suốt đời (2)','tnhn-dinh-huong-nghe-nghiep-lop-9-2','Biết AI thay đổi nghề nghiệp; nêu kỹ năng tương lai: công nghệ số, ngoại ngữ, sáng tạo.','kho',14,'Trí tuệ nhân tạo (AI) và tự động hóa đang thay đổi thị trường lao động: nghề lặp đi lặp lại đơn giản dễ bị thay thế; nghề mới ra đời (kỹ sư AI, phân tích dữ liệu). Nghề cần sáng tạo, cảm xúc, chăm sóc con người khó bị thay thế. Hành trang tương lai: kỹ năng số, ngoại ngữ, tư duy sáng tạo và tinh thần học suốt đời.','- AI (Artificial Intelligence) là trí tuệ nhân tạo, đang thay đổi nhiều nghề nghiệp hiện nay.\n- Công nghệ sinh ra nhiều nghề mới, nhưng nghề truyền thống vẫn giữ giá trị riêng.\n- Nhóm nghề khó bị AI thay thế nhất: sáng tạo, cảm xúc, chăm sóc con người.\n- Kỹ năng của tương lai: công nghệ số, ngoại ngữ, tư duy sáng tạo và học suốt đời.\n- Chủ động học hỏi công nghệ để không bị tụt hậu trong thời đại số.',5,'published',9,1,'2026-10-07 22:03:44','2026-10-07 22:03:44'),
(263,64,'Mệnh đề và tính đúng – sai của mệnh đề','toan-thpt-lop-10-lop-10-1','Nhận biết mệnh đề; xác định tính đúng – sai của mệnh đề; lập mệnh đề phủ định; dùng ký hiệu ∀, ∃.','trung_binh',15,'Mệnh đề là câu khẳng định có tính đúng hoặc sai. Câu hỏi, câu cảm thán, câu cầu khiến không phải là mệnh đề. Phủ định của \"∀x, P(x)\" là \"∃x, không P(x)\" và ngược lại.','- Mệnh đề là câu khẳng định có tính đúng hoặc sai xác định.\n- Câu hỏi, câu cảm thán không phải là mệnh đề.\n- Phủ định của \"với mọi\" là \"tồn tại\" và ngược lại, đồng thời phủ định nội dung.\n- Mệnh đề \"nếu... thì...\" đúng khi giả thiết đúng kéo theo kết luận đúng.\n- Kiểm tra tính đúng sai bằng kiến thức toán đã học.',1,'published',10,1,'2026-10-07 22:48:56','2026-10-07 22:48:56'),
(264,64,'Tập hợp và các phép toán trên tập hợp','toan-thpt-lop-10-lop-10-2','Dùng ký hiệu ∈, ∉, ⊂; thực hiện giao, hợp, hiệu hai tập hợp; biểu diễn tập số bằng khoảng, đoạn.','trung_binh',15,'A ∩ B gồm phần tử chung của A và B; A ∪ B gồm mọi phần tử của A hoặc B; A \\ B gồm phần tử thuộc A nhưng không thuộc B. Tập rỗng ∅ là tập con của mọi tập hợp.','- Phần tử thuộc tập hợp dùng kí hiệu thuộc; tập con dùng kí hiệu tập con.\n- Giao A giao B gồm các phần tử chung của A và B.\n- Hợp A hợp B gồm mọi phần tử thuộc A hoặc B, mỗi phần tử liệt kê một lần.\n- Liệt kê phần tử theo điều kiện cho trước để đếm số phần tử.\n- Vẽ sơ đồ Ven để minh hoạ giao, hợp của hai tập hợp.',2,'published',10,1,'2026-10-07 22:48:56','2026-10-07 22:48:56'),
(265,65,'Hàm số bậc hai và đồ thị parabol','toan-thpt-lop-10-lop-10-3','Xác định đỉnh, trục đối xứng, hướng bề lõm của parabol y = ax² + bx + c; tìm giá trị lớn nhất – nhỏ nhất.','trung_binh',18,'Đỉnh I(−b/2a; −Δ/4a), trục đối xứng x = −b/2a. a > 0: bề lõm hướng lên, hàm số có giá trị nhỏ nhất; a < 0: bề lõm hướng xuống, hàm số có giá trị lớn nhất.','- Đồ thị hàm số bậc hai là parabol; a > 0 bề lõm hướng lên, a < 0 hướng xuống.\n- Đỉnh parabol: hoành độ x = -b/2a, thay vào hàm số tìm tung độ.\n- Trục đối xứng là đường thẳng x = -b/2a.\n- a > 0: hàm số có giá trị nhỏ nhất tại đỉnh; a < 0: có giá trị lớn nhất tại đỉnh.\n- Vẽ parabol qua đỉnh, trục đối xứng và một vài điểm.',1,'published',10,1,'2026-10-07 22:48:56','2026-10-07 22:48:56'),
(266,65,'Dấu của tam thức bậc hai và bất phương trình bậc hai','toan-thpt-lop-10-lop-10-4','Xét dấu tam thức bậc hai theo a và Δ; giải bất phương trình bậc hai một ẩn.','kho',20,'Δ < 0: f(x) cùng dấu với a với mọi x. Δ = 0: f(x) cùng dấu với a, trừ nghiệm kép. Δ > 0: f(x) trái dấu với a giữa hai nghiệm, cùng dấu với a ngoài khoảng hai nghiệm (\"trong trái, ngoài cùng\").','- Giải f(x) = 0 để tìm nghiệm (nếu có) bằng công thức nghiệm hoặc nhẩm nghiệm.\n- Delta < 0: tam thức luôn cùng dấu với hệ số a với mọi x.\n- a > 0: f(x) < 0 giữa hai nghiệm, f(x) > 0 ngoài hai nghiệm.\n- a < 0: dấu ngược lại với trường hợp a > 0.\n- Dựa vào bảng xét dấu để giải bất phương trình bậc hai.',2,'published',10,1,'2026-10-07 22:48:56','2026-10-07 22:48:56'),
(267,66,'Góc lượng giác và giá trị lượng giác của góc đặc biệt','toan-thpt-lop-11-lop-11-1','Nhớ giá trị sin, cos, tan của các góc đặc biệt; vận dụng công thức sin²α + cos²α = 1.','trung_binh',18,'Nhớ bảng giá trị: sin 30° = cos 60° = 1/2; sin 60° = cos 30° = √3/2; tan 45° = 1. Công thức cơ bản: sin²α + cos²α = 1; tan α = sin α / cos α (cos α ≠ 0).','- Góc đặc biệt cần nhớ: sin 30 độ = 1/2, cos 60 độ = 1/2, tan 45 độ = 1.\n- Hai góc phụ nhau: sin góc này bằng cos góc kia.\n- Công thức cơ bản: sin²a + cos²a = 1 với mọi góc a.\n- tan a = sin a / cos a với cos a khác 0.\n- Dùng đường tròn lượng giác để nhớ giá trị các góc đặc biệt.',1,'published',11,1,'2026-10-07 22:48:56','2026-10-07 22:48:56'),
(268,66,'Phương trình lượng giác cơ bản','toan-thpt-lop-11-lop-11-2','Giải các phương trình sin x = a, cos x = a, tan x = a, cot x = a; nắm điều kiện xác định của tan, cot.','kho',20,'sin x = 0 ⇔ x = kπ; cos x = 0 ⇔ x = π/2 + kπ; sin x = 1 ⇔ x = π/2 + k2π; cos x = −1 ⇔ x = π + k2π. tan x xác định khi x ≠ π/2 + kπ; cot x xác định khi x ≠ kπ. |a| > 1 thì sin x = a và cos x = a vô nghiệm.','- sin x = 0 khi x = k.pi; cos x = 1 khi x = k.2pi với k nguyên.\n- tan x = 1 khi x = pi/4 + k.pi vì tan có chu kì pi.\n- Giá trị tuyệt đối của sin x và cos x không vượt quá 1, nên sin x = 2 vô nghiệm.\n- Viết họ nghiệm đầy đủ với k là số nguyên.\n- Kiểm tra nghiệm có thoả điều kiện xác định (với tan, cot).',2,'published',11,1,'2026-10-07 22:48:56','2026-10-07 22:48:56'),
(269,67,'Cấp số cộng: số hạng tổng quát và tổng n số hạng đầu','toan-thpt-lop-11-lop-11-3','Nhận biết cấp số cộng; tính số hạng tổng quát uₙ = u₁ + (n − 1)d và tổng Sₙ.','trung_binh',18,'Cấp số cộng: uₙ₊₁ = uₙ + d (d là công sai). Số hạng tổng quát: uₙ = u₁ + (n − 1)d. Tổng n số hạng đầu: Sₙ = n(u₁ + uₙ)/2 = n[2u₁ + (n − 1)d]/2.','- Cấp số cộng: hiệu hai số hạng liên tiếp không đổi, gọi là công sai d.\n- Số hạng tổng quát: uₙ = u₁ + (n - 1)d.\n- Nhận diện cấp số cộng bằng cách kiểm tra hiệu các cặp số hạng liên tiếp.\n- Tổng n số hạng đầu: Sₙ = n(u₁ + uₙ)/2.\n- Ví dụ: 1 + 2 + ... + 10 = 10 x 11 / 2 = 55.',1,'published',11,1,'2026-10-07 22:48:56','2026-10-07 22:48:56'),
(270,67,'Cấp số nhân: số hạng tổng quát và tổng n số hạng đầu','toan-thpt-lop-11-lop-11-4','Nhận biết cấp số nhân; tính số hạng tổng quát uₙ = u₁·qⁿ⁻¹ và tổng Sₙ.','kho',20,'Cấp số nhân: uₙ₊₁ = uₙ · q (q là công bội). Số hạng tổng quát: uₙ = u₁ · qⁿ⁻¹. Tổng n số hạng đầu: Sₙ = u₁(qⁿ − 1)/(q − 1) với q ≠ 1.','- Cấp số nhân: tỉ số hai số hạng liên tiếp không đổi, gọi là công bội q.\n- Số hạng tổng quát: uₙ = u₁.qⁿ⁻¹.\n- Nhận diện cấp số nhân bằng cách kiểm tra tỉ số các cặp số hạng liên tiếp.\n- Tổng n số hạng đầu: Sₙ = u₁(qⁿ - 1)/(q - 1) với q khác 1.\n- Tính từng số hạng rồi cộng để kiểm tra công thức tổng.',2,'published',11,1,'2026-10-07 22:48:56','2026-10-07 22:48:56'),
(271,68,'Đạo hàm: định nghĩa và các công thức cơ bản','toan-thpt-lop-12-lop-12-1','Tính đạo hàm của hàm đa thức, hàm phân thức đơn giản, sin, cos, eˣ, ln x bằng công thức.','trung_binh',18,'Nhớ công thức: (xⁿ)\' = n·xⁿ⁻¹; (√x)\' = 1/(2√x); (1/x)\' = −1/x²; (sin x)\' = cos x; (cos x)\' = −sin x; (eˣ)\' = eˣ; (ln x)\' = 1/x. Đạo hàm của hằng số bằng 0.','- Đạo hàm của hàm hằng bằng 0.\n- Đạo hàm của xⁿ bằng n.xⁿ⁻¹, ví dụ đạo hàm của x³ là 3x².\n- Đạo hàm của căn x là 1/(2 căn x) với x > 0; đạo hàm của 1/x là -1/x² với x khác 0.\n- Đạo hàm cho biết tốc độ thay đổi tức thời của hàm số.\n- Ghi nhớ bảng đạo hàm các hàm cơ bản.',1,'published',12,1,'2026-10-07 22:48:57','2026-10-07 22:48:57'),
(272,68,'Quy tắc tính đạo hàm: tổng, tích, thương và hàm hợp','toan-thpt-lop-12-lop-12-2','Vận dụng quy tắc đạo hàm của tổng, hiệu, tích, thương và hàm hợp để tính đạo hàm.','kho',20,'(u + v)\' = u\' + v\'; (u·v)\' = u\'v + uv\'; (u/v)\' = (u\'v − uv\')/v². Đạo hàm hàm hợp: nếu y = f(u), u = g(x) thì y\'_x = y\'_u · u\'_x, ví dụ [(3x+1)²]\' = 6(3x+1).','- Đạo hàm của tổng: đạo hàm của (u + v) bằng u\' + v\'.\n- Đạo hàm của tích: đạo hàm của (u.v) bằng u\'v + uv\'.\n- Đạo hàm của thương: đạo hàm của (u/v) bằng (u\'v - uv\')/v².\n- Đạo hàm hàm hợp: đạo hàm của f(g(x)) bằng f\'(g) nhân g\'(x).\n- Áp dụng đúng quy tắc theo dạng của hàm số.',2,'published',12,1,'2026-10-07 22:48:57','2026-10-07 22:48:57'),
(273,69,'Tính đơn điệu và cực trị của hàm số','toan-thpt-lop-12-lop-12-3','Xét tính đơn điệu bằng dấu của đạo hàm; tìm điểm cực đại, cực tiểu và giá trị cực trị.','kho',20,'y\' > 0: hàm số đồng biến; y\' < 0: hàm số nghịch biến. y\' đổi dấu từ + sang − tại x₀: x₀ là điểm cực đại; đổi dấu từ − sang +: x₀ là điểm cực tiểu.','- y\' > 0 trên khoảng nào thì hàm số đồng biến trên khoảng đó.\n- y\' < 0 trên khoảng nào thì hàm số nghịch biến trên khoảng đó.\n- Điểm cực trị là nghiệm của y\' = 0 mà y\' đổi dấu khi đi qua đó.\n- y\'\' < 0 tại điểm dừng thì đạt cực đại; y\'\' > 0 thì đạt cực tiểu.\n- Lập bảng biến thiên để kết luận tính đơn điệu và cực trị.',1,'published',12,1,'2026-10-07 22:48:57','2026-10-07 22:48:57'),
(274,69,'Giá trị lớn nhất – giá trị nhỏ nhất của hàm số','toan-thpt-lop-12-lop-12-4','Tìm GTLN, GTNN của hàm số trên một đoạn bằng cách so sánh giá trị tại điểm tới hạn và hai đầu mút.','kho',20,'Trên đoạn [a; b], hàm số liên tục luôn có GTLN và GTNN. Cách tìm: tính y\', tìm các điểm tới hạn trong (a; b), rồi so sánh giá trị hàm số tại các điểm đó với f(a), f(b).','- Trên đoạn [a; b]: giải y\' = 0 tìm điểm dừng, so sánh giá trị tại các điểm dừng và hai đầu mút.\n- Parabol mở lên: đạt giá trị nhỏ nhất tại đỉnh; mở xuống: đạt giá trị lớn nhất tại đỉnh.\n- -1 ≤ sin x ≤ 1 nên giá trị lớn nhất của sin x là 1, giá trị nhỏ nhất là -1.\n- Dùng bất đẳng thức Cô-si: x + 1/x ≥ 2 với x > 0, dấu bằng khi x = 1.\n- Kết luận giá trị lớn nhất, nhỏ nhất kèm điểm đạt được.',2,'published',12,1,'2026-10-07 22:48:57','2026-10-07 22:48:57'),
(275,70,'Khái niệm và các đặc trưng cơ bản của pháp luật','gdcd-thpt-10-lop-10-1','Nêu được khái niệm pháp luật; phân biệt 3 đặc trưng cơ bản; nhận biết văn bản quy phạm pháp luật và thứ bậc hiệu lực.','trung_binh',15,'Pháp luật là hệ thống quy tắc xử sự chung do Nhà nước ban hành và bảo đảm thực hiện bằng quyền lực Nhà nước. Ba đặc trưng: tính quy phạm phổ biến (áp dụng chung cho mọi người), tính xác định chặt chẽ về mặt hình thức (ghi rõ trong văn bản, công khai), tính được bảo đảm thực hiện bằng quyền lực Nhà nước (cưỡng chế thi hành). Ở Việt Nam, văn bản quy phạm pháp luật là nguồn chính; Hiến pháp có hiệu lực pháp lí cao nhất.','- Pháp luật là hệ thống quy tắc xử sự chung do Nhà nước ban hành, có tính bắt buộc.\n- Ba đặc trưng cơ bản: tính quy phạm phổ biến, tính xác định chặt chẽ về hình thức, được bảo đảm thực hiện bằng quyền lực Nhà nước.\n- Pháp luật được bảo đảm thực hiện bằng biện pháp cưỡng chế như xử phạt hành chính, truy tố, xét xử.\n- Ở Việt Nam, văn bản quy phạm pháp luật (Hiến pháp, luật, nghị định) là nguồn chính của pháp luật.\n- Hiểu pháp luật để sống và làm việc theo pháp luật.',1,'published',10,1,'2026-10-07 22:54:15','2026-10-07 22:54:15'),
(276,70,'Bản chất và vai trò của pháp luật','gdcd-thpt-10-lop-10-2','Phân tích được bản chất giai cấp và bản chất xã hội của pháp luật; nêu được vai trò của pháp luật đối với Nhà nước, xã hội và công dân.','trung_binh',18,'Pháp luật có hai mặt bản chất: bản chất giai cấp (thể hiện ý chí của giai cấp cầm quyền được nâng lên thành luật) và bản chất xã hội (bắt nguồn từ thực tiễn đời sống xã hội, điều chỉnh các quan hệ xã hội). Vai trò: với Nhà nước là công cụ quản lí xã hội; với xã hội là giữ gìn trật tự, an toàn; với công dân là bảo vệ quyền và lợi ích hợp pháp; với kinh tế là tạo môi trường ổn định để phát triển.','- Bản chất giai cấp: pháp luật là ý chí của giai cấp cầm quyền được nâng lên thành luật.\n- Bản chất xã hội: quy phạm pháp luật bắt nguồn từ thực tiễn đời sống, điều chỉnh các quan hệ xã hội.\n- Pháp luật là phương tiện để Nhà nước quản lý mọi mặt đời sống xã hội một cách thống nhất, hiệu quả.\n- Pháp luật ghi nhận, bảo vệ quyền cơ bản của công dân và quy định nghĩa vụ công dân phải thực hiện.\n- Pháp luật vừa quản lý xã hội vừa bảo vệ quyền con người.',2,'published',10,1,'2026-10-07 22:54:15','2026-10-07 22:54:15'),
(277,71,'Vi phạm pháp luật và các loại vi phạm','gdcd-thpt-10-lop-10-3','Nêu được khái niệm vi phạm pháp luật; phân biệt 4 loại vi phạm: hình sự, hành chính, dân sự, kỉ luật.','trung_binh',15,'Vi phạm pháp luật là hành vi trái pháp luật, có lỗi, do người có năng lực trách nhiệm pháp lí thực hiện, xâm hại các quan hệ xã hội được pháp luật bảo vệ. Bốn loại: vi phạm hình sự (tội phạm, nguy hiểm cho xã hội, bị xử lí theo Bộ luật Hình sự), vi phạm hành chính (xâm phạm quy tắc quản lí nhà nước, ví dụ vượt đèn đỏ), vi phạm dân sự (xâm phạm quan hệ tài sản, nhân thân, ví dụ vi phạm hợp đồng), vi phạm kỉ luật (vi phạm nội quy cơ quan, trường học).','- Vi phạm pháp luật phải đủ 4 dấu hiệu: trái pháp luật, có lỗi, do người có năng lực trách nhiệm pháp lý thực hiện, xâm hại quan hệ xã hội được pháp luật bảo vệ.\n- Vượt đèn đỏ là vi phạm hành chính (xâm phạm quy tắc quản lý nhà nước).\n- Vi phạm hợp đồng thuê nhà là vi phạm dân sự (xâm phạm quan hệ tài sản).\n- Giáo viên bỏ tiết là vi phạm kỷ luật (vi phạm nội quy, quy chế cơ quan).\n- Phân loại vi phạm giúp xác định hình thức xử lý phù hợp.',1,'published',10,1,'2026-10-07 22:54:15','2026-10-07 22:54:15'),
(278,71,'Trách nhiệm pháp lí và các loại trách nhiệm','gdcd-thpt-10-lop-10-4','Nêu được khái niệm trách nhiệm pháp lí; phân biệt trách nhiệm hình sự, hành chính, dân sự, kỉ luật; vận dụng vào tình huống.','kho',20,'Trách nhiệm pháp lí là nghĩa vụ mà cá nhân, tổ chức phải gánh chịu hậu quả bất lợi do hành vi vi phạm pháp luật của mình gây ra, theo quy định của pháp luật. Tương ứng 4 loại vi phạm là 4 loại trách nhiệm: hình sự (hình phạt như phạt tù, phạt tiền), hành chính (phạt tiền, tước giấy phép...), dân sự (bồi thường thiệt hại, khôi phục tình trạng ban đầu), kỉ luật (khiển trách, cảnh cáo, cách chức...). Tuổi chịu trách nhiệm hình sự: từ đủ 14 tuổi với tội rất nghiêm trọng, đặc biệt nghiêm trọng; từ đủ 16 tuổi chịu trách nhiệm về mọi tội phạm.','- Trách nhiệm pháp lý là nghĩa vụ gánh chịu hậu quả bất lợi theo quy định của pháp luật.\n- Trộm cắp tài sản là tội phạm nên phải chịu trách nhiệm hình sự.\n- Vi phạm hợp đồng mua bán chủ yếu phải bồi thường thiệt hại (trách nhiệm dân sự).\n- Từ đủ 16 tuổi phải chịu trách nhiệm hình sự về mọi tội phạm; từ đủ 14 đến dưới 16 tuổi chỉ chịu về tội rất nghiêm trọng, đặc biệt nghiêm trọng.\n- Ai vi phạm pháp luật đều phải chịu trách nhiệm tương ứng.',2,'published',10,1,'2026-10-07 22:54:15','2026-10-07 22:54:15'),
(279,72,'Sản xuất của cải vật chất và các yếu tố sản xuất','gdcd-thpt-11-lop-11-1','Nêu được vai trò của sản xuất của cải vật chất; kể được 3 yếu tố cơ bản của quá trình sản xuất.','trung_binh',15,'Sản xuất của cải vật chất là hoạt động cơ bản, quyết định sự tồn tại và phát triển của xã hội. Ba yếu tố cơ bản của quá trình sản xuất: sức lao động (năng lực lao động của con người), đối tượng lao động (những gì con người tác động vào, ví dụ đất đai, nguyên liệu) và tư liệu lao động (công cụ, máy móc, nhà xưởng — trong đó công cụ lao động là yếu tố quan trọng nhất, thể hiện trình độ phát triển).','- Sản xuất của cải vật chất tạo ra tư liệu sinh hoạt, là cơ sở cho mọi hoạt động khác của xã hội.\n- Ba yếu tố cơ bản của quá trình sản xuất: sức lao động, đối tượng lao động, tư liệu lao động.\n- Công cụ lao động là yếu tố quan trọng nhất trong tư liệu lao động, thể hiện trình độ phát triển sản xuất.\n- Đối tượng lao động là những gì con người tác động vào trong sản xuất như đất đai, nguyên liệu.\n- Hiểu quá trình sản xuất để thấy vai trò của lao động con người.',1,'published',11,1,'2026-10-07 22:54:15','2026-10-07 22:54:15'),
(280,72,'Tiêu dùng và văn hoá tiêu dùng','gdcd-thpt-11-lop-11-2','Hiểu tiêu dùng là gì; nêu được các nguyên tắc của văn hoá tiêu dùng và trách nhiệm của người tiêu dùng.','trung_binh',15,'Tiêu dùng là việc sử dụng sản phẩm, dịch vụ để thoả mãn nhu cầu đời sống. Văn hoá tiêu dùng là cách ứng xử văn minh trong tiêu dùng: tiêu dùng hợp lí, tiết kiệm, có kế hoạch; tôn trọng quyền lợi người khác; bảo vệ môi trường (hạn chế rác thải nhựa, túi ni lông); không tiêu dùng sản phẩm gây hại sức khoẻ, vi phạm pháp luật. Người tiêu dùng có quyền được bảo vệ (Luật Bảo vệ quyền lợi người tiêu dùng) và có nghĩa vụ tìm hiểu thông tin, sử dụng đúng hướng dẫn.','- Tiêu dùng là khâu cuối của quá trình tái sản xuất: sử dụng sản phẩm để thỏa mãn nhu cầu.\n- Văn hóa tiêu dùng là ứng xử văn minh: hợp lý, tiết kiệm, bảo vệ môi trường, tôn trọng người khác.\n- Người tiêu dùng có quyền được an toàn, được thông tin đầy đủ, trung thực.\n- Người tiêu dùng có nghĩa vụ tìm hiểu thông tin, sử dụng đúng hướng dẫn và bảo vệ môi trường.\n- Tiêu dùng văn minh vừa tốt cho mình vừa tốt cho xã hội.',2,'published',11,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(281,73,'Thị trường và chức năng của thị trường','gdcd-thpt-11-lop-11-3','Nêu được khái niệm thị trường; phân tích 3 chức năng: thừa nhận, điều tiết – kích thích, thông tin.','trung_binh',18,'Thị trường là nơi gặp gỡ giữa người mua và người bán, là tổng hoà các quan hệ mua bán hàng hoá, dịch vụ. Ba chức năng: (1) Thừa nhận: thị trường thừa nhận giá trị sử dụng và giá trị của hàng hoá thông qua việc mua bán; (2) Điều tiết, kích thích: điều tiết sản xuất và lưu thông, kích thích lực lượng sản xuất phát triển; (3) Thông tin: cung cấp thông tin về cung – cầu, giá cả giúp người sản xuất, kinh doanh quyết định đúng. Giá cả thị trường hình thành trên cơ sở quan hệ cung – cầu.','- Thị trường theo nghĩa rộng là tổng hòa các quan hệ mua bán, trao đổi hàng hóa, dịch vụ.\n- Chức năng thừa nhận: hàng hóa chỉ thực sự có giá trị khi được thị trường thừa nhận (có người mua).\n- Quy luật cung cầu: cung vượt cầu thì giá giảm; cầu vượt cung thì giá tăng.\n- Chức năng thông tin: thông tin về cung, cầu, giá cả giúp người sản xuất điều chỉnh kịp thời.\n- Thị trường là cầu nối giữa sản xuất và tiêu dùng.',1,'published',11,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(282,73,'Cạnh tranh trong nền kinh tế thị trường','gdcd-thpt-11-lop-11-4','Nêu được khái niệm cạnh tranh; phân tích tính hai mặt của cạnh tranh; nêu các hành vi cạnh tranh không lành mạnh bị cấm.','kho',20,'Cạnh tranh là sự ganh đua giữa các chủ thể kinh tế nhằm giành điều kiện thuận lợi trong sản xuất, tiêu thụ để thu lợi nhuận cao nhất. Mặt tích cực: kích thích lực lượng sản xuất phát triển, tăng năng suất, hạ giá thành, nâng cao chất lượng, đáp ứng nhu cầu người tiêu dùng. Mặt tiêu cực: có thể dẫn đến cạnh tranh không lành mạnh (hàng giả, quảng cáo sai sự thật, bán phá giá, đầu cơ), gây thiệt hại cho xã hội. Pháp luật cấm các hành vi cạnh tranh không lành mạnh để bảo vệ môi trường kinh doanh công bằng.','- Cạnh tranh là động lực phát triển của nền kinh tế thị trường.\n- Cạnh tranh lành mạnh thúc đẩy tiến bộ kỹ thuật, mang lại lợi ích cho người tiêu dùng.\n- Quảng cáo sai sự thật là hành vi cạnh tranh không lành mạnh, bị pháp luật cấm.\n- Pháp luật bảo đảm cạnh tranh lành mạnh, chống hàng giả và gian lận thương mại.\n- Cạnh tranh lành mạnh tốt cho cả doanh nghiệp và người tiêu dùng.',2,'published',11,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(283,74,'Quyền bình đẳng của công dân trước pháp luật','gdcd-thpt-12-lop-12-1','Nêu được nội dung quyền bình đẳng của công dân: trước pháp luật, trong hôn nhân gia đình, trong lao động, trong kinh doanh.','trung_binh',15,'Mọi công dân đều bình đẳng trước pháp luật: không ai bị phân biệt đối xử, ai vi phạm đều bị xử lí. Bình đẳng trong hôn nhân và gia đình: vợ chồng bình đẳng về quyền và nghĩa vụ. Bình đẳng trong lao động: mọi người có quyền làm việc, lựa chọn nghề nghiệp, được trả lương xứng đáng, nam nữ bình đẳng. Bình đẳng trong kinh doanh: mọi cá nhân, tổ chức có quyền tự do kinh doanh ngành nghề mà pháp luật không cấm.','- Bình đẳng trước pháp luật: mọi công dân đều bình đẳng về quyền và nghĩa vụ, không phân biệt.\n- Bình đẳng trong lao động: mọi công dân bình đẳng trong thực hiện quyền lao động, không phân biệt giới tính.\n- Bình đẳng trong kinh doanh: tự do kinh doanh trong khuôn khổ pháp luật; ngành nghề cấm thì không được kinh doanh.\n- Bình đẳng trong hôn nhân và gia đình: vợ chồng bình đẳng, con cái không phân biệt trai gái.\n- Bình đẳng là quyền cơ bản và nguyên tắc nền tảng của pháp luật.',1,'published',12,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(284,74,'Các quyền tự do cơ bản: dân chủ, khiếu nại và tố cáo','gdcd-thpt-12-lop-12-2','Nêu được quyền bầu cử, ứng cử; phân biệt khiếu nại và tố cáo; biết cách thực hiện đúng pháp luật.','trung_binh',18,'Công dân từ đủ 18 tuổi có quyền bầu cử; từ đủ 21 tuổi có quyền ứng cử vào Quốc hội, HĐND. Quyền khiếu nại: công dân khiếu nại quyết định hành chính, hành vi hành chính mà mình cho là trái pháp luật, xâm phạm quyền lợi của mình. Quyền tố cáo: công dân tố cáo hành vi vi phạm pháp luật của bất kì cá nhân, tổ chức nào gây thiệt hại cho Nhà nước, xã hội. Khi thực hiện phải trung thực, đúng trình tự, không được lợi dụng để vu khống, xúc phạm người khác.','- Công dân đủ 18 tuổi trở lên có quyền bầu cử.\n- Công dân từ đủ 21 tuổi trở lên có quyền ứng cử vào Quốc hội, Hội đồng nhân dân.\n- Khiếu nại là đề nghị xem xét lại quyết định xâm phạm quyền lợi của mình; tố cáo là báo hành vi vi phạm pháp luật gây thiệt hại chung.\n- Pháp luật nghiêm cấm lợi dụng khiếu nại, tố cáo để vu khống, xúc phạm người khác.\n- Thực hiện quyền dân chủ phải đúng pháp luật và có trách nhiệm.',2,'published',12,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(285,75,'Nghĩa vụ tuân thủ pháp luật và nghĩa vụ nộp thuế','gdcd-thpt-12-lop-12-3','Nêu được nghĩa vụ tuân thủ pháp luật của công dân; hiểu vì sao phải nộp thuế và các loại thuế cơ bản.','trung_binh',15,'Mọi công dân có nghĩa vụ tuân thủ Hiến pháp và pháp luật, tôn trọng quyền tự do của người khác. Nộp thuế là nghĩa vụ của công dân và tổ chức: thuế là nguồn thu chủ yếu của ngân sách nhà nước, dùng để xây dựng đất nước, đảm bảo quốc phòng, an sinh xã hội. Các loại thuế phổ biến: thuế thu nhập cá nhân, thuế giá trị gia tăng (VAT), thuế thu nhập doanh nghiệp, thuế tiêu thụ đặc biệt. Trốn thuế là hành vi vi phạm pháp luật.','- Tuân thủ pháp luật là nghĩa vụ của công dân và biểu hiện của nếp sống văn minh.\n- Thuế là nguồn thu chủ yếu của ngân sách nhà nước, dùng để xây dựng đất nước.\n- Thuế giá trị gia tăng đánh vào giá trị tăng thêm của hàng hóa, dịch vụ; người tiêu dùng cuối cùng chịu thuế này.\n- Trốn thuế là vi phạm pháp luật, tùy mức độ bị phạt tiền hoặc phạt tù.\n- Nộp thuế đầy đủ là nghĩa vụ và cũng là đóng góp cho đất nước.',1,'published',12,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(286,75,'Nghĩa vụ bảo vệ Tổ quốc','gdcd-thpt-12-lop-12-4','Nêu được nội dung nghĩa vụ bảo vệ Tổ quốc; hiểu nghĩa vụ quân sự và các hình thức tham gia bảo vệ Tổ quốc.','kho',18,'Bảo vệ Tổ quốc là nghĩa vụ thiêng liêng và quyền cao quý của công dân. Nội dung: trung thành với Tổ quốc; thực hiện nghĩa vụ quân sự; tham gia bảo vệ an ninh quốc gia, trật tự an toàn xã hội; tố giác hành vi xâm phạm an ninh quốc gia. Nghĩa vụ quân sự: công dân nam từ đủ 18 tuổi đến hết 25 tuổi (27 tuổi với người đã tốt nghiệp cao đẳng, đại học) trong độ tuổi gọi nhập ngũ; thực hiện 24 tháng. Có thể tham gia dân quân tự vệ, dự bị động viên.','- Hiến pháp khẳng định bảo vệ Tổ quốc là nghĩa vụ thiêng liêng và quyền cao quý của công dân.\n- Luật Nghĩa vụ quân sự quy định độ tuổi gọi nhập ngũ thực hiện nghĩa vụ quân sự.\n- Thời hạn phục vụ tại ngũ trong thời bình của hạ sĩ quan, binh sĩ là 24 tháng.\n- Tố giác hành vi xâm phạm an ninh quốc gia là góp phần bảo vệ Tổ quốc.\n- Mỗi công dân đều có trách nhiệm với sự bình yên của đất nước.',2,'published',12,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(287,76,'Định dạng văn bản và tạo mục lục tự động','tin-hoc-thpt-10-lop-10-1','Biết định dạng kí tự, đoạn văn, trang; tạo mục lục tự động bằng Heading Styles trong Word.','trung_binh',15,'Định dạng kí tự: phông chữ, cỡ chữ, kiểu chữ (đậm B, nghiêng I, gạch chân U), màu chữ. Định dạng đoạn văn: căn lề (trái, phải, giữa, đều hai bên), giãn dòng, thụt đầu dòng, khoảng cách trước/sau đoạn. Định dạng trang: khổ giấy, lề, hướng giấy, đánh số trang. Mục lục tự động: áp dụng Heading 1, Heading 2 cho các tiêu đề, rồi vào References > Table of Contents để tạo; khi sửa nội dung thì Update Table để cập nhật.','- Muốn tạo mục lục tự động trong Word, trước tiên phải áp dụng Heading Styles cho các tiêu đề.\n- Sau khi sửa nội dung, dùng Update Table để cập nhật mục lục mà không cần tạo lại.\n- Phím tắt định dạng: Ctrl+B in đậm, Ctrl+I in nghiêng, Ctrl+U gạch chân.\n- Kiểu căn lề: Justify căn đều hai bên, Left căn trái, Center căn giữa, Right căn phải.\n- Định dạng văn bản đúng chuẩn giúp tài liệu chuyên nghiệp, dễ đọc.',1,'published',10,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(288,76,'Bảng biểu và chèn đối tượng trong Word','tin-hoc-thpt-10-lop-10-2','Tạo và định dạng bảng; chèn hình ảnh, SmartArt, biểu đồ; tạo tiêu đề cho bảng và hình.','trung_binh',18,'Tạo bảng: Insert > Table, chọn số hàng/cột; có thể thêm/xoá hàng cột, gộp/tách ô, tô màu nền, kẻ viền. Chèn hình ảnh: Insert > Pictures, chỉnh kích thước, kiểu bao quanh văn bản (In line, Square, Tight...). Chèn SmartArt để vẽ sơ đồ, Insert > Chart để vẽ biểu đồ. Đặt Caption (References > Insert Caption) cho bảng/hình để đánh số tự động \"Bảng 1\", \"Hình 1\".','- Insert > Table để chèn bảng, chọn số hàng và số cột theo ý muốn.\n- Merge Cells gộp các ô đã chọn thành một ô; Split Cells tách một ô thành nhiều ô.\n- Chọn kiểu bao quanh Square hoặc Tight để chữ ôm quanh hình, không che mất chữ.\n- References > Insert Caption đánh số tự động Bảng 1, Hình 1 cho bảng biểu và hình ảnh.\n- Trình bày bảng biểu, hình ảnh khoa học giúp văn bản rõ ràng hơn.',2,'published',10,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(289,77,'Hàm cơ bản trong Excel: SUM, AVERAGE, MAX, MIN','tin-hoc-thpt-10-lop-10-3','Sử dụng thành thạo các hàm SUM, AVERAGE, MAX, MIN, COUNT; hiểu địa chỉ ô và vùng dữ liệu.','trung_binh',15,'Công thức trong Excel luôn bắt đầu bằng dấu =. Địa chỉ ô: cột + hàng (ví dụ B3); vùng dữ liệu: ô đầu:ô cuối (ví dụ B2:B10). Các hàm cơ bản: SUM(vùng) tính tổng, AVERAGE(vùng) tính trung bình cộng, MAX(vùng) tìm giá trị lớn nhất, MIN(vùng) tìm giá trị nhỏ nhất, COUNT(vùng) đếm ô chứa số. Ví dụ: =SUM(B2:B10) tính tổng điểm từ B2 đến B10.','- Mọi công thức trong Excel đều bắt đầu bằng dấu bằng (=).\n- SUM(vùng) tính tổng, AVERAGE tính trung bình, MAX tìm giá trị lớn nhất, MIN tìm giá trị nhỏ nhất.\n- Địa chỉ ô = tên cột + số hàng, ví dụ C5.\n- Ví dụ =SUM(B2:B10) tính tổng các ô từ B2 đến B10.\n- Dùng hàm giúp tính toán nhanh và chính xác hơn tính tay.',1,'published',10,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(290,77,'Hàm điều kiện IF và sắp xếp, lọc dữ liệu','tin-hoc-thpt-10-lop-10-4','Sử dụng hàm IF, COUNTIF, SUMIF; thực hiện sắp xếp và lọc dữ liệu (Filter) trong Excel.','kho',20,'Hàm IF kiểm tra điều kiện: =IF(điều kiện, giá trị_nếu_đúng, giá trị_nếu_sai). Ví dụ: =IF(B2>=5,\"Đạt\",\"Chưa đạt\"). COUNTIF(vùng, điều kiện) đếm theo điều kiện; SUMIF(vùng_đk, điều kiện, vùng_tính) tính tổng theo điều kiện. Sắp xếp: chọn vùng dữ liệu > Data > Sort (A→Z tăng dần, Z→A giảm dần). Lọc: Data > Filter, bấm mũi tên ở tiêu đề cột để chọn giá trị cần hiển thị.','- Cú pháp hàm IF: =IF(điều kiện, giá trị khi đúng, giá trị khi sai).\n- Ví dụ =IF(B2>=5,\"Đạt\",\"Chưa đạt\") trả về Đạt khi B2 = 7.\n- COUNTIF(vùng, điều kiện) đếm các ô trong vùng thỏa mãn điều kiện cho trước.\n- Data > Filter tạo nút lọc ở tiêu đề cột để hiển thị dữ liệu theo tiêu chí.\n- Hàm điều kiện và lọc dữ liệu giúp xử lý bảng tính thông minh hơn.',2,'published',10,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(291,78,'Mạng máy tính và phân loại mạng','tin-hoc-thpt-11-lop-11-1','Nêu được khái niệm mạng máy tính; phân biệt LAN, WAN, MAN; biết các kiểu kết nối cơ bản.','trung_binh',15,'Mạng máy tính là tập hợp các máy tính được kết nối với nhau để chia sẻ tài nguyên (dữ liệu, máy in, kết nối Internet...). Phân loại theo phạm vi: LAN (mạng cục bộ: trong một toà nhà, trường học), MAN (mạng đô thị: trong một thành phố), WAN (mạng diện rộng: giữa các tỉnh, quốc gia; Internet là WAN lớn nhất). Phân loại theo kiểu kết nối: mạng có dây (cáp) và mạng không dây (Wi-Fi). Lợi ích: chia sẻ tài nguyên, trao đổi thông tin nhanh, tiết kiệm chi phí.','- Mạng máy tính là các máy tính kết nối với nhau để chia sẻ tài nguyên và trao đổi thông tin.\n- LAN là mạng cục bộ phạm vi hẹp; MAN phạm vi đô thị; WAN phạm vi diện rộng.\n- Internet là mạng WAN lớn nhất, kết nối hàng tỉ thiết bị trên toàn cầu.\n- Nhờ mạng máy tính, nhiều máy có thể dùng chung máy in, dữ liệu và kết nối Internet.\n- Phân loại mạng dựa vào phạm vi địa lý kết nối.',1,'published',11,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(292,78,'Mô hình mạng và thiết bị mạng','tin-hoc-thpt-11-lop-11-2','Phân biệt mô hình khách – chủ và mạng ngang hàng; kể tên và chức năng các thiết bị mạng cơ bản.','trung_binh',18,'Mô hình khách – chủ (client – server): có máy chủ (server) cung cấp tài nguyên, dịch vụ; các máy khách (client) sử dụng. Mạng ngang hàng (peer-to-peer): các máy bình đẳng, vừa dùng vừa chia sẻ tài nguyên. Thiết bị mạng: card mạng NIC (gắn trong máy để kết nối), hub/switch (nối nhiều máy trong LAN; switch thông minh hơn hub), router (định tuyến, nối các mạng với nhau, phát Wi-Fi), modem (chuyển đổi tín hiệu để kết nối Internet), cáp mạng và access point.','- Mô hình khách – chủ: server lưu trữ và cung cấp dịch vụ, client là máy sử dụng dịch vụ.\n- Switch hoặc hub là thiết bị trung tâm nối nhiều máy tính trong mạng LAN.\n- Router định tuyến gói tin giữa các mạng, thường tích hợp phát Wi-Fi trong gia đình.\n- Mạng ngang hàng (peer-to-peer) không phân biệt server và client, phù hợp mạng nhỏ.\n- Mỗi thiết bị mạng có vai trò riêng trong việc kết nối và truyền dữ liệu.',2,'published',11,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(293,79,'Internet và các dịch vụ cơ bản','tin-hoc-thpt-11-lop-11-3','Hiểu Internet là gì; kể được các dịch vụ: Web, email, tìm kiếm, lưu trữ đám mây; hiểu địa chỉ IP và tên miền.','trung_binh',15,'Internet là mạng máy tính toàn cầu, kết nối hàng tỉ thiết bị. Mỗi thiết bị có địa chỉ IP (ví dụ 192.168.1.1); tên miền (ví dụ google.com) giúp dễ nhớ, được DNS dịch thành IP. Các dịch vụ: World Wide Web (truy cập trang web qua trình duyệt), thư điện tử email, tìm kiếm thông tin, mạng xã hội, lưu trữ đám mây (Google Drive, OneDrive), học trực tuyến, thương mại điện tử. URL là địa chỉ của một trang web, bắt đầu bằng http:// hoặc https:// (bảo mật hơn).','- Mỗi thiết bị tham gia mạng có một địa chỉ IP duy nhất, ví dụ 192.168.1.1.\n- Hệ thống DNS dịch tên miền (như google.com) thành địa chỉ IP để máy tính hiểu.\n- HTTPS mã hóa dữ liệu truyền đi, an toàn hơn HTTP khi đăng nhập, thanh toán.\n- Email, tìm kiếm, lưu trữ đám mây là các dịch vụ trên Internet; soạn thảo offline thì không.\n- Internet mang lại nhiều dịch vụ tiện ích cho học tập và đời sống.',1,'published',11,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(294,79,'An toàn thông tin và phòng chống mã độc','tin-hoc-thpt-11-lop-11-4','Nhận biết các nguy cơ mất an toàn thông tin; biết cách phòng chống virus, bảo vệ tài khoản cá nhân.','kho',20,'Nguy cơ: virus, worm, trojan (mã độc phá hoại, đánh cắp dữ liệu), phishing (giả mạo để lừa mật khẩu), ransomware (mã hoá dữ liệu đòi tiền chuộc). Phòng chống: cài phần mềm diệt virus có bản quyền và cập nhật thường xuyên; không mở tệp đính kèm, liên kết lạ; đặt mật khẩu mạnh (dài, có chữ hoa, chữ thường, số, kí tự đặc biệt), bật xác thực hai yếu tố; sao lưu dữ liệu quan trọng; cập nhật hệ điều hành; không dùng Wi-Fi công cộng cho giao dịch quan trọng.','- Phishing là hình thức lừa người dùng nhập thông tin vào trang web giả mạo.\n- Ransomware mã hóa tệp tin, nạn nhân phải trả tiền mới lấy lại được dữ liệu.\n- Mật khẩu mạnh: dài, gồm chữ hoa, chữ thường, số và ký tự đặc biệt, không đoán được.\n- Email lạ có tệp đính kèm tuyệt đối không mở vì có thể chứa mã độc.\n- Cảnh giác với đường link và tệp lạ là cách phòng chống mã độc hiệu quả.',2,'published',11,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(295,80,'Khái niệm thuật toán và các cách mô tả','tin-hoc-thpt-12-lop-12-1','Nêu được khái niệm thuật toán; mô tả được thuật toán bằng liệt kê các bước và sơ đồ khối.','trung_binh',15,'Thuật toán là dãy hữu hạn các thao tác được sắp xếp theo trình tự xác định để giải một bài toán. Tính chất: tính dừng (phải kết thúc sau hữu hạn bước), tính xác định (mỗi bước rõ ràng, không mơ hồ), tính đúng đắn (cho kết quả đúng). Hai cách mô tả phổ biến: liệt kê từng bước bằng ngôn ngữ tự nhiên, và sơ đồ khối (hình ô van: bắt đầu/kết thúc; hình chữ nhật: tính toán; hình thoi: điều kiện rẽ nhánh; mũi tên: hướng thực hiện).','- Thuật toán mô tả cách giải bài toán bằng các bước rõ ràng, hữu hạn.\n- Thuật toán phải dừng sau hữu hạn bước; tính vô hạn là sai.\n- Trong sơ đồ khối: hình thoi là điều kiện rẽ nhánh, hình chữ nhật là tính toán, ô van là bắt đầu/kết thúc, mũi tên chỉ hướng đi.\n- Sơ đồ khối mô tả thuật toán một cách trực quan bằng hình vẽ.\n- Có thể mô tả thuật toán bằng liệt kê bước hoặc bằng sơ đồ khối.',1,'published',12,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(296,80,'Cấu trúc rẽ nhánh và lặp trong thuật toán','tin-hoc-thpt-12-lop-12-2','Phân biệt cấu trúc tuần tự, rẽ nhánh, lặp; vẽ được sơ đồ khối cho bài toán đơn giản có rẽ nhánh và lặp.','kho',18,'Ba cấu trúc điều khiển cơ bản: tuần tự (thực hiện các bước theo thứ tự từ trên xuống), rẽ nhánh (nếu điều kiện đúng thì làm việc A, ngược lại làm việc B — dạng đầy đủ; hoặc dạng thiếu: chỉ làm việc A khi điều kiện đúng), lặp (lặp lại một khối thao tác khi điều kiện còn đúng — lặp với số lần biết trước như for, hoặc lặp với điều kiện như while). Mọi thuật toán đều có thể xây dựng từ ba cấu trúc này.','- Cấu trúc tuần tự thực hiện các bước theo đúng thứ tự từ trên xuống.\n- Rẽ nhánh đầy đủ (if-else): điều kiện đúng thì làm A, sai thì làm B.\n- Cấu trúc lặp (for, while) thực hiện lại khối lệnh khi điều kiện còn đúng.\n- Bài toán tính tổng các số từ 1 đến 100 phù hợp với cấu trúc lặp.\n- Ba cấu trúc cơ bản kết hợp với nhau giải được mọi bài toán.',2,'published',12,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(297,81,'Lệnh print, biến và kiểu dữ liệu trong Python','tin-hoc-thpt-12-lop-12-3','Viết được chương trình Python đầu tiên với print; khai báo và sử dụng biến; phân biệt các kiểu dữ liệu cơ bản.','trung_binh',15,'Python không cần khai báo kiểu biến trước, chỉ cần gán giá trị: ten = \"An\". Lệnh print() in ra màn hình: print(\"Xin chào\"). Các kiểu dữ liệu cơ bản: int (số nguyên: 5, -3), float (số thực: 3.5), str (chuỗi kí tự trong ngoặc kép: \"hello\"), bool (True/False). Nhập dữ liệu từ bàn phím: input() luôn trả về chuỗi, muốn tính toán phải đổi kiểu: tuoi = int(input(\"Nhập tuổi: \")). Chú thích bằng dấu #.','- Lệnh print() dùng để in ra màn hình, ví dụ print(\"Xin chào\").\n- Python gán biến bằng dấu =, không cần khai báo kiểu trước.\n- Các kiểu dữ liệu cơ bản: int (số nguyên), float (số thập phân), str (chuỗi ký tự).\n- input() trả về chuỗi (str); muốn tính toán phải đổi kiểu, ví dụ int(input(\"Nhập tuổi: \")).\n- Biến giúp lưu trữ dữ liệu để chương trình xử lý.',1,'published',12,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(298,81,'Vòng lặp for, while và câu lệnh if trong Python','tin-hoc-thpt-12-lop-12-4','Sử dụng được if/elif/else, vòng lặp for và while để giải bài toán đơn giản.','kho',20,'Câu lệnh if rẽ nhánh: if điều_kiện: (khối lệnh thụt đầu dòng); thêm elif và else cho nhiều nhánh. Vòng lặp for duyệt dãy số: for i in range(5): chạy i từ 0 đến 4; range(1, 11) từ 1 đến 10. Vòng lặp while lặp khi điều kiện còn đúng: while n > 0: ... Chú ý thụt đầu dòng (thường 4 dấu cách) để xác định khối lệnh; lệnh break thoát vòng lặp, continue bỏ qua lần lặp hiện tại.','- range(3) tạo dãy 0, 1, 2; range(a, b) chạy từ a đến b-1.\n- Vòng lặp while tiếp tục chạy chừng nào điều kiện còn đúng.\n- Python dùng thụt đầu dòng để xác định khối lệnh sau if, for, while.\n- Thụt đầu dòng không đúng làm chương trình báo lỗi hoặc chạy sai.\n- Kết hợp if với vòng lặp giải được nhiều bài toán thực tế.',2,'published',12,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(299,82,'Dòng điện, điện áp và các đại lượng điện','cong-nghe-thpt-10-lop-10-1','Nêu được khái niệm dòng điện, điện áp, điện trở, công suất; biết đơn vị đo và dụng cụ đo.','trung_binh',15,'Dòng điện là dòng chuyển dời có hướng của các hạt mang điện; cường độ dòng điện (I) đo bằng ampe (A), đo bằng ampe kế mắc nối tiếp. Điện áp (U) là hiệu điện thế giữa hai điểm, đo bằng vôn (V), đo bằng vôn kế mắc song song. Điện trở (R) cản trở dòng điện, đo bằng ôm (Ω). Định luật Ôm: I = U / R. Công suất điện P = U × I, đo bằng oát (W); điện năng tiêu thụ A = P × t, đo bằng kWh (số điện).','- Cường độ dòng điện I đo bằng ampe (A), điện áp đo bằng vôn (V), điện trở đo bằng ôm.\n- Vôn kế đo điện áp được mắc song song với đoạn mạch; ampe kế đo dòng điện mắc nối tiếp.\n- Định luật Ôm: I = U/R, dòng điện tỉ lệ thuận với điện áp, tỉ lệ nghịch với điện trở.\n- Số liệu 220V – 100W là thông số định mức: dùng đúng 220V thì công suất là 100W.\n- Nắm vững các đại lượng điện là cơ sở để học mạch điện.',1,'published',10,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(300,82,'Mạch điện một chiều: mắc nối tiếp và song song','cong-nghe-thpt-10-lop-10-2','Phân biệt cách mắc nối tiếp và song song; tính được điện trở tương đương, dòng điện, điện áp trong mạch đơn giản.','kho',18,'Mắc nối tiếp: các thiết bị nối đuôi nhau thành một vòng kín; dòng điện qua các thiết bị bằng nhau (I = I1 = I2), điện áp toàn mạch bằng tổng điện áp từng phần (U = U1 + U2), điện trở tương đương R = R1 + R2. Mắc song song: các thiết bị nối chung hai đầu; điện áp trên các nhánh bằng nhau (U = U1 = U2), dòng điện toàn mạch bằng tổng dòng các nhánh (I = I1 + I2), 1/R = 1/R1 + 1/R2. Trong gia đình, các thiết bị mắc song song để mỗi thiết bị được điện áp 220V.','- Mạch mắc nối tiếp chỉ có một đường đi nên dòng điện qua mọi thiết bị bằng nhau.\n- Điện trở tương đương mạch nối tiếp: R = R1 + R2, ví dụ 4 ôm + 6 ôm = 10 ôm.\n- Các nhánh song song cùng nối vào hai điểm chung nên điện áp trên các nhánh bằng nhau.\n- Thiết bị điện trong gia đình mắc song song: mỗi thiết bị đủ 220V, tắt một cái các cái khác vẫn chạy.\n- Phân biệt mắc nối tiếp và song song để hiểu cách đấu điện trong nhà.',2,'published',10,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(301,83,'Nguyên nhân tai nạn điện và cách phòng tránh','cong-nghe-thpt-10-lop-10-3','Kể được các nguyên nhân gây tai nạn điện; nêu các biện pháp phòng tránh trong gia đình.','trung_binh',15,'Nguyên nhân tai nạn điện: chạm trực tiếp vào vật mang điện (ổ cắm hở, dây trần), chạm gián tiếp qua vật dẫn bị nhiễm điện (vỏ máy hỏng cách điện), vi phạm khoảng cách an toàn với lưới điện cao áp, sét đánh, dùng thiết bị điện kém chất lượng. Phòng tránh: không chạm tay ướt vào thiết bị điện; ngắt điện trước khi sửa chữa; dùng aptomat, cầu dao chống rò; nối đất cho thiết bị vỏ kim loại; giữ khoảng cách an toàn với đường dây cao áp; kiểm tra định kì hệ thống điện.','- Tay ướt dẫn điện tốt, chạm vào thiết bị điện rất dễ bị giật.\n- Chim đậu trên dây điện cao thế không bị giật vì không có hiệu điện thế đáng kể qua cơ thể.\n- Aptomat tự động ngắt điện khi quá tải, ngắn mạch; loại chống rò còn bảo vệ khi rò điện.\n- Khi sửa chữa điện trong nhà, việc đầu tiên phải làm là ngắt điện.\n- Hiểu nguyên nhân tai nạn điện để phòng tránh hiệu quả.',1,'published',10,1,'2026-10-07 22:54:16','2026-10-07 22:54:16'),
(302,83,'Sơ cứu người bị điện giật','cong-nghe-thpt-10-lop-10-4','Nêu đúng trình tự các bước sơ cứu người bị điện giật; biết cách hô hấp nhân tạo và ép tim ngoài lồng ngực.','kho',18,'Trình tự sơ cứu: (1) Nhanh chóng tách nạn nhân khỏi nguồn điện bằng vật cách điện (gậy gỗ khô, vải khô) — tuyệt đối không chạm tay trần vào nạn nhân khi chưa ngắt điện; (2) Ngắt nguồn điện (cầu dao, aptomat); (3) Đặt nạn nhân nằm nơi thoáng, nới lỏng quần áo, kiểm tra hô hấp; (4) Nếu ngừng thở: hô hấp nhân tạo (thổi ngạt) kết hợp ép tim ngoài lồng ngực (100–120 lần/phút); (5) Gọi cấp cứu 115 và đưa đến cơ sở y tế gần nhất. Sơ cứu càng sớm, cơ hội cứu sống càng cao.','- Khi chưa ngắt được điện, tuyệt đối không chạm tay trần vào nạn nhân bị điện giật.\n- Số điện thoại cấp cứu y tế là 115; công an là 113; cứu hỏa là 114.\n- Nạn nhân ngừng thở cần hô hấp nhân tạo và ép tim càng sớm càng tốt.\n- Ép tim ngoài lồng ngực 100–120 lần mỗi phút, ấn sâu khoảng 5cm ở người lớn.\n- Sơ cứu đúng và kịp thời có thể cứu sống nạn nhân.',2,'published',10,1,'2026-10-07 22:54:17','2026-10-07 22:54:17'),
(303,84,'Khái niệm bản vẽ kỹ thuật và các loại đường nét','cong-nghe-thpt-11-lop-11-1','Nêu được vai trò của bản vẽ kỹ thuật; nhận biết và vẽ đúng các loại đường nét cơ bản.','trung_binh',15,'Bản vẽ kỹ thuật là ngôn ngữ chung của ngành kỹ thuật, dùng để diễn đạt hình dạng, kích thước, vật liệu của sản phẩm. Các loại đường nét: nét liền đậm (cạnh thấy, đường bao thấy), nét liền mảnh (đường kích thước, đường gióng, đường gạch gạch), nét đứt (cạnh khuất), nét chấm gạch mảnh (đường tâm, trục đối xứng), nét lượn sóng (đường giới hạn một phần hình cắt). Khổ giấy tiêu chuẩn: A0, A1, A2, A3, A4; khung tên ghi thông tin bản vẽ.','- Bản vẽ kỹ thuật là ngôn ngữ chung giúp người thiết kế và người chế tạo hiểu đúng ý nhau.\n- Nét liền đậm vẽ cạnh thấy (đường bao thấy); nét đứt vẽ cạnh khuất.\n- Nét chấm gạch mảnh vẽ đường tâm và trục đối xứng.\n- Khổ giấy A4 là 210x297mm; A3 là 297x420mm; mỗi khổ sau gấp đôi khổ trước.\n- Đọc đúng các loại đường nét là bước đầu để hiểu bản vẽ.',1,'published',11,1,'2026-10-07 22:54:17','2026-10-07 22:54:17'),
(304,84,'Hình chiếu và hình chiếu trục đo','cong-nghe-thpt-11-lop-11-2','Hiểu phép chiếu vuông góc; xác định được hình chiếu đứng, bằng, cạnh; nhận biết hình chiếu trục đo.','kho',18,'Phép chiếu vuông góc: chiếu vật thể lên mặt phẳng bằng các tia chiếu vuông góc với mặt phẳng chiếu. Ba hình chiếu cơ bản: hình chiếu đứng (nhìn từ trước), hình chiếu bằng (nhìn từ trên), hình chiếu cạnh (nhìn từ trái). Vị trí: hình chiếu bằng đặt dưới hình chiếu đứng, hình chiếu cạnh đặt bên phải hình chiếu đứng, các hình chiếu liên hệ với nhau theo quy tắc (ngang bằng, dọc thẳng). Hình chiếu trục đo (ví dụ trục đo vuông góc đều) thể hiện cả ba chiều trong một hình, giúp hình dung vật thể dễ dàng.','- Phép chiếu vuông góc: tia chiếu vuông góc với mặt phẳng chiếu tạo ra hình chiếu.\n- Hình chiếu đứng nhìn vật thể từ phía trước; hình chiếu bằng nhìn từ trên; hình chiếu cạnh nhìn từ bên trái.\n- Quy tắc bố trí: hình chiếu bằng nằm dưới hình chiếu đứng, hình chiếu cạnh nằm bên phải hình chiếu đứng.\n- Hình chiếu trục đo giúp hình dung vật thể trong không gian dễ dàng hơn.\n- Ba hình chiếu phối hợp cho biết đầy đủ hình dạng vật thể.',2,'published',11,1,'2026-10-07 22:54:17','2026-10-07 22:54:17'),
(305,85,'Đọc bản vẽ chi tiết máy đơn giản','cong-nghe-thpt-11-lop-11-3','Đọc được khung tên, hình biểu diễn, kích thước, kí hiệu trên bản vẽ chi tiết đơn giản.','trung_binh',15,'Trình tự đọc bản vẽ chi tiết: (1) Đọc khung tên: tên chi tiết, vật liệu, tỉ lệ, người vẽ; (2) Phân tích hình biểu diễn: có mấy hình chiếu, mặt cắt nào; (3) Đọc kích thước: kích thước định hình (dài, rộng, cao), kích thước định vị trí tương đối; (4) Đọc yêu cầu kỹ thuật: độ nhám bề mặt, dung sai, nhiệt luyện. Ví dụ: chi tiết dạng hộp chữ nhật 60×40×20 mm, vật liệu thép CT3, có 2 lỗ khoan đường kính 10 mm.','- Khi đọc bản vẽ chi tiết, đọc khung tên trước để biết tổng quan về chi tiết.\n- Kí hiệu đường kính là Ø (ví dụ Ø20), kí hiệu bán kính là R.\n- Kích thước định hình cho biết độ lớn của chi tiết; kích thước định vị cho biết vị trí tương đối.\n- Con số kích thước ghi phía trên đường kích thước, đơn vị mặc định là mm.\n- Đọc bản vẽ đúng trình tự giúp hiểu chính xác yêu cầu chế tạo.',1,'published',11,1,'2026-10-07 22:54:17','2026-10-07 22:54:17'),
(306,85,'Đọc bản vẽ lắp và bản vẽ nhà','cong-nghe-thpt-11-lop-11-4','Phân biệt bản vẽ chi tiết, bản vẽ lắp, bản vẽ nhà; đọc được thông tin cơ bản trên bản vẽ lắp và bản vẽ nhà.','kho',20,'Bản vẽ lắp diễn tả hình dạng, kết cấu và vị trí tương đối của các chi tiết trong một sản phẩm, kèm bảng kê (số thứ tự, tên gọi, số lượng, vật liệu từng chi tiết). Đọc bản vẽ lắp: xem hình biểu diễn chung, đối chiếu số thứ tự với bảng kê, hiểu nguyên lí làm việc. Bản vẽ nhà gồm: mặt bằng (bố trí các phòng nhìn từ trên), mặt đứng (hình dáng bên ngoài), mặt cắt (cấu tạo bên trong). Kí hiệu thường gặp: cửa đi, cửa sổ, cầu thang, hướng bắc, cốt cao độ.','- Bản vẽ lắp thể hiện cách lắp các chi tiết thành sản phẩm hoàn chỉnh.\n- Đối chiếu số thứ tự trên hình vẽ với bảng kê để biết từng chi tiết.\n- Bản vẽ nhà gồm: mặt bằng cho biết bố trí không gian, mặt đứng cho biết hình dáng bên ngoài, mặt cắt cho biết cấu tạo bên trong.\n- Kí hiệu mũi tên chỉ hướng Bắc giúp bố trí phòng ốc đón nắng, tránh nắng hợp lý.\n- Đọc được bản vẽ lắp và bản vẽ nhà phục vụ đời sống thực tế.',2,'published',11,1,'2026-10-07 22:54:17','2026-10-07 22:54:17'),
(307,86,'Cách mạng công nghiệp và công nghệ trong sản xuất','cong-nghe-thpt-12-lop-12-1','Kể được 4 cuộc cách mạng công nghiệp; nêu vai trò của công nghệ trong sản xuất hiện đại.','trung_binh',15,'Bốn cuộc cách mạng công nghiệp: lần 1 (cuối thế kỉ 18): cơ khí hoá với máy hơi nước; lần 2 (cuối thế kỉ 19): điện khí hoá, sản xuất hàng loạt; lần 3 (giữa thế kỉ 20): tự động hoá với máy tính, công nghệ thông tin; lần 4 (hiện nay): số hoá, trí tuệ nhân tạo, Internet vạn vật (IoT), dữ liệu lớn. Công nghệ giúp tăng năng suất, nâng cao chất lượng, giảm chi phí, tiết kiệm tài nguyên và bảo vệ môi trường.','- Cách mạng công nghiệp lần 1 gắn với máy hơi nước (cuối thế kỉ 18); lần 2 với điện; lần 3 với máy tính; lần 4 với số hóa và AI.\n- Cách mạng công nghiệp 4.0 đặc trưng bởi số hóa, kết nối vạn vật (IoT), trí tuệ nhân tạo và robot thông minh.\n- Công nghệ giúp sản xuất hiệu quả hơn, tiết kiệm tài nguyên và sức lao động.\n- IoT là các thiết bị như tủ lạnh, camera, cảm biến kết nối mạng và hoạt động thông minh.\n- Mỗi cuộc cách mạng công nghiệp đều thay đổi mạnh mẽ sản xuất và đời sống.',1,'published',12,1,'2026-10-07 22:54:17','2026-10-07 22:54:17'),
(308,86,'Tự động hoá và robot trong sản xuất','cong-nghe-thpt-12-lop-12-2','Hiểu khái niệm tự động hoá; kể được ứng dụng của robot trong sản xuất và đời sống.','kho',18,'Tự động hoá là ứng dụng kỹ thuật điều khiển để máy móc tự vận hành, giảm sự can thiệp của con người. Dây chuyền tự động: cảm biến thu thập thông tin, bộ điều khiển (PLC, máy tính) xử lí, cơ cấu chấp hành thực hiện. Robot công nghiệp: tay máy lắp ráp ô tô, robot hàn, robot sơn, robot đóng gói; robot phục vụ: giao hàng, y tế, gia đình. Ưu điểm: chính xác, nhanh, làm việc liên tục, thay con người trong môi trường nguy hiểm. Thách thức: chi phí đầu tư cao, đòi hỏi nhân lực trình độ cao.','- Hệ thống tự động gồm: cảm biến thu thập thông tin, bộ điều khiển xử lý, cơ cấu chấp hành thực hiện.\n- Bộ điều khiển đóng vai trò bộ não trong hệ thống tự động.\n- Robot công nghiệp làm việc chính xác, liên tục trong môi trường nguy hiểm.\n- Robot cần bảo trì và đầu tư ban đầu cao nhưng mang lại hiệu quả lâu dài.\n- Tự động hóa giúp nâng cao năng suất và giảm lao động nặng nhọc.',2,'published',12,1,'2026-10-07 22:54:17','2026-10-07 22:54:17'),
(309,87,'Ô nhiễm môi trường và nguyên nhân','cong-nghe-thpt-12-lop-12-3','Kể được các loại ô nhiễm môi trường; phân tích nguyên nhân từ hoạt động sản xuất và sinh hoạt.','trung_binh',15,'Các loại ô nhiễm: ô nhiễm không khí (khí thải công nghiệp, giao thông: CO, SO₂, bụi mịn), ô nhiễm nước (nước thải chưa xử lí, hoá chất nông nghiệp), ô nhiễm đất (rác thải, thuốc trừ sâu, kim loại nặng), ô nhiễm tiếng ồn và ô nhiễm ánh sáng. Nguyên nhân: sản xuất công nghiệp xả thải vượt chuẩn, giao thông, nông nghiệp lạm dụng hoá chất, sinh hoạt (rác thải nhựa, túi ni lông), khai thác tài nguyên bừa bãi. Hậu quả: ảnh hưởng sức khoẻ, biến đổi khí hậu, suy giảm đa dạng sinh học.','- Ô nhiễm không khí chủ yếu do khí thải chứa CO, SO2 và bụi mịn.\n- Nước thải chưa qua xử lý mang hóa chất, chất hữu cơ gây ô nhiễm nguồn nước.\n- Bụi mịn PM2.5 nhỏ hơn 2,5 micromet, rất nguy hiểm cho sức khỏe.\n- Hóa chất nông nghiệp ngấm vào đất, nước và tồn dư trong thực phẩm gây ô nhiễm.\n- Nhận biết nguyên nhân ô nhiễm là bước đầu để bảo vệ môi trường.',1,'published',12,1,'2026-10-07 22:54:17','2026-10-07 22:54:17'),
(310,87,'Biện pháp bảo vệ môi trường và phát triển bền vững','cong-nghe-thpt-12-lop-12-4','Nêu được các biện pháp bảo vệ môi trường; hiểu khái niệm phát triển bền vững và trách nhiệm của bản thân.','kho',18,'Biện pháp: xử lí chất thải trước khi thải ra môi trường (khí thải, nước thải); áp dụng công nghệ sạch, tiết kiệm năng lượng; phân loại rác tại nguồn và tái chế; trồng cây xanh; sử dụng năng lượng tái tạo (mặt trời, gió). Phát triển bền vững là phát triển đáp ứng nhu cầu hiện tại mà không làm tổn hại khả năng đáp ứng nhu cầu của thế hệ tương lai (kinh tế – xã hội – môi trường hài hoà). Mỗi học sinh có thể: tiết kiệm điện nước, hạn chế nhựa dùng một lần, tham gia trồng cây, tuyên truyền bảo vệ môi trường.','- Phát triển bền vững là sự hài hòa giữa kinh tế, xã hội và môi trường.\n- Phân loại và tái chế rác giúp giảm rác thải, tiết kiệm tài nguyên.\n- Năng lượng tái tạo: mặt trời, gió, thủy triều; năng lượng hóa thạch: than, dầu, khí.\n- Học sinh góp phần bảo vệ môi trường bằng những hành động nhỏ hằng ngày.\n- Bảo vệ môi trường hôm nay là giữ cuộc sống tốt đẹp cho mai sau.',2,'published',12,1,'2026-10-07 22:54:17','2026-10-07 22:54:17'),
(311,88,'Chuyển động thẳng đều: vận tốc và quãng đường (1)','khoa-hoc-thpt-10-lop-10-1','Tính được vận tốc, quãng đường, thời gian trong chuyển động thẳng đều; đổi đơn vị km/h sang m/s.','trung_binh',15,'Chuyển động thẳng đều có vận tốc không đổi: v = s/t; s = v·t; t = s/v. Đổi đơn vị: 1 m/s = 3,6 km/h. Đồ thị quãng đường – thời gian là đường thẳng xiên.','- Vận tốc của chuyển động thẳng đều bằng quãng đường chia cho thời gian: v = s / t.\n- Quãng đường đi được: s = v × t; ví dụ xe chạy 54 km/h trong 2 giờ đi được 108 km.\n- Ví dụ: đi bộ 6 km hết 1,5 giờ thì vận tốc trung bình là 4 km/h.\n- Trong chuyển động thẳng đều, vận tốc không đổi theo thời gian.\n- Đồ thị quãng đường – thời gian của chuyển động thẳng đều là đường thẳng xiên qua gốc tọa độ.',1,'published',10,1,'2026-10-07 22:54:54','2026-10-07 22:54:54'),
(312,88,'Chuyển động thẳng biến đổi đều: gia tốc (2)','khoa-hoc-thpt-10-lop-10-2','Tính gia tốc; vận dụng v = v₀ + at, s = v₀t + ½at²; phân biệt nhanh dần đều và chậm dần đều.','kho',18,'Gia tốc a = Δv/Δt đặc trưng cho sự thay đổi vận tốc. Nhanh dần đều: a cùng chiều v; chậm dần đều: a ngược chiều v. Rơi tự do là nhanh dần đều với g ≈ 9,8 m/s².','- Gia tốc bằng độ biến thiên vận tốc chia cho thời gian biến thiên: a = Δv / Δt.\n- Ví dụ: ô tô tăng tốc từ 10 m/s lên 20 m/s trong 5 s thì gia tốc là 2 m/s².\n- Chuyển động thẳng nhanh dần đều: gia tốc cùng chiều với vận tốc làm tốc độ tăng dần.\n- Chuyển động thẳng chậm dần đều: gia tốc ngược chiều với vận tốc làm tốc độ giảm dần.\n- Với gia tốc không đổi, quãng đường được tính bằng công thức của chuyển động thẳng biến đổi đều.',2,'published',10,1,'2026-10-07 22:54:54','2026-10-07 22:54:54'),
(313,89,'Ba định luật Newton (3)','khoa-hoc-thpt-10-lop-10-3','Phát biểu được ba định luật Newton; vận dụng F = m·a; nhận biết cặp lực – phản lực.','trung_binh',15,'Định luật I: quán tính — vật giữ nguyên trạng thái chuyển động khi hợp lực bằng 0. Định luật II: F = m·a. Định luật III: lực và phản lực cùng phương, ngược chiều, cùng độ lớn, đặt lên hai vật khác nhau.','- Định luật I Newton (định luật quán tính): vật giữ nguyên trạng thái đứng yên hoặc chuyển động thẳng đều khi không chịu lực hoặc hợp lực bằng 0.\n- Định luật II Newton: gia tốc của vật tỉ lệ thuận với lực tác dụng và tỉ lệ nghịch với khối lượng: a = F / m.\n- Ví dụ: vật khối lượng 2 kg chịu lực 10 N thì gia tốc của vật là 5 m/s².\n- Định luật III Newton: lực và phản lực đặt lên hai vật khác nhau nên không triệt tiêu nhau.\n- Ba định luật Newton là cơ sở của cơ học cổ điển, giải thích chuyển động của các vật.',1,'published',10,1,'2026-10-07 22:54:54','2026-10-07 22:54:54'),
(314,89,'Trọng lực, lực ma sát và lực đàn hồi (4)','khoa-hoc-thpt-10-lop-10-4','Tính trọng lượng P = m·g; phân biệt ma sát nghỉ/trượt; nêu đặc điểm lực đàn hồi; biết cách tăng/giảm ma sát.','kho',18,'Trọng lực P = m·g, phương thẳng đứng, chiều từ trên xuống. Ma sát nghỉ giữ vật chưa trượt; ma sát trượt ngược chiều chuyển động. Lực đàn hồi ngược chiều biến dạng, tỉ lệ với độ biến dạng.','- Trọng lượng P bằng khối lượng m nhân với gia tốc rơi tự do g: P = m × g.\n- Ví dụ: vật khối lượng 5 kg (lấy g = 10 m/s²) có trọng lượng là 50 N.\n- Lực ma sát nghỉ xuất hiện khi có lực có xu hướng làm vật trượt; nó cân bằng với lực đó.\n- Lực ma sát có lợi khi giúp ta đi lại, cầm nắm; có hại khi làm mòn chi tiết máy.\n- Lực đàn hồi của lò xo chống lại biến dạng: F = k × Δl.',2,'published',10,1,'2026-10-07 22:54:54','2026-10-07 22:54:54'),
(315,90,'Hạt cơ bản cấu tạo nên nguyên tử (1)','khoa-hoc-thpt-11-lop-11-1','Nêu điện tích, vị trí của proton, neutron, electron; xác định số hiệu nguyên tử Z.','trung_binh',15,'Nguyên tử gồm hạt nhân (proton mang điện +1, neutron không mang điện) và vỏ electron (mang điện −1). Z = số proton = số electron khi nguyên tử trung hòa. Khối lượng nguyên tử tập trung ở hạt nhân.','- Nguyên tử gồm hạt nhân (proton, nơtron) và các electron chuyển động xung quanh.\n- Proton nằm trong hạt nhân, mỗi proton mang điện tích +1.\n- Số hiệu nguyên tử Z đặc trưng cho nguyên tố hoá học và bằng số proton trong hạt nhân.\n- Nguyên tử trung hoà về điện vì điện tích dương của proton cân bằng điện tích âm của electron.\n- Electron có khối lượng rất nhỏ, chỉ bằng khoảng 1/1836 khối lượng proton.',1,'published',11,1,'2026-10-07 22:54:54','2026-10-07 22:54:54'),
(316,90,'Số khối, đồng vị và cấu hình electron (2)','khoa-hoc-thpt-11-lop-11-2','Tính số khối A = Z + N; nhận biết đồng vị; xác định số electron lớp ngoài cùng.','kho',18,'Số khối A = số proton + số neutron. Đồng vị: cùng Z, khác số neutron. Electron phân bố theo lớp K (tối đa 2), L (tối đa 8), M (tối đa 18) theo mức năng lượng tăng dần.','- Số khối A của hạt nhân bằng tổng số proton (Z) và số nơtron (N): A = Z + N.\n- Ví dụ: nguyên tử X có Z = 8, N = 8 thì A = 16, đó là đồng vị oxi-16.\n- Hai nguyên tử là đồng vị của nhau khi cùng Z (cùng nguyên tố) nhưng khác số nơtron.\n- Số electron tối đa của lớp thứ n là 2n²; lớp L (n = 2) chứa tối đa 8 electron.\n- Các electron được sắp xếp thành từng lớp, từng phân lớp theo nguyên tắc nhất định.',2,'published',11,1,'2026-10-07 22:54:54','2026-10-07 22:54:54'),
(317,91,'Nguyên tắc sắp xếp và cấu tạo bảng tuần hoàn (3)','khoa-hoc-thpt-11-lop-11-3','Nêu nguyên tắc sắp xếp theo Z tăng dần; xác định chu kì, nhóm; gọi tên các nhóm IA, IIA, VIIA, VIIIA.','trung_binh',15,'Các nguyên tố sắp xếp theo số hiệu nguyên tử tăng dần thành 7 chu kì (số lớp electron) và 18 cột. Nhóm IA: kim loại kiềm; IIA: kiềm thổ; VIIA: halogen; VIIIA: khí hiếm.','- Các nguyên tố trong bảng tuần hoàn được sắp xếp theo số hiệu nguyên tử Z tăng dần.\n- Bảng tuần hoàn hiện nay có 7 chu kì, tương ứng với 7 lớp electron.\n- Số thứ tự chu kì bằng số lớp electron của nguyên tử nguyên tố đó.\n- Nguyên tố ở chu kì 3 có 3 lớp electron.\n- Nhóm VIIIA gồm các khí hiếm: lớp ngoài cùng bền vững (8 electron) nên rất trơ về mặt hoá học.',1,'published',11,1,'2026-10-07 22:54:54','2026-10-07 22:54:54'),
(318,91,'Xu hướng biến đổi tính chất các nguyên tố (4)','khoa-hoc-thpt-11-lop-11-4','Dự đoán xu hướng biến đổi bán kính nguyên tử, độ âm điện, tính kim loại – phi kim trong chu kì và nhóm.','kho',18,'Trong chu kì (trái → phải): bán kính giảm, độ âm điện tăng, tính kim loại giảm. Trong nhóm A (trên → dưới): bán kính tăng, tính kim loại tăng. Flo có độ âm điện lớn nhất.','- Trong một chu kì, đi từ trái sang phải, điện tích hạt nhân tăng nên hút electron mạnh hơn, bán kính nguyên tử giảm.\n- Trong một nhóm A, đi từ trên xuống dưới, bán kính tăng, electron lớp ngoài dễ mất đi hơn nên tính kim loại tăng.\n- Flo là nguyên tố có độ âm điện lớn nhất trong bảng tuần hoàn.\n- Trong chu kì 3, nguyên tố đầu chu kì có tính kim loại mạnh nhất; tính kim loại giảm dần sang phải.\n- Hiểu xu hướng biến đổi giúp dự đoán tính chất của nguyên tố chưa nghiên cứu kĩ.',2,'published',11,1,'2026-10-07 22:54:54','2026-10-07 22:54:54'),
(319,92,'Cấu trúc phân tử ADN (1)','khoa-hoc-thpt-12-lop-12-1','Nêu thành phần nucleotit, nguyên tắc bổ sung A–T, G–X; suy ra mạch bổ sung; mô tả mô hình xoắn kép.','trung_binh',15,'ADN gồm hai mạch xoắn kép, đơn phân là nucleotit. Nguyên tắc bổ sung: A–T (2 liên kết hiđro), G–X (3 liên kết hiđro). Mô hình do Watson và Crick đề xuất năm 1953.','- ADN được cấu tạo từ các đơn phân là nucleotit; mỗi nucleotit gồm đường deoxyribose, axit photphoric và bazơ nitơ.\n- Năm 1953, Watson và Crick công bố mô hình xoắn kép của phân tử ADN.\n- Theo nguyên tắc bổ sung: A liên kết với T bằng 2 liên kết hiđro, G liên kết với X.\n- Đoạn mạch có trình tự A–T–G–X thì mạch bổ sung là T–A–X–G.\n- Cấu trúc xoắn kép và nguyên tắc bổ sung là cơ sở của sự nhân đôi và truyền đạt thông tin di truyền.',1,'published',12,1,'2026-10-07 22:54:54','2026-10-07 22:54:54'),
(320,92,'Gen và mã di truyền (2)','khoa-hoc-thpt-12-lop-12-2','Định nghĩa gen; nêu đặc điểm mã di truyền; nhận biết bộ ba mở đầu và các bộ ba kết thúc.','kho',18,'Gen là đoạn ADN mang thông tin di truyền. Mã di truyền đọc theo bộ ba nucleotit: AUG mở đầu; UAA, UAG, UGA kết thúc. Mã có tính phổ biến, đặc hiệu và thoái hóa.','- Gen là một đoạn của phân tử ADN mang thông tin mã hoá cho một sản phẩm nhất định (chuỗi pôlipeptit hay ARN).\n- Mã di truyền được đọc theo từng bộ ba nucleotit (codon), mỗi codon mã hoá cho một axit amin.\n- AUG vừa là bộ ba mở đầu dịch mã vừa mã hoá axit amin Metionin.\n- Mã di truyền có tính thoái hoá: nhiều codon khác nhau có thể cùng mã hoá cho một axit amin (ví dụ Lơxin).\n- Tính thoái hoá giúp giảm tác hại khi ADN bị đột biến.',2,'published',12,1,'2026-10-07 22:54:54','2026-10-07 22:54:54'),
(321,93,'Lai một cặp tính trạng và quy luật phân li (3)','khoa-hoc-thpt-12-lop-12-3','Phân biệt trội/lặn, đồng hợp/dị hợp; dự đoán tỉ lệ 3:1 (kiểu hình) và 1:2:1 (kiểu gen).','trung_binh',15,'Mendel thí nghiệm trên đậu Hà Lan: Aa × Aa cho F2 tỉ lệ 3 trội : 1 lặn. Dòng thuần có kiểu gen đồng hợp. Lai phân tích (với cá thể lặn) dùng để kiểm tra kiểu gen.','- Tính trạng trội là tính trạng được biểu hiện, lấn át sự biểu hiện của alen lặn ở cơ thể dị hợp.\n- Cơ thể có kiểu gen Aa mang hai alen khác nhau của cùng một gen nên gọi là thể dị hợp.\n- Phép lai Aa × Aa cho tỉ lệ kiểu hình ở F2 là 3 trội : 1 lặn — tỉ lệ đặc trưng của lai một cặp tính trạng.\n- Quy luật phân li của Mendel: mỗi giao tử chỉ chứa một alen của cặp alen.\n- Thí nghiệm của Mendel trên đậu Hà Lan đặt nền móng cho di truyền học.',1,'published',12,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(322,93,'Lai hai cặp tính trạng và phân li độc lập (4)','khoa-hoc-thpt-12-lop-12-4','Xác định số loại giao tử; dự đoán tỉ lệ 9:3:3:1; giải thích sự xuất hiện biến dị tổ hợp.','kho',18,'AaBb × AaBb cho 9:3:3:1 = (3:1)×(3:1). Cơ thể dị hợp n cặp gen cho 2ⁿ loại giao tử. Các gen trên các cặp NST tương đồng khác nhau phân li độc lập, tạo biến dị tổ hợp.','- Phép lai AaBb × AaBb cho tỉ lệ kiểu hình ở F2 là 9 : 3 : 3 : 1, đặc trưng của phân li độc lập.\n- Tỉ lệ 9:3:3:1 chính là tích của hai tỉ lệ 3:1, vì mỗi cặp tính trạng phân li 3:1.\n- Cơ thể có kiểu gen AaBb giảm phân tạo 4 loại giao tử (2², với n là số cặp gen dị hợp).\n- Điều kiện để các gen phân li độc lập: các cặp NST tương đồng phân li độc lập trong giảm phân.\n- Quy luật phân li độc lập giải thích sự đa dạng di truyền của sinh vật.',2,'published',12,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(323,94,'Buổi đầu độc lập: Ngô, Đinh, Tiền Lê (1)','lich-su-thpt-10-lop-10-1','Trình bày các sự kiện 938, 968, 981; nêu ý nghĩa giành độc lập và quốc hiệu Đại Cồ Việt.','trung_binh',15,'938: Ngô Quyền thắng Bạch Đằng, đóng đô Cổ Loa. 968: Đinh Bộ Lĩnh dẹp loạn 12 sứ quân, quốc hiệu Đại Cồ Việt, đô Hoa Lư. 981: Lê Hoàn đánh thắng quân Tống xâm lược.','- Chiến thắng Bạch Đằng năm 938 gắn với tên tuổi Ngô Quyền: dùng cọc gỗ đánh tan quân Nam Hán, mở ra thời kì độc lập.\n- Năm 968, Đinh Bộ Lĩnh lên ngôi hoàng đế, đặt quốc hiệu Đại Cồ Việt — quốc hiệu chính thức đầu tiên của nhà nước phong kiến Việt Nam.\n- Kinh đô nước Đại Cồ Việt thời Đinh – Tiền Lê đặt tại Hoa Lư (nay thuộc Ninh Bình).\n- Năm 981, Lê Hoàn (Lê Đại Hành) lãnh đạo kháng chiến đánh tan quân Tống, bảo vệ nền độc lập non trẻ.\n- Giai đoạn Ngô – Đinh – Tiền Lê đặt nền móng cho nhà nước phong kiến độc lập, tự chủ.',1,'published',10,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(324,94,'Các triều đại Lý, Trần, Hồ, Lê và những chiến công (2)','lich-su-thpt-10-lop-10-2','Nêu quá trình các triều đại và các chiến thắng tiêu biểu: chống Tống, chống Mông – Nguyên, Lam Sơn, Tây Sơn.','kho',18,'Lý (1009): dời đô Thăng Long 1010. Trần: ba lần thắng Mông – Nguyên. Lê sơ: khởi nghĩa Lam Sơn 1418–1427. Tây Sơn: Rạch Gầm 1785, Ngọc Hồi – Đống Đa 1789. Nguyễn thành lập 1802.','- Năm 1009, Lý Công Uẩn lên ngôi, lập ra nhà Lý, mở ra thời kì phát triển rực rỡ.\n- Nhà Trần lãnh đạo nhân dân ba lần đánh thắng Mông – Nguyên (1258, 1285, 1287–1288).\n- Lê Lợi cùng Nguyễn Trãi lãnh đạo khởi nghĩa Lam Sơn (1418–1427), giành lại độc lập từ tay nhà Minh.\n- Năm 1789, Quang Trung hành quân thần tốc, đại phá 29 vạn quân Thanh ở Ngọc Hồi – Đống Đa.\n- Mỗi triều đại đều ghi dấu những chiến công hiển hách bảo vệ Tổ quốc.',2,'published',10,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(325,95,'Giáo dục và khoa cử thời phong kiến (3)','lich-su-thpt-10-lop-10-3','Trình bày sự ra đời của Văn Miếu – Quốc Tử Giám và các khoa thi; nêu vai trò của khoa cử Nho học.','trung_binh',15,'1070 dựng Văn Miếu, 1076 mở Quốc Tử Giám, 1075 khoa thi đầu tiên, 1919 khoa thi cuối cùng. Các cấp thi Hương – Hội – Đình chọn nhân tài giúp nước.','- Năm 1076, vua Lý Nhân Tông cho mở Quốc Tử Giám — trường đại học đầu tiên của Việt Nam; Văn Miếu được dựng năm 1070.\n- Khoa thi Nho học đầu tiên: khoa thi Minh kinh bác học năm 1075 thời vua Lý Nhân Tông.\n- Chu Văn An là nhà giáo lỗi lạc thời Trần, được tôn vinh là “vạn thế sư biểu”.\n- Nền khoa cử Nho học kéo dài hơn 800 năm, khép lại với khoa thi Hội cuối cùng năm 1919.\n- Giáo dục, khoa cử tuyển chọn nhân tài, góp phần xây dựng đất nước.',1,'published',10,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(326,95,'Kiến trúc và nghệ thuật phong kiến (4)','lich-su-thpt-10-lop-10-4','Kể tên công trình kiến trúc tiêu biểu, loại hình nghệ thuật; nhận biết các di sản UNESCO của Việt Nam.','kho',18,'Chùa Một Cột (Lý), thành nhà Hồ, cố đô Huế (Nguyễn). Di sản UNESCO: cố đô Huế (1993), Hội An và Mỹ Sơn (1999), Hoàng thành Thăng Long (2010). Nghệ thuật: nhã nhạc, tuồng, chèo, quan họ, ca trù.','- Chùa Một Cột (Diên Hựu) được xây năm 1049 thời vua Lý Thái Tông.\n- Cố đô Huế (Phú Xuân) là kinh đô của nhà Nguyễn từ năm 1802 đến 1945.\n- Tháp Chăm là di sản kiến trúc của vương quốc Champa; Thánh địa Mỹ Sơn là trung tâm tôn giáo của vương quốc này.\n- Hoàng thành Thăng Long được UNESCO công nhận di sản thế giới nhân kỉ niệm 1000 năm Thăng Long – Hà Nội.\n- Kiến trúc, nghệ thuật phong kiến thể hiện tài năng và bản sắc văn hoá dân tộc.',2,'published',10,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(327,96,'Phong trào Cần Vương (1885–1896) (1)','lich-su-thpt-11-lop-11-1','Trình bày hoàn cảnh, diễn biến, ý nghĩa phong trào Cần Vương; nêu các cuộc khởi nghĩa tiêu biểu.','trung_binh',15,'Tháng 7/1885, Tôn Thất Thuyết phò vua Hàm Nghi ra Chiếu Cần Vương. Tiêu biểu: Hương Khê (Phan Đình Phùng), Ba Đình, Bãi Sậy. Phong trào kết thúc năm 1896.','- Tháng 7/1885, sau vụ Kinh thành Huế, vua Hàm Nghi ra Chiếu Cần Vương kêu gọi văn thân, sĩ phu đứng lên cứu nước.\n- Tôn Thất Thuyết phò vua Hàm Nghi xuất bôn, là người lãnh đạo phong trào.\n- Khởi nghĩa Hương Khê do Phan Đình Phùng lãnh đạo là cuộc khởi nghĩa tiêu biểu nhất của phong trào.\n- Phong trào kết thúc năm 1896 với sự hi sinh của Phan Đình Phùng.\n- Phong trào Cần Vương thể hiện tinh thần yêu nước nhưng thất bại vì thiếu đường lối đúng đắn.',1,'published',11,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(328,96,'Khởi nghĩa nông dân và phong trào Duy tân đầu thế kỉ XX (2)','lich-su-thpt-11-lop-11-2','So sánh chủ trương Phan Bội Châu – Phan Châu Trinh; nêu các phong trào Đông Du, Đông Kinh Nghĩa Thục, Yên Thế.','kho',18,'Yên Thế (Hoàng Hoa Thám, 1884–1913). Phan Bội Châu: bạo động, Đông Du (1905). Phan Châu Trinh: khai dân trí, chấn dân khí. Đông Kinh Nghĩa Thục (1907) dạy chữ quốc ngữ miễn phí.','- Khởi nghĩa Yên Thế (1884–1913) do Hoàng Hoa Thám lãnh đạo nông dân chống Pháp gần 30 năm.\n- Phong trào Đông Du (1905) do Phan Bội Châu khởi xướng: đưa thanh niên sang Nhật du học để học cách đánh Pháp.\n- Đông Kinh Nghĩa Thục mở trường dạy chữ quốc ngữ miễn phí tại Hà Nội, bị Pháp đóng cửa năm 1908.\n- Phan Châu Trinh chủ trương cải cách, nâng cao dân trí trước khi giành độc lập.\n- Các phong trào đầu thế kỉ XX mang màu sắc dân chủ tư sản nhưng đều thất bại.',2,'published',11,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(329,97,'Nguyễn Ái Quốc tìm đường cứu nước và thành lập Đảng (3)','lich-su-thpt-11-lop-11-3','Trình bày hành trình 1911–1930 của Nguyễn Ái Quốc và sự ra đời của Đảng Cộng sản Việt Nam.','trung_binh',15,'5/6/1911 rời bến Nhà Rồng. 1920 tham gia sáng lập Đảng Cộng sản Pháp; 1925 lập Hội Việt Nam Cách mạng Thanh niên. 3/2/1930 hợp nhất tại Hương Cảng thành Đảng Cộng sản Việt Nam.','- Ngày 5/6/1911, Nguyễn Tất Thành rời bến Nhà Rồng (Sài Gòn) trên tàu Đô đốc La-tu-sơ Tơ-rê-vin ra đi tìm đường cứu nước.\n- Tại Đại hội Tua (12/1920), Nguyễn Ái Quốc bỏ phiếu tán thành Quốc tế III, tham gia sáng lập Đảng Cộng sản Pháp.\n- Người tìm thấy con đường cứu nước đúng đắn: cách mạng vô sản theo chủ nghĩa Mác – Lênin.\n- Hội nghị hợp nhất tại Hương Cảng do Nguyễn Ái Quốc chủ trì đã hợp nhất ba tổ chức cộng sản thành Đảng Cộng sản Việt Nam.\n- Sự ra đời của Đảng là bước ngoặt vĩ đại của cách mạng Việt Nam.',1,'published',11,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(330,97,'Phong trào cách mạng 1930–1945 (4)','lich-su-thpt-11-lop-11-4','Nêu các cao trào 1930–1931, 1936–1939, 1939–1945; sự ra đời của Mặt trận Việt Minh và Đội Việt Nam Tuyên truyền Giải phóng quân.','kho',18,'Xô viết Nghệ Tĩnh (1930–1931). Mặt trận Việt Minh thành lập 1941. 22/12/1944 thành lập Đội Việt Nam Tuyên truyền Giải phóng quân do Võ Nguyên Giáp chỉ huy. Tổng khởi nghĩa tháng 8/1945.','- Phong trào Xô viết Nghệ Tĩnh lập nên chính quyền Xô viết đầu tiên của nhân dân.\n- Hội nghị Trung ương 8 (5/1941) do Nguyễn Ái Quốc chủ trì quyết định thành lập Mặt trận Việt Minh.\n- Đội Việt Nam Tuyên truyền Giải phóng quân được thành lập, là tiền thân của Quân đội nhân dân Việt Nam.\n- Đội gồm 34 chiến sĩ với vũ khí thô sơ tại Cao Bằng, do Võ Nguyên Giáp chỉ huy.\n- Phong trào 1930–1945 chuẩn bị lực lượng cho thắng lợi của Cách mạng tháng Tám.',2,'published',11,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(331,98,'Cách mạng tháng Tám và kháng chiến chống Pháp (1945–1954) (1)','lich-su-thpt-12-lop-12-1','Trình bày thắng lợi 19/8/1945, 2/9/1945 và 9 năm kháng chiến chống Pháp đến Điện Biên Phủ, Hiệp định Genève.','trung_binh',15,'19/8/1945 Hà Nội khởi nghĩa; 2/9/1945 Tuyên ngôn độc lập. 19/12/1946 toàn quốc kháng chiến. 7/5/1954 chiến thắng Điện Biên Phủ; 21/7/1954 kí Hiệp định Genève, vĩ tuyến 17 là giới tuyến tạm thời.','- Ngày 19/8/1945, Hà Nội khởi nghĩa giành chính quyền, mở đầu thắng lợi của Cách mạng tháng Tám.\n- Đại tướng Võ Nguyên Giáp là Tổng tư lệnh, trực tiếp chỉ huy chiến dịch Điện Biên Phủ.\n- Chiến dịch Điện Biên Phủ kết thúc thắng lợi ngày 7/5/1954, “nên vành hoa đỏ nên thiên sử vàng”.\n- Hiệp định Genève kí ngày 21/7/1954, công nhận độc lập, chủ quyền của Việt Nam.\n- Thắng lợi kháng chiến chống Pháp chấm dứt ách thống trị thực dân trên đất nước ta.',1,'published',12,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(332,98,'Kháng chiến chống Mĩ cứu nước (1954–1975) (2)','lich-su-thpt-12-lop-12-2','Trình bày các giai đoạn kháng chiến chống Mĩ: Đồng Khởi, Mậu Thân, Điện Biên Phủ trên không đến đại thắng 30/4/1975.','kho',20,'Đồng Khởi (1960, Bến Tre). Tết Mậu Thân (1968). 12/1972 \"Điện Biên Phủ trên không\". 27/1/1973 Hiệp định Paris. 30/4/1975 giải phóng miền Nam, thống nhất đất nước.','- Ngày 17/1/1960, Bến Tre nổi dậy, mở đầu phong trào Đồng Khởi.\n- “Điện Biên Phủ trên không”: 12 ngày đêm cuối năm 1972, Hà Nội bắn rơi nhiều pháo đài bay B-52 của Mĩ.\n- Hiệp định Paris buộc Mĩ phải rút quân, công nhận độc lập, chủ quyền của Việt Nam.\n- 11 giờ 30 phút ngày 30/4/1975, cờ giải phóng tung bay trên Dinh Độc Lập, kết thúc chiến dịch Hồ Chí Minh lịch sử.\n- Thắng lợi 30/4/1975 giải phóng hoàn toàn miền Nam, thống nhất đất nước.',2,'published',12,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(333,99,'Công cuộc Đổi mới từ năm 1986 (3)','lich-su-thpt-12-lop-12-3','Nêu hoàn cảnh, nội dung cơ bản và thành tựu bước đầu của đường lối Đổi mới.','trung_binh',15,'Đại hội VI (12/1986) đề ra Đổi mới, trọng tâm là đổi mới kinh tế: xóa bao cấp, đa thành phần, kinh tế thị trường định hướng xã hội chủ nghĩa. Khoán 10 (1988) thúc đẩy nông nghiệp phát triển.','- Đại hội VI (tháng 12/1986) đề ra đường lối đổi mới toàn diện đất nước.\n- Trước Đổi mới, nền kinh tế – xã hội rơi vào khủng hoảng của mô hình bao cấp, kế hoạch hoá tập trung.\n- Nội dung trọng tâm của công cuộc Đổi mới là đổi mới kinh tế.\n- Việt Nam phát triển nền kinh tế nhiều thành phần vận hành theo cơ chế thị trường.\n- Đổi mới đưa đất nước thoát khỏi khủng hoảng, đời sống nhân dân ngày càng cải thiện.',1,'published',12,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(334,99,'Việt Nam hội nhập quốc tế (4)','lich-su-thpt-12-lop-12-4','Nêu các mốc hội nhập: ASEAN (1995), APEC (1998), WTO (2007) và vai trò quốc tế của Việt Nam.','trung_binh',15,'28/7/1995 gia nhập ASEAN; 1998 gia nhập APEC; 2007 trở thành thành viên thứ 150 của WTO. EVFTA (2020), Chủ tịch ASEAN 2020, Ủy viên không thường trực Hội đồng Bảo an Liên hợp quốc 2020–2021.','- Ngày 28/7/1995, Việt Nam trở thành thành viên thứ 7 của ASEAN.\n- Năm 2007, Việt Nam trở thành thành viên thứ 150 của Tổ chức Thương mại Thế giới (WTO).\n- Việt Nam gia nhập Diễn đàn Hợp tác Kinh tế châu Á – Thái Bình Dương (APEC), hội nhập sâu rộng vào kinh tế khu vực.\n- Việt Nam hai lần đảm nhiệm Ủy viên không thường trực Hội đồng Bảo an Liên hợp quốc: 2008–2009 và 2020–2021.\n- Hội nhập quốc tế nâng cao vị thế, uy tín của Việt Nam trên trường quốc tế.',2,'published',12,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(335,100,'Hệ Mặt Trời và chuyển động của Trái Đất (1)','dia-ly-thpt-10-lop-10-1','Kể tên các hành tinh; trình bày hai chuyển động của Trái Đất và hệ quả ngày đêm, bốn mùa.','trung_binh',15,'8 hành tinh quay quanh Mặt Trời theo thứ tự: Thủy, Kim, Trái Đất, Hỏa, Mộc, Thổ, Thiên Vương, Hải Vương. Trái Đất tự quay (24 giờ) gây ngày đêm luân phiên; quay quanh Mặt Trời (365,25 ngày) kết hợp trục nghiêng gây bốn mùa.','- Thứ tự các hành tinh từ Mặt Trời: Thủy, Kim, Trái Đất, Hỏa, Mộc, Thổ, Thiên Vương, Hải Vương.\n- Trái Đất tự quay quanh trục một vòng hết 24 giờ, tạo ra hiện tượng ngày và đêm.\n- Trái Đất chuyển động quanh Mặt Trời một vòng hết 365,25 ngày, tạo ra các mùa trong năm.\n- Nửa Trái Đất được Mặt Trời chiếu sáng là ban ngày, nửa khuất là ban đêm.\n- Hai chuyển động của Trái Đất giải thích ngày đêm và các mùa.',1,'published',10,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(336,100,'Cấu tạo Trái Đất và vận động của thạch quyển (2)','dia-ly-thpt-10-lop-10-2','Nêu cấu tạo ba lớp của Trái Đất; phân biệt nội lực và ngoại lực cùng tác động lên địa hình.','kho',18,'Trái Đất gồm vỏ, bao Manti và nhân. Thạch quyển = vỏ Trái Đất + phần trên bao Manti. Nội lực (động đất, núi lửa, uốn nếp) phát sinh từ bên trong; ngoại lực (phong hóa, xói mòn, bồi tụ) có nguồn gốc từ bức xạ Mặt Trời.','- Vỏ lục địa dày 30–70km, dày hơn nhiều so với vỏ đại dương chỉ 5–10km.\n- Thạch quyển là lớp đá cứng ngoài cùng của Trái Đất, dày khoảng 100km.\n- Nội lực là lực phát sinh từ năng lượng bên trong Trái Đất.\n- Động đất, núi lửa và hiện tượng uốn nếp là kết quả của nội lực.\n- Vận động của thạch quyển không ngừng làm thay đổi bề mặt Trái Đất.',2,'published',10,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(337,101,'Khí quyển: nhiệt độ, khí áp và gió (3)','dia-ly-thpt-10-lop-10-3','Nêu cấu tạo khí quyển; giải thích sự phân bố nhiệt độ, khí áp và các loại gió chính.','trung_binh',15,'Tầng đối lưu (0–16 km) chứa các hiện tượng thời tiết. Nhiệt độ giảm theo vĩ độ và độ cao. Gió thổi từ nơi khí áp cao đến nơi khí áp thấp: gió Tín phong, gió Tây ôn đới, gió mùa.','- Các hiện tượng thời tiết như mưa, bão xảy ra ở tầng đối lưu (0–16km).\n- Cứ lên cao 100m, nhiệt độ không khí giảm khoảng 0,6 độ C.\n- Gió là sự chuyển động của không khí từ nơi áp cao về nơi áp thấp.\n- Gió Tín phong (mậu dịch) thổi thường xuyên từ áp cao cận chí tuyến về áp thấp xích đạo.\n- Nhiệt độ, khí áp và gió là ba yếu tố cơ bản của khí hậu.',1,'published',10,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(338,101,'Sinh quyển và các đới thiên nhiên (4)','dia-ly-thpt-10-lop-10-4','Nêu khái niệm sinh quyển; trình bày quy luật địa đới và các đới thiên nhiên chính.','kho',18,'Sinh quyển là nơi sinh sống của sinh vật trên Trái Đất. Quy luật địa đới: thiên nhiên thay đổi theo vĩ độ (đới nóng – ôn hòa – lạnh). Quy luật phi địa đới: thay đổi theo độ cao và địa hình.','- Sinh quyển gồm toàn bộ sinh vật và môi trường sống của chúng trên Trái Đất.\n- Thảm thực vật đặc trưng của đới nóng là rừng nhiệt đới xanh quanh năm, nhiều tầng tán.\n- Hoang mạc Xa-ha-ra ở Bắc Phi là hoang mạc nhiệt đới lớn nhất thế giới.\n- Quy luật địa đới: thiên nhiên thay đổi theo vĩ độ do lượng bức xạ Mặt Trời thay đổi.\n- Khí hậu quyết định sự phân bố sinh vật trên Trái Đất.',2,'published',10,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(339,102,'Dân số thế giới: quy mô và gia tăng (1)','dia-ly-thpt-11-lop-11-1','Nêu quy mô, sự gia tăng dân số thế giới và phân bố dân cư; tính gia tăng dân số tự nhiên.','trung_binh',15,'Dân số thế giới đạt 8 tỉ (2022); châu Á đông dân nhất; Ấn Độ là nước đông dân nhất. Gia tăng tự nhiên = tỉ suất sinh − tỉ suất tử. Bùng nổ dân số diễn ra ở các nước đang phát triển.','- Tháng 11/2022, dân số thế giới chính thức cán mốc 8 tỉ người.\n- Châu Á đông dân nhất, chiếm khoảng 60% dân số thế giới.\n- Tỉ suất gia tăng dân số tự nhiên phản ánh sự chênh lệch giữa sinh và tử.\n- Năm 2023, Ấn Độ đã vượt Trung Quốc trở thành nước đông dân nhất thế giới.\n- Quy mô và gia tăng dân số ảnh hưởng lớn đến phát triển kinh tế, xã hội.',1,'published',11,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(340,102,'Cơ cấu dân số, di cư và đô thị hóa (2)','dia-ly-thpt-11-lop-11-2','Đọc tháp dân số; phân biệt dân số trẻ – già; nêu xu hướng di cư và đô thị hóa.','kho',18,'Tháp dân số thể hiện cơ cấu theo độ tuổi và giới tính. Dân số già: Nhật Bản, châu Âu. Di cư chủ yếu từ nông thôn ra thành thị. Siêu đô thị có trên 10 triệu dân (Tokyo, Delhi, Thượng Hải...).','- Tháp dân số thể hiện cơ cấu tuổi: hình dạng tháp cho biết dân số trẻ, già hay ổn định.\n- Nhật Bản là quốc gia già hóa dân số nhanh nhất thế giới, thiếu lao động trẻ.\n- Đô thị hóa hút lao động từ nông thôn vào thành phố.\n- Siêu đô thị là đô thị có dân số rất lớn, ví dụ Tokyo, Delhi, Thượng Hải.\n- Cơ cấu dân số và đô thị hóa đặt ra nhiều thách thức cho các quốc gia.',2,'published',11,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(341,103,'Nông nghiệp và công nghiệp thế giới (3)','dia-ly-thpt-11-lop-11-3','Nêu vai trò, phân bố các cây trồng chính và đặc điểm các cuộc cách mạng công nghiệp.','trung_binh',15,'Lúa gạo tập trung ở châu Á gió mùa, lúa mì ở vùng ôn đới. Bốn cuộc cách mạng công nghiệp: hơi nước – điện – máy tính – số hóa/AI. FAO phụ trách lương thực – nông nghiệp; OPEC là tổ chức các nước xuất khẩu dầu mỏ.','- Châu Á gió mùa chiếm khoảng 90% sản lượng lúa gạo thế giới.\n- Trung Quốc dẫn đầu thế giới về sản lượng lúa mì; Nga dẫn đầu về xuất khẩu lúa mì.\n- Cách mạng công nghiệp lần thứ tư gắn với IoT, AI, dữ liệu lớn và robot.\n- Công nghiệp nặng được coi là quả đấm thép của nền kinh tế, cung cấp tư liệu sản xuất.\n- Nông nghiệp và công nghiệp là hai ngành kinh tế vật chất cơ bản.',1,'published',11,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(342,103,'Dịch vụ và toàn cầu hóa kinh tế (4)','dia-ly-thpt-11-lop-11-4','Nêu vai trò ngành dịch vụ; trình bày biểu hiện và tác động hai mặt của toàn cầu hóa.','kho',18,'Dịch vụ chiếm tỉ trọng lớn trong GDP các nước phát triển. Toàn cầu hóa biểu hiện qua tự do thương mại, công ty xuyên quốc gia, WTO (1995). Tác động: mở rộng thị trường nhưng cạnh tranh gay gắt, phụ thuộc lẫn nhau.','- Ở các nước phát triển, ngành dịch vụ chiếm trên 70% GDP.\n- Toàn cầu hóa biểu hiện rõ nét nhất trong tự do hóa thương mại và đầu tư.\n- WTO (Tổ chức Thương mại Thế giới) thành lập năm 1995, điều tiết thương mại toàn cầu.\n- Công ty xuyên quốc gia là chủ thể thúc đẩy toàn cầu hóa kinh tế.\n- Dịch vụ và toàn cầu hóa đang định hình nền kinh tế thế giới hiện đại.',2,'published',11,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(343,104,'Vị trí địa lí và địa hình Việt Nam (1)','dia-ly-thpt-12-lop-12-1','Nêu vị trí, phạm vi lãnh thổ và đặc điểm địa hình (3/4 đồi núi); kể các dạng địa hình chính.','trung_binh',15,'Diện tích 331.212 km², bờ biển dài 3.260 km, biên giới đất liền 4.639 km, tiếp giáp 3 nước. Địa hình 3/4 là đồi núi, hướng Tây Bắc – Đông Nam; đỉnh Phan-xi-păng 3.143 m; hai đồng bằng lớn là sông Hồng và sông Cửu Long.','- Việt Nam rộng khoảng 331.212km2, đứng thứ 65 thế giới về diện tích.\n- Đường bờ biển Việt Nam dài khoảng 3.260km, từ Móng Cái đến Hà Tiên.\n- Đỉnh Phan-xi-păng cao 3.143m, được mệnh danh là nóc nhà Đông Dương.\n- Địa hình Việt Nam: đồi núi chiếm 3/4, đồng bằng chỉ 1/4 diện tích.\n- Vị trí và địa hình tạo nên đặc điểm tự nhiên riêng của Việt Nam.',1,'published',12,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(344,104,'Khí hậu, sông ngòi và đất Việt Nam (2)','dia-ly-thpt-12-lop-12-2','Trình bày tính chất nhiệt đới gió mùa; nêu đặc điểm sông ngòi và các loại đất chính.','kho',18,'Khí hậu nhiệt đới gió mùa, phân hóa Bắc – Nam rõ rệt. Sông ngòi dày đặc, nhiều nước: Mê Công, sông Hồng. Hai loại đất chính: feralit ở đồi núi và phù sa ở đồng bằng.','- Khí hậu Việt Nam nóng ẩm quanh năm, mưa theo mùa, chịu ảnh hưởng gió mùa châu Á.\n- Sông Mê Công dài 4.350km; đoạn chảy qua Việt Nam gọi là sông Tiền, sông Hậu.\n- Đất feralit chiếm khoảng 65% diện tích, phân bố chủ yếu ở vùng đồi núi.\n- Mùa mưa ở miền Bắc trùng với mùa gió tây nam nóng ẩm.\n- Khí hậu, sông ngòi và đất đai là điều kiện quan trọng cho nông nghiệp.',2,'published',12,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(345,105,'Nông nghiệp Việt Nam (3)','dia-ly-thpt-12-lop-12-3','Nêu thế mạnh lúa gạo, cây công nghiệp, thủy sản và các vùng sản xuất chính.','trung_binh',15,'Đồng bằng sông Cửu Long là vựa lúa lớn nhất; Tây Nguyên trồng cà phê; Đông Nam Bộ trồng cao su. Việt Nam thuộc top đầu thế giới về xuất khẩu gạo, đứng thứ 2 về cà phê, top đầu về hồ tiêu và điều.','- Đồng bằng sông Cửu Long là vựa lúa lớn nhất, chiếm hơn 50% sản lượng lúa cả nước.\n- Việt Nam là nước xuất khẩu cà phê lớn thứ hai thế giới, chỉ sau Bra-xin.\n- Đất bazan Tây Nguyên rất thích hợp trồng cà phê và cây công nghiệp lâu năm.\n- Đồng bằng sông Cửu Long cũng là vùng nuôi trồng thủy sản lớn nhất cả nước với cá tra, tôm sú.\n- Nông nghiệp là thế mạnh truyền thống và hiện đại của Việt Nam.',1,'published',12,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(346,105,'Công nghiệp và dịch vụ Việt Nam (4)','dia-ly-thpt-12-lop-12-4','Nêu các ngành công nghiệp trọng điểm, trung tâm công nghiệp và thế mạnh du lịch, giao thông.','kho',18,'Dầu khí là ngành công nghiệp trọng điểm (lọc dầu Dung Quất). TP.HCM là trung tâm công nghiệp lớn nhất. Du lịch biển đảo là thế mạnh: Hạ Long, Hội An, Huế, Phú Quốc. Cảng Cát Lái (TP.HCM) là cảng biển lớn nhất.','- Dầu khí là ngành công nghiệp trọng điểm, đóng góp lớn vào ngân sách và xuất khẩu.\n- TP.HCM và vùng Đông Nam Bộ là trung tâm công nghiệp lớn nhất cả nước.\n- Du lịch biển là thế mạnh nổi bật với đường bờ biển dài và nhiều bãi biển đẹp.\n- Cụm cảng TP.HCM là cảng biển lớn nhất, cửa ngõ xuất nhập khẩu của cả nước.\n- Công nghiệp và dịch vụ đang chuyển dịch cơ cấu kinh tế Việt Nam.',2,'published',12,1,'2026-10-07 22:54:55','2026-10-07 22:54:55'),
(347,106,'Đọc hiểu truyện ngắn: cốt truyện và nhân vật (1)','ngu-van-thpt-10-doc-hieu-truyen-1','Nhận biết các yếu tố cơ bản của truyện ngắn: cốt truyện, tình huống truyện, nhân vật và người kể chuyện.','trung_binh',15,'Cốt truyện là chuỗi sự kiện liên kết bằng quan hệ nhân quả. Tình huống truyện là hoàn cảnh đặc biệt làm nảy sinh câu chuyện. Chú ý ngôi kể (thứ nhất/thứ ba) và vai trò của từng nhân vật.','- Cốt truyện là hệ thống sự kiện có quan hệ nhân quả, thường phát triển qua: mở đầu – thắt nút – cao trào – mở nút – kết thúc.\n- Tình huống truyện là hoàn cảnh đặc biệt làm nảy sinh sự việc; qua cách nhân vật ứng xử, tính cách và chủ đề được bộc lộ.\n- Người kể chuyện ngôi thứ nhất xưng “tôi”, kể theo điểm nhìn hạn chế của mình.\n- Nhân vật chính giữ vai trò trung tâm, mọi sự kiện xoay quanh nhân vật này.\n- Đọc hiểu truyện cần bám sát văn bản, không suy diễn xa rời chi tiết.',1,'published',10,1,'2026-10-07 22:55:05','2026-10-07 22:55:05'),
(348,106,'Đọc hiểu truyện ngắn: chi tiết, chủ đề và thông điệp (2)','ngu-van-thpt-10-doc-hieu-truyen-2','Phân tích chi tiết nghệ thuật, xác định chủ đề và rút ra thông điệp của truyện ngắn.','trung_binh',15,'Chi tiết nghệ thuật là chi tiết tiêu biểu, giàu sức gợi. Chủ đề là vấn đề trung tâm của tác phẩm; thông điệp là điều tác giả muốn gửi gắm tới người đọc.','- Chi tiết nghệ thuật là chi tiết được chọn lọc kĩ, giàu sức gợi, góp phần khắc họa nhân vật và thể hiện chủ đề.\n- Chủ đề là vấn đề trung tâm mà tác phẩm tập trung phản ánh và thể hiện.\n- Thông điệp là điều tác giả gửi gắm, chỉ hiện ra khi khái quát toàn bộ diễn biến, số phận nhân vật và kết thúc.\n- Tư tưởng là cách nhìn, cách đánh giá của tác giả về cuộc sống, thể hiện qua toàn bộ tác phẩm.\n- Đọc hiểu sâu là đi từ chi tiết đến chủ đề, thông điệp của tác phẩm.',2,'published',10,1,'2026-10-07 22:55:05','2026-10-07 22:55:05'),
(349,107,'Đọc hiểu thơ: thể thơ, nhịp điệu và vần (1)','ngu-van-thpt-10-doc-hieu-tho-1','Nhận biết các thể thơ quen thuộc; phân tích nhịp điệu, vần và tác dụng của chúng.','trung_binh',15,'Xác định thể thơ qua số câu, số chữ mỗi câu. Chú ý cách gieo vần (vần chân, vần lưng) và cách ngắt nhịp tạo tiết tấu cho bài thơ.','- Thơ lục bát: câu lục (6 chữ) xen câu bát (8 chữ), gieo vần ở tiếng thứ 6 của câu lục và câu bát.\n- Nhịp là cách ngắt câu thơ thành từng đoạn tạo tiết tấu (ví dụ nhịp 2/2, 4/4 trong câu 8 chữ).\n- Vần là sự lặp lại âm thanh ở cuối (hoặc giữa) câu thơ, tạo nhạc tính và sự liên kết.\n- Thơ tự do phá bỏ khuôn mẫu gò bó của thơ cách luật, nhịp điệu theo cảm xúc tự nhiên.\n- Đọc thơ cần chú ý thể thơ, nhịp, vần để cảm nhận nhạc điệu của bài.',1,'published',10,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(350,107,'Đọc hiểu thơ: hình ảnh thơ và cảm xúc trữ tình (2)','ngu-van-thpt-10-doc-hieu-tho-2','Cảm nhận hình ảnh thơ, xác định chủ thể trữ tình và cảm xúc trữ tình chủ đạo.','trung_binh',15,'Hình ảnh thơ được gợi lên từ ngôn ngữ giàu sức gợi. Chủ thể trữ tình là người bộc lộ cảm xúc trong bài thơ; hãy gọi tên cảm xúc chủ đạo và tìm những hình ảnh thể hiện nó.','- Hình ảnh thơ không phải ảnh chụp mà là hình ảnh hiện lên trong tâm trí người đọc từ ngôn ngữ thơ.\n- Chủ thể trữ tình (thường xưng “tôi”, “ta”, “anh”, “em”) là người trực tiếp bộc lộ cảm xúc.\n- Cảm xúc trữ tình thấm đẫm trong hình ảnh, từ ngữ và giọng điệu của toàn bài.\n- Từ láy, từ gợi hình, gợi thanh làm câu thơ sinh động như có hình, có tiếng.\n- Đọc thơ là lắng nghe cảm xúc của chủ thể trữ tình qua từng hình ảnh.',2,'published',10,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(351,108,'Nghị luận về tư tưởng đạo lí: khái niệm và thao tác lập luận (1)','ngu-van-thpt-11-tu-tuong-dao-li-1','Nắm khái niệm nghị luận về tư tưởng đạo lí; sử dụng các thao tác lập luận giải thích, chứng minh, bình luận.','trung_binh',15,'Nghị luận về tư tưởng đạo lí bàn về các quan niệm đạo đức, lối sống. Luận điểm là ý chính cần chứng minh; luận cứ là lí lẽ và dẫn chứng. Các thao tác chính: giải thích, chứng minh, bình luận, so sánh.','- Nghị luận về tư tưởng đạo lí bàn về các vấn đề thuộc lĩnh vực tư tưởng, đạo đức, lối sống.\n- Thao tác giải thích: làm rõ nghĩa của khái niệm, giúp người đọc hiểu đúng vấn đề.\n- Thao tác chứng minh: dùng dẫn chứng (số liệu, tấm gương, sự việc) và lí lẽ để làm sáng tỏ luận điểm.\n- Luận điểm là ý chính của bài; mỗi luận điểm cần được triển khai bằng luận cứ.\n- Bài nghị luận cần lập luận chặt chẽ, dẫn chứng thuyết phục.',1,'published',11,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(352,108,'Nghị luận về tư tưởng đạo lí: phân tích đề và sử dụng dẫn chứng (2)','ngu-van-thpt-11-tu-tuong-dao-li-2','Phân tích đề bài, lập dàn ý; lựa chọn và sử dụng dẫn chứng tiêu biểu, xác thực.','trung_binh',15,'Khi phân tích đề: xác định vấn đề nghị luận, phạm vi và yêu cầu. Dẫn chứng phải tiêu biểu, xác thực, phù hợp với luận điểm; tránh dẫn chứng bịa đặt hoặc chung chung.','- Phân tích đề giúp xác định đúng vấn đề và góc độ bàn luận, tránh lạc đề.\n- Dẫn chứng phải chọn lọc: tiêu biểu, xác thực, gắn chặt với luận điểm đang chứng minh.\n- Bố cục ba phần là chuẩn mực: mở bài nêu vấn đề, thân bài triển khai, kết bài khẳng định.\n- Câu chuyển đoạn tạo sự liên kết giữa các đoạn, giúp mạch lập luận trôi chảy.\n- Dẫn chứng càng gần gũi thực tế càng có sức thuyết phục.',2,'published',11,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(353,109,'Nghị luận về hiện tượng đời sống: nhận diện và đánh giá (1)','ngu-van-thpt-11-hien-tuong-doi-song-1','Nhận diện hiện tượng đời sống trong đề bài; đánh giá mặt tích cực và tiêu cực của hiện tượng.','trung_binh',15,'Nghị luận về hiện tượng đời sống bàn về các sự việc, hiện tượng nổi bật trong đời sống. Cần mô tả hiện tượng, đánh giá khách quan cả mặt tốt và mặt xấu, tránh phiến diện.','- Hiện tượng đời sống là những sự việc, hiện tượng có thật, nổi bật trong đời sống hằng ngày.\n- Bước đầu tiên: nhận diện đúng hiện tượng — đó là hiện tượng gì, biểu hiện ra sao — rồi mới đánh giá.\n- Đánh giá cần khách quan, toàn diện để bài văn thuyết phục và sâu sắc.\n- Vì bàn về đời sống thực nên dẫn chứng phải lấy từ thực tế có thật, đáng tin cậy.\n- Bài văn hay là bài vừa nhận diện đúng, vừa đánh giá sâu.',1,'published',11,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(354,109,'Nghị luận về hiện tượng đời sống: nguyên nhân và giải pháp (2)','ngu-van-thpt-11-hien-tuong-doi-song-2','Phân tích nguyên nhân của hiện tượng; đề xuất giải pháp khắc phục hợp lí.','trung_binh',15,'Với hiện tượng tiêu cực: tìm nguyên nhân khách quan và chủ quan, đề xuất giải pháp cụ thể, khả thi. Với hiện tượng tích cực: nêu ý nghĩa và cách nhân rộng.','- Phân tích nguyên nhân cần thấy cả yếu tố chủ quan (ý thức con người) và khách quan (môi trường, quản lí).\n- Giải pháp phải cụ thể, làm được trong thực tế, hướng tới từng đối tượng liên quan.\n- Với hiện tượng tích cực, bài văn nên ngợi ca ý nghĩa và lan toả trong cộng đồng.\n- Liên hệ bản thân thể hiện sự thấm thía vấn đề và trách nhiệm của người viết.\n- Kết bài khẳng định lại quan điểm và kêu gọi hành động.',2,'published',11,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(355,110,'Phân tích tác phẩm văn xuôi: nhân vật và tình huống truyện (1)','ngu-van-thpt-12-phan-tich-van-xuoi-1','Phân tích nhân vật qua ngoại hình, hành động, lời nói, tâm lí; phân tích vai trò của tình huống truyện.','kho',20,'Phân tích nhân vật cần bám vào các chi tiết: ngoại hình, hành động, lời nói, diễn biến tâm lí. Tình huống truyện là hoàn cảnh đặc biệt bộc lộ tính cách nhân vật và chủ đề tác phẩm.','- Tính cách nhân vật bộc lộ qua bốn phương diện: ngoại hình, hành động, lời nói và tâm lí.\n- Phân tích tình huống truyện giúp thấy “cái thế” mà nhân vật bị đặt vào — nơi tính cách và tư tưởng bộc lộ rõ nhất.\n- Diễn biến tâm lí nhân vật bộc lộ rõ nhất khi đối mặt với xung đột, biến cố hoặc lựa chọn khó khăn.\n- Lời nói là “cửa sổ” tâm hồn: qua đối thoại và độc thoại, tính cách nhân vật hiện lên chân thực.\n- Phân tích nhân vật phải gắn với tình huống và gắn với chủ đề tác phẩm.',1,'published',12,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(356,110,'Phân tích tác phẩm văn xuôi: giá trị nội dung và nghệ thuật (2)','ngu-van-thpt-12-phan-tich-van-xuoi-2','Đánh giá giá trị nội dung (hiện thực, nhân đạo) và giá trị nghệ thuật của tác phẩm văn xuôi.','kho',20,'Giá trị hiện thực: tác phẩm phản ánh hiện thực đời sống. Giá trị nhân đạo: sự đồng cảm, ngợi ca, phê phán. Giá trị nghệ thuật: tình huống, kết cấu, ngôn ngữ, giọng điệu.','- Giá trị hiện thực: tác phẩm như “tấm gương” phản ánh đời sống, xã hội một thời.\n- Giá trị nhân đạo là tình cảm nhân văn: yêu thương, đồng cảm, đấu tranh cho con người.\n- Giá trị nghệ thuật nằm ở cách xây dựng tình huống, kết cấu, ngôn ngữ, giọng điệu...\n- Nội dung và nghệ thuật thống nhất: tư tưởng sâu sắc cần hình thức nghệ thuật đặc sắc để thể hiện.\n- Đánh giá tác phẩm phải toàn diện cả nội dung và nghệ thuật.',2,'published',12,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(357,111,'Phân tích thơ: tứ thơ, hình tượng và cảm xúc (1)','ngu-van-thpt-12-phan-tich-tho-1','Xác định tứ thơ; phân tích hình tượng thơ và diễn biến cảm xúc trữ tình.','kho',20,'Tứ thơ là ý tưởng trung tâm của bài thơ. Phân tích hình tượng thơ qua từ ngữ, biện pháp tu từ; theo dõi mạch cảm xúc từ đầu đến cuối bài.','- Tứ thơ là “xương sống” ý tưởng, gắn kết các hình ảnh, cảm xúc trong bài.\n- Hình tượng thơ là hình ảnh nghệ thuật được tạo bằng ngôn từ, nhạc điệu và biện pháp tu từ.\n- Khi phân tích một khổ thơ: đi từ từ ngữ, hình ảnh đặc sắc đến biện pháp tu từ và cảm xúc chủ đạo.\n- Mạch cảm xúc trong bài thơ thường vận động: từ nhớ đến thương, từ buồn đến hi vọng...\n- Bám sát tứ thơ giúp bài phân tích có trọng tâm, không lan man.',1,'published',12,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(358,111,'Phân tích thơ: giá trị tư tưởng và nghệ thuật (2)','ngu-van-thpt-12-phan-tich-tho-2','Đánh giá giá trị tư tưởng và những đặc sắc nghệ thuật của bài thơ.','kho',20,'Giá trị tư tưởng: tình cảm, quan niệm mà bài thơ gửi gắm. Nghệ thuật: thể thơ, vần nhịp, từ ngữ, hình ảnh, biện pháp tu từ, giọng điệu. Kết bài khái quát và nêu cảm nhận.','- Giá trị tư tưởng của bài thơ là chiều sâu nhận thức và tình cảm nhân văn mà bài thơ gửi gắm.\n- Đặc sắc nghệ thuật của thơ là sự kết hợp của nhạc điệu, ngôn từ, hình ảnh và giọng điệu.\n- Kết bài khái quát lại giá trị tư tưởng, nghệ thuật và để lại cảm nhận chân thành.\n- Nội dung và nghệ thuật thống nhất: phân tích tách rời sẽ phiến diện.\n- Một bài phân tích thơ hay vừa sâu sắc về tư tưởng, vừa tinh tế về nghệ thuật.',2,'published',12,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(359,112,'Phong cách ngôn ngữ văn chương: ba đặc trưng (1)','tieng-viet-thpt-10-pcnc-van-chuong-1','Nắm ba đặc trưng của phong cách ngôn ngữ văn chương: tính hình tượng, tính truyền cảm, tính cá thể hóa.','trung_binh',15,'Phong cách ngôn ngữ văn chương có ba đặc trưng: tính hình tượng (gợi hình ảnh cụ thể), tính truyền cảm (gợi cảm xúc), tính cá thể hóa (dấu ấn riêng của tác giả).','- Phong cách ngôn ngữ văn chương có 3 đặc trưng: hình tượng, truyền cảm, cá thể hoá.\n- Tính hình tượng: gợi hình ảnh cụ thể thay vì khái niệm trừu tượng.\n- Tính truyền cảm: truyền đạt cảm xúc, không chỉ thông tin.\n- Tính cá thể hoá: mỗi nhà văn có giọng riêng qua cách dùng từ, đặt câu.\n- Nhận diện văn bản văn chương qua hình ảnh, cảm xúc, giọng điệu riêng.',1,'published',10,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(360,112,'Phong cách ngôn ngữ văn chương: nhận diện trong văn bản (2)','tieng-viet-thpt-10-pcnc-van-chuong-2','Nhận diện phong cách ngôn ngữ văn chương trong văn bản cụ thể; phân biệt với các phong cách khác.','trung_binh',15,'Dấu hiệu nhận biết: ngôn ngữ giàu hình ảnh, cảm xúc; nhiều biện pháp tu từ; dấu ấn cá nhân rõ nét. So sánh với phong cách báo chí, khoa học, hành chính để phân biệt.','- Văn bản văn chương dùng nhiều biện pháp tu từ để tạo hình ảnh, cảm xúc.\n- Ngôn ngữ văn chương là ngôn ngữ toàn dân được chọn lọc, tinh luyện.\n- Phong cách báo chí: thời sự, ngắn gọn, khách quan — khác văn chương.\n- Nhận diện phong cách qua dấu hiệu: hình ảnh, cảm xúc, giọng điệu.\n- Phân biệt văn bản văn chương với văn bản báo chí.',2,'published',10,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(361,113,'Phong cách ngôn ngữ báo chí: đặc trưng và chức năng (1)','tieng-viet-thpt-10-pcnc-bao-chi-1','Nắm đặc trưng của phong cách ngôn ngữ báo chí: tính thông tin, tính thời sự, tính ngắn gọn.','trung_binh',15,'Phong cách báo chí phục vụ chức năng thông tin thời sự. Đặc trưng: tính thông tin thời sự, tính ngắn gọn, tính sinh động hấp dẫn. Ngôn ngữ rõ ràng, chính xác, dễ hiểu.','- Chức năng chính của báo chí: thông tin nhanh về sự kiện thời sự.\n- Đặc trưng báo chí: thời sự (kịp thời), ngắn gọn, rõ ràng, dễ hiểu.\n- Báo chí hướng tới công chúng rộng rãi nên diễn đạt phải dễ hiểu.\n- Tính hình tượng đậm nét là của văn chương, không phải báo chí.\n- Nhận diện phong cách báo chí qua tính thời sự, ngắn gọn, khách quan.',1,'published',10,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(362,113,'Phong cách ngôn ngữ báo chí: bản tin và phóng sự (2)','tieng-viet-thpt-10-pcnc-bao-chi-2','Phân biệt bản tin và phóng sự; nhận biết ngôn ngữ báo chí trong các thể loại.','trung_binh',15,'Bản tin: đưa tin ngắn gọn, khách quan (ai, cái gì, ở đâu, khi nào). Phóng sự: phản ánh sâu, có miêu tả, bình luận, giàu hình ảnh hơn nhưng vẫn đảm bảo tính thời sự.','- Bản tin: ngắn, khách quan, cung cấp thông tin cơ bản.\n- Bản tin đầy đủ trả lời: ai, việc gì, ở đâu, khi nào, diễn biến ra sao.\n- Phóng sự: sâu, có miêu tả, bình luận, sinh động hơn bản tin.\n- Tít báo: ngắn, trúng, hấp dẫn và phải trung thực.\n- Phân biệt bản tin với phóng sự theo độ dài và cách viết.',2,'published',10,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(363,114,'Câu và các thành phần câu: câu đơn, câu ghép (1)','tieng-viet-thpt-11-cau-thanh-phan-1','Phân biệt câu đơn và câu ghép; xác định chủ ngữ, vị ngữ trong câu.','trung_binh',15,'Câu đơn có một cụm chủ ngữ – vị ngữ; câu ghép có từ hai cụm chủ ngữ – vị ngữ trở lên. Chủ ngữ trả lời Ai? Cái gì?; vị ngữ trả lời Làm gì? Thế nào? Là gì?','- Câu đơn gồm một cụm chủ ngữ - vị ngữ: \"Em / đang học bài\".\n- Câu ghép gồm nhiều vế, mỗi vế cấu tạo như một câu đơn.\n- Chủ ngữ nêu đối tượng được nói tới; vị ngữ trả lời Làm gì? Thế nào? Là gì?.\n- Xác định vế câu để phân biệt câu đơn với câu ghép.\n- Phân tích đúng chủ ngữ, vị ngữ trong câu.',1,'published',11,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(364,114,'Câu và các thành phần câu: thành phần phụ, câu đặc biệt (2)','tieng-viet-thpt-11-cau-thanh-phan-2','Nhận biết trạng ngữ, các thành phần biệt lập; nhận biết câu đặc biệt và câu rút gọn.','trung_binh',15,'Trạng ngữ chỉ thời gian, nơi chốn, nguyên nhân, mục đích... Câu đặc biệt không có cấu tạo chủ ngữ – vị ngữ (thường là cụm từ). Câu rút gọn lược bớt thành phần có thể khôi phục được.','- Trạng ngữ là thành phần phụ, bổ sung ý nghĩa hoàn cảnh cho câu.\n- Câu đặc biệt không phân tích được C-V: \"Ôi!\", \"Mưa!\".\n- Câu rút gọn có thể khôi phục C-V: \"Đang học bài.\" thành \"Em đang học bài.\".\n- Thành phần biệt lập tách khỏi nòng cốt câu: \"Này, bạn ơi!\".\n- Phân biệt câu đặc biệt với câu rút gọn.',2,'published',11,1,'2026-10-07 22:55:06','2026-10-07 22:55:06'),
(365,115,'Biện pháp tu từ: so sánh, nhân hóa, ẩn dụ, hoán dụ (1)','tieng-viet-thpt-11-bien-phap-tu-tu-1','Nhận diện và phân tích tác dụng của so sánh, nhân hóa, ẩn dụ, hoán dụ.','trung_binh',15,'So sánh: đối chiếu hai sự vật có nét tương đồng (có từ so sánh). Nhân hóa: gán đặc điểm người cho vật. Ẩn dụ: gọi tên sự vật này bằng tên sự vật khác có nét tương đồng (không có từ so sánh). Hoán dụ: gọi tên bằng nét liên tưởng gần gũi.','- So sánh: có từ so sánh \"như\" — \"Mặt trời xuống biển như hòn lửa\".\n- Nhân hoá: gán đặc điểm con người cho sự vật, làm vật vô tri có hồn.\n- Ẩn dụ: gọi thẳng sự vật này bằng tên sự vật khác, không dùng từ so sánh.\n- Hoán dụ: lấy vật chứa chỉ vật bị chứa — \"Cả lớp vỗ tay\" chỉ học sinh.\n- Nhận diện đúng biện pháp tu từ theo dấu hiệu của câu.',1,'published',11,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(366,115,'Biện pháp tu từ: điệp ngữ, liệt kê, nói quá, chơi chữ (2)','tieng-viet-thpt-11-bien-phap-tu-tu-2','Nhận diện và phân tích tác dụng của điệp ngữ, liệt kê, nói quá, nói giảm, chơi chữ.','trung_binh',15,'Điệp ngữ: lặp lại từ ngữ để nhấn mạnh, tạo nhịp điệu. Liệt kê: kể ra hàng loạt sự vật cùng loại. Nói quá: phóng đại mức độ. Chơi chữ: dùng từ đồng âm, đa nghĩa tạo hiệu quả hài hước, sâu sắc.','- Điệp ngữ: lặp lại từ ngữ để nhấn mạnh, tạo nhịp điệu.\n- Liệt kê: kể ra hàng loạt tạo ấn tượng đầy đủ, dồn dập.\n- Nói quá (khoa trương): phóng đại sự vật — \"đứt từng khúc ruột\".\n- Chơi chữ: dùng từ đồng âm, đa nghĩa tạo hiệu quả hài hước, sâu sắc.\n- Nhận diện đúng biện pháp tu từ theo tác dụng của nó.',2,'published',11,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(367,116,'Chữa lỗi dùng từ: lỗi về nghĩa và kết hợp từ (1)','tieng-viet-thpt-12-chua-loi-1','Phát hiện và chữa các lỗi dùng từ sai nghĩa, kết hợp từ thiếu chính xác, lặp từ, dùng từ Hán Việt sai.','kho',20,'Các lỗi thường gặp: dùng từ không đúng nghĩa, kết hợp từ gượng ép, lặp từ, dùng từ địa phương/khẩu ngữ trong văn viết trang trọng, nhầm từ Hán Việt. Khi chữa: thay từ đúng nghĩa, đúng phong cách.','- Lỗi dùng từ sai nghĩa: dùng từ không đúng nghĩa trong ngữ cảnh.\n- Kết hợp từ phải tự nhiên, đúng nghĩa và đúng ngữ cảnh.\n- Đọc kĩ cả câu để phát hiện từ dùng chưa chính xác.\n- Sửa từ sai bằng từ đúng nghĩa, đúng kết hợp.\n- Kiểm tra lại câu sau khi sửa lỗi dùng từ.',1,'published',12,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(368,116,'Chữa lỗi đặt câu: lỗi về cấu trúc và logic (2)','tieng-viet-thpt-12-chua-loi-2','Phát hiện và chữa các lỗi câu thiếu thành phần, sai trật tự, lủng củng, mâu thuẫn logic.','kho',20,'Các lỗi thường gặp: câu thiếu chủ ngữ hoặc vị ngữ, sắp xếp trật tự từ sai, câu dài lủng củng, các vế câu mâu thuẫn logic. Khi chữa: bổ sung thành phần thiếu, sắp xếp lại trật tự hợp lí.','- Câu thiếu chủ ngữ: trạng ngữ đứng đầu không thay thế được chủ ngữ.\n- Ví dụ: \"Qua bài thơ, cho em hiểu...\" sửa thành \"Bài thơ cho em hiểu...\".\n- Câu lủng củng: ý tứ rối rắm, các vế không liên kết chặt chẽ.\n- Xác định chủ ngữ, vị ngữ để phát hiện câu thiếu thành phần.\n- Viết lại câu cho đủ thành phần và mạch lạc.',2,'published',12,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(369,117,'Liên kết văn bản: các phép liên kết (1)','tieng-viet-thpt-12-lien-ket-van-ban-1','Nhận biết các phép liên kết: lặp từ ngữ, đồng nghĩa – trái nghĩa, nối, thế.','trung_binh',15,'Các phép liên kết chính: phép lặp (lặp từ ngữ), phép đồng nghĩa/trái nghĩa, phép nối (dùng quan hệ từ, từ nối), phép thế (dùng từ thay thế như ấy, đó, việc này).','- Phép lặp: lặp lại từ ngữ ở các câu để liên kết — \"Mẹ tôi... Mẹ tôi...\".\n- Phép thế: dùng từ thay thế — \"Lan rất chăm. Cô ấy luôn dậy sớm.\".\n- Phép nối: dùng từ nối liên kết ý nghĩa giữa các câu.\n- Phép tương phản: dùng cặp từ trái nghĩa (vui - buồn, nhanh - chậm).\n- Nhận diện đúng phép liên kết trong đoạn văn.',1,'published',12,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(370,117,'Liên kết văn bản: tính mạch lạc của đoạn văn (2)','tieng-viet-thpt-12-lien-ket-van-ban-2','Đánh giá tính mạch lạc của đoạn văn; sắp xếp câu theo trình tự hợp lí.','trung_binh',15,'Đoạn văn mạch lạc khi các câu liên kết chặt chẽ, triển khai đúng chủ đề theo một trình tự (thời gian, không gian, logic...). Câu chủ đề thường đứng đầu hoặc cuối đoạn.','- Đoạn văn mạch lạc: liên kết chặt, đúng chủ đề, trình tự hợp lí.\n- Câu chủ đề nêu ý chính, thường đứng đầu hoặc cuối đoạn.\n- Trình tự triển khai hợp lí giúp người đọc theo dõi dễ dàng.\n- Dấu hiệu thiếu mạch lạc: câu không liên kết, ý lộn xộn, lạc đề.\n- Kiểm tra tính mạch lạc khi viết và sửa đoạn văn.',2,'published',12,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(371,118,'Ôn tập các thì: hiện tại đơn và hiện tại tiếp diễn (1)','tieng-anh-thpt-10-cac-thi-co-ban-1','Phân biệt và sử dụng đúng thì hiện tại đơn (thói quen, sự thật) và hiện tại tiếp diễn (đang diễn ra).','trung_binh',15,'Present simple: S + V(s/es) — habits, facts (every day, usually). Present continuous: S + am/is/are + V-ing — happening now (now, at the moment, Look!).','- Hiện tại đơn diễn tả thói quen và sự thật hiển nhiên.\n- Ngôi thứ ba số ít: động từ thêm s/es (she goes, water boils).\n- Hiện tại tiếp diễn diễn tả hành động đang xảy ra: am/is/are + V-ing.\n- Dấu hiệu tiếp diễn: now, at the moment, Look!\n- Phân biệt \"every day\" (hiện tại đơn) với \"now\" (tiếp diễn).',1,'published',10,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(372,118,'Ôn tập các thì: quá khứ đơn và tương lai đơn (2)','tieng-anh-thpt-10-cac-thi-co-ban-2','Sử dụng đúng thì quá khứ đơn (hành động đã xong) và tương lai đơn (quyết định, dự đoán).','trung_binh',15,'Past simple: S + V-ed/V2 — finished actions (yesterday, last week, in 2020). Future simple: S + will + V — decisions, predictions (tomorrow, next week, I think...).','- Quá khứ đơn diễn tả hành động đã xảy ra và kết thúc trong quá khứ.\n- Dấu hiệu: yesterday, last night, last week.\n- Động từ bất quy tắc đổi dạng (go thành went); có quy tắc thêm -ed.\n- Tương lai đơn: will + động từ nguyên mẫu, dùng cho dự đoán và quyết định lúc nói.\n- Phân biệt thì theo dấu hiệu thời gian trong câu.',2,'published',10,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(373,119,'Câu điều kiện loại 1: cấu trúc và cách dùng (1)','tieng-anh-thpt-10-cau-dieu-kien-1-1','Nắm cấu trúc If + hiện tại đơn, will + V; dùng câu điều kiện loại 1 diễn tả điều có thể xảy ra.','trung_binh',15,'Type 1: If + S + V (present simple), S + will + V. Diễn tả điều kiện có thể xảy ra ở hiện tại/tương lai. Mệnh đề If có thể đứng trước hoặc sau.','- Cấu trúc câu điều kiện loại 1: If + hiện tại đơn, will + động từ nguyên mẫu.\n- Diễn tả điều kiện có thể xảy ra ở hiện tại hoặc tương lai.\n- Khi mệnh đề If đứng trước, dùng dấu phẩy ngăn cách hai mệnh đề.\n- Mệnh đề If không dùng \"will\".\n- Chia đúng động từ ở cả hai mệnh đề theo cấu trúc.',1,'published',10,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(374,119,'Câu điều kiện loại 1: luyện tập vận dụng (2)','tieng-anh-thpt-10-cau-dieu-kien-1-2','Vận dụng câu điều kiện loại 1 trong các tình huống; phân biệt với câu điều kiện loại 0.','trung_binh',15,'Type 0 (sự thật hiển nhiên): If + present simple, present simple. Type 1 (có thể xảy ra): If + present simple, will + V. Chú ý dấu phẩy khi mệnh đề If đứng trước.','- Ôn cấu trúc: If + hiện tại đơn, will + động từ nguyên mẫu.\n- Chủ ngữ he/she ở mệnh đề If: động từ thêm s/es (studies, is late).\n- Mệnh đề chính: will + động từ nguyên mẫu, không thêm s.\n- Nhận diện câu điều kiện loại 1 đúng cấu trúc.\n- Viết lại và sửa lỗi câu điều kiện loại 1.',2,'published',10,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(375,120,'Câu bị động: các thì cơ bản (1)','tieng-anh-thpt-11-cau-bi-dong-1','Chuyển câu chủ động sang bị động ở các thì hiện tại đơn, quá khứ đơn, tương lai đơn, hiện tại tiếp diễn.','trung_binh',15,'Passive: S + be + V-ed/V3 (+ by O). Chia \"be\" theo thì: is/are (hiện tại), was/were (quá khứ), will be (tương lai), is/are being (tiếp diễn). Tân ngữ của câu chủ động thành chủ ngữ câu bị động.','- Bị động hiện tại đơn: am/is/are + V-ed/V3 (are made).\n- Bị động quá khứ đơn: was/were + V-ed/V3 (was written thành written).\n- Bị động tương lai đơn: will be + V-ed/V3 (will be built).\n- Bị động hiện tại tiếp diễn: am/is/are + being + V-ed/V3.\n- Chuyển câu chủ động sang bị động, chia \"be\" đúng thì và số.',1,'published',11,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(376,120,'Câu bị động: dạng đặc biệt và động từ khuyết thiếu (2)','tieng-anh-thpt-11-cau-bi-dong-2','Dùng câu bị động với động từ khuyết thiếu, thì hiện tại hoàn thành; câu bị động hai tân ngữ.','kho',20,'Modal passive: S + modal + be + V-ed (must be cleaned). Present perfect passive: S + have/has + been + V-ed. Với hai tân ngữ, có thể đưa tân ngữ gián tiếp hoặc trực tiếp lên làm chủ ngữ.','- Bị động với động từ khuyết thiếu: modal + be + V-ed (must be cleaned, should be finished).\n- Bị động hiện tại hoàn thành: have/has + been + V-ed.\n- Câu có hai tân ngữ: có thể đưa tân ngữ gián tiếp hoặc trực tiếp lên làm chủ ngữ.\n- Nhớ dạng V3 của động từ bất quy tắc: built, written, given.\n- Chuyển đúng sang bị động theo thì và modal.',2,'published',11,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(377,121,'Câu tường thuật: câu trần thuật và câu hỏi (1)','tieng-anh-thpt-11-cau-tuong-thuat-1','Chuyển câu trần thuật và câu hỏi Yes/No, Wh- sang câu tường thuật; lùi thì đúng.','trung_binh',15,'Reported speech: lùi thì (present → past, past → past perfect, will → would). Câu trần thuật: S + said/told + (that) + clause. Yes/No: asked + if/whether. Wh-: asked + từ để hỏi.','- Tường thuật phải lùi thì: hiện tại đơn thành quá khứ đơn, will thành would.\n- Đổi đại từ và trạng từ chỉ thời gian: I thành she/he, tomorrow thành the next day.\n- Câu hỏi Yes/No: asked + if/whether + S + V, không đảo ngữ.\n- Câu hỏi Wh-: asked + từ để hỏi + S + V, không đảo ngữ.\n- Giữ đúng thứ tự S + V sau từ nối trong câu tường thuật.',1,'published',11,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(378,121,'Câu tường thuật: câu mệnh lệnh và câu điều kiện (2)','tieng-anh-thpt-11-cau-tuong-thuat-2','Tường thuật câu mệnh lệnh, yêu cầu (told/asked + to-V); tường thuật câu điều kiện.','kho',20,'Commands: S + told/asked + O + (not) to-V. Câu điều kiện loại 2, 3 khi tường thuật giữ nguyên thì. Chú ý đổi đại từ, trạng từ chỉ thời gian/nơi chốn (now → then, here → there, today → that day).','- Mệnh lệnh tường thuật: told/asked + tân ngữ + to-V.\n- Mệnh lệnh phủ định: told + tân ngữ + not to-V.\n- Yêu cầu lịch sự: asked + tân ngữ + to-V.\n- Câu điều kiện loại 2, 3 khi tường thuật giữ nguyên thì.\n- Đổi đại từ cho phù hợp: me thành her/him.',2,'published',11,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(379,122,'Mệnh đề quan hệ rút gọn: V-ing và V-ed (1)','tieng-anh-thpt-12-menh-de-quan-he-1','Rút gọn mệnh đề quan hệ chủ động bằng V-ing và bị động bằng V-ed.','kho',20,'Mệnh đề quan hệ chủ động (who/which + V) rút gọn thành V-ing: the boy who plays → the boy playing. Mệnh đề bị động (who/which + be + V-ed) rút gọn thành V-ed: the car which was made → the car made.','- Mệnh đề quan hệ chủ động rút gọn bằng V-ing: who plays thành playing.\n- Mệnh đề quan hệ bị động rút gọn bằng V-ed: which was made thành made.\n- Thì tiếp diễn chủ động cũng rút gọn bằng V-ing: who is talking thành talking.\n- Khi rút gọn, bỏ đại từ quan hệ và động từ \"be\".\n- Chọn dạng rút gọn đúng theo nghĩa chủ động hay bị động.',1,'published',12,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(380,122,'Mệnh đề quan hệ rút gọn: to-V và luyện tập tổng hợp (2)','tieng-anh-thpt-12-menh-de-quan-he-2','Rút gọn mệnh đề quan hệ bằng to-V (sau số thứ tự, so sánh nhất); luyện tập tổng hợp ba dạng.','kho',20,'Dùng to-V khi mệnh đề có số thứ tự (the first, the second), so sánh nhất (the best), hoặc chỉ mục đích: the first student to finish. Không rút gọn mệnh đề quan hệ không xác định có dấu phẩy bằng to-V.','- Sau số thứ tự (the first, the second) rút gọn bằng to-V.\n- Sau so sánh nhất (the best, the tallest) rút gọn bằng to-V.\n- Dạng bị động của to-V: to be + V-ed (the house to be built).\n- Không nhầm to-V với V-ing/V-ed khi có dấu hiệu số thứ tự, so sánh nhất.\n- Luyện tập tổng hợp cả ba dạng rút gọn V-ing, V-ed và to-V.',2,'published',12,1,'2026-10-07 22:55:07','2026-10-07 22:55:07'),
(381,123,'Đảo ngữ: cấu trúc cơ bản (1)','tieng-anh-thpt-12-dao-ngu-1','Nắm cấu trúc đảo ngữ với các trạng từ phủ định: never, rarely, hardly, no sooner, only.','kho',20,'Khi trạng từ phủ định đứng đầu câu, đảo trợ động từ lên trước chủ ngữ: Never have I seen...; Rarely does she come...; Hardly had he arrived when...; No sooner had... than...; Only when... did...','- Trạng từ phủ định đứng đầu câu thì đảo trợ động từ lên trước chủ ngữ.\n- Never/Rarely + trợ động từ + S + V: Rarely does she go...\n- Hardly + quá khứ hoàn thành đảo ngữ: Hardly had he arrived when...\n- Đảo ngữ giữ nguyên thì; động từ sau trợ động từ ở dạng nguyên mẫu.\n- Nhận diện câu cần đảo ngữ theo trạng từ phủ định đầu câu.',1,'published',12,1,'2026-10-07 22:55:08','2026-10-07 22:55:08'),
(382,123,'Đảo ngữ: luyện tập nâng cao (2)','tieng-anh-thpt-12-dao-ngu-2','Vận dụng đảo ngữ trong câu điều kiện (were/had/should) và các cấu trúc nâng cao.','kho',20,'Đảo ngữ câu điều kiện: Should you need help... (= If you should need); Were I rich... (= If I were); Had he studied... (= If he had studied). Chú ý: đảo ngữ không dùng với \"not\" thừa.','- Đảo ngữ câu điều kiện loại 1: Should + S + V, bỏ \"if\".\n- Đảo ngữ câu điều kiện loại 2: Were + S..., bỏ \"if\".\n- Đảo ngữ câu điều kiện loại 3: Had + S + V-ed..., bỏ \"if\".\n- Only + cụm trạng từ đầu câu thì đảo trợ động từ: Only when... did he understand.\n- Viết lại câu điều kiện thành dạng đảo ngữ đúng.',2,'published',12,1,'2026-10-07 22:55:08','2026-10-07 22:55:08'),
(383,124,'Hợp âm là gì: cấu tạo hợp âm ba trưởng và thứ','am-nhac-thpt-10-lop-10-1','Nhận biết khái niệm hợp âm; phân biệt hợp âm trưởng và hợp âm thứ qua cấu tạo quãng 3.','trung_binh',15,'Hợp âm ba (triad) gồm 3 nốt xếp chồng theo quãng 3: nốt gốc (root), nốt bậc 3 và nốt bậc 5. Hợp âm trưởng: quãng 3 trưởng + quãng 5 đúng (ví dụ C – E – G). Hợp âm thứ: quãng 3 thứ + quãng 5 đúng (ví dụ C – Eb – G). Ký hiệu quốc tế: C là Đô trưởng, Cm là Đô thứ.','- Hợp âm ba (triad) gồm 3 nốt xếp chồng theo quãng 3: nốt gốc, nốt bậc 3 và nốt bậc 5.\n- Hợp âm trưởng = quãng 3 trưởng + quãng 5 đúng (ví dụ Đô trưởng gồm C – E – G).\n- Hợp âm thứ = quãng 3 thứ + quãng 5 đúng, âm sắc trầm buồn hơn hợp âm trưởng.\n- Ký hiệu quốc tế: không có chữ \"m\" là trưởng (C), có chữ \"m\" là thứ (Am).\n- Hợp âm là nền tảng của đệm hát và hòa âm trong âm nhạc.',1,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(384,124,'Vòng hợp âm thông dụng và cách gọi tên hợp âm','am-nhac-thpt-10-lop-10-2','Gọi tên hợp âm theo ký hiệu quốc tế; nhận biết các vòng hợp âm phổ biến như I – V – vi – IV.','trung_binh',15,'Hợp âm được ký hiệu bằng chữ cái: C, D, E, F, G, A, B tương ứng Đô, Rê, Mi, Fa, Sol, La, Si. Chữ m viết sau nghĩa là thứ (Am = La thứ). Số 7 nghĩa là hợp âm 7 (G7 = Sol 7). Vòng hợp âm là chuỗi hợp âm lặp lại tạo nên khung của bài hát, ví dụ vòng C – G – Am – F rất phổ biến trong nhạc nhẹ.','- Ký hiệu quốc tế: A = La, B = Si, C = Đô, D = Rê, E = Mi, F = Fa, G = Sol.\n- Vòng hợp âm C – G – Am – F gồm các bậc I – V – vi – IV trong giọng Đô trưởng.\n- Hợp âm bậc V của giọng Đô trưởng là Sol, ký hiệu là G.\n- Không có chữ \"m\" là hợp âm trưởng; có chữ \"m\" là hợp âm thứ (Bb là Si giáng trưởng).\n- Vòng hợp âm I – V – vi – IV rất phổ biến trong nhiều bài hát.',2,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(385,125,'Khóa nhạc, nốt nhạc và các loại nhịp','am-nhac-thpt-10-lop-10-3','Nhận biết khóa Sol, khóa Fa; đọc nốt trên khuông nhạc; phân biệt nhịp đơn và nhịp kép.','trung_binh',15,'Khóa Sol (khóa Treble) dùng cho giọng cao và tay phải piano; khóa Fa (khóa Bass) dùng cho giọng trầm và tay trái piano. Nốt nhạc xếp trên 5 dòng kẻ và 4 khe. Nhịp 2/4, 3/4, 4/4 là nhịp đơn; nhịp 6/8, 9/8, 12/8 là nhịp kép (mỗi phách chia làm 3).','- Khóa Sol còn gọi là khóa Treble, dùng cho giọng cao và tay phải piano.\n- Khóa nhạc xác định vị trí các nốt trên khuông nhạc.\n- Khuông nhạc chuẩn gồm 5 dòng kẻ và 4 khe.\n- Nhịp đơn có mẫu số là 4 (2/4, 3/4, 4/4); nhịp kép có mẫu số là 8 và tử số chia hết cho 3 (6/8, 9/8).\n- Đọc đúng khóa nhạc là bước đầu tiên để đọc bản nhạc.',1,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(386,125,'Dấu hóa, nhịp phức và kỹ thuật đọc bản nhạc nhanh','am-nhac-thpt-10-lop-10-4','Hiểu tác dụng của dấu thăng, giáng, bình; đọc được bản nhạc có nhiều dấu hóa và nhịp đổi.','kho',20,'Dấu thăng (#) nâng nốt lên nửa cung, dấu giáng (b) hạ nốt xuống nửa cung, dấu bình (♮) hủy tác dụng của thăng/giáng. Dấu hóa ghi ở đầu khuông nhạc (bộ khóa) áp dụng cho cả bản nhạc. Kỹ thuật đọc nhanh: đọc theo cụm nốt thay vì từng nốt, nhìn trước 1–2 ô nhịp, nhận diện mẫu hợp âm quen thuộc.','- Dấu thăng (#) nâng cao độ của nốt lên nửa cung, ví dụ Fa thành Fa thăng.\n- Dấu giáng (b) hạ cao độ của nốt xuống nửa cung.\n- Dấu bình (♮) trả nốt về cao độ tự nhiên, hủy bỏ thăng hoặc giáng.\n- Dấu hóa đặt ở đầu khuông nhạc (bộ khóa) có tác dụng cho toàn bản nhạc.\n- Kỹ thuật đọc bản nhạc nhanh: nhận diện cụm nốt quen thuộc thay vì đọc từng nốt rời rạc.',2,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(387,126,'Nhạc cách mạng và nhạc tiền chiến','am-nhac-thpt-11-lop-11-1','Hiểu bối cảnh ra đời của nhạc cách mạng và nhạc tiền chiến; nhận biết đặc điểm nội dung của hai dòng nhạc.','trung_binh',15,'Nhạc cách mạng ra đời trong hai cuộc kháng chiến, nội dung ca ngợi quê hương, cổ vũ chiến đấu; tiêu biểu là Quốc ca Tiến quân ca. Nhạc tiền chiến (trước năm 1945) mang màu sắc lãng mạn, trữ tình, ca ngợi tình yêu quê hương đất nước. Cả hai dòng đều có giá trị lịch sử và nghệ thuật lớn.','- Nhạc cách mạng ra đời và phát triển mạnh trong hai cuộc kháng chiến, giai điệu hào hùng, cổ vũ chiến đấu.\n- Nhạc tiền chiến lãng mạn, trữ tình, ra đời trước Cách mạng tháng Tám.\n- Tiến quân ca được chọn làm Quốc ca của Việt Nam.\n- Cả hai dòng nhạc đều có giá trị lịch sử và nghệ thuật lớn.\n- Tìm hiểu các dòng nhạc giúp hiểu thêm lịch sử dân tộc qua âm nhạc.',1,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(388,126,'Nhạc trữ tình, nhạc trẻ và dòng nhạc dân gian đương đại','am-nhac-thpt-11-lop-11-2','Phân biệt nhạc trữ tình, nhạc trẻ; hiểu khái niệm phối khí mới cho chất liệu dân gian.','trung_binh',15,'Nhạc trữ tình (bolero) có giai điệu chậm, lời ca da diết về tình yêu quê hương. Nhạc trẻ gắn với đời sống đô thị hiện đại, tiết tấu sôi động, hòa âm theo xu hướng quốc tế. Dòng nhạc dân gian đương đại dùng chất liệu dân ca, nhạc cụ dân tộc phối với hòa âm hiện đại.','- Nhạc trữ tình (bolero) có giai điệu chậm, lời ca da diết về tình yêu quê hương, đôi lứa.\n- Nhạc trẻ phản ánh đời sống đô thị hiện đại với tiết tấu sôi động.\n- Phối khí mới cho chất liệu dân gian: dùng hòa âm và nhạc cụ hiện đại làm mới làn điệu truyền thống.\n- Mỗi dòng nhạc phục vụ một nhu cầu thưởng thức khác nhau của khán giả.\n- Âm nhạc Việt Nam ngày càng đa dạng, hội nhập mà vẫn giữ bản sắc dân tộc.',2,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(389,127,'Nhạc sĩ là ai: vai trò của người sáng tác','am-nhac-thpt-11-lop-11-3','Hiểu công việc của nhạc sĩ: sáng tác giai điệu, viết lời, phối khí; phân biệt nhạc sĩ với ca sĩ.','trung_binh',15,'Nhạc sĩ là người sáng tác âm nhạc: viết giai điệu, lời ca và ý tưởng hòa âm. Ca sĩ là người thể hiện tác phẩm. Một người có thể vừa là nhạc sĩ vừa là ca sĩ. Tác quyền bảo vệ quyền lợi của người sáng tác khi tác phẩm được sử dụng.','- Nhạc sĩ là người sáng tác: viết giai điệu, lời ca và ý tưởng hòa âm, phối khí.\n- Ca sĩ là người thể hiện tác phẩm của nhạc sĩ đến với khán giả.\n- Mỗi vai trò là một mắt xích quan trọng trong đời sống âm nhạc.\n- Một bài hát hay cần cả sáng tác tốt và thể hiện tốt.\n- Ngoài nhạc sĩ và ca sĩ còn có người hòa âm, phối khí góp phần hoàn thiện tác phẩm.',1,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(390,127,'Các thế hệ nhạc sĩ Việt Nam hiện đại','am-nhac-thpt-11-lop-11-4','Nhận biết các thế hệ nhạc sĩ theo thời kỳ lịch sử và đóng góp chung của mỗi thế hệ.','kho',20,'Nhạc sĩ Việt Nam hiện đại thường được xếp theo thế hệ gắn với thời kỳ lịch sử: thế hệ tiền chiến đặt nền móng tân nhạc; thế hệ kháng chiến với nhạc cách mạng; thế hệ sau năm 1975 phát triển nhạc nhẹ; thế hệ đương đại hội nhập quốc tế. Mỗi thế hệ đều để lại những tác phẩm gắn với đời sống dân tộc.','- Thế hệ tiền chiến đặt nền móng cho tân nhạc — nhạc Việt Nam hiện đại theo lối phương Tây.\n- Thế hệ kháng chiến để lại dòng nhạc cách mạng hào hùng.\n- Năm 1975 (đất nước thống nhất) là mốc chia các thế hệ nhạc sĩ trước và sau.\n- Mỗi thế hệ gắn với một thời kỳ lịch sử và dòng nhạc riêng.\n- Các thế hệ nhạc sĩ nối tiếp nhau làm giàu kho tàng âm nhạc Việt Nam.',2,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(391,128,'Nhạc cổ điển, jazz và blues','am-nhac-thpt-12-lop-12-1','Hiểu khái niệm âm nhạc bác học; nhận biết đặc điểm của jazz và blues.','trung_binh',15,'Nhạc cổ điển (âm nhạc bác học) là dòng nhạc nghệ thuật phương Tây, được ghi chép bằng bản nhạc chuẩn xác, biểu diễn trong nhà hát. Jazz ra đời ở Mỹ đầu thế kỷ 20, đặc trưng bởi ứng tác (improvisation) và tiết tấu swing. Blues là tiền thân của jazz, giai điệu buồn, cấu trúc 12 ô nhịp.','- Âm nhạc bác học là dòng nhạc nghệ thuật phương Tây, thường gọi là nhạc cổ điển — chuẩn mực, tinh tế.\n- Jazz ra đời ở Mỹ đầu thế kỷ 20 từ cộng đồng người Mỹ gốc Phi, đặc trưng bởi sự tự do, ngẫu hứng.\n- Blues có giai điệu trầm buồn, là nguồn gốc của jazz và rock.\n- Ba thể loại có mối quan hệ nguồn gốc: blues sinh ra jazz, jazz ảnh hưởng nhiều dòng nhạc hiện đại.\n- Thưởng thức các thể loại giúp mở rộng hiểu biết về âm nhạc thế giới.',1,'published',12,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(392,128,'Rock, pop, hip-hop và nhạc điện tử','am-nhac-thpt-12-lop-12-2','Phân biệt rock, pop, hip-hop, EDM qua đặc điểm tiết tấu, nhạc cụ và cách thể hiện.','trung_binh',15,'Rock dùng guitar điện, trống, bass với âm thanh mạnh mẽ. Pop có giai điệu dễ nhớ, hướng đến đại chúng. Hip-hop nổi bật với rap (đọc có nhịp điệu trên nền beat). Nhạc điện tử (EDM) được tạo chủ yếu bằng máy tính và thiết bị điện tử, thường dùng trong vũ trường và lễ hội âm nhạc.','- Rock mạnh mẽ với guitar điện, trống và bass là nhạc cụ đặc trưng.\n- Pop là nhạc đại chúng: giai điệu dễ nhớ, dễ hát theo, hướng đến đông đảo khán giả.\n- Hip-hop gắn với rap và văn hóa đường phố, tiết tấu khỏe khoắn.\n- EDM (nhạc điện tử) được tạo ra từ thiết bị điện tử và máy tính, tiết tấu dồn dập.\n- Mỗi thể loại có tiết tấu, nhạc cụ và cách thể hiện riêng.',2,'published',12,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(393,129,'Giao hưởng và concerto','am-nhac-thpt-12-lop-12-3','Hiểu cấu tạo của bản giao hưởng (4 chương) và concerto (nhạc cụ độc tấu với dàn nhạc).','kho',20,'Giao hưởng (symphony) là tác phẩm lớn cho dàn nhạc giao hưởng, thường gồm 4 chương với tốc độ khác nhau: nhanh – chậm – vừa – nhanh. Concerto là tác phẩm cho một nhạc cụ độc tấu (violin, piano...) đối thoại với dàn nhạc, thường có 3 chương. Cả hai đều là đỉnh cao của âm nhạc bác học.','- Bản giao hưởng (symphony) điển hình gồm 4 chương với tốc độ khác nhau.\n- Giao hưởng tôn vinh sức mạnh tập thể của cả dàn nhạc.\n- Concerto là cuộc đối thoại giữa nhạc cụ độc tấu và dàn nhạc, tôn vinh cá nhân nghệ sĩ.\n- Cả hai đều là đỉnh cao của âm nhạc bác học phương Tây.\n- Nghe giao hưởng và concerto giúp cảm nhận chiều sâu của âm nhạc cổ điển.',1,'published',12,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(394,129,'Opera, nhạc kịch và nhạc thính phòng','am-nhac-thpt-12-lop-12-4','Phân biệt opera với nhạc kịch; hiểu khái niệm nhạc thính phòng và các biên chế biểu diễn.','kho',20,'Opera là vở nhạc kịch mà diễn viên hát toàn bộ lời thoại, kết hợp dàn nhạc, phục trang và sân khấu hoành tráng. Nhạc kịch hiện đại (musical) xen kẽ hát và thoại. Nhạc thính phòng (chamber music) viết cho nhóm nhỏ nhạc công (song tấu, tam tấu, tứ tấu), biểu diễn trong không gian nhỏ, đòi hỏi sự phối hợp tinh tế.','- Opera là vở nhạc kịch mà diễn viên hát toàn bộ lời thoại, quy mô hoành tráng.\n- Nhạc kịch hiện đại (musical) xen kẽ các đoạn hát và thoại, gần gũi với khán giả hơn opera.\n- Nhạc thính phòng là nhạc cho nhóm nhạc cụ nhỏ, biểu diễn trong không gian nhỏ, tinh tế.\n- Ba hình thức có quy mô và phong cách khác nhau: hoành tráng, gần gũi, tinh tế.\n- Thưởng thức các hình thức sân khấu âm nhạc giúp mở rộng vốn hiểu biết nghệ thuật.',2,'published',12,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(395,130,'Mỹ thuật Trung Hoa và Nhật Bản','my-thuat-thpt-10-lop-10-1','Nhận biết tranh thủy mặc Trung Hoa và tranh khắc gỗ ukiyo-e Nhật Bản qua chất liệu và đặc điểm.','trung_binh',15,'Tranh thủy mặc Trung Hoa dùng mực đen trên giấy hoặc lụa, đề tài sơn thủy, coi trọng khoảng trống và khí vận. Tranh khắc gỗ ukiyo-e của Nhật Bản in nhiều bản màu, đề tài đời sống, phong cảnh, nổi tiếng với hình ảnh sóng và núi Phú Sĩ. Cả hai đều ảnh hưởng sâu đến mỹ thuật thế giới.','- Tranh thủy mặc Trung Hoa dùng mực đen pha nước vẽ trên giấy hoặc lụa, phong cách tối giản.\n- Thủy là nước, mặc là mực — thủy mặc nghĩa là dùng nước pha mực để vẽ.\n- Tranh khắc gỗ ukiyo-e của Nhật Bản in nhiều bản màu, rực rỡ và sinh động.\n- Thủy mặc chú trọng ý cảnh và khoảng trống; ukiyo-e chú trọng màu sắc và chi tiết.\n- Cả hai đều là đỉnh cao mỹ thuật Đông Á, ảnh hưởng sâu rộng đến nghệ thuật thế giới.',1,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(396,130,'Mỹ thuật truyền thống Việt Nam','my-thuat-thpt-10-lop-10-2','Nhận biết tranh dân gian Đông Hồ, Hàng Trống; hiểu các chất liệu truyền thống: sơn mài, lụa, khắc gỗ.','trung_binh',15,'Tranh Đông Hồ (Bắc Ninh) in từ ván khắc gỗ trên giấy điệp, màu từ thiên nhiên, đề tài dân gian. Tranh Hàng Trống (Hà Nội) in nét rồi tô màu tay, đề tài thờ cúng, chúc tụng. Sơn mài và lụa là chất liệu đặc sắc của hội họa Việt Nam hiện đại.','- Tranh Đông Hồ: in ván khắc gỗ trên giấy điệp quét điệp, làng Đông Hồ, Bắc Ninh.\n- Tranh Hàng Trống: in ván lấy nét rồi tô màu bằng tay nên mềm mại.\n- Sơn mài dùng nhựa cây sơn ta, qua nhiều lớp mài tạo độ bóng sâu, sang trọng.\n- Tranh lụa mềm mại, nhẹ nhàng; tranh khắc gỗ mộc mạc, khỏe khoắn.\n- Mỹ thuật truyền thống Việt Nam mộc mạc mà tinh tế, giàu bản sắc dân tộc.',2,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(397,131,'Mỹ thuật Ai Cập, Hy Lạp và La Mã cổ đại','my-thuat-thpt-10-lop-10-3','Nhận biết đặc điểm mỹ thuật Ai Cập (luật frontal) và điêu khắc Hy Lạp – La Mã (tả thực, cân đối).','trung_binh',15,'Mỹ thuật Ai Cập gắn với tín ngưỡng, tuân thủ luật frontal: mặt vẽ nghiêng, mắt nhìn thẳng, thân nhìn thẳng. Hy Lạp cổ đại đề cao vẻ đẹp cơ thể con người, điêu khắc tả thực, cân đối theo tỷ lệ vàng. La Mã kế thừa Hy Lạp, phát triển nghệ thuật chân dung và kiến trúc vòm, mái vòm.','- Luật frontal của Ai Cập cổ đại: quy tắc tạo hình cứng nhắc — mặt nghiêng, mắt và thân nhìn thẳng.\n- Mỹ thuật Ai Cập gắn với tâm linh, phục vụ đời sống sau khi chết của pharaoh.\n- Điêu khắc Hy Lạp tôn vinh vẻ đẹp con người với tỷ lệ cân đối, tả thực.\n- La Mã kế thừa Hy Lạp, chú trọng tính thực dụng và chân dung tả thực.\n- Ba nền mỹ thuật đặt nền móng cho nghệ thuật phương Tây sau này.',1,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(398,131,'Phục hưng, Ấn tượng và nghệ thuật hiện đại','my-thuat-thpt-10-lop-10-4','Hiểu tinh thần Phục hưng; nhận biết trường phái Ấn tượng và các trào lưu nghệ thuật hiện đại.','kho',20,'Phục hưng (thế kỷ 14–16) hồi sinh tinh thần cổ điển, phát minh luật phối cảnh, đề cao con người. Ấn tượng (cuối thế kỷ 19) vẽ ngoài trời, chấm phá màu để ghi lại ấn tượng ánh sáng. Nghệ thuật hiện đại thế kỷ 20 bùng nổ nhiều trào lưu: lập thể, siêu thực, trừu tượng... phá vỡ quy tắc tạo hình truyền thống.','- Phục hưng (Renaissance) hồi sinh văn hóa cổ điển Hy Lạp – La Mã vào thế kỷ 14–16.\n- Thành tựu kỹ thuật của hội họa Phục hưng: luật phối cảnh vẽ không gian ba chiều trên mặt phẳng.\n- Trường phái Ấn tượng chú trọng cảm xúc ánh sáng, màu sắc tươi sáng, nét vẽ nhanh.\n- Nghệ thuật hiện đại phá cách, thể hiện cái tôi và tư duy mới của nghệ sĩ.\n- Dòng chảy mỹ thuật phương Tây: cổ điển chuẩn mực, Ấn tượng cảm xúc, hiện đại phá cách.',2,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(399,132,'Cân bằng, tương phản và điểm nhấn','my-thuat-thpt-11-lop-11-1','Vận dụng cân bằng đối xứng/bất đối xứng; tạo tương phản và điểm nhấn trong bố cục.','trung_binh',15,'Cân bằng đối xứng tạo cảm giác trang trọng, ổn định; cân bằng bất đối xứng tạo sự năng động. Tương phản (sáng–tối, to–nhỏ, nóng–lạnh) giúp các yếu tố nổi bật. Điểm nhấn là vị trí thu hút mắt nhìn đầu tiên, thường đặt theo quy tắc một phần ba.','- Cân bằng đối xứng: hai bên bố cục giống nhau, tạo cảm giác trang trọng, ổn định.\n- Cân bằng bất đối xứng: các yếu tố khác nhau nhưng vẫn hài hòa, tạo cảm giác năng động.\n- Tương phản tạo ra bằng sự đối lập rõ rệt: to – nhỏ, đậm – nhạt, nóng – lạnh.\n- Điểm nhấn là chi tiết nổi bật nhất, dẫn mắt người xem trong thiết kế.\n- Ba nguyên lý nền tảng giúp mọi thiết kế chuyên nghiệp và thu hút.',1,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(400,132,'Nhịp điệu, tỷ lệ, thống nhất và khoảng trắng','my-thuat-thpt-11-lop-11-2','Hiểu nhịp điệu thị giác, tỷ lệ vàng, tính thống nhất và vai trò của khoảng trắng.','trung_binh',15,'Nhịp điệu là sự lặp lại có quy luật tạo chuyển động cho mắt. Tỷ lệ vàng (khoảng 1:1,618) được coi là tỷ lệ hài hòa. Thống nhất là sự gắn kết các yếu tố thành tổng thể. Khoảng trắng (negative space) giúp bố cục thoáng, sang và dễ đọc, không phải chỗ trống lãng phí.','- Nhịp điệu thị giác là sự lặp lại có quy luật, tạo chuyển động cho mắt người xem.\n- Tỷ lệ vàng khoảng 1:1,618 được coi là tỷ lệ hài hòa, đẹp nhất.\n- Tính thống nhất: mọi yếu tố trong thiết kế phải liên kết, phục vụ một ý tưởng chung.\n- Khoảng trắng (không gian âm) giúp thiết kế thoáng, dễ đọc và sang trọng.\n- Bốn nguyên lý hoàn thiện một thiết kế chuyên nghiệp.',2,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(401,133,'Vòng tròn màu và các nhóm màu','my-thuat-thpt-11-lop-11-3','Đọc vòng tròn màu; phân biệt màu nóng/lạnh, màu bậc 1/2/3 và các cặp màu bổ túc.','trung_binh',15,'Vòng tròn màu gồm 12 màu: 3 màu bậc 1 (đỏ, vàng, lam), 3 màu bậc 2 (cam, lục, tím) pha từ hai màu bậc 1, 6 màu bậc 3. Màu nóng (đỏ, cam, vàng) gợi năng lượng; màu lạnh (lam, lục, tím) gợi sự yên tĩnh. Hai màu đối diện nhau là cặp bổ túc, đặt cạnh nhau tạo tương phản mạnh.','- Vòng tròn màu chuẩn gồm 12 màu: 3 màu bậc 1, 3 màu bậc 2, 6 màu bậc 3.\n- Ba màu bậc 1 (màu gốc): đỏ, vàng, lam — không pha được từ màu khác.\n- Màu nóng: đỏ – cam – vàng; màu lạnh: lam – lục – tím.\n- Cặp màu bổ túc nằm đối diện nhau trên vòng tròn màu: đỏ – lục, cam – lam, vàng – tím.\n- Đọc được vòng tròn màu là nền tảng để phối màu trong thiết kế.',1,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(402,133,'Phối màu và tâm lý màu sắc','my-thuat-thpt-11-lop-11-4','Vận dụng các công thức phối màu; hiểu ý nghĩa tâm lý của màu sắc trong thiết kế.','kho',20,'Các công thức phối màu phổ biến: đơn sắc (một màu nhiều sắc độ), tương đồng (màu kề nhau), bổ túc (hai màu đối diện), bộ ba (tam giác đều trên vòng tròn màu). Mỗi màu gợi cảm xúc riêng: đỏ – nhiệt huyết, xanh lam – tin cậy, xanh lá – thiên nhiên, vàng – lạc quan, đen – sang trọng, trắng – tinh khiết.','- Phối đơn sắc: một màu gốc với nhiều sắc độ đậm nhạt — an toàn, tinh tế, dễ dùng.\n- Phối tương đồng: các màu kề nhau trên vòng tròn màu — hài hòa, nhẹ nhàng.\n- Phối bổ túc: cặp màu đối diện nhau — tương phản mạnh, nổi bật, cần tiết chế khi dùng.\n- Mỗi màu gợi tâm lý riêng: đỏ năng động, xanh dương tin cậy, xanh lá tươi mới.\n- Chọn công thức phối màu phù hợp với thông điệp muốn truyền tải.',2,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(403,134,'Logo và nhận diện thương hiệu','my-thuat-thpt-12-lop-12-1','Hiểu vai trò của logo; nhận biết các loại logo và nguyên tắc thiết kế logo tốt.','trung_binh',15,'Logo là dấu hiệu nhận biết cốt lõi của thương hiệu, gồm các loại: chữ (logotype), biểu tượng (symbol), kết hợp cả hai. Logo tốt phải đơn giản, dễ nhớ, bền vững theo thời gian và dùng được ở mọi kích thước. Hệ nhận diện thương hiệu gồm logo, màu sắc, font chữ, danh thiếp, bao bì... thống nhất với nhau.','- Logo là dấu hiệu nhận biết trung tâm của thương hiệu, xuất hiện trên mọi ấn phẩm.\n- Các loại logo: logotype (dạng chữ), biểu tượng (dạng hình), kết hợp chữ và hình.\n- Nguyên tắc logo tốt: đơn giản, dễ nhớ, dễ nhận biết ở mọi kích cỡ.\n- Logo phải thể hiện được tính cách và lĩnh vực hoạt động của thương hiệu.\n- Hệ nhận diện thương hiệu gồm logo, màu sắc, font chữ được dùng nhất quán.',1,'published',12,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(404,134,'Poster, typography và lưới bố cục','my-thuat-thpt-12-lop-12-2','Hiểu cấu trúc poster hiệu quả; nắm kiến thức cơ bản về typography và lưới bố cục.','trung_binh',15,'Poster hiệu quả có thứ bậc thông tin rõ: tiêu đề nổi bật, hình ảnh thu hút, thông tin chi tiết vừa đủ. Typography là nghệ thuật chữ: chọn font phù hợp (serif trang trọng, sans-serif hiện đại), chú ý cỡ chữ, giãn dòng, căn lề. Lưới bố cục (grid) giúp sắp xếp các yếu tố gọn gàng, nhất quán trên nhiều trang.','- Poster hiệu quả cần thứ bậc thông tin rõ ràng: tiêu đề nổi bật nhất, chi tiết phụ nhỏ hơn.\n- Typography là nghệ thuật sắp đặt và thiết kế chữ, quyết định vẻ đẹp của phần chữ.\n- Font serif có chân (trang trọng, cổ điển); font sans-serif không chân (hiện đại, gọn gàng).\n- Lưới bố cục giúp sắp xếp các yếu tố ngay hàng thẳng lối, chuyên nghiệp.\n- Bốn thành phần của poster hiệu quả: tiêu đề, hình ảnh, thông tin chi tiết và lời kêu gọi hành động.',2,'published',12,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(405,135,'Các phong cách kiến trúc tiêu biểu','my-thuat-thpt-12-lop-12-3','Nhận biết kiến trúc cổ điển, Gothic, hiện đại và kiến trúc truyền thống Việt Nam.','trung_binh',15,'Kiến trúc cổ điển Hy Lạp – La Mã dùng hệ cột và thức cột nghiêm ngặt. Gothic nổi bật với vòm nhọn, cửa sổ kính màu, tháp cao vút. Kiến trúc hiện đại đề cao công năng, vật liệu mới (thép, kính, bê tông). Kiến trúc truyền thống Việt Nam: mái cong, đình chùa, dùng gỗ và ngói, hài hòa với thiên nhiên.','- Kiến trúc cổ điển Hy Lạp – La Mã nổi bật với hệ cột và thức cột (Doric, Ionic, Corinthian).\n- Kiến trúc Gothic vươn cao lên trời với vòm nhọn và kính màu rực rỡ.\n- Kiến trúc hiện đại chú trọng công năng, đường nét đơn giản, vật liệu mới.\n- Kiến trúc truyền thống Việt Nam: mái cong, kết cấu gỗ, hài hòa với thiên nhiên.\n- Mỗi phong cách có ngôn ngữ hình thức riêng, phản ánh thời đại và văn hóa.',1,'published',12,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(406,135,'Điêu khắc: hình thức và chất liệu','my-thuat-thpt-12-lop-12-4','Phân biệt điêu khắc tròn và phù điêu; hiểu các chất liệu điêu khắc và vai trò của tượng đài.','kho',20,'Điêu khắc tròn là tượng có thể xem từ mọi phía; phù điêu là hình nổi trên mặt phẳng (nổi cao, nổi thấp). Chất liệu đa dạng: đá, gỗ, đồng, đất nung, vật liệu composite hiện đại. Tượng đài trong không gian công cộng tôn vinh nhân vật, sự kiện lịch sử, đòi hỏi sự trang nghiêm và bền vững.','- Điêu khắc tròn là tượng độc lập ba chiều, có thể xem từ mọi phía.\n- Phù điêu là hình nổi trên mặt phẳng nền, gồm nổi cao và nổi thấp.\n- Chất liệu điêu khắc phổ biến: đá, gỗ, đồng, thạch cao, đất nung.\n- Tượng đài thường đặt nơi công cộng để tưởng niệm nhân vật, sự kiện lịch sử.\n- Chọn chất liệu phù hợp quyết định độ bền và vẻ đẹp của tác phẩm điêu khắc.',2,'published',12,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(407,136,'Sân thi đấu, cầu thủ và thời gian thi đấu','gdtc-thpt-10-lop-10-1','Nắm kích thước sân, số cầu thủ, thời gian thi đấu và quy định thay người cơ bản.','trung_binh',15,'Sân bóng đá 11 người dài 90–120m, rộng 45–90m (tiêu chuẩn quốc tế khoảng 105×68m). Mỗi đội 11 cầu thủ gồm 1 thủ môn; trận đấu không tiếp tục nếu một đội còn dưới 7 người. Trận đấu gồm 2 hiệp, mỗi hiệp 45 phút, nghỉ giữa hiệp tối đa 15 phút. Bóng đá hiện đại cho thay tối đa 5 cầu thủ mỗi trận.','- Mỗi đội bóng đá có 11 cầu thủ trên sân: 1 thủ môn và 10 cầu thủ khác.\n- Trận đấu chuẩn gồm 2 hiệp, mỗi hiệp 45 phút, nghỉ giữa hiệp tối đa 15 phút.\n- Kích thước sân bóng đá 11 người tuân theo quy định của luật FIFA.\n- Mỗi đội được thay người theo quy định riêng của từng giải đấu.\n- Nắm chắc các con số cơ bản là nền tảng để hiểu luật bóng đá.',1,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(408,136,'Việt vị, phạm lỗi và các quả phạt','gdtc-thpt-10-lop-10-2','Hiểu luật việt vị; phân biệt các quả phạt trực tiếp, gián tiếp, phạt đền và thẻ phạt.','kho',20,'Việt vị: cầu thủ đứng gần khung thành đối phương hơn bóng và cầu thủ áp chót của đối phương tại thời điểm đồng đội chuyền bóng, và tham gia tình huống. Không việt vị khi nhận bóng từ phát bóng, ném biên, phạt góc. Phạm lỗi trong vòng cấm bị phạt đền. Thẻ vàng cảnh cáo; hai thẻ vàng hoặc thẻ đỏ trực tiếp bị truất quyền thi đấu.','- Luật việt vị xét tại thời điểm đồng đội chuyền bóng, không phải lúc nhận bóng.\n- Không bị thổi việt vị khi nhận bóng từ phát bóng, ném biên và phạt góc.\n- Phạt trực tiếp: đá thẳng vào khung thành được tính bàn thắng.\n- Phạm lỗi trong vòng cấm địa bị phạt đền (penalty), đá từ chấm 11m.\n- Một tình huống việt vị cần cả vị trí việt vị và sự tham gia vào tình huống bóng.',2,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(409,137,'Các vị trí trên sân bóng đá','gdtc-thpt-10-lop-10-3','Nhận biết 4 tuyến: thủ môn, hậu vệ, tiền vệ, tiền đạo và vai trò của từng vị trí.','trung_binh',15,'Thủ môn là người duy nhất được dùng tay trong vòng cấm, có nhiệm vụ bảo vệ khung thành. Hậu vệ ngăn chặn đối phương ghi bàn (trung vệ, hậu vệ biên). Tiền vệ là cầu nối giữa phòng ngự và tấn công. Tiền đạo có nhiệm vụ ghi bàn, gồm tiền đạo cắm và tiền đạo cánh.','- Bốn tuyến trên sân: thủ môn, hậu vệ, tiền vệ, tiền đạo.\n- Thủ môn là người duy nhất được dùng tay trong vòng cấm địa, nhiệm vụ bảo vệ khung thành.\n- Hậu vệ là tuyến phòng ngự, ngăn cản đối phương ghi bàn.\n- Tiền vệ là cầu nối giữa phòng ngự và tấn công, điều tiết nhịp độ trận đấu.\n- Tiền đạo là tuyến tấn công, nhiệm vụ chính là ghi bàn thắng.',1,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(410,137,'Sơ đồ chiến thuật cơ bản','gdtc-thpt-10-lop-10-4','Đọc sơ đồ chiến thuật 4-4-2, 4-3-3, 3-5-2; hiểu khái niệm pressing và phản công.','kho',20,'Sơ đồ chiến thuật ghi số cầu thủ từng tuyến không tính thủ môn: 4-4-2 cân bằng, 4-3-3 thiên về tấn công biên, 3-5-2 chắc chắn ở giữa sân. Pressing là gây áp lực ngay bên phần sân đối phương để giành bóng. Phản công là chuyển nhanh từ phòng ngự sang tấn công khi cướp được bóng.','- Sơ đồ chiến thuật ghi số cầu thủ từng tuyến, không tính thủ môn (ví dụ 4-4-2: 4 hậu vệ, 4 tiền vệ, 2 tiền đạo).\n- Sơ đồ 4-3-3 với 3 tiền đạo thiên về tấn công, tạo sức ép lớn ở hai biên.\n- Nhiều hậu vệ thì thiên về phòng ngự, nhiều tiền đạo thì thiên về tấn công.\n- Pressing là chiến thuật gây sức ép ngay trên phần sân của đối phương.\n- Phản công là tổ chức tấn công nhanh ngay khi vừa giành lại được bóng.',2,'published',10,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(411,138,'Luật bóng chuyền: sân, đội hình và cách tính điểm','gdtc-thpt-11-lop-11-1','Nắm kích thước sân, chiều cao lưới, đội hình 6 người và cách tính điểm theo thể thức rally.','trung_binh',15,'Sân bóng chuyền dài 18m, rộng 9m; lưới cao 2,43m (nam) và 2,24m (nữ). Mỗi đội 6 người trên sân. Tính điểm theo thể thức rally: mỗi pha bóng đều có điểm, đội thắng pha bóng được phát bóng tiếp. Thắng 1 set khi đạt 25 điểm và hơn đối phương ít nhất 2 điểm; set 5 (nếu có) đánh đến 15 điểm.','- Sân bóng chuyền tiêu chuẩn dài 18m, rộng 9m.\n- Chiều cao lưới bóng chuyền nam là 2,43m, lưới nữ là 2,24m.\n- Mỗi đội 6 người trên sân, tính điểm theo thể thức rally (mỗi pha bóng đều có điểm).\n- Thắng set khi đạt 25 điểm và hơn đối phương ít nhất 2 điểm.\n- Ghi nhớ các con số chuẩn giúp hiểu và chơi bóng chuyền đúng luật.',1,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(412,138,'Luật bóng chuyền: luân chuyển, chạm bóng và lỗi thường gặp','gdtc-thpt-11-lop-11-2','Hiểu luật luân chuyển vị trí, số lần chạm bóng và các lỗi kỹ thuật thường gặp.','trung_binh',15,'Khi giành quyền phát bóng từ đối phương, đội phải luân chuyển vị trí theo chiều kim đồng hồ. Mỗi đội được chạm bóng tối đa 3 lần trước khi đưa bóng sang sân đối phương (chắn bóng không tính). Lỗi thường gặp: chạm lưới, dẫm vạch giữa sân, bóng chạm ăng-ten, cầu thủ hàng sau tấn công trên vạch 3m.','- Khi giành quyền phát bóng, đội bóng chuyền phải luân chuyển vị trí theo chiều kim đồng hồ.\n- Mỗi đội được chạm bóng tối đa 3 lần; riêng chắn bóng không tính là một lần chạm.\n- Luân chuyển vị trí đảm bảo mọi cầu thủ đều trải qua các vị trí trên sân.\n- Các lỗi kỹ thuật thường gặp: chạm lưới, bóng ra ngoài, quá 3 lần chạm.\n- Phân biệt hành vi hợp lệ và phạm lỗi giúp thi đấu đúng luật, tránh mất điểm.',2,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(413,139,'Luật cầu lông: sân, cách tính điểm và giao cầu','gdtc-thpt-11-lop-11-3','Nắm kích thước sân đơn/đôi, cách tính điểm 21 và quy định giao cầu đúng luật.','trung_binh',15,'Sân cầu lông dài 13,4m; rộng 6,1m (đánh đôi) và 5,18m (đánh đơn). Lưới cao 1,55m ở cột. Mỗi set đánh đến 21 điểm theo thể thức rally, phải hơn đối phương 2 điểm; nếu 29 đều, ai được 30 trước thì thắng. Giao cầu phải đánh từ dưới thắt lưng, cầu bay chéo sang ô đối diện.','- Sân cầu lông dài 13,4m; sân đơn rộng 5,18m, sân đôi rộng 6,1m (đơn và đôi chỉ khác chiều rộng).\n- Tính điểm rally: mỗi set đánh đến 21 điểm, thắng 2 trong 3 set thì thắng trận.\n- Giao cầu phải đánh sang ô chéo sân của đối phương mới hợp lệ.\n- Cầu chạm vạch vẫn tính là trong sân.\n- Nắm chắc kích thước sân và luật tính điểm để thi đấu đúng luật.',1,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(414,139,'Luật cầu lông: lỗi và tình huống đặc biệt','gdtc-thpt-11-lop-11-4','Nhận biết các lỗi: chạm lưới, cầu ngoài sân, giao cầu sai; hiểu quy định đánh lại và đổi sân.','kho',20,'Lỗi trong cầu lông: cầu rơi ngoài vạch giới hạn, cầu không qua lưới, chạm lưới khi cầu còn trong cuộc, giao cầu sai quy định. Khi có sự cố ngoài ý muốn (cầu mắc trên lưới), trọng tài cho đánh lại pha bóng đó. Đổi sân khi kết thúc mỗi set và giữa set 3 khi một bên đạt 11 điểm.','- Chạm lưới khi cầu còn trong cuộc là lỗi, bị mất điểm ngay.\n- Đánh cầu ra ngoài sân hoặc cầu không qua lưới đều bị mất điểm.\n- Giao cầu sai kỹ thuật (không chéo sân, đánh quá cao) bị phạt mất điểm.\n- Khi có sự cố khách quan không xác định được, trọng tài cho đánh lại pha bóng.\n- Hai bên đổi sân theo quy định giữa các set đấu.',2,'published',11,1,'2026-10-07 22:58:54','2026-10-07 22:58:54'),
(415,140,'Các nhóm chất dinh dưỡng cho người tập luyện','gdtc-thpt-12-lop-12-1','Kể tên 6 nhóm chất dinh dưỡng và vai trò của từng nhóm với người tập thể thao.','trung_binh',15,'Sáu nhóm chất: bột đường (carbohydrate) là nhiên liệu chính cho vận động; đạm (protein) xây dựng và phục hồi cơ bắp; chất béo cung cấp năng lượng dự trữ; vitamin và khoáng chất điều hòa hoạt động cơ thể; nước chiếm 60–70% cơ thể, mất nước làm giảm hiệu suất. Người tập luyện cần ăn đa dạng, đủ chất, không bỏ bữa.','- Sáu nhóm chất dinh dưỡng: bột đường, đạm, béo, vitamin, khoáng chất và nước.\n- Bột đường là nhiên liệu chính, cung cấp năng lượng nhanh nhất cho cơ bắp hoạt động.\n- Đạm là vật liệu xây dựng và sửa chữa các sợi cơ sau buổi tập.\n- Vitamin và khoáng chất giúp chuyển hóa năng lượng, tăng sức đề kháng.\n- Nước chiếm phần lớn cơ thể; mất nước làm giảm hiệu suất vận động rõ rệt.',1,'published',12,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(416,140,'Ăn uống trước, trong và sau khi tập luyện','gdtc-thpt-12-lop-12-2','Biết cách ăn uống hợp lý quanh buổi tập: thời điểm, loại thực phẩm và bù nước.','trung_binh',15,'Trước tập 2–3 giờ: ăn bữa giàu bột đường, ít béo, dễ tiêu. Trong buổi tập kéo dài: bù nước thường xuyên, có thể dùng nước có điện giải. Sau tập 30–60 phút: bổ sung đạm và bột đường để phục hồi cơ. Tránh ăn quá no ngay trước tập, tránh đồ uống có cồn và nhiều đường.','- Trước buổi tập 2–3 giờ: ăn bữa giàu bột đường, ít béo, dễ tiêu để tránh đầy bụng.\n- Trong buổi tập kéo dài: bù nước đều đặn từng ngụm nhỏ, tránh để mất nước giảm hiệu suất.\n- Sau buổi tập: bổ sung đạm và bột đường trong 1–2 giờ để phục hồi cơ bắp.\n- Tránh đồ ăn nhiều dầu mỡ và nước có gas quanh thời gian tập luyện.\n- Dinh dưỡng quanh buổi tập quyết định hiệu quả tập luyện và tốc độ phục hồi.',2,'published',12,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(417,141,'Nguyên tắc tập luyện khoa học','gdtc-thpt-12-lop-12-3','Nắm các nguyên tắc: tăng tiến dần, đặc thù, đa dạng, nghỉ ngơi hồi phục.','trung_binh',15,'Tăng tiến dần: tăng khối lượng, cường độ từ từ để cơ thể thích nghi. Đặc thù: tập đúng nhóm cơ và kỹ năng của môn mình chơi. Đa dạng: kết hợp sức bền, sức mạnh, linh hoạt để phát triển toàn diện. Nghỉ ngơi: cơ bắp phát triển trong lúc nghỉ; tập quá sức gây quá tải, chấn thương và sa sút phong độ.','- Nguyên tắc tăng tiến dần: tăng khối lượng và cường độ từ từ để cơ thể thích nghi an toàn.\n- Nguyên tắc đặc thù: muốn giỏi môn nào phải tập bài tập đặc thù cho môn đó.\n- Nguyên tắc đa dạng: thay đổi bài tập để cơ thể phát triển toàn diện, tránh nhàm chán.\n- Nguyên tắc nghỉ ngơi, hồi phục: cơ bắp phát triển trong lúc nghỉ; tập quá sức gây chấn thương.\n- Tập luyện khoa học là tập từ từ, đúng đặc thù, đa dạng bài tập và có nghỉ ngơi hợp lý.',1,'published',12,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(418,141,'Khởi động, thả lỏng và phòng tránh chấn thương','gdtc-thpt-12-lop-12-4','Hiểu vai trò của khởi động và thả lỏng; nhận biết chấn thương thường gặp và cách xử trí ban đầu.','kho',20,'Khởi động 10–15 phút làm nóng cơ, tăng nhịp tim, bôi trơn khớp, giảm nguy cơ chấn thương. Thả lỏng sau tập giúp cơ thể trở lại trạng thái bình thường, giảm đau cơ. Chấn thương thường gặp: bong gân, căng cơ, trật khớp. Xử trí ban đầu theo nguyên tắc RICE: nghỉ ngơi, chườm lạnh, băng ép, kê cao; chấn thương nặng phải đến cơ sở y tế.','- Một buổi tập hoàn chỉnh gồm các giai đoạn: khởi động, phần chính và thả lỏng.\n- Khởi động 10–15 phút làm nóng cơ, bôi trơn khớp, giảm nguy cơ chấn thương.\n- Thả lỏng sau buổi tập giúp đào thải chất cặn, giảm đau cơ ngày hôm sau.\n- Chấn thương thường gặp: chuột rút, bong gân, căng cơ — xử trí ban đầu theo nguyên tắc RICE.\n- Dừng tập ngay khi thấy đau bất thường, không cố gắng chịu đựng.',2,'published',12,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(419,142,'Sắp xếp ưu tiên với ma trận Eisenhower','trai-nghiem-huong-nghiep-thpt-10-lop-10-1','Phân loại công việc theo mức độ quan trọng – khẩn cấp; lập kế hoạch tuần hiệu quả.','trung_binh',15,'Ma trận Eisenhower chia việc thành 4 ô: quan trọng và khẩn cấp (làm ngay), quan trọng nhưng không khẩn cấp (lên lịch), khẩn cấp nhưng không quan trọng (ủy thác), không quan trọng cũng không khẩn cấp (loại bỏ). Học sinh nên dành nhiều thời gian cho ô 2: ôn bài, đọc sách. Lập kế hoạch tuần vào đầu tuần, mỗi tối rà soát lại.','- Ma trận Eisenhower chia công việc theo hai tiêu chí: quan trọng và khẩn cấp.\n- Ô 1 (quan trọng và khẩn cấp): làm ngay lập tức, ưu tiên cao nhất.\n- Ô 2 (quan trọng nhưng không khẩn cấp): lên lịch thực hiện — nên đầu tư nhiều cho ô này.\n- Ô 3 (khẩn cấp nhưng không quan trọng): ủy thác cho người khác nếu có thể.\n- Ô 4 (không quan trọng, không khẩn cấp): hạn chế hoặc loại bỏ khỏi kế hoạch.',1,'published',10,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(420,142,'Kỹ thuật Pomodoro và vượt qua trì hoãn','trai-nghiem-huong-nghiep-thpt-10-lop-10-2','Áp dụng Pomodoro 25/5; nhận biết nguyên nhân trì hoãn và cách khắc phục.','trung_binh',15,'Pomodoro: học tập trung 25 phút, nghỉ 5 phút; sau 4 phiên nghỉ dài 15–30 phút. Trì hoãn thường do việc quá lớn (chia nhỏ ra), sợ thất bại (bắt đầu từ phần dễ nhất) hoặc xao nhãng (tắt thông báo, dọn bàn học). Quy tắc 2 phút: việc gì làm được trong 2 phút thì làm ngay.','- Kỹ thuật Pomodoro: 25 phút tập trung cao độ rồi nghỉ 5 phút; sau 4 phiên thì nghỉ dài.\n- Chu kỳ 25/5 là cốt lõi giúp duy trì sự tập trung mà không kiệt sức.\n- Tắt thông báo điện thoại, dọn bàn học gọn gàng để tránh xao nhãng.\n- Nguyên nhân trì hoãn thường gặp: việc quá lớn, sợ thất bại, thiếu động lực.\n- Chia việc lớn thành việc nhỏ và bắt đầu ngay 5 phút đầu để vượt qua trì hoãn.',2,'published',10,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(421,143,'Ghi chú Cornell và kỹ thuật Feynman','trai-nghiem-huong-nghiep-thpt-10-lop-10-3','Ghi chú theo phương pháp Cornell; dùng kỹ thuật Feynman để kiểm tra mức độ hiểu bài.','trung_binh',15,'Ghi chú Cornell chia trang thành 3 phần: ghi chú chính, cột từ khóa/câu hỏi, phần tóm tắt cuối trang. Kỹ thuật Feynman: giải thích lại kiến thức bằng lời đơn giản như đang dạy người khác; chỗ nào lúng túng chính là chỗ chưa hiểu, cần học lại. Dạy lại cho bạn là cách học sâu nhất.','- Ghi chú Cornell chia trang giấy thành 3 phần: ghi chú chính, cột từ khóa/câu hỏi và phần tóm tắt.\n- Cột từ khóa/câu hỏi dùng để tự đặt câu hỏi ôn tập sau buổi học.\n- Phần tóm tắt ghi ý chính của bài bằng lời của mình sau mỗi buổi học.\n- Kỹ thuật Feynman: giải thích lại bài bằng lời đơn giản như đang dạy người khác — chỗ nào vướng là chỗ chưa hiểu.\n- Học chủ động (tự kiểm tra, giải thích lại) giúp ghi nhớ lâu hơn nhiều so với đọc thụ động.',1,'published',10,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(422,143,'Ôn tập ngắt quãng và chiến lược làm bài thi','trai-nghiem-huong-nghiep-thpt-10-lop-10-4','Áp dụng spaced repetition; xây dựng chiến lược phân bổ thời gian và kiểm tra bài thi.','kho',20,'Ôn tập ngắt quãng (spaced repetition): ôn lại sau 1 ngày, 3 ngày, 1 tuần, 1 tháng thay vì nhồi nhét một lúc. Tự kiểm tra bằng cách đóng sách và viết ra những gì nhớ được. Khi làm bài thi: đọc hết đề, làm câu dễ trước, phân bổ thời gian theo điểm số, dành 5–10 phút cuối kiểm tra lại.','- Ôn tập ngắt quãng (spaced repetition): ôn lại sau 1 ngày, 3 ngày, 1 tuần, 1 tháng giúp nhớ lâu.\n- Kỹ thuật tự kiểm tra (retrieval practice): tự gợi nhớ kiến thức thay vì chỉ đọc lại.\n- Chiến lược làm bài thi: đọc kỹ đề, làm câu dễ trước, phân bổ thời gian hợp lý.\n- Dành thời gian cuối giờ kiểm tra lại bài để tránh sai sót đáng tiếc.\n- Ôn cách quãng và tự kiểm tra là hai cách ôn tập hiệu quả nhất.',2,'published',10,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(423,144,'Sáu nhóm tính cách nghề nghiệp Holland','trai-nghiem-huong-nghiep-thpt-11-lop-11-1','Nhận biết 6 nhóm R-I-A-S-E-C và ví dụ nghề đặc trưng của mỗi nhóm.','trung_binh',15,'Lý thuyết Holland chia tính cách nghề nghiệp thành 6 nhóm: Realistic (kỹ thuật – thợ, kỹ sư), Investigative (nghiên cứu – nhà khoa học, bác sĩ), Artistic (nghệ thuật – họa sĩ, nhạc sĩ), Social (xã hội – giáo viên, tư vấn), Enterprising (quản lý – doanh nhân, lãnh đạo), Conventional (nghiệp vụ – kế toán, hành chính). Mỗi người là sự kết hợp của 2–3 nhóm.','- Lý thuyết Holland chia tính cách nghề nghiệp thành 6 nhóm: R – I – A – S – E – C.\n- R (Realistic): nhóm kỹ thuật, thích làm việc với máy móc, công cụ.\n- I (Investigative): nhóm nghiên cứu, thích tìm tòi, phân tích, khám phá.\n- A (Artistic): nhóm nghệ thuật, thích sáng tạo và tự do thể hiện.\n- S (Social): nhóm xã hội, thích giúp đỡ và giao tiếp với con người.\n- E (Enterprising): nhóm quản lý, thích lãnh đạo và thuyết phục; C (Conventional): nhóm nghiệp vụ, thích trật tự và số liệu.',1,'published',11,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(424,144,'Các lĩnh vực nghề nghiệp trong xã hội hiện đại','trai-nghiem-huong-nghiep-thpt-11-lop-11-2','Có cái nhìn tổng quan về các lĩnh vực: công nghệ, y tế, giáo dục, kinh tế, nghệ thuật, dịch vụ.','trung_binh',15,'Các lĩnh vực lớn: công nghệ thông tin (lập trình, dữ liệu, an ninh mạng), y tế – sức khỏe, giáo dục – đào tạo, kinh tế – tài chính – kinh doanh, kỹ thuật – xây dựng, nghệ thuật – truyền thông, dịch vụ – du lịch. Công nghệ và chuyển đổi số đang tạo ra nhiều nghề mới, đồng thời thay đổi yêu cầu của nghề truyền thống.','- Lĩnh vực công nghệ thông tin: lập trình viên, chuyên gia dữ liệu, an ninh mạng — phát triển nhanh nhất hiện nay.\n- Lĩnh vực y tế: bác sĩ, điều dưỡng — chăm sóc sức khỏe cộng đồng.\n- Lĩnh vực giáo dục: giáo viên, giảng viên — đào tạo nguồn nhân lực cho xã hội.\n- Lĩnh vực kinh tế: kế toán, marketing, quản trị kinh doanh.\n- Chuyển đổi số đang tạo ra nhiều nghề mới và thay đổi các nghề truyền thống.',2,'published',11,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(425,145,'Sở thích, năng lực và tính cách','trai-nghiem-huong-nghiep-thpt-11-lop-11-3','Phân biệt sở thích – năng lực – tính cách; biết cách tự đánh giá bản thân khách quan.','trung_binh',15,'Sở thích là điều bạn thích làm; năng lực là điều bạn làm tốt; tính cách là cách bạn hành xử ổn định. Ba yếu tố này có thể khác nhau: thích vẽ chưa chắc vẽ giỏi. Tự đánh giá qua kết quả học tập các môn, nhận xét của thầy cô bạn bè, trải nghiệm hoạt động ngoại khóa và các bài trắc nghiệm hướng nghiệp uy tín.','- Sở thích là điều bạn thích làm — điểm khởi đầu của hướng nghiệp.\n- Năng lực là điều bạn làm giỏi — quyết định khả năng thành công với nghề.\n- Tính cách là cách bạn hành xử, phản ứng — ảnh hưởng đến sự phù hợp với môi trường làm việc.\n- Thích một nghề chưa đủ: thích vẽ chưa chắc vẽ giỏi, cần cả năng lực và tính cách phù hợp.\n- Tự đánh giá khách quan cả ba yếu tố giúp chọn nghề đúng đắn.',1,'published',11,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(426,145,'Giá trị nghề nghiệp và mục tiêu cuộc đời','trai-nghiem-huong-nghiep-thpt-11-lop-11-4','Xác định giá trị nghề nghiệp của bản thân; đặt mục tiêu theo nguyên tắc SMART.','kho',20,'Giá trị nghề nghiệp là điều bạn coi trọng trong công việc: thu nhập, ổn định, sáng tạo, giúp đỡ người khác, danh tiếng, tự do... Không có giá trị nào đúng cho mọi người, quan trọng là trung thực với mình. Mục tiêu SMART: cụ thể (Specific), đo được (Measurable), khả thi (Achievable), phù hợp (Relevant), có thời hạn (Time-bound).','- Giá trị nghề nghiệp là điều bạn coi trọng trong công việc: thu nhập, ổn định, sáng tạo, giúp đỡ người khác.\n- Xác định giá trị của bản thân giúp chọn nghề phù hợp với mong muốn sâu xa.\n- Mục tiêu SMART: Specific (cụ thể), Measurable (đo được), Achievable (khả thi), Relevant (phù hợp), Time-bound (có thời hạn).\n- Mục tiêu càng cụ thể càng dễ lập kế hoạch và kiên trì thực hiện.\n- Viết mục tiêu ra giấy và xem lại thường xuyên để không lạc hướng.',2,'published',11,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(427,146,'Tiêu chí chọn ngành học phù hợp','trai-nghiem-huong-nghiep-thpt-12-lop-12-1','Liệt kê các tiêu chí chọn ngành: bản thân, nhu cầu xã hội, điều kiện gia đình; tránh các sai lầm phổ biến.','trung_binh',15,'Chọn ngành dựa trên 3 chân kiềng: hiểu mình (sở thích, năng lực), hiểu nghề (công việc thực tế, thu nhập, cơ hội), hiểu điều kiện (học lực, tài chính gia đình). Sai lầm phổ biến: chọn theo phong trào, chọn vì tên ngành nghe hay, chọn theo ý cha mẹ mà bỏ qua bản thân, chỉ nhìn điểm chuẩn năm trước.','- Chọn ngành dựa trên 3 chân kiềng: hiểu mình, hiểu nghề và hiểu điều kiện (học lực, tài chính gia đình).\n- Hiểu mình gồm sở thích, năng lực, tính cách và giá trị nghề nghiệp.\n- Hiểu nghề gồm công việc thực tế, yêu cầu, cơ hội việc làm và thu nhập.\n- Sai lầm cần tránh: chọn ngành theo phong trào, theo bạn bè hoặc chỉ vì ngành đang hot.\n- Chọn ngành là quyết định quan trọng — cần thời gian tìm hiểu kỹ và trao đổi với người có kinh nghiệm.',1,'published',12,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(428,146,'Tìm hiểu trường và phương thức xét tuyển','trai-nghiem-huong-nghiep-thpt-12-lop-12-2','Biết cách tìm hiểu thông tin trường; nắm các phương thức xét tuyển đại học phổ biến.','trung_binh',15,'Tìm hiểu trường qua website chính thức: chương trình đào tạo, học phí, cơ sở vật chất, việc làm sau tốt nghiệp. Các phương thức xét tuyển phổ biến: điểm thi tốt nghiệp THPT, xét học bạ, đánh giá năng lực/tư duy, xét tuyển thẳng, chứng chỉ quốc tế. Nên đăng ký nhiều nguyện vọng theo thứ tự ưu tiên từ cao đến thấp.','- Nguồn thông tin đáng tin nhất về trường đại học là website chính thức của trường.\n- Các phương thức xét tuyển phổ biến: điểm thi tốt nghiệp THPT, xét học bạ, đánh giá năng lực, xét tuyển thẳng.\n- Hai nhóm phương thức chính: dựa trên điểm số và dựa trên thành tích.\n- Tìm hiểu kỹ ngành học, học phí và cơ sở vật chất trước khi đăng ký.\n- Chuẩn bị hồ sơ đầy đủ và nộp đúng thời hạn quy định.',2,'published',12,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(429,147,'Viết CV và chuẩn bị hồ sơ ấn tượng','trai-nghiem-huong-nghiep-thpt-12-lop-12-3','Biết cấu trúc một CV tốt; chuẩn bị hồ sơ ứng tuyển học bổng/việc làm đầy đủ.','trung_binh',15,'CV tốt gồm: thông tin liên hệ, mục tiêu ngắn gọn, học vấn, kinh nghiệm/hoạt động, kỹ năng, chứng chỉ. Nguyên tắc: trung thực tuyệt đối, gọn trong 1–2 trang, không lỗi chính tả, dùng động từ hành động và con số cụ thể. Hồ sơ ứng tuyển thường gồm CV, thư giới thiệu bản thân, bằng cấp/chứng chỉ và ảnh chân dung lịch sự.','- Một CV tốt gồm các phần: thông tin cá nhân, mục tiêu, học vấn, kinh nghiệm/hoạt động và kỹ năng.\n- Nguyên tắc quan trọng nhất khi viết CV: trung thực tuyệt đối, không bịa đặt thông tin.\n- CV cần gọn gàng, rõ ràng, nhấn mạnh điểm mạnh phù hợp với vị trí ứng tuyển.\n- Kiểm tra kỹ chính tả và định dạng trước khi gửi hồ sơ.\n- Chuẩn bị hồ sơ đầy đủ theo yêu cầu: CV, đơn ứng tuyển, bằng cấp và giấy tờ liên quan.',1,'published',12,1,'2026-10-07 22:58:55','2026-10-07 22:58:55'),
(430,147,'Kỹ năng trả lời phỏng vấn','trai-nghiem-huong-nghiep-thpt-12-lop-12-4','Chuẩn bị câu trả lời cho câu hỏi thường gặp; thể hiện tác phong chuyên nghiệp khi phỏng vấn.','kho',20,'Chuẩn bị trước: tìm hiểu về trường/công ty, luyện trả lời các câu hỏi thường gặp (giới thiệu bản thân, điểm mạnh – điểm yếu, vì sao chọn chúng tôi). Trong phỏng vấn: đến sớm, ăn mặc lịch sự, giao tiếp bằng mắt, trả lời ngắn gọn có ví dụ cụ thể, đặt câu hỏi ngược lại khi được mời. Sau phỏng vấn, gửi thư cảm ơn là điểm cộng lớn.','- Trước buổi phỏng vấn: tìm hiểu kỹ về nơi mình ứng tuyển, chuẩn bị câu trả lời cho câu hỏi thường gặp.\n- Đến đúng giờ, trang phục lịch sự gọn gàng tạo ấn tượng tốt đầu tiên.\n- Trả lời rõ ràng, tự tin và trung thực; nhìn vào mắt người phỏng vấn.\n- Chuẩn bị câu hỏi để hỏi lại nhà tuyển dụng thể hiện sự quan tâm nghiêm túc.\n- Sau phỏng vấn: cảm ơn lịch sự và chờ đợi, không giục giã.',2,'published',12,1,'2026-10-07 22:58:55','2026-10-07 22:58:55');
