INSERT INTO `questions` VALUES
(1,1,'quiz',6,'125 + 78 = ?','Đặt tính rồi cộng: 125 + 78 = 203. Nhớ 1 ở hàng chục khi 5 + 8 = 13.','de',10,1,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(2,1,'quiz',6,'940 − 267 = ?','940 − 267 = 673. Mượn 1 ở hàng trăm vì 4 chục không trừ được 6 chục.','de',10,2,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(3,1,'quiz',6,'Một cửa hàng bán 245 cuốn sách buổi sáng và 318 cuốn buổi chiều. Cả ngày bán được bao nhiêu cuốn?','Cả ngày bán được 245 + 318 = 563 cuốn sách.','de',10,3,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(4,1,'matching',6,'Nối mỗi phép tính với kết quả đúng.','45 + 27 = 72; 96 − 38 = 58; 123 + 45 = 168; 200 − 75 = 125.','de',10,4,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(5,1,'matching',6,'Nối mỗi bài toán lời văn với phép tính đúng.','Thêm vào thì cộng, bớt đi thì trừ: 15 + 8, 20 − 6, 32 + 29.','de',10,5,1,'2026-10-07 20:45:31','2026-10-07 20:45:31'),
(6,1,'matching',6,'Nối mỗi tổng hoặc hiệu với giá trị của nó.','150 + 230 = 380; 500 − 145 = 355; 999 + 1 = 1000.','de',10,6,1,'2026-10-07 20:45:32','2026-10-07 20:45:32'),
(7,2,'sort',6,'Kéo mỗi phép tính vào nhóm ĐÚNG hoặc SAI.','12 × 5 = 60 đúng; 7 × 8 = 56 nên 54 là sai; 144 : 12 = 12 đúng; 96 : 4 = 24 nên 26 là sai.','de',10,1,1,'2026-10-07 20:45:32','2026-10-07 20:45:32'),
(8,2,'sort',6,'Kéo mỗi phép tính vào nhóm kết quả CHẴN hoặc LẺ.','Số lẻ nhân số lẻ cho kết quả lẻ; số chẵn chia hết cho 2 cho kết quả chẵn.','de',10,2,1,'2026-10-07 20:45:32','2026-10-07 20:45:32'),
(9,2,'sort',6,'Kéo mỗi phép tính vào nhóm NHÂN hoặc CHIA.','Dấu × là phép nhân, dấu : là phép chia.','de',10,3,1,'2026-10-07 20:45:32','2026-10-07 20:45:32'),
(10,2,'fill',6,'25 × 4 = ___','25 × 4 = 100. Có thể nhẩm: 25 × 4 = (20 × 4) + (5 × 4) = 80 + 20 = 100.','de',10,4,1,'2026-10-07 20:45:32','2026-10-07 20:45:32'),
(11,2,'fill',6,'Một hộp có 12 cái bánh. 8 hộp như vậy có tất cả ___ cái bánh.','12 × 8 = 96 cái bánh.','de',10,5,1,'2026-10-07 20:45:32','2026-10-07 20:45:32'),
(12,2,'fill',6,'360 : 9 = ___','360 : 9 = 40. Nhẩm: 36 : 9 = 4 nên 360 : 9 = 40.','de',10,6,1,'2026-10-07 20:45:32','2026-10-07 20:45:32'),
(13,3,'quiz',6,'1/3 + 2/3 = ?','Hai phân số cùng mẫu số: cộng tử số, giữ nguyên mẫu số. 1/3 + 2/3 = 3/3 = 1.','trung_binh',10,1,1,'2026-10-07 20:45:32','2026-10-07 20:45:32'),
(14,3,'quiz',6,'3/4 − 1/4 = ?','3/4 − 1/4 = 2/4, rút gọn được 1/2.','trung_binh',10,2,1,'2026-10-07 20:45:32','2026-10-07 20:45:32'),
(15,3,'quiz',6,'1/2 + 1/4 = ?','Quy đồng: 1/2 = 2/4. Vậy 2/4 + 1/4 = 3/4.','trung_binh',10,3,1,'2026-10-07 20:45:32','2026-10-07 20:45:32'),
(16,3,'matching',6,'Nối mỗi phép tính với kết quả đúng (đã rút gọn).','Cùng mẫu số thì cộng/trừ tử số: 4/6 rút gọn = 2/3; 4/8 rút gọn = 1/2; 4/10 rút gọn = 2/5.','trung_binh',10,4,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(17,3,'matching',6,'Nối mỗi yêu cầu với kết quả đúng.','Quy đồng là đưa về cùng mẫu số; tối giản là chia cả tử và mẫu cho ước chung lớn nhất.','trung_binh',10,5,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(18,3,'matching',6,'Nối mỗi phép tính với kết quả đúng.','1/2 + 1/3 = 3/6 + 2/6 = 5/6; 2/3 − 1/6 = 4/6 − 1/6 = 1/2; 3/4 + 1/8 = 6/8 + 1/8 = 7/8.','trung_binh',10,6,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(19,4,'sort',6,'Kéo mỗi giá trị vào nhóm LỚN HƠN 1 hoặc NHỎ HƠN 1.','Phân số có tử lớn hơn mẫu thì lớn hơn 1, tử nhỏ hơn mẫu thì nhỏ hơn 1.','trung_binh',10,1,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(20,4,'sort',6,'Kéo mỗi phép tính vào nhóm NHÂN hoặc CHIA.','Dấu × là phép nhân, dấu : là phép chia.','trung_binh',10,2,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(21,4,'sort',6,'Kéo mỗi phép tính vào nhóm ĐÚNG hoặc SAI.','4/7 : 4 = 4/28 = 1/7, nên đáp án 1/28 là sai.','trung_binh',10,3,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(22,4,'fill',6,'2/3 × 3/4 = ___','Nhân tử với tử, mẫu với mẫu: 6/12 = 1/2.','trung_binh',10,4,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(23,4,'fill',6,'3/5 : 2 = ___','3/5 : 2 = 3/5 × 1/2 = 3/10.','trung_binh',10,5,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(24,4,'fill',6,'5/6 : 5 = ___','5/6 : 5 = 5/6 × 1/5 = 5/30 = 1/6.','trung_binh',10,6,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(25,5,'quiz',7,'Thu gọn đơn thức 2x · 3x² ta được','Nhân hệ số: 2 × 3 = 6; nhân biến: x · x² = x³. Kết quả 6x³.','trung_binh',10,1,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(26,5,'quiz',7,'Bậc của đơn thức 4x²y³ là','Bậc của đơn thức là tổng số mũ của các biến: 2 + 3 = 5.','trung_binh',10,2,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(27,5,'quiz',7,'Đơn thức nào đồng dạng với 5xy²?','Hai đơn thức đồng dạng có cùng phần biến: cùng là xy².','trung_binh',10,3,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(28,5,'matching',7,'Nối mỗi phép nhân đơn thức với kết quả thu gọn.','Nhân hệ số với hệ số, cộng số mũ của cùng biến: a·a = a², x²·x = x³, y·y³ = y⁴.','trung_binh',10,4,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(29,5,'matching',7,'Nối mỗi đơn thức với bậc của nó.','Bậc là tổng số mũ các biến; đơn thức hằng (số) có bậc 0.','trung_binh',10,5,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(30,5,'matching',7,'Nối mỗi phép cộng/trừ đơn thức đồng dạng với kết quả.','Chỉ cộng/trừ được các đơn thức đồng dạng: cộng hệ số, giữ nguyên phần biến.','trung_binh',10,6,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(31,6,'sort',7,'Kéo mỗi phép tính vào nhóm làm TRƯỚC hoặc làm SAU.','Thứ tự: trong ngoặc trước, rồi đến nhân/chia, cuối cùng cộng/trừ.','kho',10,1,1,'2026-10-07 20:45:33','2026-10-07 20:45:33'),
(32,6,'sort',7,'Kéo mỗi khẳng định vào nhóm ĐÚNG hoặc SAI.','Thay x = 3 vào 2x² được 2 × 9 = 18, không phải 12.','kho',10,2,1,'2026-10-07 20:45:34','2026-10-07 20:45:34'),
(33,6,'sort',7,'Kéo mỗi biểu thức vào nhóm MỘT BIẾN hoặc HAI BIẾN.','Biểu thức một biến chỉ chứa một chữ (x), hai biến chứa hai chữ (x và y, hoặc a và b).','kho',10,3,1,'2026-10-07 20:45:34','2026-10-07 20:45:34'),
(34,6,'fill',7,'Với x = 5, giá trị của biểu thức 2x + 3 là ___','Thay x = 5: 2 × 5 + 3 = 10 + 3 = 13.','kho',10,4,1,'2026-10-07 20:45:34','2026-10-07 20:45:34'),
(35,6,'fill',7,'Với a = 2 và b = 3, giá trị của biểu thức a² + b là ___','Thay a = 2, b = 3: 2² + 3 = 4 + 3 = 7.','kho',10,5,1,'2026-10-07 20:45:34','2026-10-07 20:45:34'),
(36,6,'fill',7,'Với x = 4, giá trị của biểu thức 5x − 7 là ___','Thay x = 4: 5 × 4 − 7 = 20 − 7 = 13.','kho',10,6,1,'2026-10-07 20:45:34','2026-10-07 20:45:34'),
(37,7,'quiz',7,'Góc nào sau đây là góc nhọn?','Góc nhọn có số đo nhỏ hơn 90 độ. Góc 45 độ là góc nhọn.','de',10,1,1,'2026-10-07 20:45:34','2026-10-07 20:45:34'),
