(186,31,'matching',8,'Nối mỗi địa danh với sự kiện lịch sử.','Trận Bạch Đằng 1288 tiêu diệt hoàn toàn đạo quân xâm lược.','trung_binh',10,6,1,'2026-10-07 20:45:48','2026-10-07 20:45:48'),
(187,32,'sort',8,'Kéo mỗi tác phẩm vào nhóm CỦA TRẦN HƯNG ĐẠO hoặc KHÔNG PHẢI.','\"Nam quốc sơn hà\" gắn với Lý Thường Kiệt; \"Đại Việt sử ký toàn thư\" do Ngô Sĩ Liên biên soạn.','trung_binh',10,1,1,'2026-10-07 20:45:48','2026-10-07 20:45:48'),
(188,32,'sort',8,'Kéo mỗi khẳng định vào nhóm ĐÚNG hoặc SAI.','Ông là tướng, không phải vua; là bậc anh hùng dân tộc.','trung_binh',10,2,1,'2026-10-07 20:45:48','2026-10-07 20:45:48'),
(189,32,'sort',8,'Kéo mỗi trận đánh vào cuộc kháng chiến đúng.','Chương Dương, Tây Kết thuộc lần 2; Vân Đồn, Bạch Đằng thuộc lần 3.','trung_binh',10,3,1,'2026-10-07 20:45:48','2026-10-07 20:45:48'),
