(13043,386,'quiz',10,'Dấu hóa bất thường (ghi ngay trước nốt nhạc) có hiệu lực trong phạm vi nào?','Dấu hóa bất thường chỉ có hiệu lực trong ô nhịp chứa nó, sang ô nhịp mới thì hết hiệu lực.','kho',10,19,1,'2026-10-08 09:55:34','2026-10-08 09:55:34'),
(13044,217,'quiz',7,'Trong một quãng, nốt có cao độ thấp hơn thường được gọi là nốt nào?','Trong một quãng, nốt thấp hơn gọi là nốt dưới, nốt cao hơn gọi là nốt trên.','de',10,19,1,'2026-10-08 09:55:34','2026-10-08 09:55:34'),
(13045,386,'quiz',10,'Nhịp 5/4 thuộc loại nhịp nào?','Nhịp 5/4 gồm 5 phách chia thành nhóm 3+2 hoặc 2+3, là nhịp hỗn hợp.','kho',10,20,1,'2026-10-08 09:55:34','2026-10-08 09:55:34'),
(13046,217,'quiz',7,'Ví dụ nào sau đây là quãng 2?','Quãng 2 gồm hai nốt kề nhau, trong các đáp án chỉ Đô - Rê là hai nốt kề nhau.','de',10,20,1,'2026-10-08 09:55:35','2026-10-08 09:55:35'),
(13047,386,'matching',10,'Nối mỗi bộ khóa với giọng tương ứng.','Số lượng và vị trí dấu hóa trong bộ khóa xác định giọng của bản nhạc.','kho',10,21,1,'2026-10-08 09:55:35','2026-10-08 09:55:35'),
(13048,217,'matching',7,'Nối mỗi tên quãng với cặp nốt tương ứng (đếm từ nốt Đô).','Tên quãng bằng số nốt đếm được từ nốt dưới lên nốt trên.','de',10,21,1,'2026-10-08 09:55:35','2026-10-08 09:55:35'),
(13049,386,'matching',10,'Nối mỗi loại nhịp với ví dụ của nó.','Nhịp C (common time) là cách viết tắt quen thuộc của nhịp 4/4.','kho',10,22,1,'2026-10-08 09:55:35','2026-10-08 09:55:35'),
(13050,217,'matching',7,'Nối mỗi quãng với số nốt đếm được từ nốt dưới lên nốt trên.','Quãng mấy thì đếm được bấy nhiêu nốt từ nốt dưới tới nốt trên.','de',10,22,1,'2026-10-08 09:55:35','2026-10-08 09:55:35'),
